/**
 * Virtual Filesystem (VFS) for the agent
 *
 * Provides an in-memory filesystem using just-bash that allows:
 * - Users to upload files (images, CSVs, etc.)
 * - Agent to read files via read_file tool
 * - Agent to execute bash commands via bash tool
 */

import { Bash, InMemoryFs } from "just-bash/browser";
import { getCustomCommands } from "./custom-commands";

// Singleton instances
let fs: InMemoryFs | null = null;
let bash: Bash | null = null;

// Skill files are mounted on every VFS creation (global, not per-session)
let skillFilesCache: Record<string, Uint8Array | string> = {};

export function setSkillFiles(
  files: Record<string, Uint8Array | string>,
): void {
  skillFilesCache = files;
}

/**
 * Get or create the virtual filesystem instance
 */
export function getVfs(): InMemoryFs {
  if (!fs) {
    fs = new InMemoryFs({
      "/home/user/uploads/.keep": "",
      ...skillFilesCache,
    });
  }
  return fs;
}

/**
 * Get or create the Bash instance
 */
export function getBash(): Bash {
  if (!bash) {
    bash = new Bash({
      fs: getVfs(),
      cwd: "/home/user",
      customCommands: getCustomCommands(),
    });
  }
  return bash;
}

/**
 * Reset the VFS (clears all files, creates fresh instances)
 */
export function resetVfs(): void {
  fs = null;
  bash = null;
}

/**
 * Snapshot all files in the VFS as path→Uint8Array pairs.
 * Only captures files (not directories or symlinks).
 */
export async function snapshotVfs(): Promise<
  { path: string; data: Uint8Array }[]
> {
  const vfs = getVfs();
  const allPaths = vfs.getAllPaths();
  const files: { path: string; data: Uint8Array }[] = [];

  for (const p of allPaths) {
    // Skip skill files — they're managed globally, not per-session
    if (p.startsWith("/home/skills/")) continue;
    try {
      const stat = await vfs.stat(p);
      if (stat.isFile) {
        const data = await vfs.readFileBuffer(p);
        // Create a copy of the data so snapshots do not share mutable buffers
        const dataCopy = new Uint8Array(data.byteLength);
        dataCopy.set(data);
        files.push({ path: p, data: dataCopy });
      }
    } catch {
      // skip unreadable entries
    }
  }

  return files;
}

/**
 * Restore VFS from a snapshot. Resets existing state and writes all files.
 */
export async function restoreVfs(
  files: { path: string; data: Uint8Array }[],
): Promise<void> {
  resetVfs();

  if (files.length === 0) {
    // Just initialize the default VFS (includes skills from cache)
    getVfs();
    return;
  }

  // Build InitialFiles record: skills (global) + session files
  const initialFiles: Record<string, Uint8Array | string> = {
    "/home/user/uploads/.keep": "",
    ...skillFilesCache,
  };
  for (const f of files) {
    initialFiles[f.path] = f.data;
  }

  fs = new InMemoryFs(initialFiles);
  bash = null; // will be lazily created with the new fs
}

/**
 * Write a file to the VFS
 */
export async function writeFile(
  path: string,
  content: string | Uint8Array,
): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;

  // Ensure parent directory exists
  const dir = fullPath.substring(0, fullPath.lastIndexOf("/"));
  if (dir && dir !== "/") {
    try {
      await vfs.mkdir(dir, { recursive: true });
    } catch {
      // Directory might already exist
    }
  }

  await vfs.writeFile(fullPath, content);
}

/**
 * Read a file from the VFS
 */
export async function readFile(path: string): Promise<string> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.readFile(fullPath);
}

/**
 * Read a file as binary from the VFS
 */
export async function readFileBuffer(path: string): Promise<Uint8Array> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.readFileBuffer(fullPath);
}

/**
 * Check if a file exists in the VFS
 */
export async function fileExists(path: string): Promise<boolean> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  return vfs.exists(fullPath);
}

/**
 * Delete a file from the VFS
 */
export async function deleteFile(path: string): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  await vfs.rm(fullPath);
}

/**
 * List files in the VFS uploads directory
 */
export async function listUploads(): Promise<string[]> {
  const vfs = getVfs();
  try {
    // Recursively list all files under /home/user/uploads
    const walk = async (dir: string): Promise<string[]> => {
      const entries = await vfs.readdir(dir);
      const results: string[] = [];
      for (const entry of entries) {
        if (entry === ".keep") continue;
        const fullPath = `${dir}/${entry}`;
        try {
          const stat = await vfs.stat(fullPath);
          if (stat.isDirectory) {
            const nested = await walk(fullPath);
            results.push(...nested);
          } else if (stat.isFile) {
            results.push(fullPath);
          }
        } catch {
          // ignore
        }
      }
      return results;
    };

    const files = await walk("/home/user/uploads");
    return files.map((p) => p.replace("/home/user/uploads/", ""));
  } catch {
    return [];
  }
}

/**
 * Check if a file is empty (size === 0)
 */
export async function isFileEmpty(path: string): Promise<boolean> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  try {
    const stat = await vfs.stat(fullPath);
    return stat.isFile && stat.size === 0;
  } catch {
    return false;
  }
}

/**
 * Get file stats from VFS
 */
export async function getFileStat(path: string): Promise<{
  exists: boolean;
  isFile: boolean;
  size: number;
} | null> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  try {
    const stat = await vfs.stat(fullPath);
    return {
      exists: true,
      isFile: stat.isFile,
      size: stat.size,
    };
  } catch {
    return null;
  }
}

/**
 * Download a file from VFS to the user's computer
 * Creates a temporary anchor element with download attribute
 */
export async function downloadFile(
  path: string,
  filename?: string,
): Promise<void> {
  const vfs = getVfs();
  const fullPath = path.startsWith("/") ? path : `/home/user/uploads/${path}`;
  const data = await vfs.readFileBuffer(fullPath);

  // Determine MIME type from filename
  const actualFilename = filename || fullPath.split("/").pop() || "download";
  const { mimeType } = getFileType(actualFilename);

  // Create blob and download - copy data to ensure ArrayBuffer compatibility
  const dataCopy = new Uint8Array(data);
  const blob = new Blob([dataCopy], { type: mimeType });
  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");
  link.href = url;
  link.download = actualFilename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);

  URL.revokeObjectURL(url);
}

/**
 * Get file type (helper for determining if it's an image, etc.)
 */
export function getFileType(filename: string): {
  isImage: boolean;
  mimeType: string;
} {
  const ext = filename.toLowerCase().split(".").pop() || "";
  const imageExts: Record<string, string> = {
    png: "image/png",
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    gif: "image/gif",
    webp: "image/webp",
    svg: "image/svg+xml",
    bmp: "image/bmp",
    ico: "image/x-icon",
  };

  if (ext in imageExts) {
    return { isImage: true, mimeType: imageExts[ext] };
  }

  const mimeTypes: Record<string, string> = {
    txt: "text/plain",
    csv: "text/csv",
    json: "application/json",
    xml: "application/xml",
    html: "text/html",
    css: "text/css",
    js: "application/javascript",
    ts: "application/typescript",
    md: "text/markdown",
    pdf: "application/pdf",
  };

  return {
    isImage: false,
    mimeType: mimeTypes[ext] || "application/octet-stream",
  };
}

/**
 * Convert ArrayBuffer/Uint8Array to base64
 */
export function toBase64(data: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < data.length; i++) {
    binary += String.fromCharCode(data[i]);
  }
  return btoa(binary);
}
