/**
 * MCP connection form validation (Phase 3 of mcp-settings-ui-plan).
 *
 * Pure, UI-facing validation that mirrors the runtime contract in
 * `validation.ts` so the settings panel can show inline field errors
 * before the user clicks Save / Test. The runtime validator remains
 * the single source of truth at request time — this module is purely
 * advisory.
 *
 * The shape returned is keyed by form field name so the React
 * component can render errors next to each input without inferring
 * which diagnostic belongs where.
 */

import {
  parseEntraScopes,
  validateEntraAuthFields,
} from "./entra-auth-validation";
import type { MCPSecretScope, MCPTransportKind } from "./types";

/** Allowed transports for the form — mirrors `TRANSPORTS` in validation.ts. */
export const FORM_TRANSPORTS: readonly MCPTransportKind[] = [
  "streamable_http",
  "sse",
];

export const FORM_AUTH_TYPES = ["none", "bearer", "header", "entra"] as const;
export type FormAuthType = (typeof FORM_AUTH_TYPES)[number];

export const FORM_SECRET_SCOPES: readonly MCPSecretScope[] = [
  "session",
  "local",
];

export const ID_PATTERN = /^[a-z0-9][a-z0-9_-]{1,31}$/;
export const HEADER_NAME_PATTERN = /^[A-Za-z0-9-]{1,64}$/;
export const MIN_REQUEST_TIMEOUT_MS = 1000;
export const MAX_REQUEST_TIMEOUT_MS = 120000;
export const DEFAULT_REQUEST_TIMEOUT_MS = 30000;

/** Form-state shape the editor maintains while the user is typing. */
export interface MCPConnectionFormDraft {
  name: string;
  transport: MCPTransportKind;
  endpoint: string;
  enabled: boolean;
  requestTimeoutMs: number | "";
  authType: FormAuthType;
  /** Custom-header name when `authType === "header"`. */
  headerName: string;
  /** Storage scope used for the secret reference. */
  secretScope: MCPSecretScope;
  /** Plaintext secret typed into the editor; never persisted by the form layer. */
  bearerSecret: string;
  /** Plaintext header value typed into the editor; never persisted by the form layer. */
  headerSecret: string;
  /** Acknowledgement of the local-storage warning when `secretScope === "local"`. */
  localStorageConfirmed: boolean;
  entraTenantId: string;
  entraClientId: string;
  entraScopes: string;
  entraRedirectUri: string;
}

export interface MCPConnectionFormErrors {
  name?: string;
  endpoint?: string;
  requestTimeoutMs?: string;
  headerName?: string;
  bearerSecret?: string;
  headerSecret?: string;
  localStorageConfirmed?: string;
  entraTenantId?: string;
  entraClientId?: string;
  entraScopes?: string;
  entraRedirectUri?: string;
}

/** Build a blank form draft using the contract defaults. */
export function blankConnectionDraft(): MCPConnectionFormDraft {
  return {
    name: "",
    transport: "streamable_http",
    endpoint: "",
    enabled: true,
    requestTimeoutMs: DEFAULT_REQUEST_TIMEOUT_MS,
    authType: "none",
    headerName: "",
    secretScope: "session",
    bearerSecret: "",
    headerSecret: "",
    localStorageConfirmed: false,
    entraTenantId: "common",
    entraClientId: "",
    entraScopes: "",
    entraRedirectUri: "",
  };
}

/** Build the internal runtime connection ID from the user-facing name. */
export function deriveConnectionIdFromName(name: string): string {
  const asciiName = name
    .trim()
    .toLowerCase()
    .normalize("NFKD")
    .split("")
    .filter((char) => {
      const codePoint = char.charCodeAt(0);
      return codePoint < 0x0300 || codePoint > 0x036f;
    })
    .join("");
  const slug = asciiName
    .replace(/[^a-z0-9_-]+/g, "-")
    .replace(/[-_]{2,}/g, "-")
    .replace(/^[^a-z0-9]+/, "")
    .replace(/[^a-z0-9]+$/, "");

  return normalizeConnectionId(slug || "mcp");
}

/** Derive an ID and append a numeric suffix when the base is already taken. */
export function deriveUniqueConnectionIdFromName(
  name: string,
  existingIds: ReadonlySet<string> = new Set<string>(),
): string {
  const base = deriveConnectionIdFromName(name);
  if (!existingIds.has(base)) return base;

  for (let suffixNumber = 2; suffixNumber < 1000; suffixNumber += 1) {
    const suffix = `-${suffixNumber}`;
    const prefix = base
      .slice(0, Math.max(1, 32 - suffix.length))
      .replace(/[-_]+$/, "");
    const candidate = normalizeConnectionId(`${prefix}${suffix}`);
    if (!existingIds.has(candidate)) return candidate;
  }

  throw new Error("Unable to derive a unique MCP connection ID from the name.");
}

/**
 * Validate the in-flight form for the editor. The returned record only
 * contains entries for fields that currently fail validation; an empty
 * object means the form is ready to save / test.
 *
 * Connection IDs are derived from the name by the caller; users no
 * longer edit that field directly.
 */
export function validateConnectionDraft(
  draft: MCPConnectionFormDraft,
  options: {
    /** True when the user is editing an existing entry; the secret may already be in storage. */
    isEditing?: boolean;
    /** True when the secret reference already has a value in the chosen storage scope. */
    secretAlreadyStored?: boolean;
  } = {},
): MCPConnectionFormErrors {
  const errors: MCPConnectionFormErrors = {};

  // Name
  const nameTrimmed = draft.name.trim();
  if (!nameTrimmed) {
    errors.name = "Name is required.";
  } else if (nameTrimmed.length > 80) {
    errors.name = "Keep the name under 80 characters.";
  }

  // Endpoint — mirror runtime contract: absolute URL, https or http-on-localhost.
  const endpointError = validateEndpointString(draft.endpoint);
  if (endpointError) errors.endpoint = endpointError;

  // Timeout
  if (draft.requestTimeoutMs === "") {
    // empty is treated as "use default" — allowed.
  } else if (
    !Number.isInteger(draft.requestTimeoutMs) ||
    draft.requestTimeoutMs < MIN_REQUEST_TIMEOUT_MS ||
    draft.requestTimeoutMs > MAX_REQUEST_TIMEOUT_MS
  ) {
    errors.requestTimeoutMs = `Timeout must be an integer between ${MIN_REQUEST_TIMEOUT_MS} and ${MAX_REQUEST_TIMEOUT_MS} ms.`;
  }

  // Auth-specific checks
  if (draft.authType === "bearer") {
    if (
      !draft.bearerSecret &&
      !(options.isEditing && options.secretAlreadyStored)
    ) {
      errors.bearerSecret = "Bearer token is required.";
    }
  }
  if (draft.authType === "header") {
    const headerNameTrimmed = draft.headerName.trim();
    if (!headerNameTrimmed) {
      errors.headerName = "Header name is required.";
    } else if (!HEADER_NAME_PATTERN.test(headerNameTrimmed)) {
      errors.headerName = "Use 1–64 chars: letters, digits, or '-'.";
    }
    if (
      !draft.headerSecret &&
      !(options.isEditing && options.secretAlreadyStored)
    ) {
      errors.headerSecret = "Header value is required.";
    }
  }
  if (draft.authType === "entra") {
    const validation = validateEntraAuthFields(
      {
        tenantId: draft.entraTenantId,
        clientId: draft.entraClientId,
        scopes: parseEntraScopes(draft.entraScopes),
        redirectUri: draft.entraRedirectUri.trim() || undefined,
      },
      { requireSameOriginRedirect: true },
    );
    for (const diagnostic of validation.diagnostics) {
      if (diagnostic.field === "auth.tenantId") {
        errors.entraTenantId = diagnostic.message;
      } else if (diagnostic.field === "auth.clientId") {
        errors.entraClientId = diagnostic.message;
      } else if (diagnostic.field.startsWith("auth.scopes")) {
        errors.entraScopes = diagnostic.message;
      } else if (diagnostic.field === "auth.redirectUri") {
        errors.entraRedirectUri = diagnostic.message;
      }
    }
  }

  // Local-storage acknowledgement
  if (
    draft.authType !== "none" &&
    draft.authType !== "entra" &&
    draft.secretScope === "local" &&
    !draft.localStorageConfirmed
  ) {
    errors.localStorageConfirmed = "Confirm local storage to continue.";
  }

  return errors;
}

/** True when the draft has no field errors. */
export function isDraftValid(errors: MCPConnectionFormErrors): boolean {
  for (const _ in errors) {
    return false;
  }
  return true;
}

/**
 * Validate a JSON string used for sample-call arguments. Returns
 * `{ ok: true, value }` on success or `{ ok: false, error }` with a
 * human-readable error message.
 */
export function validateJsonArguments(
  source: string,
): { ok: true; value: Record<string, unknown> } | { ok: false; error: string } {
  const trimmed = source.trim();
  if (!trimmed) {
    return { ok: true, value: {} };
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(trimmed);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Invalid JSON syntax.";
    return { ok: false, error: message };
  }
  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    return {
      ok: false,
      error: 'Arguments must be a JSON object (e.g. {"q": "hello"}).',
    };
  }
  return { ok: true, value: parsed as Record<string, unknown> };
}

function validateEndpointString(value: string): string | undefined {
  const trimmed = value.trim();
  if (!trimmed) return "Endpoint URL is required.";
  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    return "Endpoint must be an absolute URL.";
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") {
    return "Endpoint must use http or https.";
  }
  if (
    url.protocol === "http:" &&
    url.hostname !== "localhost" &&
    url.hostname !== "127.0.0.1" &&
    url.hostname !== "[::1]"
  ) {
    return "Plain http is only allowed for localhost.";
  }
  return undefined;
}

function normalizeConnectionId(value: string): string {
  let candidate = value.slice(0, 32).replace(/[-_]+$/, "");
  if (!candidate) candidate = "mcp";
  if (candidate.length === 1) candidate = `${candidate}-mcp`;
  if (candidate.length > 32) candidate = candidate.slice(0, 32);
  if (ID_PATTERN.test(candidate)) return candidate;
  return "mcp";
}
