/**
 * Nudge reasons + canonical nudge user messages.
 *
 * PR-4A. Each nudge reason maps to a single user-message string appended
 * to {@link AgentRunState.ephemeralMessages}. Per blueprint §8 ephemeral
 * nudges are NOT persisted to {@link AgentState.messages}; they are merged
 * into the outbound message list at provider call time and cleared after
 * the next successful turn.
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §5 (decision rules), §8 (ephemerality)
 *   - docs/agent-refactor-implementation-plan.md PR-4A step 3.1, 3.3
 */

export type NudgeReason =
  | "content_filter_empty"
  | "empty_response"
  | "toolcall_parse_miss"
  | "length_truncated_tool_args"
  | "thinking_only"
  | "final_finalization_pass"
  | "planner_no_deliverable"
  | "action_without_tools"
  | "plan_schema_invalid";

/**
 * Per-reason retry ceilings (blueprint §5). When the ceiling is reached
 * the rule's terminal action becomes `finalize` (or, for
 * `final_finalization_pass`, the run is allowed to terminate normally).
 */
export const NUDGE_CEILINGS: Readonly<Record<NudgeReason, number>> = {
  content_filter_empty: 1,
  empty_response: 2,
  toolcall_parse_miss: 1,
  length_truncated_tool_args: 2,
  thinking_only: 3,
  final_finalization_pass: 1,
  planner_no_deliverable: 2,
  action_without_tools: 1,
  plan_schema_invalid: 2,
};

/**
 * Canonical user-message text for each nudge reason. These are appended to
 * {@link AgentRunState.ephemeralMessages} and shipped verbatim to the
 * provider on the next turn.
 */
const NUDGE_TEXTS: Readonly<Record<NudgeReason, string>> = {
  content_filter_empty:
    "The previous response was filtered with no content. Please try again with a safe rephrasing of the same answer.",
  empty_response:
    "The previous response was empty. Please respond again, calling the appropriate tools or providing the requested answer.",
  toolcall_parse_miss:
    "Your previous turn signaled a tool call but the arguments could not be parsed. Please re-issue the tool call with valid JSON arguments.",
  length_truncated_tool_args:
    "Your previous tool call was cut off because the response hit the max output-token limit, so its JSON arguments were truncated mid-stream and could not be applied. Re-issue the call with a smaller payload: split large writes into multiple smaller batches (e.g. ~25 rows at a time), trim per-cell text, or call the tool repeatedly with narrower ranges. Keep each tool call well under the token budget.",
  thinking_only:
    "Please continue the task by invoking the relevant tools.",
  final_finalization_pass:
    "Iteration budget reached. Use the existing tool results to finalize: run the final quality checks and provide the final answer. Additional tool calls are unnecessary unless one is required to avoid a factual error.",
  planner_no_deliverable:
    "The previous turn did not produce the requested deliverable. Please continue by invoking the relevant tools to complete the user's request.",
  action_without_tools:
    "Please complete the requested work using the available tools, then report concise results.",
  plan_schema_invalid:
    "The submitted plan failed schema validation. Please re-submit using the documented schema with all required fields.",
};

export function nudgeText(reason: NudgeReason): string {
  return NUDGE_TEXTS[reason];
}

export function nudgeCeiling(reason: NudgeReason): number {
  return NUDGE_CEILINGS[reason];
}
