import { Type, type Static } from "@sinclair/typebox";

const nullableNumber = Type.Union([Type.Number(), Type.Null()]);

export const wordAnchorSchema = Type.Object({
  paragraphIndex: Type.Optional(nullableNumber),
  scopeParagraphIndex: Type.Optional(nullableNumber),
  matchedParagraphIndex: Type.Optional(Type.Number()),
  occurrenceIndexInParagraph: Type.Optional(Type.Number()),
  startOffset: Type.Optional(Type.Number()),
  endOffset: Type.Optional(Type.Number()),
  startOffsetInParagraph: Type.Optional(Type.Number()),
  endOffsetInParagraph: Type.Optional(Type.Number()),
  textPreview: Type.Optional(Type.String()),
  paragraphPreview: Type.Optional(Type.String()),
  prefix: Type.Optional(Type.String()),
  quote: Type.Optional(Type.String()),
  suffix: Type.Optional(Type.String()),
});

export type WordAnchor = Static<typeof wordAnchorSchema>;

export function getAnchorDocumentParagraphIndex(
  anchor?: WordAnchor,
): number | null {
  if (!anchor) {
    return null;
  }

  return typeof anchor.paragraphIndex === "number" ? anchor.paragraphIndex : null;
}

export function getAnchorScopeParagraphIndex(anchor?: WordAnchor): number | null {
  if (!anchor) {
    return null;
  }

  if (typeof anchor.scopeParagraphIndex === "number") {
    return anchor.scopeParagraphIndex;
  }

  return typeof anchor.matchedParagraphIndex === "number"
    ? anchor.matchedParagraphIndex
    : null;
}

export function getAnchorOccurrenceIndex(anchor?: WordAnchor): number | null {
  if (!anchor) {
    return null;
  }

  return typeof anchor.occurrenceIndexInParagraph === "number"
    ? anchor.occurrenceIndexInParagraph
    : null;
}

export function hasMatchSpecificAnchor(anchor?: WordAnchor): boolean {
  return Boolean(
    anchor &&
      (getAnchorOccurrenceIndex(anchor) !== null ||
        anchor.startOffsetInParagraph !== undefined ||
        anchor.endOffsetInParagraph !== undefined ||
        Boolean(anchor.quote) ||
        Boolean(anchor.prefix) ||
        Boolean(anchor.suffix)),
  );
}

export function resolveDocumentParagraphIndexes(
  paragraphTexts: string[],
  documentParagraphTexts: string[],
): Array<number | null> {
  if (paragraphTexts.length === 0 || documentParagraphTexts.length === 0) {
    return paragraphTexts.map(() => null);
  }

  const contiguousStart = findContiguousParagraphSequence(
    paragraphTexts,
    documentParagraphTexts,
  );
  if (contiguousStart !== null) {
    return paragraphTexts.map((_, index) => contiguousStart + index);
  }

  const resolvedIndexes: Array<number | null> = [];
  let searchFrom = 0;

  for (const paragraphText of paragraphTexts) {
    let resolvedIndex: number | null = null;

    for (
      let candidateIndex = searchFrom;
      candidateIndex < documentParagraphTexts.length;
      candidateIndex++
    ) {
      if ((documentParagraphTexts[candidateIndex] ?? "") !== paragraphText) {
        continue;
      }

      resolvedIndex = candidateIndex;
      searchFrom = candidateIndex + 1;
      break;
    }

    resolvedIndexes.push(resolvedIndex);
  }

  return resolvedIndexes;
}

export function getResolvedDocumentParagraphRange(
  paragraphIndexes: Array<number | null> | undefined,
): {
  startParagraph: number | null;
  endParagraph: number | null;
  documentIndexed: boolean;
} {
  if (!paragraphIndexes || paragraphIndexes.length === 0) {
    return {
      startParagraph: null,
      endParagraph: null,
      documentIndexed: false,
    };
  }

  const resolvedIndexes = paragraphIndexes.filter(
    (paragraphIndex): paragraphIndex is number =>
      typeof paragraphIndex === "number",
  );

  if (resolvedIndexes.length !== paragraphIndexes.length) {
    return {
      startParagraph: null,
      endParagraph: null,
      documentIndexed: false,
    };
  }

  return {
    startParagraph: resolvedIndexes[0] ?? null,
    endParagraph: resolvedIndexes[resolvedIndexes.length - 1] ?? null,
    documentIndexed: true,
  };
}

export function anchorMatchesParagraphText(
  anchor: WordAnchor | undefined,
  paragraphText: string | undefined,
): boolean {
  if (!anchor) {
    return true;
  }

  const normalizedParagraph = normalizeComparableText(paragraphText ?? "");
  const checks: boolean[] = [];

  const textPreview = normalizeComparableText(anchor.textPreview ?? "");
  if (textPreview) {
    checks.push(normalizedParagraph.includes(textPreview));
  }

  const paragraphPreview = normalizeComparableText(anchor.paragraphPreview ?? "");
  if (paragraphPreview) {
    checks.push(normalizedParagraph.includes(paragraphPreview));
  }

  const quote = normalizeComparableText(anchor.quote ?? "");
  if (quote) {
    checks.push(normalizedParagraph.includes(quote));
  }

  const contextualQuoteMatch = matchesAnchorQuoteContext(
    normalizedParagraph,
    anchor,
  );
  if (contextualQuoteMatch !== null) {
    checks.push(contextualQuoteMatch);
  }

  return checks.length === 0 ? true : checks.every(Boolean);
}

export function findLiteralMatchOffsets(
  text: string,
  searchText: string,
  matchCase: boolean,
): number[] {
  if (!searchText) {
    return [0];
  }

  const haystack = matchCase ? text : text.toLocaleLowerCase();
  const needle = matchCase ? searchText : searchText.toLocaleLowerCase();
  const offsets: number[] = [];
  let searchFrom = 0;

  while (searchFrom <= haystack.length - needle.length) {
    const nextIndex = haystack.indexOf(needle, searchFrom);
    if (nextIndex === -1) {
      break;
    }

    offsets.push(nextIndex);
    searchFrom = nextIndex + Math.max(needle.length, 1);
  }

  return offsets;
}

function findContiguousParagraphSequence(
  paragraphTexts: string[],
  documentParagraphTexts: string[],
): number | null {
  if (paragraphTexts.length === 0) {
    return null;
  }

  outer: for (
    let startIndex = 0;
    startIndex <= documentParagraphTexts.length - paragraphTexts.length;
    startIndex++
  ) {
    for (let offset = 0; offset < paragraphTexts.length; offset++) {
      if ((documentParagraphTexts[startIndex + offset] ?? "") !== paragraphTexts[offset]) {
        continue outer;
      }
    }

    return startIndex;
  }

  return null;
}

function matchesAnchorQuoteContext(
  normalizedParagraph: string,
  anchor: WordAnchor,
): boolean | null {
  const quote = normalizeComparableText(anchor.quote ?? "");
  const prefix = normalizeComparableText(anchor.prefix ?? "");
  const suffix = normalizeComparableText(anchor.suffix ?? "");

  if (!quote || (!prefix && !suffix)) {
    return null;
  }

  const quoteIndex = normalizedParagraph.indexOf(quote);
  if (quoteIndex === -1) {
    return false;
  }

  if (prefix) {
    const beforeQuote = normalizedParagraph.substring(0, quoteIndex);
    if (!beforeQuote.includes(prefix)) {
      return false;
    }
  }

  if (suffix) {
    const afterQuote = normalizedParagraph.substring(quoteIndex + quote.length);
    if (!afterQuote.includes(suffix)) {
      return false;
    }
  }

  return true;
}

function normalizeComparableText(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}