// Simple sandbox implementation for air-gapped environments
// SES lockdown disabled for compatibility with buffer@6 and other polyfills

export function sandboxedEval(
  code: string,
  globals: Record<string, unknown>,
): unknown {
  // Create a sandboxed function with limited globals
  const fn = new Function(
    ...Object.keys(globals),
    `"use strict"; return (async () => { ${code} })();`,
  );
  return fn(...Object.values(globals));
}
