function formatTimestamp(iso: string | undefined): string {
  if (!iso) return "never";
  try {
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return "never";
    return date.toLocaleTimeString(undefined, {
      hour: "numeric",
      minute: "2-digit",
    });
  } catch {
    return "never";
  }
}

function shortenEndpoint(endpoint: string): string {
  try {
    const url = new URL(endpoint);
    return `${url.host}${url.pathname.replace(/\/$/, "")}`;
  } catch {
    return endpoint;
  }
}

function draftFromConnection(
  connection: UserMCPConnection,
): MCPConnectionFormDraft {
  const draft = blankConnectionDraft();
  draft.name = connection.label;
  draft.transport = connection.transport;
  draft.endpoint = connection.endpoint;
  draft.enabled = connection.enabled;
  draft.requestTimeoutMs = connection.requestTimeoutMs ?? "";
  if (connection.auth.type === "none") {
    draft.authType = "none";
  } else if (connection.auth.type === "bearer") {
    draft.authType = "bearer";
    draft.secretScope = connection.auth.tokenRef.scope;
    // localStorage already opted-in for existing local-scope refs
    draft.localStorageConfirmed = connection.auth.tokenRef.scope === "local";
  } else {
    if (connection.auth.type === "header") {
      draft.authType = "header";
      draft.headerName = connection.auth.headerName;
      draft.secretScope = connection.auth.headerValueRef.scope;
      draft.localStorageConfirmed =
        connection.auth.headerValueRef.scope === "local";
    } else {
      draft.authType = "entra";
      draft.entraTenantId = connection.auth.tenantId;
      draft.entraClientId = connection.auth.clientId;
      draft.entraScopes = connection.auth.scopes.join("\n");
      draft.entraRedirectUri = connection.auth.redirectUri ?? "";
    }
  }
  return draft;
}

function buildAuthFromDraft(
  draft: MCPConnectionFormDraft,
  connectionId: string,
): { auth: MCPAuthConfig; secretKey?: string } {
  if (draft.authType === "none") {
    return { auth: { type: "none" } };
  }
  if (draft.authType === "bearer") {
    const key = buildSecretKey(connectionId, "token");
    if (!key) {
      throw new Error("Unable to build secret key for the connection name.");
    }
    return {
      auth: {
        type: "bearer",
        tokenRef: { scope: draft.secretScope, key },
      },
      secretKey: key,
    };
  }
  if (draft.authType === "entra") {
    const clientId = draft.entraClientId.trim();
    const scopes = normalizeEntraScopes(parseEntraScopes(draft.entraScopes), {
      clientId,
    });
    const redirectUri = draft.entraRedirectUri.trim();
    return {
      auth: {
        type: "entra",
        tenantId: draft.entraTenantId.trim(),
        clientId,
        scopes,
        ...(redirectUri ? { redirectUri } : {}),
      },
    };
  }
  const key = buildSecretKey(connectionId, "header");
  if (!key) {
    throw new Error("Unable to build secret key for the connection name.");
  }
  return {
    auth: {
      type: "header",
      headerName: draft.headerName.trim(),
      headerValueRef: { scope: draft.secretScope, key },
    },
    secretKey: key,
  };
}

function persistConnection(
  draft: MCPConnectionFormDraft,
  options: { editingId?: string },
): { settings: UserMCPSettings; saved: UserMCPConnection } {
  const settings = loadUserMCPSettings();
  const previous = options.editingId
    ? settings.connections.find((c) => c.id === options.editingId)
    : undefined;
  const previousAuth = previous?.auth;
  const otherIds = deploymentMCPConnectionIds();
  for (const connection of settings.connections) {
    if (connection.id !== options.editingId) otherIds.add(connection.id);
  }
  const derivedId = deriveUniqueConnectionIdFromName(draft.name, otherIds);
  const built = buildAuthFromDraft(draft, derivedId);
  const requestTimeoutMs =
    typeof draft.requestTimeoutMs === "number"
      ? draft.requestTimeoutMs
      : undefined;
  const keepPreviousStatus =
    previous !== undefined &&
    previous.id === derivedId &&
    previous.transport === draft.transport &&
    previous.endpoint === draft.endpoint.trim() &&
    previous.enabled === draft.enabled &&
    previous.requestTimeoutMs === requestTimeoutMs &&
    authConfigEquals(previous.auth, built.auth);

  const next: UserMCPConnection = {
    id: derivedId,
    label: draft.name.trim(),
    transport: draft.transport,
    endpoint: draft.endpoint.trim(),
    enabled: draft.enabled,
    auth: built.auth,
    ...(requestTimeoutMs !== undefined ? { requestTimeoutMs } : {}),
    ...(keepPreviousStatus && previous?.lastTestedAt
      ? { lastTestedAt: previous.lastTestedAt }
      : {}),
    ...(keepPreviousStatus && previous?.lastStatus
      ? { lastStatus: previous.lastStatus }
      : {}),
    ...(keepPreviousStatus && previous?.lastToolCount !== undefined
      ? { lastToolCount: previous.lastToolCount }
      : {}),
  };

  const others = settings.connections.filter((c) => c.id !== options.editingId);
  others.push(next);

  const previousRef = previousAuth ? getSecretRef(previousAuth) : null;
  const nextRef = getSecretRef(built.auth);
  if (built.secretKey && nextRef) {
    const typedSecret =
      draft.authType === "bearer"
        ? draft.bearerSecret
        : draft.authType === "header"
          ? draft.headerSecret
          : "";
    if (typedSecret) {
      setSecret(draft.secretScope, built.secretKey, typedSecret);
      purgeStaleSecretScope(built.secretKey, draft.secretScope);
    } else if (
      previousAuth &&
      previousRef &&
      previousAuth.type === built.auth.type
    ) {
      const existingSecret = getSecret(previousRef.scope, previousRef.key);
      if (existingSecret) {
        setSecret(nextRef.scope, nextRef.key, existingSecret);
        purgeStaleSecretScope(nextRef.key, nextRef.scope);
      }
    }
  }

  if (previousAuth) {
    const shouldRemovePreviousSecret =
      !nextRef ||
      previousAuth.type !== built.auth.type ||
      !previousRef ||
      previousRef.scope !== nextRef.scope ||
      previousRef.key !== nextRef.key;
    if (shouldRemovePreviousSecret) {
      removeConnectionSecrets({ auth: previousAuth });
    }
  }

  const nextSettings: UserMCPSettings = { version: 1, connections: others };
  saveUserMCPSettings(nextSettings);
  return { settings: nextSettings, saved: next };
}

function authConfigEquals(a: MCPAuthConfig, b: MCPAuthConfig): boolean {
  if (a.type !== b.type) return false;
  if (a.type === "none" && b.type === "none") return true;
  if (a.type === "bearer" && b.type === "bearer") {
    return (
      a.tokenRef.scope === b.tokenRef.scope && a.tokenRef.key === b.tokenRef.key
    );
  }
  if (a.type === "header" && b.type === "header") {
    return (
      a.headerName === b.headerName &&
      a.headerValueRef.scope === b.headerValueRef.scope &&
      a.headerValueRef.key === b.headerValueRef.key
    );
  }
  if (a.type === "entra" && b.type === "entra") {
    return (
      a.tenantId === b.tenantId &&
      a.clientId === b.clientId &&
      a.redirectUri === b.redirectUri &&
      a.scopes.length === b.scopes.length &&
      a.scopes.every((scope, index) => scope === b.scopes[index])
    );
  }
  return false;
}

function canReuseStoredSecret(
  connection: UserMCPConnection,
  draft: MCPConnectionFormDraft,
): boolean {
  if (draft.authType === "none" || draft.authType === "entra") return false;
  if (connection.auth.type !== draft.authType) return false;
  return isSecretAlreadyStored(connection);
}

function deriveDraftConnectionId(
  draft: MCPConnectionFormDraft,
  connections: readonly UserMCPConnection[],
  editingId?: string | null,
): string {
  const otherIds = deploymentMCPConnectionIds();
  for (const connection of connections) {
    if (connection.id !== editingId) otherIds.add(connection.id);
  }
  return deriveUniqueConnectionIdFromName(draft.name || "draft", otherIds);
}

function deploymentMCPConnectionIds(): Set<string> {
  const ids = new Set<string>();
  const raw = getRuntimeConfigSync().mcp;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return ids;
  const connections = (raw as { connections?: unknown }).connections;
  if (!Array.isArray(connections)) return ids;
  for (const entry of connections) {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) continue;
    const id = (entry as { id?: unknown }).id;
    if (typeof id === "string") ids.add(id);
  }
  return ids;
}

function isSecretAlreadyStored(connection: UserMCPConnection): boolean {
  const ref = getSecretRef(connection.auth);
  if (!ref) return false;
  const value = getSecret(ref.scope, ref.key);
  return typeof value === "string" && value.length > 0;
}

function updateConnectionStatus(
  connectionId: string,
  patch: Partial<UserMCPConnection>,
): void {
  const settings = loadUserMCPSettings();
  const next: UserMCPSettings = {
    version: 1,
    connections: settings.connections.map((c) =>
      c.id === connectionId ? { ...c, ...patch } : c,
    ),
  };
  saveUserMCPSettings(next);
}

function deleteConnection(
  connectionId: string,
  options: { removeSecrets: boolean },
): UserMCPSettings {
  const settings = loadUserMCPSettings();
  const target = settings.connections.find((c) => c.id === connectionId);
  if (target && options.removeSecrets) {
    removeConnectionSecrets({ auth: target.auth });
  }
  const next: UserMCPSettings = {
    version: 1,
    connections: settings.connections.filter((c) => c.id !== connectionId),
  };
  saveUserMCPSettings(next);
  return next;
}

function readSampleArgs(toolName: string): string {
  if (typeof window === "undefined") return "{}";
  try {
    const stored = window.sessionStorage.getItem(
      SAMPLE_ARGS_STORAGE_PREFIX + toolName,
    );
    return stored ?? "{}";
  } catch {
    return "{}";
  }
}

function writeSampleArgs(toolName: string, value: string): void {
  if (typeof window === "undefined") return;
  try {
    window.sessionStorage.setItem(SAMPLE_ARGS_STORAGE_PREFIX + toolName, value);
  } catch {
    // Best-effort.
  }
}

function summarizeToolContent(content: ToolContent[]): string {
  if (content.length === 0) return "(no content returned)";
  return content
    .map((part) => {
      if (part.type === "text") return part.text;
      if (part.type === "image") {
        return `[image:${part.mimeType ?? "unknown"}] ${part.data.length} bytes`;
      }
      return `[${(part as { type: string }).type ?? "part"}]`;
    })
    .join("\n\n");
}

export function MCPConnectionsSection(): JSX.Element {
  const styles = useStyles();
  const { refreshAgent } = useChat();
  const [settings, setSettings] = useState<UserMCPSettings>(() =>
    loadUserMCPSettings(),
  );
  const [statusById, setStatusById] = useState<
    Record<string, ConnectionStatusInfo>
  >(() => {
    const initial: Record<string, ConnectionStatusInfo> = {};
    for (const conn of settings.connections) {
      initial[conn.id] = {
        status: conn.enabled ? (conn.lastStatus ?? "not_tested") : "disabled",
        testedAt: conn.lastTestedAt,
        toolCount: conn.lastToolCount,
      };
    }
    return initial;
  });
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [draft, setDraft] = useState<MCPConnectionFormDraft>(() =>
    blankConnectionDraft(),
  );
  const [editorTestResult, setEditorTestResult] =
    useState<TestConnectionResult | null>(null);
  const [editorTesting, setEditorTesting] = useState(false);
  const [showBearerSecret, setShowBearerSecret] = useState(false);
  const [showHeaderSecret, setShowHeaderSecret] = useState(false);
  const [pendingDeletion, setPendingDeletion] =
    useState<UserMCPConnection | null>(null);
  const [deletionRemoveSecrets, setDeletionRemoveSecrets] = useState(true);
  const [sampleTarget, setSampleTarget] = useState<{
    connection: UserMCPConnection;
    tool: DiscoveredToolPreview;
  } | null>(null);
  const [sampleArgsText, setSampleArgsText] = useState("{}");
  const [sampleArgsError, setSampleArgsError] = useState<string | null>(null);
  const [sampleResult, setSampleResult] = useState<SampleCallResult | null>(
    null,
  );
  const [sampleRunning, setSampleRunning] = useState(false);
  const [savedNote, setSavedNote] = useState<string>("");

  const service = useMemo(
    () =>
      new MCPSettingsService({
        sessionStorage:
          typeof window === "undefined" ? undefined : window.sessionStorage,
        localStorage:
          typeof window === "undefined" ? undefined : window.localStorage,
      }),
    [],
  );

  // Auto-clear save note
  useEffect(() => {
    if (!savedNote) return undefined;
    const t = setTimeout(() => setSavedNote(""), 3500);
    return () => clearTimeout(t);
  }, [savedNote]);

  const formErrors: MCPConnectionFormErrors = useMemo(() => {
    let secretAlreadyStored = false;
    if (editingId) {
      const existing = settings.connections.find((c) => c.id === editingId);
      if (existing) {
        secretAlreadyStored = canReuseStoredSecret(existing, draft);
      }
    }
    return validateConnectionDraft(draft, {
      isEditing: editingId !== null,
      secretAlreadyStored,
    });
  }, [draft, editingId, settings]);

  const formIsValid = isDraftValid(formErrors);

  const openEditor = useCallback((connection?: UserMCPConnection) => {
    if (connection) {
      setEditingId(connection.id);
      setDraft(draftFromConnection(connection));
    } else {
      setEditingId(null);
      setDraft(blankConnectionDraft());
    }
    setEditorTestResult(null);
    setShowBearerSecret(false);
    setShowHeaderSecret(false);
    setEditorOpen(true);
  }, []);

  const closeEditor = useCallback(() => {
    setEditorOpen(false);
    setEditingId(null);
    setDraft(blankConnectionDraft());
    setEditorTestResult(null);
  }, []);

  const updateDraft = useCallback((patch: Partial<MCPConnectionFormDraft>) => {
    setDraft((prev) => ({ ...prev, ...patch }));
    setEditorTestResult(null);
  }, []);

  const buildFormState = useCallback(
    (target: UserMCPConnection): MCPSettingsFormState => {
      // Editor uses the in-flight draft; saved-row tests pass `target` only.
      if (editorOpen && editingId === target.id) {
        const derivedId = deriveDraftConnectionId(
          draft,
          settings.connections,
          editingId,
        );
        return {
          connection: {
            ...target,
            id: derivedId,
            label: draft.name.trim() || "Draft MCP",
            transport: draft.transport,
            endpoint: draft.endpoint.trim(),
            enabled: draft.enabled,
            requestTimeoutMs:
              typeof draft.requestTimeoutMs === "number"
                ? draft.requestTimeoutMs
                : undefined,
            auth: synthesizeAuthForTest(draft, target.auth, derivedId),
          },
          bearerSecret:
            draft.authType === "bearer" && draft.bearerSecret
              ? draft.bearerSecret
              : undefined,
          headerSecret:
            draft.authType === "header" && draft.headerSecret
              ? draft.headerSecret
              : undefined,
        };
      }
      return { connection: target };
    },
    [draft, editingId, editorOpen, settings.connections],
  );

  const persistStatus = useCallback(
    (connectionId: string, info: ConnectionStatusInfo) => {
      setStatusById((prev) => ({ ...prev, [connectionId]: info }));
      updateConnectionStatus(connectionId, {
        lastTestedAt: info.testedAt,
        lastStatus: info.status,
        lastToolCount: info.toolCount,
      });
      setSettings(loadUserMCPSettings());
    },
    [],
  );

  const runTest = useCallback(
    async (connection: UserMCPConnection) => {
      setStatusById((prev) => ({
        ...prev,
        [connection.id]: { ...prev[connection.id], status: "testing" },
      }));
      const formState = buildFormState(connection);
      const result = await service.testConnection(formState);
      const info: ConnectionStatusInfo = {
        status: result.status === "invalid_config" ? "failed" : result.status,
        testedAt: result.testedAt,
        toolCount: result.toolCount,
        errorMessage: result.error?.message,
        errorCode: result.error?.code,
        tools: result.tools,
      };
      if (editorOpen && editingId === connection.id) {
        setEditorTestResult(result);
      }
      // Persist only when this maps to a real saved connection
      if (settings.connections.some((c) => c.id === connection.id)) {
        persistStatus(connection.id, info);
      } else {
        setStatusById((prev) => ({ ...prev, [connection.id]: info }));
      }
    },
    [buildFormState, editingId, editorOpen, persistStatus, service, settings],
  );

  const runEditorTest = useCallback(async () => {
    setEditorTestResult(null);
    setEditorTesting(true);
    try {
      const derivedId = deriveDraftConnectionId(
        draft,
        settings.connections,
        editingId,
      );
      const formState: MCPSettingsFormState = {
        connection: {
          id: derivedId,
          label: draft.name.trim() || "Draft MCP",
          transport: draft.transport,
          endpoint: draft.endpoint.trim(),
          enabled: draft.enabled,
          requestTimeoutMs:
            typeof draft.requestTimeoutMs === "number"
              ? draft.requestTimeoutMs
              : undefined,
          auth: synthesizeAuthForTest(draft, undefined, derivedId),
        },
        bearerSecret:
          draft.authType === "bearer" && draft.bearerSecret
            ? draft.bearerSecret
            : undefined,
        headerSecret:
          draft.authType === "header" && draft.headerSecret
            ? draft.headerSecret
            : undefined,
      };
      const result = await service.testConnection(formState);
      setEditorTestResult(result);
    } finally {
      setEditorTesting(false);
    }
  }, [draft, editingId, service, settings.connections]);

  const handleSave = useCallback(() => {
    if (!formIsValid) return;
    try {
      const { settings: nextSettings, saved } = persistConnection(draft, {
        editingId: editingId ?? undefined,
      });
      setSettings(nextSettings);
      // Carry editor test result into status row when present
      if (editorTestResult) {
        const info: ConnectionStatusInfo = {
          status:
            editorTestResult.status === "invalid_config"
              ? "failed"
              : editorTestResult.status,
          testedAt: editorTestResult.testedAt,
          toolCount: editorTestResult.toolCount,
          errorMessage: editorTestResult.error?.message,
          errorCode: editorTestResult.error?.code,
          tools: editorTestResult.tools,
        };
        persistStatus(saved.id, info);
      } else {
        setStatusById((prev) => ({
          ...prev,
          [saved.id]: prev[saved.id] ?? {
            status: saved.enabled ? "not_tested" : "disabled",
          },
        }));
      }
      setSavedNote("Saved. Applies on next message.");
      closeEditor();
      refreshAgent();
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Failed to save connection.";
      setEditorTestResult({
        status: "failed",
        testedAt: new Date().toISOString(),
        durationMs: 0,
        error: { code: "SAVE_FAILED", message, retryable: false },
      });
    }
  }, [
    closeEditor,
    draft,
    editingId,
    editorTestResult,
    formIsValid,
    persistStatus,
    refreshAgent,
  ]);

  const handleToggleEnabled = useCallback(
    (connection: UserMCPConnection, enabled: boolean) => {
      const next = settings.connections.map((c) =>
        c.id === connection.id ? { ...c, enabled } : c,
      );
      const nextSettings: UserMCPSettings = { version: 1, connections: next };
      saveUserMCPSettings(nextSettings);
      setSettings(nextSettings);
      setStatusById((prev) => ({
        ...prev,
        [connection.id]: enabled
          ? {
              ...prev[connection.id],
              status:
                prev[connection.id]?.status === "disabled"
                  ? "not_tested"
                  : (prev[connection.id]?.status ?? "not_tested"),
            }
          : { status: "disabled" },
      }));
      setSavedNote("Saved. Applies on next message.");
      refreshAgent();
    },
    [refreshAgent, settings],
  );

  const confirmDeletion = useCallback(() => {
    if (!pendingDeletion) return;
    const next = deleteConnection(pendingDeletion.id, {
      removeSecrets: deletionRemoveSecrets,
    });
    setSettings(next);
    setStatusById((prev) => {
      const copy = { ...prev };
      delete copy[pendingDeletion.id];
      return copy;
    });
    setPendingDeletion(null);
    setSavedNote("Connection deleted. Applies on next message.");
    refreshAgent();
  }, [deletionRemoveSecrets, pendingDeletion, refreshAgent]);

  const openSampleDialog = useCallback(
    (connection: UserMCPConnection, tool: DiscoveredToolPreview) => {
      setSampleTarget({ connection, tool });
      setSampleArgsText(readSampleArgs(tool.namespacedName));
      setSampleArgsError(null);
      setSampleResult(null);
    },
    [],
  );

  const closeSampleDialog = useCallback(() => {
    setSampleTarget(null);
    setSampleResult(null);
    setSampleArgsError(null);
  }, []);

  const runSampleCall = useCallback(async () => {
    if (!sampleTarget) return;
    const parsed = validateJsonArguments(sampleArgsText);
    if ("error" in parsed && parsed.error) {
      setSampleArgsError(parsed.error);
      return;
    }
    const args = "value" in parsed ? parsed.value : {};
    setSampleArgsError(null);
    writeSampleArgs(sampleTarget.tool.namespacedName, sampleArgsText);
    setSampleRunning(true);
    setSampleResult(null);
    try {
      const formState: MCPSettingsFormState = {
        connection: sampleTarget.connection,
      };
      const result = await service.callSampleTool(
        formState,
        sampleTarget.tool.remoteName,
        args,
      );
      setSampleResult(result);
    } finally {
      setSampleRunning(false);
    }
  }, [sampleArgsText, sampleTarget, service]);

  const renderRow = (connection: UserMCPConnection) => {
    const info = statusById[connection.id] ?? {
      status: connection.enabled ? "not_tested" : "disabled",
    };
    const status = info.status;
    return (
      <div key={connection.id} className={styles.row}>
        <div className={styles.rowHeader}>
          <div className={styles.rowMeta}>
            <span className={styles.rowLabel}>{connection.label}</span>
            <span className={styles.rowSubtitle}>
              {shortenEndpoint(connection.endpoint)}
            </span>
          </div>
          <div className={styles.rowActions}>
            <Tooltip
              content={connection.enabled ? "Disable" : "Enable"}
              relationship="label"
            >
              <Switch
                checked={connection.enabled}
                onChange={(_e, data) =>
                  handleToggleEnabled(connection, !!data.checked)
                }
              />
            </Tooltip>
            <Tooltip content="Test" relationship="label">
              <Button
                appearance="transparent"
                icon={<PlugConnectedRegular fontSize={14} />}
                onClick={() => void runTest(connection)}
                size="small"
                disabled={status === "testing"}
              />
            </Tooltip>
            <Tooltip content="Edit" relationship="label">
              <Button
                appearance="transparent"
                icon={<EditRegular fontSize={14} />}
                onClick={() => openEditor(connection)}
                size="small"
              />
            </Tooltip>
            <Tooltip content="Delete" relationship="label">
              <Button
                appearance="transparent"
                icon={<DeleteRegular fontSize={14} />}
                onClick={() => {
                  setPendingDeletion(connection);
                  setDeletionRemoveSecrets(true);
                }}
                size="small"
              />
            </Tooltip>
          </div>
        </div>
        <div className={styles.rowFooter}>
          <Badge appearance="outline" color={STATUS_TONE[status]} size="small">
            {STATUS_LABEL[status]}
          </Badge>
          <span>
            {connection.transport === "streamable_http" ? "HTTP" : "SSE"}
          </span>
          {info.toolCount !== undefined && status === "connected" && (
            <span>
              {info.toolCount} tool{info.toolCount === 1 ? "" : "s"}
            </span>
          )}
          <span>last: {formatTimestamp(info.testedAt)}</span>
          {info.errorMessage && (
            <span className={styles.errorText}>
              {info.errorCode ? `${info.errorCode}: ` : ""}
              {info.errorMessage}
            </span>
          )}
        </div>
        {status === "connected" && info.tools && info.tools.length > 0 && (
          <div className={styles.toolsBlock}>
            {info.tools.map((tool) => (
              <div key={tool.namespacedName} className={styles.toolItem}>
                <div className={styles.toolMeta}>
                  <span className={styles.toolName}>{tool.namespacedName}</span>
                  <span className={styles.toolDescription}>
                    {tool.description}
                  </span>
                </div>
                <Tooltip content="Sample call" relationship="label">
                  <Button
                    appearance="transparent"
                    icon={<PlayRegular fontSize={14} />}
                    onClick={() => openSampleDialog(connection, tool)}
                    size="small"
                  />
                </Tooltip>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className={styles.section}>
      <div className={styles.sectionTitle}>mcp connections</div>
      <Caption2 className={styles.helpText}>
        Configure remote MCP servers. Saved connections become available to the
        agent on the next message.
      </Caption2>

      {settings.connections.length > 0 ? (
        <div className={styles.list}>{settings.connections.map(renderRow)}</div>
      ) : (
        <div className={styles.emptyState}>No MCP connections configured</div>
      )}

      <div className={styles.buttonRow}>
        <Button
          appearance="outline"
          icon={<AddRegular fontSize={14} />}
          onClick={() => openEditor()}
          size="small"
          className={styles.flexOne}
        >
          Add connection
        </Button>
      </div>
      {savedNote && (
        <Caption2 className={styles.helpText}>{savedNote}</Caption2>
      )}

      {/* Editor dialog */}
      <Dialog
        open={editorOpen}
        onOpenChange={(_e, data) => {
          if (!data.open) closeEditor();
        }}
        modalType="modal"
      >
        <DialogSurface>
          <DialogBody>
            <DialogTitle>
              {editingId ? "Edit MCP connection" : "Add MCP connection"}
            </DialogTitle>
            <DialogContent>
              <ConnectionEditorForm
                draft={draft}
                errors={formErrors}
                isEditing={editingId !== null}
                showBearerSecret={showBearerSecret}
                showHeaderSecret={showHeaderSecret}
                onShowBearerSecret={setShowBearerSecret}
                onShowHeaderSecret={setShowHeaderSecret}
                onChange={updateDraft}
              />
              {editorTesting && (
                <div className={styles.spinnerRowWithMargin}>
                  <Spinner size="tiny" /> <Text size={200}>Testing…</Text>
                </div>
              )}
              {editorTestResult && !editorTesting && (
                <EditorTestResult result={editorTestResult} />
              )}
            </DialogContent>
            <DialogActions>
              <Button
                appearance="secondary"
                onClick={() => void runEditorTest()}
                disabled={editorTesting}
                icon={<PlugConnectedRegular fontSize={14} />}
              >
                Test connection
              </Button>
              <Button appearance="secondary" onClick={closeEditor}>
                Cancel
              </Button>
              <Button
                appearance="primary"
                onClick={handleSave}
                disabled={!formIsValid}
              >
                Save
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>

      {/* Delete confirmation */}
      <Dialog
        open={pendingDeletion !== null}
        onOpenChange={(_e, data) => {
          if (!data.open) setPendingDeletion(null);
        }}
        modalType="alert"
      >
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Delete connection</DialogTitle>
            <DialogContent>
              <Text>
                Remove “{pendingDeletion?.label}” from MCP connections?
              </Text>
              {pendingDeletion && getSecretRef(pendingDeletion.auth) && (
                <div className={styles.marginTopSmall}>
                  <Checkbox
                    checked={deletionRemoveSecrets}
                    onChange={(_e, data) =>
                      setDeletionRemoveSecrets(!!data.checked)
                    }
                    label="Also remove the stored secret for this connection"
                  />
                </div>
              )}
            </DialogContent>
            <DialogActions>
              <Button
                appearance="secondary"
                onClick={() => setPendingDeletion(null)}
              >
                Cancel
              </Button>
              <Button appearance="primary" onClick={confirmDeletion}>
                Delete
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>

      {/* Sample-call dialog */}
      <Dialog
        open={sampleTarget !== null}
        onOpenChange={(_e, data) => {
          if (!data.open) closeSampleDialog();
        }}
        modalType="modal"
      >
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Sample call</DialogTitle>
            <DialogContent>
              {sampleTarget && (
                <SampleCallEditor
                  tool={sampleTarget.tool}
                  argsText={sampleArgsText}
                  argsError={sampleArgsError}
                  onArgsChange={(value) => {
                    setSampleArgsText(value);
                    setSampleArgsError(null);
                  }}
                  result={sampleResult}
                  running={sampleRunning}
                />
              )}
            </DialogContent>
            <DialogActions>
              <Button appearance="secondary" onClick={closeSampleDialog}>
                Close
              </Button>
              <Button
                appearance="primary"
                onClick={() => void runSampleCall()}
                disabled={sampleRunning}
                icon={<PlayRegular fontSize={14} />}
              >
                {sampleRunning ? "Running…" : "Run"}
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>

      <Divider />
    </div>
  );
}

interface ConnectionEditorFormProps {
  draft: MCPConnectionFormDraft;
  errors: MCPConnectionFormErrors;
  isEditing: boolean;
  showBearerSecret: boolean;
  showHeaderSecret: boolean;
  onShowBearerSecret: (value: boolean) => void;
  onShowHeaderSecret: (value: boolean) => void;
  onChange: (patch: Partial<MCPConnectionFormDraft>) => void;
}

function ConnectionEditorForm({
  draft,
  errors,
  isEditing,
  showBearerSecret,
  showHeaderSecret,
  onShowBearerSecret,
  onShowHeaderSecret,
  onChange,
}: ConnectionEditorFormProps): JSX.Element {
  const styles = useStyles();
  return (
    <div className={styles.formGrid}>
      <Field
        label="Name"
        validationMessage={errors.name}
        validationState={errors.name ? "error" : undefined}
      >
        <Input
          value={draft.name}
          onChange={(e) => onChange({ name: e.target.value })}
          placeholder="Company Search"
          size="small"
        />
      </Field>

      <Field label="Transport">
        <div className={styles.toggleGroup}>
          <Button
            appearance={
              draft.transport === "streamable_http" ? "primary" : "outline"
            }
            onClick={() => onChange({ transport: "streamable_http" })}
            size="small"
            className={styles.flexOne}
          >
            Streamable HTTP
          </Button>
          <Button
            appearance={draft.transport === "sse" ? "primary" : "outline"}
            onClick={() => onChange({ transport: "sse" as MCPTransportKind })}
            size="small"
            className={styles.flexOne}
          >
            SSE
          </Button>
        </div>
      </Field>

      <Field
        label="Endpoint"
        validationMessage={errors.endpoint}
        validationState={errors.endpoint ? "error" : undefined}
      >
        <Input
          value={draft.endpoint}
          onChange={(e) => onChange({ endpoint: e.target.value })}
          placeholder="https://mcp.company.com/v1"
          size="small"
        />
      </Field>

      <Field
        label="Request timeout (ms)"
        validationMessage={errors.requestTimeoutMs}
        validationState={errors.requestTimeoutMs ? "error" : undefined}
      >
        <Input
          type="number"
          value={
            draft.requestTimeoutMs === "" ? "" : String(draft.requestTimeoutMs)
          }
          onChange={(e) => {
            const raw = e.target.value;
            if (raw === "") onChange({ requestTimeoutMs: "" });
            else {
              const n = Number(raw);
              onChange({ requestTimeoutMs: Number.isFinite(n) ? n : "" });
            }
          }}
          size="small"
        />
      </Field>

      <Field label="Authentication">
        <div className={styles.toggleGroup}>
          {(
            [
              "none",
              "bearer",
              "header",
              "entra",
            ] as const satisfies readonly FormAuthType[]
          ).map((type) => (
            <Button
              key={type}
              appearance={draft.authType === type ? "primary" : "outline"}
              onClick={() => onChange({ authType: type })}
              size="small"
              className={styles.flexOne}
            >
              {type === "none"
                ? "None"
                : type === "bearer"
                  ? "Bearer"
                  : type === "header"
                    ? "Header"
                    : "Entra ID"}
            </Button>
          ))}
        </div>
      </Field>

      {draft.authType === "bearer" && (
        <Field
          label="Bearer token"
          validationMessage={errors.bearerSecret}
          validationState={errors.bearerSecret ? "error" : undefined}
          hint={
            isEditing && !draft.bearerSecret
              ? "Leave blank to keep the existing token."
              : undefined
          }
        >
          <div className={styles.inputWithButton}>
            <Input
              type={showBearerSecret ? "text" : "password"}
              value={draft.bearerSecret}
              onChange={(e) => onChange({ bearerSecret: e.target.value })}
              placeholder="paste token"
              size="small"
              className={styles.flexOne}
            />
            <Button
              appearance="transparent"
              icon={
                showBearerSecret ? (
                  <EyeOffRegular fontSize={14} />
                ) : (
                  <EyeRegular fontSize={14} />
                )
              }
              onClick={() => onShowBearerSecret(!showBearerSecret)}
              size="small"
            />
          </div>
        </Field>
      )}

      {draft.authType === "header" && (
        <>
          <Field
            label="Header name"
            validationMessage={errors.headerName}
            validationState={errors.headerName ? "error" : undefined}
          >
            <Input
              value={draft.headerName}
              onChange={(e) => onChange({ headerName: e.target.value })}
              placeholder="X-Api-Key"
              size="small"
            />
          </Field>
          <Field
            label="Header value"
            validationMessage={errors.headerSecret}
            validationState={errors.headerSecret ? "error" : undefined}
            hint={
              isEditing && !draft.headerSecret
                ? "Leave blank to keep the existing secret."
                : undefined
            }
          >
            <div className={styles.inputWithButton}>
              <Input
                type={showHeaderSecret ? "text" : "password"}
                value={draft.headerSecret}
                onChange={(e) => onChange({ headerSecret: e.target.value })}
                placeholder="paste header value"
                size="small"
                className={styles.flexOne}
              />
              <Button
                appearance="transparent"
                icon={
                  showHeaderSecret ? (
                    <EyeOffRegular fontSize={14} />
                  ) : (
                    <EyeRegular fontSize={14} />
                  )
                }
                onClick={() => onShowHeaderSecret(!showHeaderSecret)}
                size="small"
              />
            </div>
          </Field>
        </>
      )}

      {draft.authType === "entra" && (
        <>
          <Field
            label="Tenant ID"
            validationMessage={errors.entraTenantId}
            validationState={errors.entraTenantId ? "error" : undefined}
          >
            <Input
              value={draft.entraTenantId}
              onChange={(e) => onChange({ entraTenantId: e.target.value })}
              placeholder="common or tenant GUID"
              size="small"
            />
          </Field>
          <Field
            label="Client ID"
            validationMessage={errors.entraClientId}
            validationState={errors.entraClientId ? "error" : undefined}
          >
            <Input
              value={draft.entraClientId}
              onChange={(e) => onChange({ entraClientId: e.target.value })}
              placeholder="add-in app registration GUID"
              size="small"
            />
          </Field>
          <Field
            label="MCP API scopes"
            validationMessage={errors.entraScopes}
            validationState={errors.entraScopes ? "error" : undefined}
            hint="Use the MCP server App ID URI or a full scope. App ID URIs use .default."
          >
            <Textarea
              value={draft.entraScopes}
              onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
                onChange({ entraScopes: e.target.value })
              }
              placeholder="api://{server-client-id}"
              resize="vertical"
            />
          </Field>
          <Field
            label="Redirect URI"
            validationMessage={errors.entraRedirectUri}
            validationState={errors.entraRedirectUri ? "error" : undefined}
            hint="Optional; defaults to this add-in's taskpane URL."
          >
            <Input
              value={draft.entraRedirectUri}
              onChange={(e) => onChange({ entraRedirectUri: e.target.value })}
              placeholder="https://localhost:3000/taskpane.html"
              size="small"
            />
          </Field>
        </>
      )}

      {draft.authType !== "none" && draft.authType !== "entra" && (
        <>
          <Field label="Secret storage">
            <div className={styles.toggleGroup}>
              <Button
                appearance={
                  draft.secretScope === "session" ? "primary" : "outline"
                }
                onClick={() =>
                  onChange({
                    secretScope: "session" as MCPSecretScope,
                    localStorageConfirmed: false,
                  })
                }
                size="small"
                className={styles.flexOne}
              >
                Session
              </Button>
              <Button
                appearance={
                  draft.secretScope === "local" ? "primary" : "outline"
                }
                onClick={() =>
                  onChange({ secretScope: "local" as MCPSecretScope })
                }
                size="small"
                className={styles.flexOne}
              >
                Local
              </Button>
            </div>
          </Field>
          {draft.secretScope === "local" && (
            <Field
              validationMessage={errors.localStorageConfirmed}
              validationState={
                errors.localStorageConfirmed ? "error" : undefined
              }
            >
              <Checkbox
                checked={draft.localStorageConfirmed}
                onChange={(_e, data) =>
                  onChange({ localStorageConfirmed: !!data.checked })
                }
                label={LOCAL_PERSISTENCE_WARNING}
              />
            </Field>
          )}
        </>
      )}

      <Field label="Enabled">
        <Switch
          checked={draft.enabled}
          onChange={(_e, data) => onChange({ enabled: !!data.checked })}
        />
      </Field>
    </div>
  );
}

function EditorTestResult({
  result,
}: {
  result: TestConnectionResult;
}): JSX.Element {
  const styles = useStyles();
  if (result.status === "connected") {
    return (
      <div className={`${styles.toolsBlock} ${styles.marginTopSmall}`}>
        <Text size={200} weight="medium">
          Connected — {result.toolCount ?? result.tools?.length ?? 0} tool(s)
        </Text>
        {result.tools?.map((tool) => (
          <div key={tool.namespacedName} className={styles.toolItem}>
            <div className={styles.toolMeta}>
              <span className={styles.toolName}>{tool.namespacedName}</span>
              <span className={styles.toolDescription}>{tool.description}</span>
            </div>
          </div>
        ))}
      </div>
    );
  }

  if (result.status === "disabled") {
    return (
      <Text size={200} className={styles.marginTopSmall}>
        Connection is disabled.
      </Text>
    );
  }

  return (
    <div className={`${styles.errorText} ${styles.marginTopSmall}`}>
      {result.error?.code ? `${result.error.code}: ` : ""}
      {result.error?.message ?? "Test failed."}
    </div>
  );
}

interface SampleCallEditorProps {
  tool: DiscoveredToolPreview;
  argsText: string;
  argsError: string | null;
  onArgsChange: (value: string) => void;
  result: SampleCallResult | null;
  running: boolean;
}

function SampleCallEditor({
  tool,
  argsText,
  argsError,
  onArgsChange,
  result,
  running,
}: SampleCallEditorProps): JSX.Element {
  const styles = useStyles();
  return (
    <div className={styles.formGrid}>
      <div>
        <Label size="small">Tool</Label>
        <div className={styles.toolName}>{tool.namespacedName}</div>
        <div className={styles.toolDescription}>{tool.description}</div>
      </div>
      <Field
        label="JSON arguments"
        validationMessage={argsError ?? undefined}
        validationState={argsError ? "error" : undefined}
      >
        <Textarea
          value={argsText}
          onChange={(e: ChangeEvent<HTMLTextAreaElement>) =>
            onArgsChange(e.target.value)
          }
          className={styles.jsonInput}
          textarea={{ className: styles.jsonInput }}
          resize="vertical"
        />
      </Field>
      {running && (
        <div className={styles.spinnerRow}>
          <Spinner size="tiny" /> <Text size={200}>Calling tool…</Text>
        </div>
      )}
      {result && !running && <SampleResultRenderer result={result} />}
    </div>
  );
}

function SampleResultRenderer({
  result,
}: {
  result: SampleCallResult;
}): JSX.Element {
  const styles = useStyles();
  if (result.kind === "success") {
    const text = summarizeToolContent(result.content);
    const images = result.content.filter((c) => c.type === "image");
    return (
      <div>
        <Text size={200} weight="medium">
          Success ({result.durationMs} ms)
        </Text>
        <div className={styles.resultBlock}>{text}</div>
        {images.map((img) =>
          img.type === "image" ? (
            <img
              key={`${img.mimeType ?? "image"}-${img.data.slice(0, 32)}`}
              alt="MCP result"
              src={`data:${img.mimeType ?? "image/png"};base64,${img.data}`}
              className={styles.resultImage}
            />
          ) : null,
        )}
      </div>
    );
  }
  return (
    <div className={styles.errorText}>
      {result.error.code}: {result.error.message}
    </div>
  );
}

function synthesizeAuthForTest(
  draft: MCPConnectionFormDraft,
  fallback: MCPAuthConfig | undefined,
  connectionId: string,
): MCPAuthConfig {
  if (draft.authType === "none") return { type: "none" };
  if (draft.authType === "bearer") {
    const fallbackKey =
      fallback?.type === "bearer" ? fallback.tokenRef.key : undefined;
    const key =
      buildSecretKey(connectionId, "token") ??
      fallbackKey ??
      "officeai-mcp-draft-token";
    return {
      type: "bearer",
      tokenRef: { scope: draft.secretScope, key },
    };
  }
  if (draft.authType === "entra") {
    const clientId = draft.entraClientId.trim();
    const redirectUri = draft.entraRedirectUri.trim();
    return {
      type: "entra",
      tenantId: draft.entraTenantId.trim(),
      clientId,
      scopes: normalizeEntraScopes(parseEntraScopes(draft.entraScopes), {
        clientId,
      }),
      ...(redirectUri ? { redirectUri } : {}),
    };
  }
  const fallbackKey =
    fallback?.type === "header" ? fallback.headerValueRef.key : undefined;
  const key =
    buildSecretKey(connectionId, "header") ??
    fallbackKey ??
    "officeai-mcp-draft-header";
  return {
    type: "header",
    headerName: draft.headerName.trim() || "X-Api-Key",
    headerValueRef: { scope: draft.secretScope, key },
  };
}
