/**
 * Planner prompt builders (PR-10a).
 *
 * Pure builders extracted from `agent.ts` per
 * docs/post-pr7-cleanup-plan.md §PR-10a. The functions return the exact
 * same prose the orchestrator was inlining before the extraction; the
 * only behavioral change is that all `this.` access has been replaced by
 * an explicit `PlannerPromptContext`. Snapshot tests in
 * `tests/agent/planner/prompts.test.ts` pin the output byte-for-byte so
 * any future drift is reviewable in a diff.
 *
 * The orchestrator now owns nothing about how planner prompts are
 * composed beyond calling these two functions.
 */

/**
 * Per-call inputs the orchestrator must supply. Captures every piece of
 * agent state the legacy `this.`-bound prompt builders read so the
 * extracted functions stay pure.
 */
export interface PlannerPromptContext {
  /**
   * Pre-formatted structured-plan checklist text from the most recent
   * successful `submit_plan` call (PR-6 §6.3). When non-null, takes
   * precedence over the prose phases — the structured composer is used
   * instead of the prose builder. Pass `null` to force the prose path.
   */
  cachedStructuredPlanText: string | null;

  /**
   * Predicate used to decide whether the prompt may reference the
   * `write_progress` VFS run-log workflow. The orchestrator sources this
   * from `internalState.tools` so MCP-disabled tools and turn-scoped
   * filtering are honoured automatically.
   */
  hasToolNamed: (toolName: string) => boolean;
}

/**
 * Optional per-iteration tuning the orchestrator computes from FSM
 * state before each planner directive injection.
 */
export interface PlannerExecutionPromptOptions {
  complexMode?: boolean;
  forceCompaction?: boolean;
  executedToolCalls?: number;
}

/**
 * Build the planner prompt the orchestrator injects as a synthetic
 * user message at the top of each planner-mode turn.
 *
 * Behaviour-preserving extraction of the legacy
 * `Agent.buildPlannerExecutionPrompt`. When a structured plan is
 * cached, delegates to {@link composeStructuredPlannerInstruction};
 * otherwise emits the prose phases (planner / continuation, optionally
 * with the complex-workflow QC + bookkeeping rules).
 */
export function buildPlannerExecutionPrompt(
  ctx: PlannerPromptContext,
  hasExecutedToolsInRun: boolean,
  options?: PlannerExecutionPromptOptions,
): string {
  const complexMode = options?.complexMode ?? false;
  const forceCompaction = options?.forceCompaction ?? false;
  const executedToolCalls = options?.executedToolCalls ?? 0;

  // PR-6 §6.3: when a structured plan was successfully submitted before
  // the loop started, prefer it over the prose phases. The plan text is
  // a deterministic checklist; the prose execution-discipline footer is
  // still appended so deliverable gating, bookkeeping rules, and
  // QC-before-finalize rules remain consistent across both paths.
  if (ctx.cachedStructuredPlanText) {
    return composeStructuredPlannerInstruction(
      ctx,
      ctx.cachedStructuredPlanText,
      hasExecutedToolsInRun,
      { complexMode, forceCompaction, executedToolCalls },
    );
  }

  if (complexMode) {
    const canUseVfsProgressFile =
      ctx.hasToolNamed("write_progress") && ctx.hasToolNamed("read");
    const progressFileInstructions = canUseVfsProgressFile
      ? "Context freshness + compaction (required): Use write_progress to maintain a markdown run log.\n- During PLAN phase: create/update this markdown with sections: Objective, Assumptions, Plan Checklist, Evidence Log, Open Risks, Quality Checks.\n- During EXECUTION phase: update checklist and evidence after meaningful progress.\n- During QUALITY CHECK phase: write pass/fail checks and remediation if needed.\n- Only rewrite this file when content materially changes; avoid redundant read/write loops.\n- When context grows, compact by writing a concise snapshot to this file and continue from the snapshot instead of repeating verbose history."
      : "Context freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history.";

    const compactionInstruction = forceCompaction
      ? "Compaction checkpoint: perform a compaction update now before further execution."
      : "";

    const progressBookkeepingDoesNotCountRule = `IMPORTANT - Bookkeeping does NOT satisfy EXECUTION: Writing/updating the run log, any "wiki", "log", "task", "plan", or "notes" markdown file, or any other progress/bookkeeping file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable (e.g., reading source data, transforming it, and writing it to the workbook/sheet/document the user asked for). In every iteration where you have not yet performed at least one such deliverable-producing tool call, you must call one before writing or updating any progress/bookkeeping file. Never end a turn after only writing bookkeeping files when the user's deliverable is incomplete.`;

    if (!hasExecutedToolsInRun) {
      return `Planner mode (complex workload): follow the three phases below to complete the request.\nPhase 1 - PLAN: create a short actionable checklist tied to the user request.\nPhase 2 - EXECUTION: begin executing the checklist items using the available tools.\nPhase 3 - QUALITY CHECK: before the final answer, verify outcomes against requirements and run at least one concrete validation/read-back step.\n${progressFileInstructions}\n${progressBookkeepingDoesNotCountRule}\n${compactionInstruction}\nAfter producing the plan, please continue by invoking the relevant tools. Additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.`;
    }

    return `Planner mode (complex workload): continue execution until complete, then run QUALITY CHECK before the final answer.\nExecution status: ${executedToolCalls} tool call(s) executed in this run.\nIf prior planner state is missing, reconstruct the remaining steps from tool results, conversation history, and workspace state.\nRequired QUALITY CHECK before the final answer:\n- Confirm each user requirement is satisfied.\n- Run concrete verification using available tools (for example read-back, search, or inspection).\n- Report residual risk or gaps explicitly.\n${progressFileInstructions}\n${progressBookkeepingDoesNotCountRule}\n${compactionInstruction}\nPrior checklists or planner output do not need to be re-shared. Provide the final answer once execution and quality checks are complete.`;
  }

  if (!hasExecutedToolsInRun) {
    return "Planner mode: create a short execution plan from the current request and available conversation context, then invoke the required tools to carry it out. If any prior checklist is missing, infer the next best steps from the repo/files and continue execution. After producing the plan, please continue by invoking the relevant tools; additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.";
  }
  return "Planner mode: continue executing the remaining tool steps until complete. If prior planner state is missing, reconstruct the remaining steps from tool results, conversation history, and the current workspace state, then keep executing. Prior checklists or planner output do not need to be re-shared. Provide the final answer once tool execution is complete.";
}

/**
 * Compose the structured-plan variant of the planner instruction.
 *
 * Behaviour-preserving extraction of the legacy
 * `Agent.composeStructuredPlannerInstruction`. The structured plan
 * checklist (already formatted by `formatPlanAsChecklist`) is wrapped
 * with the same QC/bookkeeping/progress-file footers the prose path
 * uses, so the two surfaces stay interchangeable from the model's
 * perspective.
 */
export function composeStructuredPlannerInstruction(
  ctx: PlannerPromptContext,
  structuredPlanText: string,
  hasExecutedToolsInRun: boolean,
  options: {
    complexMode: boolean;
    forceCompaction: boolean;
    executedToolCalls: number;
  },
): string {
  const compactionInstruction = options.forceCompaction
    ? "\nCompaction checkpoint: perform a compaction update now before further execution."
    : "";

  const canUseVfsProgressFile =
    ctx.hasToolNamed("write_progress") && ctx.hasToolNamed("read");
  const progressFileInstructions = options.complexMode
    ? canUseVfsProgressFile
      ? "\nContext freshness + compaction (required): Use write_progress to maintain a markdown run log. Update it after meaningful progress and compact verbose history into a snapshot when context grows."
      : "\nContext freshness + compaction: compact prior findings into concise summaries and continue from the compacted summary instead of repeating verbose history."
    : "";

  const bookkeepingRule = options.complexMode
    ? `\nIMPORTANT - Bookkeeping does NOT satisfy EXECUTION: writing or updating any progress/wiki/log/checklist file does NOT count as completing an EXECUTION step. EXECUTION means invoking the tools that produce the user-visible deliverable. Never end a turn after only writing bookkeeping files when the user's deliverable is incomplete.`
    : "";

  const qcRule = options.complexMode
    ? `\nQUALITY CHECK before final answer: confirm each user requirement is satisfied, run concrete verification using available tools (read-back, search, or inspection), and report residual risk or gaps explicitly.`
    : "";

  const continuationFooter = hasExecutedToolsInRun
    ? `\nExecution status: ${options.executedToolCalls} tool call(s) executed in this run. Please continue executing the remaining steps. Provide the final answer once all steps and quality checks are complete.`
    : "\nPlease carry out the steps above using the available tools. After producing the plan, continue by invoking the relevant tools; additional user confirmation is unnecessary, and prior planner output does not need to be re-shared.";

  return `Planner mode (structured plan):\n${structuredPlanText}${continuationFooter}${qcRule}${progressFileInstructions}${bookkeepingRule}${compactionInstruction}`;
}
