/**
 * MCP tool adapter (PR-3B.1).
 *
 * Maps remote MCP tool descriptors into internal {@link Tool} records
 * with namespaced names per docs/mcp-connection-contract.md §4 and
 * docs/agent-refactor-blueprint.md §4.2.
 *
 * Default metadata for every adapted MCP tool is `category: "read"`,
 * `parallelSafe: false`, `origin: "mcp"`. Server-advertised hints are
 * advisory only and MUST NOT upgrade `category` or `parallelSafe`.
 *
 * Note on suffix hash: blueprint §4.2 specifies sha256 + base32-lower.
 * PR-3B.1 uses a deterministic 32-bit FNV-1a hash encoded in
 * base32-lower for the truncation suffix to keep the adapter
 * synchronous (Web Crypto digest is async). The suffix is a
 * disambiguator for over-length names, not a security primitive;
 * collision resistance at 30 bits is adequate for the per-connection
 * adaptation set. PR-3B.2 may revisit if the catalog grows large.
 */

import type { MCPInvocationClient } from "./client";
import type { MCPRemoteToolDescriptor } from "./types";
import type { Tool, ToolResult } from "../types";

const NAMESPACE_PREFIX = "mcp__";
const NAME_MAX_LEN = 64;
const NAME_PATTERN = /^[a-zA-Z0-9_-]{1,64}$/;
const SAFE_CHAR = /[^a-zA-Z0-9_-]/g;
const SUFFIX_LEN = 6;
/** Base32 alphabet (lowercase, RFC 4648 without padding). */
const BASE32_ALPHABET = "abcdefghijklmnopqrstuvwxyz234567";

/** Sanitize a single name segment per contract §4. */
export function sanitizeNameSegment(segment: string): string {
  return segment.replace(SAFE_CHAR, "-");
}

/** FNV-1a 32-bit hash of a UTF-16 string (sufficient for §4.2 disambiguation). */
function fnv1a32(input: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i) & 0xff;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

/** 30 bits of `value` rendered as 6 base32-lower chars. */
function toBase32Lower6(value: number): string {
  let result = "";
  let v = value >>> 0;
  for (let i = 0; i < SUFFIX_LEN; i++) {
    result = BASE32_ALPHABET[v & 0x1f] + result;
    v >>>= 5;
  }
  return result;
}

/**
 * Build a namespaced tool name from a connection id and remote tool name.
 *
 * Returns `null` if the connection id segment alone (with the prefix and
 * separator) already exceeds the length budget — the connection id is
 * never truncated per blueprint §4.2.
 */
export function buildNamespacedToolName(
  connectionId: string,
  remoteToolName: string,
): string | null {
  const idSeg = sanitizeNameSegment(connectionId);
  const remoteSeg = sanitizeNameSegment(remoteToolName);
  const fixed = `${NAMESPACE_PREFIX}${idSeg}__`;

  // Connection id segment is never truncated.
  if (fixed.length >= NAME_MAX_LEN) {
    return null;
  }

  const naive = `${fixed}${remoteSeg}`;
  if (naive.length <= NAME_MAX_LEN && NAME_PATTERN.test(naive)) {
    return naive;
  }

  // Truncate remote segment and append a deterministic 6-char suffix
  // hash of the original full name.
  const fullOriginal = `${NAMESPACE_PREFIX}${connectionId}__${remoteToolName}`;
  const suffix = toBase32Lower6(fnv1a32(fullOriginal));
  const remoteBudget = NAME_MAX_LEN - fixed.length - SUFFIX_LEN;
  if (remoteBudget < 1) {
    return null;
  }
  const truncated = remoteSeg.slice(0, remoteBudget);
  const candidate = `${fixed}${truncated}${suffix}`;
  return NAME_PATTERN.test(candidate) ? candidate : null;
}

/** Sanitize a description for prompt-safety (plain text + size limit). */
export function sanitizeToolDescription(
  raw: string | undefined,
  remoteToolName: string,
  serverLabel: string,
): string {
  const fallback = `MCP tool ${remoteToolName} from ${serverLabel}`;
  if (!raw) return fallback;
  const stripped = raw
    .replace(/[\u0000-\u001f\u007f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!stripped) return fallback;
  return stripped.length > 1024 ? `${stripped.slice(0, 1021)}...` : stripped;
}

export interface AdaptedMCPTool {
  tool: Tool;
  /** Original remote tool name (pre-namespacing). */
  remoteToolName: string;
}

export interface AdaptMCPToolOptions {
  connectionId: string;
  serverLabel: string;
  client: MCPInvocationClient;
}

/**
 * Adapt a single remote MCP tool descriptor into an internal Tool.
 * Returns `null` when namespacing fails (see {@link buildNamespacedToolName}).
 */
export function adaptMCPTool(
  descriptor: MCPRemoteToolDescriptor,
  options: AdaptMCPToolOptions,
): AdaptedMCPTool | null {
  const namespaced = buildNamespacedToolName(
    options.connectionId,
    descriptor.name,
  );
  if (!namespaced) return null;

  const description = sanitizeToolDescription(
    descriptor.description,
    descriptor.name,
    options.serverLabel,
  );

  const tool: Tool = {
    name: namespaced,
    label: `${options.serverLabel}: ${descriptor.name}`,
    description,
    parameters:
      descriptor.inputSchema &&
      typeof descriptor.inputSchema === "object" &&
      !Array.isArray(descriptor.inputSchema)
        ? descriptor.inputSchema
        : { type: "object", properties: {}, additionalProperties: true },
    category: "read",
    parallelSafe: false,
    origin: "mcp",
    mcpRef: {
      connectionId: options.connectionId,
      serverLabel: options.serverLabel,
      remoteToolName: descriptor.name,
    },
    execute: async (
      _toolCallId: string,
      params: Record<string, unknown>,
      signal?: AbortSignal,
    ): Promise<ToolResult> => {
      return options.client.callTool({
        connectionId: options.connectionId,
        remoteToolName: descriptor.name,
        arguments: params,
        signal,
      });
    },
  };

  return { tool, remoteToolName: descriptor.name };
}
