/**
 * Per-(connectionId, toolName) run-scoped circuit breaker (PR-3B.3).
 *
 * Tracks consecutive `MCP_TOOL_INVOCATION_FAILED` results for a
 * specific MCP tool. Once the failure count meets the configured
 * threshold (default 5; runtime-configurable), that tool is marked
 * unavailable for the remainder of the run. The breaker is per-tool,
 * not per-connection — sibling tools on the same connection remain
 * callable.
 *
 * `MCP_TOOL_TIMEOUT` and `MCP_TOOL_ABORTED` do NOT count toward the
 * threshold (they are user/orchestrator-initiated, not failures
 * attributable to the tool itself).
 *
 * Breaker state is run-scoped: callers MUST invoke {@link reset} at run
 * end so the next run starts with all tools callable again. Each
 * reset emits a matching `mcp_tool_circuit_reset` event so dashboards
 * can pair open/close events.
 *
 * See docs/agent-refactor-blueprint.md §4.1 (point 8) and
 * docs/agent-refactor-implementation-plan.md §2.5.10c.
 */

export const DEFAULT_CIRCUIT_BREAKER_THRESHOLD = 5;

export type MCPToolFailureCode =
  | "MCP_TOOL_INVOCATION_FAILED"
  | "MCP_TOOL_TIMEOUT"
  | "MCP_TOOL_ABORTED"
  | "MCP_TOOL_NOT_FOUND"
  | "MCP_RESPONSE_INVALID"
  | "MCP_CONNECTION_UNAUTHORIZED"
  | "MCP_CONNECTION_UNAVAILABLE";

/** Codes that count toward the consecutive-failure threshold. */
const COUNTABLE_FAILURE_CODES = new Set<MCPToolFailureCode>([
  "MCP_TOOL_INVOCATION_FAILED",
]);

export interface MCPCircuitBreakerOptions {
  /** Failure threshold; defaults to {@link DEFAULT_CIRCUIT_BREAKER_THRESHOLD}. */
  threshold?: number;
}

export interface MCPCircuitOpenEvent {
  connectionId: string;
  toolName: string;
  failureCount: number;
}

export interface MCPCircuitResetEvent {
  connectionId: string;
  toolName: string;
}

interface BreakerEntry {
  failures: number;
  open: boolean;
}

function keyFor(connectionId: string, toolName: string): string {
  return `${connectionId}\u0000${toolName}`;
}

export class MCPCircuitBreaker {
  private readonly threshold: number;
  private readonly entries = new Map<string, BreakerEntry>();

  constructor(options: MCPCircuitBreakerOptions = {}) {
    const raw = options.threshold ?? DEFAULT_CIRCUIT_BREAKER_THRESHOLD;
    this.threshold = Math.max(1, Math.floor(raw));
  }

  /** Returns true if the (connectionId, toolName) pair is open (unavailable). */
  isOpen(connectionId: string, toolName: string): boolean {
    return this.entries.get(keyFor(connectionId, toolName))?.open === true;
  }

  /**
   * Record a tool result. Returns a `MCPCircuitOpenEvent` only on the
   * transition that actually opens the breaker (so callers can emit
   * telemetry exactly once and surface the one-shot ephemeral note).
   *
   * Codes outside {@link COUNTABLE_FAILURE_CODES} (TIMEOUT, ABORTED,
   * etc.) are ignored: they neither increment nor reset the counter.
   * A successful invocation resets the consecutive-failure counter for
   * that pair (without touching the open flag — once open, only
   * {@link reset} restores availability).
   */
  recordResult(
    connectionId: string,
    toolName: string,
    outcome: "success" | MCPToolFailureCode,
  ): MCPCircuitOpenEvent | null {
    const key = keyFor(connectionId, toolName);
    const entry = this.entries.get(key) ?? { failures: 0, open: false };

    if (outcome === "success") {
      entry.failures = 0;
      this.entries.set(key, entry);
      return null;
    }

    if (!COUNTABLE_FAILURE_CODES.has(outcome)) {
      this.entries.set(key, entry);
      return null;
    }

    entry.failures += 1;
    if (!entry.open && entry.failures >= this.threshold) {
      entry.open = true;
      this.entries.set(key, entry);
      return {
        connectionId,
        toolName,
        failureCount: entry.failures,
      };
    }

    this.entries.set(key, entry);
    return null;
  }

  /**
   * Drop all breaker state and return one reset event per pair that
   * was open at the time of reset. Callers SHOULD emit
   * `mcp_tool_circuit_reset` telemetry for each returned event so the
   * open/close pairs match in dashboards.
   */
  reset(): MCPCircuitResetEvent[] {
    const events: MCPCircuitResetEvent[] = [];
    for (const [key, entry] of this.entries) {
      if (entry.open) {
        const sep = key.indexOf("\u0000");
        events.push({
          connectionId: key.slice(0, sep),
          toolName: key.slice(sep + 1),
        });
      }
    }
    this.entries.clear();
    return events;
  }
}
