/**
 * MCP settings service (Phase 2 of mcp-settings-ui-plan).
 *
 * UI-facing wrapper around the existing MCP runtime primitives that
 * lets the settings panel:
 *   - validate an in-flight connection form,
 *   - run an MCP `initialize` + `tools/list` discovery handshake,
 *   - invoke a single discovered tool with user-provided JSON args,
 * without involving the live agent loop, lifecycle manager, or
 * dispatcher.
 *
 * Secrets supplied through the form (i.e. the user is still typing,
 * has not yet saved) are never written to persistent storage by this
 * module; they are injected into a per-call overlay storage that the
 * underlying {@link LiveMCPInvocationClient} reads at request time.
 *
 * See docs/mcp-settings-ui-plan.md §"Runtime service" /
 * §"Discovery status" / §"Call sample tool" for the contract this
 * implements. Telemetry is emitted by the UI layer, not by the
 * service. This module emits redacted console diagnostics for supportability,
 * but otherwise stays free of side effects beyond network I/O.
 */

import { type AgentError, isAgentError } from "../errors";
import type { ToolContent, ToolResult } from "../types";
import { LiveMCPInvocationClient } from "./client";
import type { EntraTokenProvider } from "./entra-token-provider";
import {
  buildNamespacedToolName,
  sanitizeToolDescription,
} from "./tool-adapter";
import type { MCPNormalizedConnection, MCPRemoteToolDescriptor } from "./types";
import type { ReadStorageLike, UserMCPConnection } from "./user-settings";
import { userConnectionToConnectionConfig } from "./user-settings";
import { validateMCPConnectionsConfig } from "./validation";

const LOG_PREFIX = "[MCPSettings]";

/**
 * Status mapping the settings UI uses for a per-connection badge. See
 * §"Discovery status" — `degraded` is reserved for the saved/live
 * lifecycle and is not produced by the settings service.
 */
export type TestConnectionStatus =
  | "connected"
  | "unauthorized"
  | "failed"
  | "disabled"
  | "invalid_config";

/**
 * UI-safe per-tool preview produced from a successful discovery. The
 * `namespacedName` mirrors what the agent will see if the connection
 * is saved and the catalog snapshot picks it up.
 */
export interface DiscoveredToolPreview {
  remoteName: string;
  namespacedName: string;
  description: string;
  inputSchema: Record<string, unknown>;
}

export interface TestConnectionError {
  code: string;
  message: string;
  /** True when a retry without config changes might succeed. */
  retryable: boolean;
}

export interface TestConnectionResult {
  status: TestConnectionStatus;
  /** ISO-8601 timestamp of when the test settled. */
  testedAt: string;
  /** Wall-clock duration in ms; 0 when the test short-circuited. */
  durationMs: number;
  toolCount?: number;
  tools?: DiscoveredToolPreview[];
  error?: TestConnectionError;
}

export interface SampleCallSuccess {
  kind: "success";
  content: ToolContent[];
  durationMs: number;
}

export interface SampleCallFailure {
  kind: "error";
  error: TestConnectionError;
  durationMs: number;
}

export type SampleCallResult = SampleCallSuccess | SampleCallFailure;

/**
 * Form state the settings UI hands to the service. The `connection`
 * field carries the persisted shape; `bearerSecret`/`headerSecret`
 * carry unsaved secret values typed into the dialog and override
 * whatever the connection's secret reference points to in storage.
 */
export interface MCPSettingsFormState {
  connection: UserMCPConnection;
  bearerSecret?: string;
  headerSecret?: string;
}

export interface MCPSettingsServiceOptions {
  /** Defaults to global `fetch`. */
  fetchImpl?: typeof fetch;
  /** Storage that backs `auth.tokenRef.scope === "session"`. */
  sessionStorage?: ReadStorageLike;
  /** Storage that backs `auth.tokenRef.scope === "local"`. */
  localStorage?: ReadStorageLike;
  /** Replay-deterministic clock; defaults to `Date.now`. */
  now?: () => number;
  entraTokenProvider?: EntraTokenProvider;
}

interface OverlayParams {
  bearerSecret?: string;
  headerSecret?: string;
  base?: ReadStorageLike;
}

type LogLevel = "debug" | "info" | "warn";

/**
 * Read-only storage that returns an injected secret value when its
 * key matches the form's auth ref, falling back to the supplied base
 * storage otherwise. Used so the service can run discovery against an
 * unsaved secret without ever calling `setItem`.
 */
class OverlayStorage implements ReadStorageLike {
  constructor(
    private readonly overrides: ReadonlyMap<string, string>,
    private readonly base?: ReadStorageLike,
  ) {}

  getItem(key: string): string | null {
    const override = this.overrides.get(key);
    if (override !== undefined) return override;
    if (!this.base) return null;
    try {
      return this.base.getItem(key);
    } catch {
      return null;
    }
  }
}

function buildOverlay(
  connection: MCPNormalizedConnection,
  params: OverlayParams,
): OverlayStorage {
  const overrides = new Map<string, string>();
  if (connection.auth.type === "bearer" && params.bearerSecret !== undefined) {
    overrides.set(connection.auth.tokenRef.key, params.bearerSecret);
  }
  if (connection.auth.type === "header" && params.headerSecret !== undefined) {
    overrides.set(connection.auth.headerValueRef.key, params.headerSecret);
  }
  return new OverlayStorage(overrides, params.base);
}

function classifyAgentError(error: AgentError): TestConnectionError {
  return {
    code: error.code,
    message: error.message,
    retryable: error.details?.retryable === true,
  };
}

function toUiError(error: unknown): TestConnectionError {
  if (isAgentError(error)) return classifyAgentError(error);
  if (error instanceof Error) {
    return { code: "UNKNOWN", message: error.message, retryable: false };
  }
  return {
    code: "UNKNOWN",
    message: "Unexpected error while contacting MCP server.",
    retryable: false,
  };
}

function statusForError(error: TestConnectionError): TestConnectionStatus {
  return error.code === "MCP_CONNECTION_UNAUTHORIZED"
    ? "unauthorized"
    : "failed";
}

function sanitizeUrlForLog(rawUrl: string): string {
  try {
    const url = new URL(rawUrl);
    url.username = "";
    url.password = "";
    url.search = "";
    url.hash = "";
    return url.toString();
  } catch {
    return "<invalid-url>";
  }
}

function authSummaryForLog(
  connection: UserMCPConnection,
): Record<string, unknown> {
  if (connection.auth.type === "none") {
    return { type: "none" };
  }
  if (connection.auth.type === "bearer") {
    return {
      type: "bearer",
      secretScope: connection.auth.tokenRef.scope,
      hasSecretRef: true,
    };
  }
  if (connection.auth.type === "entra") {
    return {
      type: "entra",
      tenantId: connection.auth.tenantId,
      clientId: connection.auth.clientId,
      scopeCount: connection.auth.scopes.length,
    };
  }
  return {
    type: "header",
    headerName: connection.auth.headerName,
    secretScope: connection.auth.headerValueRef.scope,
    hasSecretRef: true,
  };
}

function logMcpSettings(
  level: LogLevel,
  message: string,
  details: Record<string, unknown>,
): void {
  if (level === "warn") {
    console.warn(LOG_PREFIX, message, details);
  } else if (level === "info") {
    console.info(LOG_PREFIX, message, details);
  } else {
    console.debug(LOG_PREFIX, message, details);
  }
}

function previewFor(
  connectionId: string,
  serverLabel: string,
  descriptor: MCPRemoteToolDescriptor,
): DiscoveredToolPreview | null {
  const namespaced = buildNamespacedToolName(connectionId, descriptor.name);
  if (!namespaced) return null;
  const inputSchema =
    descriptor.inputSchema &&
    typeof descriptor.inputSchema === "object" &&
    !Array.isArray(descriptor.inputSchema)
      ? (descriptor.inputSchema as Record<string, unknown>)
      : { type: "object", properties: {}, additionalProperties: true };
  return {
    remoteName: descriptor.name,
    namespacedName: namespaced,
    description: sanitizeToolDescription(
      descriptor.description,
      descriptor.name,
      serverLabel,
    ),
    inputSchema,
  };
}

export class MCPSettingsService {
  private readonly fetchImpl: typeof fetch;
  private readonly sessionStorageRef?: ReadStorageLike;
  private readonly localStorageRef?: ReadStorageLike;
  private readonly now: () => number;
  private readonly entraTokenProvider?: EntraTokenProvider;

  constructor(options: MCPSettingsServiceOptions = {}) {
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.sessionStorageRef = options.sessionStorage;
    this.localStorageRef = options.localStorage;
    this.now = options.now ?? (() => Date.now());
    this.entraTokenProvider = options.entraTokenProvider;
  }

  /**
   * Validate the form, run `initialize` + `tools/list`, and return a
   * UI-safe status object. Disabled connections short-circuit to the
   * `disabled` status without performing any network I/O.
   */
  async testConnection(
    form: MCPSettingsFormState,
    signal?: AbortSignal,
  ): Promise<TestConnectionResult> {
    const start = this.now();
    const testedAt = new Date(start).toISOString();

    logMcpSettings("info", "test:start", {
      connectionId: form.connection.id,
      label: form.connection.label,
      transport: form.connection.transport,
      endpoint: sanitizeUrlForLog(form.connection.endpoint),
      enabled: form.connection.enabled,
      requestTimeoutMs: form.connection.requestTimeoutMs,
      auth: authSummaryForLog(form.connection),
      hasInFormBearerSecret: form.bearerSecret !== undefined,
      hasInFormHeaderSecret: form.headerSecret !== undefined,
    });

    if (!form.connection.enabled) {
      logMcpSettings("info", "test:disabled", {
        connectionId: form.connection.id,
        durationMs: 0,
      });
      return { status: "disabled", testedAt, durationMs: 0 };
    }

    const normalized = this.normalizeForTest(form);
    if (normalized.kind === "invalid") {
      const durationMs = Math.max(0, this.now() - start);
      logMcpSettings("warn", "test:invalid-config", {
        connectionId: form.connection.id,
        durationMs,
        message: normalized.message,
      });
      return {
        status: "invalid_config",
        testedAt,
        durationMs,
        error: {
          code: "MCP_CONFIG_INVALID",
          message: normalized.message,
          retryable: false,
        },
      };
    }

    const { client, connection } = this.buildClient(
      normalized.connection,
      form,
    );
    try {
      const descriptors = await client.listTools({
        connectionId: connection.id,
        signal,
      });
      const previews: DiscoveredToolPreview[] = [];
      for (const descriptor of descriptors) {
        const preview = previewFor(connection.id, connection.label, descriptor);
        if (preview) previews.push(preview);
      }
      const durationMs = Math.max(0, this.now() - start);
      logMcpSettings("info", "test:connected", {
        connectionId: connection.id,
        durationMs,
        discoveredToolCount: descriptors.length,
        previewToolCount: previews.length,
      });
      return {
        status: "connected",
        testedAt,
        durationMs,
        toolCount: previews.length,
        tools: previews,
      };
    } catch (error) {
      const uiError = toUiError(error);
      const durationMs = Math.max(0, this.now() - start);
      logMcpSettings("warn", "test:failed", {
        connectionId: connection.id,
        durationMs,
        status: statusForError(uiError),
        error: uiError,
      });
      return {
        status: statusForError(uiError),
        testedAt,
        durationMs,
        error: uiError,
      };
    } finally {
      client.closeConnection(connection.id);
    }
  }

  /**
   * Invoke a single remote tool against the form's connection. Returns
   * a discriminated result so the UI can render text / image content
   * for success and a structured `MCP_*` payload for failure.
   */
  async callSampleTool(
    form: MCPSettingsFormState,
    remoteToolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<SampleCallResult> {
    const start = this.now();

    logMcpSettings("info", "sample-call:start", {
      connectionId: form.connection.id,
      remoteToolName,
      transport: form.connection.transport,
      endpoint: sanitizeUrlForLog(form.connection.endpoint),
      argumentKeys: Object.keys(args),
    });

    const normalized = this.normalizeForTest(form);
    if (normalized.kind === "invalid") {
      const durationMs = Math.max(0, this.now() - start);
      logMcpSettings("warn", "sample-call:invalid-config", {
        connectionId: form.connection.id,
        remoteToolName,
        durationMs,
        message: normalized.message,
      });
      return {
        kind: "error",
        error: {
          code: "MCP_CONFIG_INVALID",
          message: normalized.message,
          retryable: false,
        },
        durationMs,
      };
    }

    const { client, connection } = this.buildClient(
      normalized.connection,
      form,
    );
    try {
      const result: ToolResult = await client.callTool({
        connectionId: connection.id,
        remoteToolName,
        arguments: args,
        signal,
      });
      const durationMs = Math.max(0, this.now() - start);
      logMcpSettings("info", "sample-call:success", {
        connectionId: connection.id,
        remoteToolName,
        durationMs,
        contentTypes: result.content.map((item) => item.type),
      });
      return {
        kind: "success",
        content: result.content,
        durationMs,
      };
    } catch (error) {
      const durationMs = Math.max(0, this.now() - start);
      const uiError = toUiError(error);
      logMcpSettings("warn", "sample-call:failed", {
        connectionId: connection.id,
        remoteToolName,
        durationMs,
        error: uiError,
      });
      return {
        kind: "error",
        error: uiError,
        durationMs,
      };
    } finally {
      client.closeConnection(connection.id);
    }
  }

  private normalizeForTest(
    form: MCPSettingsFormState,
  ):
    | { kind: "ok"; connection: MCPNormalizedConnection }
    | { kind: "invalid"; message: string } {
    const raw = {
      version: 1 as const,
      connections: [userConnectionToConnectionConfig(form.connection)],
    };
    const result = validateMCPConnectionsConfig(raw);
    if (result.valid.length === 0) {
      const message =
        result.diagnostics.map((d) => `${d.field}: ${d.message}`).join("; ") ||
        "MCP connection config is invalid.";
      return { kind: "invalid", message };
    }
    return { kind: "ok", connection: result.valid[0] };
  }

  private buildClient(
    connection: MCPNormalizedConnection,
    form: MCPSettingsFormState,
  ): { client: LiveMCPInvocationClient; connection: MCPNormalizedConnection } {
    const sessionOverlay = buildOverlay(connection, {
      bearerSecret:
        connection.auth.type === "bearer" &&
        connection.auth.tokenRef.scope === "session"
          ? form.bearerSecret
          : undefined,
      headerSecret:
        connection.auth.type === "header" &&
        connection.auth.headerValueRef.scope === "session"
          ? form.headerSecret
          : undefined,
      base: this.sessionStorageRef,
    });
    const localOverlay = buildOverlay(connection, {
      bearerSecret:
        connection.auth.type === "bearer" &&
        connection.auth.tokenRef.scope === "local"
          ? form.bearerSecret
          : undefined,
      headerSecret:
        connection.auth.type === "header" &&
        connection.auth.headerValueRef.scope === "local"
          ? form.headerSecret
          : undefined,
      base: this.localStorageRef,
    });

    const client = new LiveMCPInvocationClient({
      connections: new Map([[connection.id, connection]]),
      fetchImpl: this.fetchImpl,
      sessionStorage: sessionOverlay,
      localStorage: localOverlay,
      entraTokenProvider: this.entraTokenProvider,
    });
    return { client, connection };
  }
}
