import { createAgentError } from "../../errors";

export interface ProviderStreamReadOptions {
  signal?: AbortSignal;
  idleTimeoutMs: number;
  providerName: string;
  createAbortError?: (reason: unknown) => unknown;
  createIdleTimeoutError?: (
    idleTimeoutMs: number,
    providerName: string,
  ) => unknown;
}

export function readStreamChunkWithTimeout<T>(
  reader: ReadableStreamDefaultReader<T>,
  {
    signal,
    idleTimeoutMs,
    providerName,
    createAbortError,
    createIdleTimeoutError,
  }: ProviderStreamReadOptions,
): Promise<ReadableStreamReadResult<T>> {
  if (signal?.aborted) {
    const reason =
      signal.reason ?? new DOMException("Stream aborted", "AbortError");
    const error = createAbortError?.(reason) ?? reason;
    void reader.cancel(reason).catch(() => undefined);
    return Promise.reject(error);
  }

  return new Promise<ReadableStreamReadResult<T>>((resolve, reject) => {
    let settled = false;

    const cleanup = () => {
      clearTimeout(timeoutId);
      signal?.removeEventListener("abort", onAbort);
    };

    const fail = (error: unknown, cancelReason: unknown = error) => {
      if (settled) return;
      settled = true;
      cleanup();
      void reader.cancel(cancelReason).catch(() => undefined);
      reject(error);
    };

    const onAbort = () => {
      const reason =
        signal?.reason ?? new DOMException("Stream aborted", "AbortError");
      fail(createAbortError?.(reason) ?? reason, reason);
    };

    const timeoutId = setTimeout(() => {
      const timeoutReason = new DOMException(
        `${providerName} stream stalled for ${Math.round(idleTimeoutMs / 1000)}s`,
        "TimeoutError",
      );
      const timeoutError =
        createIdleTimeoutError?.(idleTimeoutMs, providerName) ??
        createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `${providerName} stream stalled for ${Math.round(idleTimeoutMs / 1000)}s while waiting for model output.`,
          { cause: timeoutReason },
        );
      fail(timeoutError, timeoutReason);
    }, idleTimeoutMs);

    signal?.addEventListener("abort", onAbort, { once: true });

    reader.read().then(
      (result) => {
        if (settled) return;
        settled = true;
        cleanup();
        resolve(result);
      },
      (error) => fail(error),
    );
  });
}

/**
 * Detects whether `error` originated from a stream-body timeout that this
 * module (or an equivalent provider-side watchdog) created. Matches errors
 * whose `cause` is a `DOMException` with `name === "TimeoutError"`, which is
 * the shape used by both `readStreamChunkWithTimeout`'s idle watchdog and
 * the provider-level "only-keepalive" meaningful-stream watchdogs.
 *
 * Used by provider retry loops to decide whether a stream-body error is
 * transient enough to retry (e.g. a slow first chunk on a large prompt)
 * vs. a structural failure that should bubble out immediately.
 */
export function isStreamIdleTimeoutError(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const cause = (error as { cause?: unknown }).cause;
  if (typeof DOMException === "undefined") return false;
  return cause instanceof DOMException && cause.name === "TimeoutError";
}
