export function IdePanel() {
  const styles = useStyles();
  const { refreshUploads } = useChat();
  const [files, setFiles] = useState<string[]>([]);
  const [currentFile, setCurrentFile] = useState<string | null>(null);
  const [content, setContent] = useState("");
  const [isDirty, setIsDirty] = useState(false);
  const [newFileName, setNewFileName] = useState("");
  const [hoveredFile, setHoveredFile] = useState<string | null>(null);
  const [expandedFolders, setExpandedFolders] = useState<
    Record<string, boolean>
  >({});
  const [terminalLines, setTerminalLines] = useState<TerminalLine[]>([
    {
      id: "terminal-ready",
      kind: "meta",
      text: "VFS terminal ready. Files live under /home/user/uploads.",
    },
  ]);
  const [terminalInput, setTerminalInput] = useState("");
  const [terminalCwd, setTerminalCwd] = useState("/home/user");
  const [terminalEnv, setTerminalEnv] = useState<Record<string, string>>({});
  const [terminalHistory, setTerminalHistory] = useState<string[]>([]);
  const [historyIndex, setHistoryIndex] = useState<number>(-1);
  const [terminalHeight, setTerminalHeight] = useState(DEFAULT_TERMINAL_HEIGHT);
  const [isTerminalRunning, setIsTerminalRunning] = useState(false);
  const [isResizingTerminal, setIsResizingTerminal] = useState(false);
  const editorSurfaceRef = useRef<HTMLDivElement | null>(null);
  const folderInputRef = useRef<HTMLInputElement | null>(null);
  const terminalInputRef = useRef<HTMLInputElement | null>(null);
  const terminalOutputRef = useRef<HTMLDivElement | null>(null);
  const terminalResizeStateRef = useRef<{
    startY: number;
    startHeight: number;
  } | null>(null);

  const loadFiles = useCallback(async () => {
    const uploads = await listUploads();
    setFiles(uploads);
  }, []);

  useEffect(() => {
    void loadFiles();
  }, [loadFiles]);

  const openFile = useCallback(async (path: string) => {
    try {
      const text = await readFile(path);
      setCurrentFile(path);
      setContent(text);
      setIsDirty(false);
    } catch (error) {
      console.error("Failed to open file", error);
    }
  }, []);

  const handleFolderUploadClick = useCallback(() => {
    folderInputRef.current?.click();
  }, []);

  const handleFolderFiles = useCallback(
    async (folderFiles: FileList | null) => {
      if (!folderFiles) return;
      const fileArray = Array.from(folderFiles);
      if (fileArray.length === 0) return;

      // Keep nested folder structure under /home/user/uploads.
      await Promise.all(
        fileArray.map(async (file) => {
          const relativePath = (file.webkitRelativePath || file.name).replace(
            /\\/g,
            "/",
          );
          const bytes = new Uint8Array(await file.arrayBuffer());
          await writeFile(`/home/user/uploads/${relativePath}`, bytes);
        }),
      );

      await loadFiles();
      await refreshUploads();
    },
    [loadFiles, refreshUploads],
  );

  const saveFile = useCallback(async () => {
    if (!currentFile) return;
    await writeFile(currentFile, content);
    setIsDirty(false);
    await loadFiles();
  }, [content, currentFile, loadFiles]);

  const downloadFile = useCallback(async () => {
    if (!currentFile) return;

    try {
      const data = await readFileBuffer(currentFile);
      const blob = new Blob([data.buffer as ArrayBuffer], {
        type: "application/octet-stream",
      });
      const url = URL.createObjectURL(blob);
      const filename = currentFile.split("/").pop() || "file";
      const link = document.createElement("a");
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Failed to download file", error);
    }
  }, [currentFile]);

  const downloadAllFiles = useCallback(async () => {
    try {
      const uploads = await listUploads();
      if (uploads.length === 0) return;

      const entries: Record<string, Uint8Array> = {};
      for (const file of uploads) {
        const data = await readFileBuffer(file);
        entries[file] = data;
      }

      const zipped = zipSync(entries, { level: 9 });
      const blob = new Blob([zipped.buffer as ArrayBuffer], {
        type: "application/zip",
      });
      const filename = `map-files-${new Date().toISOString().slice(0, 10)}.zip`;
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Failed to download all files", error);
    }
  }, []);

  const createNewFile = useCallback(
    async (event?: React.FormEvent) => {
      event?.preventDefault();
      const name = newFileName.trim();
      if (!name) return;

      await writeFile(name, "");
      setNewFileName("");
      await loadFiles();
      await openFile(name);
    },
    [loadFiles, newFileName, openFile],
  );

  useEffect(() => {
    if (files.length === 0) return;
    if (!currentFile || !files.includes(currentFile)) {
      void openFile(files[0]);
    }
  }, [currentFile, files, openFile]);

  // biome-ignore lint/correctness/useExhaustiveDependencies: Re-run when terminal lines change to keep output pinned to the latest line.
  useEffect(() => {
    if (!terminalOutputRef.current) return;
    terminalOutputRef.current.scrollTop =
      terminalOutputRef.current.scrollHeight;
  }, [terminalLines]);

  const getMaxTerminalHeight = useCallback(() => {
    const editorHeight =
      editorSurfaceRef.current?.getBoundingClientRect().height ?? 0;
    if (editorHeight <= 0) {
      return DEFAULT_TERMINAL_HEIGHT;
    }

    return Math.max(
      MIN_TERMINAL_HEIGHT,
      Math.floor(editorHeight - MIN_EDITOR_HEIGHT - TERMINAL_SPLITTER_SIZE),
    );
  }, []);

  const clampTerminalHeight = useCallback(
    (nextHeight: number) => {
      return Math.min(
        Math.max(nextHeight, MIN_TERMINAL_HEIGHT),
        getMaxTerminalHeight(),
      );
    },
    [getMaxTerminalHeight],
  );

  useEffect(() => {
    if (!editorSurfaceRef.current) return;
    editorSurfaceRef.current.style.setProperty(
      "--ide-terminal-height",
      `${terminalHeight}px`,
    );
  }, [terminalHeight]);

  useEffect(() => {
    const syncTerminalHeight = () => {
      setTerminalHeight((prev) => clampTerminalHeight(prev));
    };

    syncTerminalHeight();
    window.addEventListener("resize", syncTerminalHeight);
    return () => window.removeEventListener("resize", syncTerminalHeight);
  }, [clampTerminalHeight]);

  useEffect((): void | (() => void) => {
    if (!isResizingTerminal) {
      return undefined;
    }

    const previousCursor = document.body.style.cursor;
    const previousUserSelect = document.body.style.userSelect;

    document.body.style.cursor = "row-resize";
    document.body.style.userSelect = "none";

    return () => {
      document.body.style.cursor = previousCursor;
      document.body.style.userSelect = previousUserSelect;
    };
  }, [isResizingTerminal]);

  const focusTerminalInput = useCallback(() => {
    window.requestAnimationFrame(() => {
      const input = terminalInputRef.current;
      if (!input) return;
      input.focus();
      input.setSelectionRange(input.value.length, input.value.length);
    });
  }, []);

  useEffect(() => {
    focusTerminalInput();
  }, [focusTerminalInput]);

  const appendTerminalLine = useCallback(
    (kind: TerminalLineKind, text: string) => {
      const trimmed = text.trim();
      if (!trimmed) return;
      setTerminalLines((prev) => [
        ...prev,
        {
          id: `${Date.now()}-${prev.length}`,
          kind,
          text: trimmed,
        },
      ]);
    },
    [],
  );

  const runTerminalCommand = useCallback(async () => {
    const command = terminalInput.trim();
    if (!command || isTerminalRunning) return;

    setTerminalInput("");
    setIsTerminalRunning(true);
    setTerminalHistory((prev) => [...prev, command]);
    setHistoryIndex(-1);
    appendTerminalLine("command", `${terminalCwd}$ ${command}`);

    try {
      const bash = getBash();
      const timeoutMs = 30000;
      const execPromise = bash.exec(command, {
        cwd: terminalCwd,
        env: terminalEnv,
      });

      const result = await Promise.race([
        execPromise,
        new Promise<never>((_, reject) => {
          setTimeout(() => {
            reject(new Error(`Command timed out after ${timeoutMs}ms.`));
          }, timeoutMs);
        }),
      ]);

      if (result.stdout) appendTerminalLine("stdout", result.stdout);
      if (result.stderr) appendTerminalLine("stderr", result.stderr);
      if (result.exitCode !== 0) {
        appendTerminalLine("meta", `[exit code: ${result.exitCode}]`);
      }

      const env = result.env ?? {};
      setTerminalEnv(env);
      setTerminalCwd(env.PWD || terminalCwd);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown terminal error";
      appendTerminalLine("stderr", message);
    } finally {
      setIsTerminalRunning(false);
    }
  }, [
    appendTerminalLine,
    isTerminalRunning,
    terminalCwd,
    terminalEnv,
    terminalInput,
  ]);

  const clearTerminal = useCallback(() => {
    setTerminalLines([]);
  }, []);

  const handleTerminalResizeStart = useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      event.preventDefault();
      event.currentTarget.setPointerCapture(event.pointerId);
      terminalResizeStateRef.current = {
        startY: event.clientY,
        startHeight: terminalHeight,
      };
      setIsResizingTerminal(true);
    },
    [terminalHeight],
  );

  const handleTerminalResizeMove = useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      const resizeState = terminalResizeStateRef.current;
      if (!resizeState) return;

      const delta = resizeState.startY - event.clientY;
      setTerminalHeight(clampTerminalHeight(resizeState.startHeight + delta));
    },
    [clampTerminalHeight],
  );

  const handleTerminalResizeEnd = useCallback(
    (event: React.PointerEvent<HTMLButtonElement>) => {
      if (event.currentTarget.hasPointerCapture(event.pointerId)) {
        event.currentTarget.releasePointerCapture(event.pointerId);
      }
      terminalResizeStateRef.current = null;
      setIsResizingTerminal(false);
    },
    [],
  );

  const handleTerminalResizeKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (event.key === "ArrowUp") {
        event.preventDefault();
        setTerminalHeight((prev) =>
          clampTerminalHeight(prev + TERMINAL_RESIZE_STEP),
        );
        return;
      }

      if (event.key === "ArrowDown") {
        event.preventDefault();
        setTerminalHeight((prev) =>
          clampTerminalHeight(prev - TERMINAL_RESIZE_STEP),
        );
      }
    },
    [clampTerminalHeight],
  );

  const handleTerminalKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (isTerminalRunning) return;

      if (event.key === "Enter") {
        event.preventDefault();
        void runTerminalCommand();
        return;
      }

      if (event.key === "ArrowUp") {
        event.preventDefault();
        setHistoryIndex((prev) => {
          if (terminalHistory.length === 0) return -1;
          const nextIndex =
            prev < 0 ? terminalHistory.length - 1 : Math.max(0, prev - 1);
          setTerminalInput(terminalHistory[nextIndex]);
          return nextIndex;
        });
        return;
      }

      if (event.key === "ArrowDown") {
        event.preventDefault();
        setHistoryIndex((prev) => {
          if (terminalHistory.length === 0 || prev < 0) return -1;
          const nextIndex = prev + 1;
          if (nextIndex >= terminalHistory.length) {
            setTerminalInput("");
            return -1;
          }
          setTerminalInput(terminalHistory[nextIndex]);
          return nextIndex;
        });
      }
    },
    [isTerminalRunning, runTerminalCommand, terminalHistory],
  );

  const currentFileLabel = currentFile ?? "No file selected";
  const editorStatusLabel = currentFile
    ? isDirty
      ? "Unsaved changes"
      : "Saved"
    : "Create or select a file";
  const terminalStatusLabel = isTerminalRunning ? "Running" : "Ready";
  const terminalResizeMax = getMaxTerminalHeight();

  const getTerminalLineLabel = (kind: TerminalLineKind): string => {
    switch (kind) {
      case "command":
        return "cmd";
      case "stderr":
        return "err";
      case "meta":
        return "sys";
      default:
        return "out";
    }
  };

  const getTerminalLineClassName = (kind: TerminalLineKind): string => {
    switch (kind) {
      case "command":
        return styles.terminalLineCommand;
      case "stderr":
        return styles.terminalLineError;
      case "meta":
        return styles.terminalLineMeta;
      default:
        return "";
    }
  };

  const getTerminalLineLabelClassName = (kind: TerminalLineKind): string => {
    switch (kind) {
      case "command":
        return styles.terminalLineLabelCommand;
      case "stderr":
        return styles.terminalLineLabelError;
      default:
        return "";
    }
  };

  const getTerminalLineContentClassName = (kind: TerminalLineKind): string => {
    switch (kind) {
      case "stderr":
        return styles.terminalLineContentError;
      case "meta":
        return styles.terminalLineContentMeta;
      default:
        return "";
    }
  };

  const fileRows = useMemo(() => {
    type TreeNode = {
      name: string;
      path: string;
      children: Record<string, TreeNode>;
      isFile: boolean;
    };

    const root: TreeNode = {
      name: "",
      path: "",
      children: {},
      isFile: false,
    };

    for (const file of files) {
      const parts = file.split("/");
      let node = root;
      for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        const isFile = i === parts.length - 1;
        const path = parts.slice(0, i + 1).join("/");
        if (!node.children[part]) {
          node.children[part] = {
            name: part,
            path,
            children: {},
            isFile,
          };
        }
        node = node.children[part];
      }
    }

    const renderNode = (node: TreeNode, depth = 0): JSX.Element[] => {
      const isSelected = node.isFile && node.path === currentFile;
      const isHovered = node.path === hoveredFile;
      const isExpanded = expandedFolders[node.path];
      const handleNodeAction = () => {
        if (node.isFile) {
          void openFile(node.path);
        } else {
          setExpandedFolders((prev) => ({
            ...prev,
            [node.path]: !prev[node.path],
          }));
        }
      };

      const row = (
        <button
          type="button"
          key={node.path}
          className={
            isSelected
              ? `${styles.fileRow} ${styles.fileRowSelected}`
              : isHovered
                ? `${styles.fileRow} ${styles.fileRowHover}`
                : styles.fileRow
          }
          onMouseEnter={() => setHoveredFile(node.path)}
          onMouseLeave={() => setHoveredFile(null)}
          onClick={handleNodeAction}
          onKeyDown={(event) => {
            if (event.key === "Enter" || event.key === " ") {
              event.preventDefault();
              handleNodeAction();
            }
          }}
        >
          <span className={styles.fileRowContent}>
            {Array.from({ length: depth }, (_, index) => (
              <span
                key={`${node.path}-indent-${index}`}
                className={styles.fileRowIndent}
                aria-hidden="true"
              />
            ))}
            {!node.isFile ? (
              isExpanded ? (
                <ChevronDownRegular />
              ) : (
                <ChevronRightRegular />
              )
            ) : (
              <span className={styles.fileRowSpacer} aria-hidden="true" />
            )}
            {node.isFile ? <DocumentRegular /> : <FolderRegular />}
            <span className={styles.fileRowLabel}>{node.name}</span>
          </span>
          {isSelected && <CheckmarkRegular />}
        </button>
      );

      const children: JSX.Element[] = [row];
      if (!node.isFile && isExpanded) {
        const sorted = Object.values(node.children).sort((a, b) => {
          if (a.isFile !== b.isFile) return a.isFile ? 1 : -1;
          return a.name.localeCompare(b.name);
        });
        for (const child of sorted) {
          children.push(...renderNode(child, depth + 1));
        }
      }
      return children;
    };

    const roots = Object.values(root.children).sort((a, b) => {
      if (a.isFile !== b.isFile) return a.isFile ? 1 : -1;
      return a.name.localeCompare(b.name);
    });

    return roots.flatMap((node) => renderNode(node));
  }, [
    currentFile,
    expandedFolders,
    files,
    hoveredFile,
    openFile,
    styles.fileRowContent,
    styles.fileRow,
    styles.fileRowHover,
    styles.fileRowIndent,
    styles.fileRowLabel,
    styles.fileRowSelected,
    styles.fileRowSpacer,
  ]);

  return (
    <div className={styles.root}>
      <div className={styles.sidebar}>
        <div className={styles.toolbar}>
          <Text weight="semibold">Files</Text>
          <Menu>
            <MenuTrigger>
              <Button
                appearance="secondary"
                size="small"
                className={styles.toolbarMenuButton}
              >
                Actions
              </Button>
            </MenuTrigger>
            <MenuPopover>
              <MenuList>
                <MenuItem
                  icon={<SaveRegular />}
                  onClick={saveFile}
                  disabled={!currentFile || !isDirty}
                >
                  Save
                </MenuItem>
                <MenuItem
                  icon={<ArrowDownloadRegular />}
                  onClick={downloadFile}
                  disabled={!currentFile}
                >
                  Download
                </MenuItem>
                <MenuItem
                  icon={<ArrowDownloadRegular />}
                  onClick={downloadAllFiles}
                  disabled={files.length === 0}
                >
                  Export ZIP
                </MenuItem>
              </MenuList>
            </MenuPopover>
          </Menu>
        </div>
        <Divider />
        <form className={styles.newFileForm} onSubmit={createNewFile}>
          <Input
            placeholder="New file name"
            value={newFileName}
            onChange={(_, data) => setNewFileName(data.value)}
            size="small"
          />
          <div className={styles.newFileActions}>
            <Button
              icon={<AddRegular />}
              appearance="primary"
              size="small"
              className={styles.newFileActionButton}
              onClick={() => void createNewFile()}
              disabled={!newFileName.trim()}
            >
              Create
            </Button>
            <Button
              icon={<FolderRegular />}
              appearance="secondary"
              size="small"
              className={styles.newFileActionButton}
              onClick={handleFolderUploadClick}
            >
              Upload
            </Button>
          </div>
        </form>
        <input
          ref={folderInputRef}
          type="file"
          className={styles.hiddenInput}
          multiple
          onChange={(event) => void handleFolderFiles(event.target.files)}
          {...({ webkitdirectory: "true", directory: "true" } as any)}
        />
        <Divider />
        <div className={styles.fileList}>{fileRows}</div>
      </div>
      <div className={styles.editor} ref={editorSurfaceRef}>
        <div className={styles.editorPane}>
          <div className={styles.paneHeader}>
            <div className={styles.paneHeaderText}>
              <Text weight="semibold" className={styles.paneTitle}>
                Editor
              </Text>
              <Text className={styles.paneSubtitle}>{currentFileLabel}</Text>
            </div>
            <Text
              className={
                isDirty
                  ? `${styles.paneStatus} ${styles.paneStatusDirty}`
                  : styles.paneStatus
              }
            >
              {editorStatusLabel}
            </Text>
          </div>
          <textarea
            className={styles.textarea}
            value={content}
            onChange={(event) => {
              setContent(event.target.value);
              setIsDirty(true);
            }}
            aria-label={
              currentFile ? `Editor for ${currentFile}` : "File editor"
            }
            placeholder="Select or create a file to edit"
            spellCheck={false}
            title={currentFileLabel}
          />
        </div>
        <button
          type="button"
          className={
            isResizingTerminal
              ? `${styles.splitter} ${styles.splitterActive}`
              : styles.splitter
          }
          aria-label="Resize terminal"
          title="Resize terminal"
          onPointerDown={handleTerminalResizeStart}
          onPointerMove={handleTerminalResizeMove}
          onPointerUp={handleTerminalResizeEnd}
          onPointerCancel={handleTerminalResizeEnd}
          onKeyDown={handleTerminalResizeKeyDown}
        >
          <span className={styles.splitterHandle} />
        </button>
        <div className={styles.terminal}>
          <div className={styles.terminalHeader}>
            <div className={styles.paneHeaderText}>
              <Text weight="semibold" className={styles.paneTitle}>
                Terminal
              </Text>
              <Text className={styles.paneSubtitle}>{terminalCwd}</Text>
            </div>
            <div className={styles.terminalHeaderMeta}>
              <Text
                className={
                  isTerminalRunning
                    ? `${styles.terminalStatus} ${styles.terminalStatusRunning}`
                    : styles.terminalStatus
                }
              >
                {terminalStatusLabel}
              </Text>
              <Button
                appearance="secondary"
                size="small"
                onClick={() => {
                  clearTerminal();
                  focusTerminalInput();
                }}
              >
                Clear
              </Button>
            </div>
          </div>
          <div className={styles.terminalOutput} ref={terminalOutputRef}>
            {terminalLines.length === 0 ? (
              <div className={styles.terminalEmptyState}>
                <Text weight="semibold">Ready in {terminalCwd}</Text>
                <Text>Run commands against the in-memory workspace.</Text>
                <ul className={styles.terminalHintList}>
                  <li className={styles.terminalHintItem}>pwd</li>
                  <li className={styles.terminalHintItem}>ls</li>
                  <li className={styles.terminalHintItem}>cat &lt;file&gt;</li>
                </ul>
              </div>
            ) : (
              terminalLines.map((line) => (
                <div
                  key={line.id}
                  className={`${styles.terminalLine} ${getTerminalLineClassName(
                    line.kind,
                  )}`.trim()}
                >
                  <span
                    className={`${styles.terminalLineLabel} ${getTerminalLineLabelClassName(
                      line.kind,
                    )}`.trim()}
                  >
                    {getTerminalLineLabel(line.kind)}
                  </span>
                  <span
                    className={`${styles.terminalLineContent} ${getTerminalLineContentClassName(
                      line.kind,
                    )}`.trim()}
                  >
                    {line.text}
                  </span>
                </div>
              ))
            )}
          </div>
          <div className={styles.terminalFooter}>
            <div className={styles.terminalPromptRow}>
              <span className={styles.terminalPromptText}>{terminalCwd}$</span>
              <Input
                ref={terminalInputRef}
                className={styles.terminalInput}
                value={terminalInput}
                onChange={(_, data) => setTerminalInput(data.value)}
                onKeyDown={handleTerminalKeyDown}
                placeholder={
                  isTerminalRunning
                    ? "Command running..."
                    : "Type a command and press Enter"
                }
                readOnly={isTerminalRunning}
                aria-busy={isTerminalRunning}
              />
              <Button
                appearance="primary"
                onClick={() => {
                  void runTerminalCommand();
                  focusTerminalInput();
                }}
                disabled={isTerminalRunning || !terminalInput.trim()}
              >
                Run
              </Button>
            </div>
            <Text className={styles.terminalPromptHint}>
              Press Enter to run, Up/Down for history, drag the divider to
              resize.
            </Text>
          </div>
        </div>
      </div>
    </div>
  );
}
