/**
 * Shared chat-completions stream decoder helpers.
 *
 * PR-2: extracts the chunk → content-blocks / tool-calls accumulation logic
 * that used to be inlined in the Azure/OpenAI agent implementations
 * (~L975-L1080). The full streaming loop stays in each provider for now;
 * this module only exposes the small pure helpers that were duplicated.
 *
 * See docs/agent-refactor-blueprint.md §7 and docs/agent-refactor-implementation-plan.md PR-2 step 1.1.
 */

import type { AssistantContentBlock, UsageInfo } from "../../types";
import type { LLMTurnResult } from "../provider";

export interface ToolCallInProgress {
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  accumulatedArgs?: string;
  /**
   * Set to `true` by {@link parseAccumulatedToolArgs} when the streamed
   * `accumulatedArgs` were non-empty but `JSON.parse` rejected them. The
   * decoder uses this to drop tool calls that were truncated mid-string
   * by `finish_reason: "length"`, so the FSM can surface a length-aware
   * nudge instead of dispatching a tool with empty arguments.
   */
  parseFailed?: boolean;
}

export interface StreamedToolCallDelta {
  index?: number;
  id?: string;
  function?: { name?: string; arguments?: string };
}

/**
 * Append a streamed text delta to the trailing text block, or start a new
 * text block if the last block isn't text.
 */
export function appendTextDelta(
  blocks: AssistantContentBlock[],
  text: string,
): void {
  if (!text) return;
  const last = blocks[blocks.length - 1];
  if (last?.type === "text") {
    last.text += text;
  } else {
    blocks.push({ type: "text", text });
  }
}

/**
 * Append a streamed reasoning_content delta to the trailing thinking block,
 * or start a new thinking block. Used by Kimi-K2.5 / reasoning models.
 */
export function appendReasoningDelta(
  blocks: AssistantContentBlock[],
  text: string,
): void {
  if (!text) return;
  const last = blocks[blocks.length - 1];
  if (last?.type === "thinking") {
    last.thinking += text;
  } else {
    blocks.push({ type: "thinking", thinking: text });
  }
}

/**
 * Returns true when a chat-completions `finish_reason` indicates the model
 * tried to make a tool call. Per blueprint §7 this is part of the
 * `sawToolCallSignal` contract.
 */
export function finishReasonIndicatesToolCall(
  reason: string | null | undefined,
): boolean {
  return reason === "tool_calls" || reason === "function_call";
}

/**
 * Upsert a streamed tool-call delta keyed by `index` (Azure chat-completions
 * format). Unknown indices receive a zero-initialized record.
 */
export function upsertStreamedToolCall(
  byIndex: Map<number, ToolCallInProgress>,
  delta: StreamedToolCallDelta,
): void {
  const idx = delta.index ?? 0;
  let existing = byIndex.get(idx);
  if (!existing) {
    existing = {
      id: delta.id ?? "",
      name: delta.function?.name ?? "",
      arguments: {},
      accumulatedArgs: "",
    };
    byIndex.set(idx, existing);
  }
  if (delta.id && !existing.id) {
    existing.id = delta.id;
  }
  if (delta.function?.name) {
    existing.name = delta.function.name;
  }
  if (delta.function?.arguments) {
    existing.accumulatedArgs =
      (existing.accumulatedArgs ?? "") + delta.function.arguments;
  }
}

/**
 * Parse each tool call's accumulated JSON-string arguments into an object.
 * Logs a warning and falls back to `{}` on parse failure to mirror the
 * pre-refactor behavior of both agents. Tool calls whose JSON could not
 * be parsed are also marked with `parseFailed: true` so callers can
 * distinguish "intentionally empty" from "truncated mid-stream".
 */
export function parseAccumulatedToolArgs(
  toolCalls: ToolCallInProgress[],
  logPrefix?: string,
): number {
  let parseFailures = 0;
  for (const tc of toolCalls) {
    if (!tc.accumulatedArgs) continue;
    try {
      tc.arguments = JSON.parse(tc.accumulatedArgs);
      tc.parseFailed = false;
    } catch (e) {
      parseFailures += 1;
      tc.parseFailed = true;
      if (logPrefix) {
        console.warn(
          `${logPrefix} Failed to parse tool arguments:`,
          tc.accumulatedArgs,
          e,
        );
      }
      tc.arguments = {};
    }
  }
  return parseFailures;
}

/**
 * Convert finalized tool calls into `tool_call` assistant content blocks
 * and append them to `blocks`.
 */
export function appendToolCallBlocks(
  blocks: AssistantContentBlock[],
  toolCalls: ToolCallInProgress[],
): void {
  for (const tc of toolCalls) {
    blocks.push({
      type: "tool_call",
      id: tc.id,
      name: tc.name,
      arguments: tc.arguments,
    });
  }
}

// ============ Streaming loop ============

/**
 * Streamed `function_call` delta (legacy Azure chat-completions shape).
 */
export interface LegacyFunctionCallDelta {
  name?: string;
  arguments?: string;
}

/**
 * Minimal chunk shape consumed by `decodeChatCompletionStream`. Matches the
 * chat-completions `{ choices: [{ delta }] }` wire shape used by both OpenAI
 * and Azure. Per-provider transports normalize their incoming events into
 * this shape before passing them in (e.g. Azure responses-API events go
 * through `normalizeStreamChunk` first; raw chat-completions chunks pass
 * through unmodified).
 */
export interface ChatCompletionStreamChunk {
  choices?: Array<{
    delta?: {
      content?: string;
      reasoning_content?: string;
      tool_calls?: StreamedToolCallDelta[];
      function_call?: LegacyFunctionCallDelta;
    };
    finish_reason?: string | null;
  }>;
  usage?: {
    prompt_tokens?: number;
    completion_tokens?: number;
    total_tokens?: number;
  };
}

export interface DecodeChatCompletionStreamOptions {
  /** Log prefix for parse warnings, e.g. "[AzureProvider]". */
  logPrefix: string;
  /**
   * Synthesize a stable id for the (legacy) `function_call` shape when the
   * upstream never emitted any modern `tool_calls`. Returns a unique
   * tool-call id string. Optional: providers that don't support the legacy
   * shape can omit this and the decoder will skip legacy-call synthesis.
   */
  synthesizeLegacyFunctionCallId?: () => string;
  /**
   * Synthesize a stable id when an upstream `tool_calls` delta arrived
   * without an `id` (Azure observed this in practice). Receives the
   * 0-based sort index of the tool call within the turn.
   */
  synthesizeMissingToolCallId?: (sortIndex: number) => string;
  /**
   * Per-chunk inspection hook for provider-specific diagnostics (e.g. dev
   * logging of the first few raw chunks). The decoder treats the chunk as
   * read-only; the hook must not mutate `chunk`.
   */
  onChunk?: (chunk: ChatCompletionStreamChunk, chunkIndex: number) => void;
}

function getAbortReason(signal: AbortSignal): unknown {
  return signal.reason ?? new DOMException("Stream aborted", "AbortError");
}

export function hasMeaningfulChatCompletionDelta(
  chunk: ChatCompletionStreamChunk,
): boolean {
  for (const choice of chunk.choices ?? []) {
    if (choice.finish_reason) return true;

    const delta = choice.delta;
    if (delta?.content || delta?.reasoning_content) return true;

    if (
      delta?.tool_calls?.some(
        (toolCall) =>
          Boolean(toolCall.id) ||
          Boolean(toolCall.function?.name) ||
          Boolean(toolCall.function?.arguments),
      )
    ) {
      return true;
    }

    if (delta?.function_call?.name || delta?.function_call?.arguments) {
      return true;
    }
  }

  return false;
}

/**
 * Decode a stream of normalized chat-completion chunks into the unified
 * `LLMTurnResult` shape. This is the extracted shared loop that previously
 * lived inline in both `OpenAIProvider.decodeStream` and
 * `AzureProvider.decodeStream`. Per blueprint §7 the `sawToolCallSignal`
 * contract is preserved: any tool-call delta or `tool_calls`/`function_call`
 * finish_reason sets the flag, even when JSON parsing fails and the
 * `toolCalls` array ends up empty.
 *
 * The legacy `function_call` shape is only synthesized into a tool call
 * when `synthesizeLegacyFunctionCallId` is supplied and no modern
 * `tool_calls` were emitted; this matches the pre-PR-9a Azure behavior and
 * keeps OpenAI free of the legacy code path.
 */
export async function decodeChatCompletionStream(
  events: AsyncIterable<ChatCompletionStreamChunk>,
  signal: AbortSignal,
  opts: DecodeChatCompletionStreamOptions,
): Promise<LLMTurnResult> {
  const contentBlocks: AssistantContentBlock[] = [];
  const toolCallsByIndex = new Map<number, ToolCallInProgress>();
  const legacyFunctionCall: { name: string; accumulatedArgs: string } = {
    name: "",
    accumulatedArgs: "",
  };

  let usageInfo:
    | {
        prompt_tokens?: number;
        completion_tokens?: number;
        total_tokens?: number;
      }
    | undefined;
  let chunkCount = 0;
  let hitTokenLimit = false;
  let sawToolCallSignal = false;
  let lastFinishReason: string | null = null;

  if (signal.aborted) throw getAbortReason(signal);

  for await (const event of events) {
    if (signal.aborted) throw getAbortReason(signal);
    chunkCount++;

    if (opts.onChunk) opts.onChunk(event, chunkCount);

    if (event.usage) {
      usageInfo = event.usage;
    }

    for (const choice of event.choices ?? []) {
      if (choice.finish_reason) {
        lastFinishReason = choice.finish_reason;
      }
      if (choice.finish_reason === "length") {
        hitTokenLimit = true;
      }
      if (finishReasonIndicatesToolCall(choice.finish_reason)) {
        sawToolCallSignal = true;
      }

      const delta = choice.delta;
      if (delta?.content) appendTextDelta(contentBlocks, delta.content);
      if (delta?.reasoning_content)
        appendReasoningDelta(contentBlocks, delta.reasoning_content);

      if (delta?.tool_calls) {
        sawToolCallSignal = true;
        for (const tc of delta.tool_calls) {
          upsertStreamedToolCall(toolCallsByIndex, tc);
        }
      }

      const legacyFc = delta?.function_call;
      if (legacyFc && opts.synthesizeLegacyFunctionCallId) {
        sawToolCallSignal = true;
        if (legacyFc.name) legacyFunctionCall.name = legacyFc.name;
        if (legacyFc.arguments)
          legacyFunctionCall.accumulatedArgs += legacyFc.arguments;
      }
    }
  }

  const toolCalls = finalizeToolCalls(
    toolCallsByIndex,
    opts.synthesizeMissingToolCallId,
  );

  if (
    toolCalls.length === 0 &&
    legacyFunctionCall.name &&
    opts.synthesizeLegacyFunctionCallId
  ) {
    toolCalls.push({
      id: opts.synthesizeLegacyFunctionCallId(),
      name: legacyFunctionCall.name,
      arguments: {},
      accumulatedArgs: legacyFunctionCall.accumulatedArgs,
    });
  }

  if (hitTokenLimit) {
    console.warn(
      `${opts.logPrefix} WARNING: Model hit max_completion_tokens limit.`,
    );
  }

  const parseFailures = parseAccumulatedToolArgs(toolCalls, opts.logPrefix);
  if (parseFailures > 0) {
    console.warn(
      `${opts.logPrefix} [PROVIDER_STREAM_PARSE_ERROR] Failed to parse ${parseFailures} tool-call argument payload(s).`,
    );
  }

  // When the stream was truncated by `max_completion_tokens`, any tool
  // call whose JSON arguments failed to parse is guaranteed to be
  // truncated mid-string (not just malformed). Dispatching such a call
  // with `arguments: {}` would waste an iteration on a tool that errors
  // out on missing required fields. Drop the broken entries instead so
  // the FSM's Rule 4 path (`sawToolCallSignal && toolCalls.length === 0`)
  // surfaces a length-aware nudge asking the model to retry with a
  // smaller payload.
  let droppedTruncatedToolCalls = 0;
  if (hitTokenLimit && parseFailures > 0) {
    for (let i = toolCalls.length - 1; i >= 0; i--) {
      if (toolCalls[i].parseFailed) {
        toolCalls.splice(i, 1);
        droppedTruncatedToolCalls += 1;
      }
    }
    if (droppedTruncatedToolCalls > 0) {
      console.warn(
        `${opts.logPrefix} [PROVIDER_STREAM_PARSE_ERROR] Dropped ${droppedTruncatedToolCalls} tool call(s) truncated by max_completion_tokens; the FSM will request a smaller retry.`,
      );
    }
  }

  if (sawToolCallSignal && toolCalls.length === 0) {
    console.warn(
      `${opts.logPrefix} [PROVIDER_STREAM_PARSE_ERROR] Saw tool-call stream signals but finalized zero parseable tool calls.`,
    );
  }
  appendToolCallBlocks(contentBlocks, toolCalls);

  const finishReason: LLMTurnResult["finishReason"] = hitTokenLimit
    ? "length"
    : lastFinishReason === "content_filter"
      ? "content_filter"
      : sawToolCallSignal || toolCalls.length > 0
        ? "tool_calls"
        : lastFinishReason === "stop" ||
            (lastFinishReason === null && contentBlocks.length > 0)
          ? "stop"
          : "unknown";

  const usage: UsageInfo | undefined = usageInfo
    ? {
        input: usageInfo.prompt_tokens ?? 0,
        output: usageInfo.completion_tokens ?? 0,
        cacheRead: 0,
        cacheWrite: 0,
      }
    : undefined;

  return {
    blocks: contentBlocks,
    toolCalls: toolCalls.map((tc) => ({
      type: "tool_call",
      id: tc.id,
      name: tc.name,
      arguments: tc.arguments,
    })),
    finishReason,
    sawToolCallSignal,
    usage,
    rawChunkCount: chunkCount,
  };
}

/**
 * Stable, index-sorted finalize: drop entries that never received a name
 * (incomplete fragments), synthesize ids for entries that arrived without
 * one (Azure observed this), and return in delta-index order.
 */
function finalizeToolCalls(
  byIndex: Map<number, ToolCallInProgress>,
  synthesizeMissingId?: (sortIndex: number) => string,
): ToolCallInProgress[] {
  return [...byIndex.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, tc], idx) => ({
      ...tc,
      id:
        tc.id ||
        (synthesizeMissingId ? synthesizeMissingId(idx) : `tool_call_${idx}`),
    }))
    .filter((tc) => tc.name.trim().length > 0);
}
