/**
 * Dev-only NDJSON turn recorder (PR-2 step 1.4b).
 *
 * Captures a structured trace of an agent run — request/result summaries,
 * dispatched tool calls and their results, decision branches, and final
 * stop reason — to a session-scoped file in the in-memory VFS at
 * `/home/user/uploads/.officeai-turn-recordings/`.
 *
 * Constraints from docs/agent-refactor-implementation-plan.md PR-2 §1.4b:
 *   - Dev-build only (`import.meta.env.DEV`).
 *   - Off by default; opt-in via `localStorage["officeai-turn-recording"] = "1"`
 *     or runtime config.
 *   - VFS-only storage; no persistence beyond the current browser session.
 *   - Field allowlisting + redaction of API keys / auth headers / MCP
 *     secrets before any value reaches disk.
 *   - Best-effort: recorder failures MUST NOT affect agent execution.
 *
 */

import type { AgentMessage, AssistantContentBlock, UsageInfo } from "./types";
import { writeFile } from "../vfs";

const RECORDINGS_DIR = "/home/user/uploads/.officeai-turn-recordings";
const ENABLE_FLAG_KEY = "officeai-turn-recording";

const SENSITIVE_KEY_RE =
  /(api[-_]?key|authorization|auth[-_]?token|access[-_]?token|refresh[-_]?token|bearer|secret|password|client[-_]?secret|cookie|set-cookie)/i;

const REDACTED = "[REDACTED]";
const MAX_STRING_LEN = 4000;
const MAX_DEPTH = 6;

export interface RecordedMessageSummary {
  role: AgentMessage["role"];
  textChars?: number;
  contentTypes?: string[];
  toolCallNames?: string[];
  toolCallId?: string;
  imageCount?: number;
  isError?: boolean;
}

export interface RecordedContentBlockSummary {
  type: AssistantContentBlock["type"];
  textChars?: number;
  id?: string;
  name?: string;
  argumentKeys?: string[];
}

export interface RecordedToolCallSummary {
  id: string;
  name: string;
  argumentKeys: string[];
}

export type TurnRecorderEvent =
  | {
      type: "run_start";
      runId: string;
      timestampMs: number;
      agent: string;
      model?: string;
      apiMode?: string;
      executionModel?: string;
      toolCount?: number;
    }
  | {
      type: "turn_request";
      runId: string;
      timestampMs: number;
      iteration: number;
      requestMode: "chat_completions" | "responses";
      messageCount: number;
      messages: RecordedMessageSummary[];
      toolNames: string[];
      toolCount: number;
      thinkingLevel: string;
      maxOutputTokens: number;
      wasTruncated: boolean;
      plannerInstructionInjected: boolean;
      tokenCount?: unknown;
    }
  | {
      type: "turn_result";
      runId: string;
      timestampMs: number;
      iteration: number;
      contentBlocks: RecordedContentBlockSummary[];
      toolCalls: RecordedToolCallSummary[];
      finishReason: string;
      sawToolCallSignal: boolean;
      rawChunkCount: number;
      usage?: UsageInfo;
    }
  | {
      type: "tool_call";
      runId: string;
      timestampMs: number;
      toolCallId: string;
      name: string;
      arguments: unknown;
      result?: unknown;
      isError: boolean;
      durationMs: number;
    }
  | {
      type: "decision";
      runId: string;
      timestampMs: number;
      branch: string;
      detail?: Record<string, unknown>;
    }
  | {
      type: "run_end";
      runId: string;
      timestampMs: number;
      stopReason: string;
      error?: string;
    };

function isDevBuild(): boolean {
  try {
    // Vite injects import.meta.env.DEV at build time.
    return Boolean(
      (import.meta as unknown as { env?: { DEV?: boolean } })?.env?.DEV,
    );
  } catch {
    return false;
  }
}

function readEnableFlag(): boolean {
  try {
    if (typeof globalThis === "undefined") return false;
    const ls = (globalThis as { localStorage?: Storage }).localStorage;
    if (!ls) return false;
    const v = ls.getItem(ENABLE_FLAG_KEY);
    return v === "1" || v === "true";
  } catch {
    return false;
  }
}

export function isTurnRecordingEnabled(): boolean {
  return isDevBuild() && readEnableFlag();
}

function redactValue(value: unknown, depth: number): unknown {
  if (depth > MAX_DEPTH) return "[truncated:depth]";
  if (value === null || value === undefined) return value;
  const t = typeof value;
  if (t === "string") {
    const s = value as string;
    return s.length > MAX_STRING_LEN
      ? `${s.slice(0, MAX_STRING_LEN)}…[truncated:${s.length - MAX_STRING_LEN}]`
      : s;
  }
  if (t === "number" || t === "boolean") return value;
  if (Array.isArray(value)) {
    return value.slice(0, 100).map((v) => redactValue(v, depth + 1));
  }
  if (t === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (SENSITIVE_KEY_RE.test(k)) {
        out[k] = REDACTED;
        continue;
      }
      out[k] = redactValue(v, depth + 1);
    }
    return out;
  }
  // function / symbol / bigint — drop.
  return undefined;
}

export function redactForRecording(value: unknown): unknown {
  return redactValue(value, 0);
}

export function summarizeMessages(
  messages: AgentMessage[],
): RecordedMessageSummary[] {
  return messages.map((message) => {
    if (message.role === "user") {
      return {
        role: "user",
        textChars: message.content.length,
      };
    }

    if (message.role === "assistant") {
      return {
        role: "assistant",
        textChars: message.content.reduce((total, block) => {
          if (block.type === "text") return total + block.text.length;
          if (block.type === "thinking") return total + block.thinking.length;
          return total;
        }, 0),
        contentTypes: message.content.map((block) => block.type),
        toolCallNames: message.content
          .filter(
            (
              block,
            ): block is Extract<AssistantContentBlock, { type: "tool_call" }> =>
              block.type === "tool_call",
          )
          .map((block) => block.name),
      };
    }

    return {
      role: "tool",
      textChars: message.content.reduce((total, block) => {
        if (block.type === "text") return total + block.text.length;
        return total;
      }, 0),
      contentTypes: message.content.map((block) => block.type),
      toolCallId: message.toolCallId,
      imageCount: message.content.filter((block) => block.type === "image")
        .length,
      isError: message.isError,
    };
  });
}

export function summarizeContentBlocks(
  blocks: AssistantContentBlock[],
): RecordedContentBlockSummary[] {
  return blocks.map((block) => {
    if (block.type === "text") {
      return { type: "text", textChars: block.text.length };
    }
    if (block.type === "thinking") {
      return { type: "thinking", textChars: block.thinking.length };
    }
    return {
      type: "tool_call",
      id: block.id,
      name: block.name,
      argumentKeys: Object.keys(block.arguments).sort(),
    };
  });
}

export function summarizeToolCalls(
  toolCalls: Array<{
    id: string;
    name: string;
    arguments: Record<string, unknown>;
  }>,
): RecordedToolCallSummary[] {
  return toolCalls.map((toolCall) => ({
    id: toolCall.id,
    name: toolCall.name,
    argumentKeys: Object.keys(toolCall.arguments).sort(),
  }));
}

function sessionFileName(sessionStartMs: number): string {
  const iso = new Date(sessionStartMs).toISOString().replace(/[:.]/g, "-");
  return `${RECORDINGS_DIR}/session-${iso}.ndjson`;
}

class TurnRecorder {
  private readonly sessionStartMs = Date.now();
  private readonly filePath = sessionFileName(this.sessionStartMs);
  private buffered = "";
  private flushing = false;
  private warned = false;

  record(event: TurnRecorderEvent): void {
    let line: string;
    try {
      line = `${JSON.stringify(redactForRecording(event))}\n`;
    } catch (err) {
      this.warnOnce("serialize", err);
      return;
    }
    this.buffered += line;
    void this.flush();
  }

  private async flush(): Promise<void> {
    if (this.flushing || !this.buffered) return;
    this.flushing = true;
    const pending = this.buffered;
    this.buffered = "";
    try {
      // Append by re-reading is expensive; the VFS has no append API,
      // so we rewrite the accumulated transcript. Acceptable for the
      // dev-only NDJSON recorder; at scale a custom command can be added.
      const existing = await readExistingSafe(this.filePath);
      await writeFile(this.filePath, existing + pending);
    } catch (err) {
      this.warnOnce("flush", err);
      // Re-buffer so we don't drop events on transient failures.
      this.buffered = pending + this.buffered;
    } finally {
      this.flushing = false;
    }
  }

  private warnOnce(stage: string, err: unknown): void {
    if (this.warned) return;
    this.warned = true;
    console.warn(`[turn-recorder] ${stage} failed`, err);
  }

  getFilePath(): string {
    return this.filePath;
  }
}

async function readExistingSafe(path: string): Promise<string> {
  try {
    const { readFile, fileExists } = await import("../vfs");
    if (!(await fileExists(path))) return "";
    return await readFile(path);
  } catch {
    return "";
  }
}

let singleton: TurnRecorder | null = null;
let singletonChecked = false;

export function getTurnRecorder(): TurnRecorder | null {
  if (singletonChecked) return singleton;
  singletonChecked = true;
  if (!isTurnRecordingEnabled()) {
    singleton = null;
    return null;
  }
  singleton = new TurnRecorder();
  return singleton;
}

/** Test-only: reset singleton resolution. */
export function _resetTurnRecorderForTests(): void {
  singleton = null;
  singletonChecked = false;
}

export type { TurnRecorder };
