import { MAX_CONTEXT_TOKENS } from "../token-manager";
import { type WorkflowManager, createWorkflowManager } from "../workflow";
import { Agent } from "./agent";
import { AzureProvider } from "./providers/azure-provider";
import {
  OpenAIProvider,
  type OpenAIProviderConfig,
} from "./providers/openai-provider";
import type { AgentMessage, ThinkingLevel, Tool } from "./types";

export type AzureAgent = Agent;
export type OpenAIAgent = Agent;

export interface AzureAgentConfig {
  endpoint: string;
  deploymentName: string;
  apiMode?: "chat-completions" | "responses";
  apiKey?: string;
  useEntraId?: boolean;
  azureClientId?: string;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  tools: Tool[];
  messages?: AgentMessage[];
  rateLimitDelayMs?: number;
  maxRetries?: number;
  maxContextTokens?: number;
  maxOutputTokens?: number;
  enableCircuitBreaker?: boolean;
  useWorkflowManager?: boolean;
  workflowManager?: WorkflowManager;
  workflowMaxRequestsPerMinute?: number;
  workflowMaxConcurrent?: number;
  executionModel?: "standard" | "planner";
  mcpConfig?: unknown;
}

export interface OpenAIAgentConfig {
  apiKey: string;
  model: string;
  baseUrl?: string;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  tools: Tool[];
  messages?: AgentMessage[];
  rateLimitDelayMs?: number;
  maxRetries?: number;
  maxContextTokens?: number;
  maxOutputTokens?: number;
  enableCircuitBreaker?: boolean;
  useWorkflowManager?: boolean;
  workflowManager?: WorkflowManager;
  workflowMaxRequestsPerMinute?: number;
  workflowMaxConcurrent?: number;
  executionModel?: "standard" | "planner";
  mcpConfig?: unknown;
}

const AZURE_DEFAULTS: Partial<AzureAgentConfig> = {
  rateLimitDelayMs: 5000,
  maxRetries: 5,
  maxContextTokens: MAX_CONTEXT_TOKENS,
  maxOutputTokens: 8192,
  enableCircuitBreaker: true,
  useWorkflowManager: true,
  executionModel: "planner",
  apiMode: "chat-completions",
};

const OPENAI_DEFAULTS: Partial<OpenAIAgentConfig> = {
  rateLimitDelayMs: 1000,
  maxRetries: 3,
  maxContextTokens: MAX_CONTEXT_TOKENS,
  // Raised from 4096 to match Azure's default and to fit larger tool-call
  // payloads (e.g. ~100-row `set_cell_range` writes). At 4096 a single
  // large write was being truncated mid-stream by `max_completion_tokens`,
  // forcing the FSM to nudge the model into many small batches and
  // sometimes triggering 45 s SSE stalls between batches.
  maxOutputTokens: 8192,
  enableCircuitBreaker: true,
  baseUrl: "https://api.openai.com/v1",
  useWorkflowManager: true,
  executionModel: "planner",
};

function resolveWorkflowManager(
  provider: "azure" | "openai",
  config: {
    workflowManager?: WorkflowManager;
    useWorkflowManager?: boolean;
    workflowMaxRequestsPerMinute?: number;
    workflowMaxConcurrent?: number;
  },
  defaults: { maxRequests: number; maxConcurrent: number },
): { workflowManager: WorkflowManager; ownsWorkflowManager: boolean } {
  if (config.workflowManager) {
    return {
      workflowManager: config.workflowManager,
      ownsWorkflowManager: false,
    };
  }

  if (config.useWorkflowManager) {
    return {
      workflowManager: createWorkflowManager(provider, {
        rateLimit: {
          maxRequests:
            config.workflowMaxRequestsPerMinute ?? defaults.maxRequests,
          windowMs: 60000,
          adaptiveLimiting: true,
        },
        queue: {
          maxConcurrent: config.workflowMaxConcurrent ?? defaults.maxConcurrent,
          maxQueueSize: 50,
          defaultTimeoutMs: 60000,
          enableDeduplication: true,
          dedupWindowMs: 5000,
        },
      }),
      ownsWorkflowManager: true,
    };
  }

  const workflowManager = createWorkflowManager(provider);
  workflowManager.updateRateLimitConfig({ maxRequests: 10000, windowMs: 1000 });
  return { workflowManager, ownsWorkflowManager: true };
}

/**
 * Strip keys whose value is `undefined` so a spread-merge does not clobber
 * provider defaults when the chat layer passes through `undefined` for an
 * untuned runtime knob. Without this, `{ ...DEFAULTS, ...config }` where
 * `config.maxOutputTokens === undefined` silently demotes the default
 * (e.g. Azure's 8192 was being reset to `undefined`, which then fell
 * through to `Agent`'s internal 4096 floor — capping 100-row writes
 * mid-stream).
 */
function withoutUndefined<T extends object>(obj: T): T {
  const out: Partial<T> = {};
  for (const key of Object.keys(obj) as Array<keyof T>) {
    const value = obj[key];
    if (value !== undefined) {
      out[key] = value;
    }
  }
  return out as T;
}

/** @deprecated Use {@link createAgent} with `{ provider: "azure", ... }`. */
export function createAzureAgent(config: AzureAgentConfig): Agent {
  const merged: AzureAgentConfig = {
    ...AZURE_DEFAULTS,
    ...withoutUndefined(config),
  };
  const { workflowManager, ownsWorkflowManager } = resolveWorkflowManager(
    "azure",
    merged,
    { maxRequests: 20, maxConcurrent: 1 },
  );
  const provider = new AzureProvider({
    endpoint: merged.endpoint,
    deploymentName: merged.deploymentName,
    apiMode: merged.apiMode,
    apiKey: merged.apiKey,
    useEntraId: merged.useEntraId,
    azureClientId: merged.azureClientId,
    maxRetries: merged.maxRetries,
    workflowManager,
  });

  return new Agent({
    provider,
    systemPrompt: merged.systemPrompt,
    thinkingLevel: merged.thinkingLevel,
    tools: merged.tools,
    mcpConfig: merged.mcpConfig,
    messages: merged.messages,
    rateLimitDelayMs: merged.rateLimitDelayMs,
    maxContextTokens: merged.maxContextTokens,
    maxOutputTokens: merged.maxOutputTokens,
    enableCircuitBreaker: merged.enableCircuitBreaker,
    workflowManager,
    ownsWorkflowManager,
    executionModel: merged.executionModel,
    agentLabel: "AzureAgent",
    modelLabel: merged.deploymentName,
    apiMode: merged.apiMode,
  });
}

/** @deprecated Use {@link createAgent} with `{ provider: "openai", ... }`. */
export function createOpenAIAgent(config: OpenAIAgentConfig): Agent {
  const merged: OpenAIAgentConfig = {
    ...OPENAI_DEFAULTS,
    ...withoutUndefined(config),
  };
  const { workflowManager, ownsWorkflowManager } = resolveWorkflowManager(
    "openai",
    merged,
    { maxRequests: 50, maxConcurrent: 2 },
  );
  const providerConfig: OpenAIProviderConfig = {
    apiKey: merged.apiKey,
    model: merged.model,
    baseUrl: merged.baseUrl,
    maxRetries: merged.maxRetries,
    workflowManager,
  };

  return new Agent({
    provider: new OpenAIProvider(providerConfig),
    systemPrompt: merged.systemPrompt,
    thinkingLevel: merged.thinkingLevel,
    tools: merged.tools,
    mcpConfig: merged.mcpConfig,
    messages: merged.messages,
    rateLimitDelayMs: merged.rateLimitDelayMs,
    maxContextTokens: merged.maxContextTokens,
    maxOutputTokens: merged.maxOutputTokens,
    enableCircuitBreaker: merged.enableCircuitBreaker,
    workflowManager,
    ownsWorkflowManager,
    executionModel: merged.executionModel,
    agentLabel: "OpenAIAgent",
    modelLabel: merged.model,
  });
}

/**
 * Discriminated config for {@link createAgent}. Branch on `provider` to pick
 * between Azure-specific (`endpoint`, `deploymentName`, `apiMode`,
 * `useEntraId`, `azureClientId`) and OpenAI-specific (`model`, `baseUrl`)
 * fields. All other tuning knobs are shared.
 */
export type CreateAgentConfig =
  | ({ provider: "azure" } & AzureAgentConfig)
  | ({ provider: "openai" } & OpenAIAgentConfig);

/**
 * Single canonical factory. Branches on `config.provider` to construct the
 * right `LLMProvider`, then returns a configured `Agent`. Prefer this over
 * the legacy `createAzureAgent` / `createOpenAIAgent` factories, which now
 * delegate here.
 */
export function createAgent(config: CreateAgentConfig): Agent {
  if (config.provider === "azure") {
    const { provider: _provider, ...azureConfig } = config;
    return createAzureAgent(azureConfig);
  }
  const { provider: _provider, ...openaiConfig } = config;
  return createOpenAIAgent(openaiConfig);
}
