type HostType = "excel" | "outlook" | "word" | "web";

function getHostContext(): { name: string; type: HostType } {
  if (
    typeof Office === "undefined" ||
    typeof Office.context === "undefined" ||
    Office.context === null
  ) {
    return { name: "OfficeAI", type: "web" };
  }

  // Check if running in Outlook
  if (Office.context?.mailbox) {
    return { name: "Microsoft Outlook", type: "outlook" };
  }

  if (Office.context?.host === Office.HostType.Excel) {
    return { name: "Microsoft Excel", type: "excel" };
  }

  // Check if running in Word
  if (Office.context?.host === Office.HostType.Word) {
    return { name: "Microsoft Word", type: "word" };
  }

  return { name: "OfficeAI", type: "web" };
}

function isOfficeHostAvailable(): boolean {
  return getHostContext().type !== "web";
}

function getToolsForHost(): Tool[] {
  const host = getHostContext();
  const webSafeTools = new Set([
    "read",
    "bash",
    "write_file",
    "write_progress",
  ]);
  switch (host.type) {
    case "outlook":
      return OUTLOOK_TOOLS as Tool[];
    case "word":
      return WORD_TOOLS as Tool[];
    case "web":
      return (EXCEL_TOOLS as Tool[]).filter((t) => webSafeTools.has(t.name));
    default:
      return EXCEL_TOOLS as Tool[];
  }
}

function getEndpointHost(config: ProviderConfig): string {
  const endpoint =
    config.provider === "azure"
      ? getAzureEndpoint(config)
      : config.openaiBaseUrl || config.myAiBaseUrl;

  try {
    return endpoint ? new URL(endpoint).host : "unknown";
  } catch {
    return "invalid";
  }
}

function getUsernameForTelemetry(): string | null {
  const storedEntraUsername = getStoredEntraUsername();
  if (storedEntraUsername) {
    return storedEntraUsername;
  }

  try {
    const email = Office?.context?.mailbox?.userProfile?.emailAddress;
    if (typeof email === "string" && email.trim().length > 0) {
      return email.trim();
    }
  } catch {
    // Ignore host-specific identity access issues.
  }
  return null;
}

