import { AIRGAP_CONFIG } from "../../airgap-config";
import { DEFAULT_MAX_BYTES, truncateHead } from "../../truncate";
import { type AgentError, createAgentError, isAgentError } from "../errors";
import { readStreamChunkWithTimeout } from "../providers/shared/stream-read";
import type { ToolContent, ToolResult } from "../types";
import {
  type EntraTokenProvider,
  defaultEntraTokenProvider,
  isEntraTokenError,
} from "./entra-token-provider";
import type { MCPNormalizedConnection, MCPRemoteToolDescriptor } from "./types";

const JSON_RPC_VERSION = "2.0";
const STREAMABLE_HTTP_PROTOCOL_VERSION = "2025-11-25";
const LEGACY_SSE_PROTOCOL_VERSION = "2024-11-05";
const DEFAULT_MAX_RETRIES = 2;
const DEFAULT_BASE_RETRY_DELAY_MS = 250;
const LOG_PREFIX = "[MCPTransport]";

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id: number;
  method: string;
  params?: Record<string, unknown>;
}

interface JsonRpcNotification {
  jsonrpc: "2.0";
  method: string;
  params?: Record<string, unknown>;
}

interface JsonRpcErrorObject {
  code?: number;
  message?: string;
  data?: unknown;
}

interface JsonRpcSuccessEnvelope {
  jsonrpc: "2.0";
  id?: number | string | null;
  result: unknown;
}

interface JsonRpcErrorEnvelope {
  jsonrpc: "2.0";
  id?: number | string | null;
  error: JsonRpcErrorObject;
}

type JsonRpcEnvelope = JsonRpcSuccessEnvelope | JsonRpcErrorEnvelope;

interface SseEvent {
  event: string;
  data: string;
}

interface ConnectionSessionState {
  initialized: boolean;
  protocolVersion: string;
  sessionId?: string;
  legacyPostEndpoint?: string;
}

interface TransportResponse {
  json: JsonRpcEnvelope | null;
  sessionId?: string;
  protocolVersion?: string;
  legacyPostEndpoint?: string;
}

interface RequestContext {
  connectionId: string;
  remoteToolName?: string;
  operation: "initialize" | "discover" | "call" | "notify";
}

type LogLevel = "debug" | "info" | "warn";

interface FetchLogContext extends RequestContext {
  url: string;
  method: string;
  startedAtMs: number;
}

export interface StorageLike {
  getItem(key: string): string | null;
}

export interface LiveMCPTransportOptions {
  fetchImpl?: typeof fetch;
  sessionStorage?: StorageLike;
  localStorage?: StorageLike;
  entraTokenProvider?: EntraTokenProvider;
  maxRetries?: number;
  baseRetryDelayMs?: number;
  random?: () => number;
  sleep?: (ms: number, signal?: AbortSignal) => Promise<void>;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isJsonRpcEnvelope(value: unknown): value is JsonRpcEnvelope {
  return (
    isPlainObject(value) &&
    value.jsonrpc === JSON_RPC_VERSION &&
    ("result" in value || "error" in value)
  );
}

// Coarse allow-list of codes that MAY be retried; the per-error
// `details.retryable` flag is consulted to make the final decision so a 4xx
// surfaced as one of these codes (e.g. malformed payload with retryable:false)
// is not retried.
const RETRYABLE_CODE_ALLOWLIST = new Set([
  "MCP_CONNECTION_UNAVAILABLE",
  "MCP_DISCOVERY_FAILED",
  "MCP_TOOL_TIMEOUT",
  "MCP_TOOL_INVOCATION_FAILED",
]);

function isRetryableError(error: AgentError): boolean {
  if (!RETRYABLE_CODE_ALLOWLIST.has(error.code)) {
    return false;
  }
  const flag = error.details?.retryable;
  // Default to retryable when unset to preserve prior behaviour for codes whose
  // emit sites do not populate `details.retryable`.
  return flag !== false;
}

function truncateText(text: string): string {
  const truncation = truncateHead(text, { maxBytes: DEFAULT_MAX_BYTES });
  if (!truncation.truncated) {
    return truncation.content;
  }
  return `${truncation.content}\n[truncated to ${DEFAULT_MAX_BYTES} bytes]`;
}

function stringifyUnknown(value: unknown): string {
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function sanitizeUrlForLog(rawUrl: string): string {
  try {
    const url = new URL(rawUrl);
    url.username = "";
    url.password = "";
    url.search = "";
    url.hash = "";
    return url.toString();
  } catch {
    return "<invalid-url>";
  }
}

function describeErrorForLog(error: unknown): Record<string, string> {
  if (isAgentError(error)) {
    return {
      type: "AgentError",
      code: error.code,
      message: error.message,
    };
  }
  if (error instanceof Error) {
    return {
      type: error.name || "Error",
      message: error.message,
    };
  }
  return {
    type: typeof error,
    message: String(error),
  };
}

function logMcpTransport(
  level: LogLevel,
  message: string,
  details: Record<string, unknown>,
): void {
  if (level === "warn") {
    console.warn(LOG_PREFIX, message, details);
  } else if (level === "info") {
    console.info(LOG_PREFIX, message, details);
  } else {
    console.debug(LOG_PREFIX, message, details);
  }
}

function bindFetchToGlobal(fetchImpl: typeof fetch): typeof fetch {
  return ((input, init) =>
    fetchImpl.call(globalThis, input, init)) as typeof fetch;
}

function buildClientInfo() {
  return {
    name: "OfficeAI",
    title: "OfficeAI",
    version: "0.2.1-airgap",
  };
}

function protocolVersionFor(connection: MCPNormalizedConnection): string {
  return connection.transport === "streamable_http"
    ? STREAMABLE_HTTP_PROTOCOL_VERSION
    : LEGACY_SSE_PROTOCOL_VERSION;
}

export class LiveMCPTransport {
  private readonly fetchImpl: typeof fetch;
  private readonly sessionStorageRef?: StorageLike;
  private readonly localStorageRef?: StorageLike;
  private readonly entraTokenProvider: EntraTokenProvider;
  private readonly maxRetries: number;
  private readonly baseRetryDelayMs: number;
  private readonly random: () => number;
  private readonly sleep: (ms: number, signal?: AbortSignal) => Promise<void>;
  private readonly sessions = new Map<string, ConnectionSessionState>();
  private readonly initInFlight = new Map<string, Promise<void>>();
  private nextRequestId = 1;

  constructor(options: LiveMCPTransportOptions = {}) {
    this.fetchImpl = bindFetchToGlobal(options.fetchImpl ?? globalThis.fetch);
    this.sessionStorageRef = options.sessionStorage;
    this.localStorageRef = options.localStorage;
    this.entraTokenProvider =
      options.entraTokenProvider ?? defaultEntraTokenProvider;
    this.maxRetries = Math.max(0, options.maxRetries ?? DEFAULT_MAX_RETRIES);
    this.baseRetryDelayMs = Math.max(
      1,
      options.baseRetryDelayMs ?? DEFAULT_BASE_RETRY_DELAY_MS,
    );
    this.random = options.random ?? Math.random;
    this.sleep =
      options.sleep ??
      ((ms, signal) =>
        new Promise((resolve) => {
          if (signal?.aborted) {
            resolve();
            return;
          }

          const onAbort = () => {
            clearTimeout(timeoutId);
            signal?.removeEventListener("abort", onAbort);
            resolve();
          };

          const timeoutId = setTimeout(() => {
            signal?.removeEventListener("abort", onAbort);
            resolve();
          }, ms);

          signal?.addEventListener("abort", onAbort, { once: true });
        }));
  }

  private async waitForPromiseOrAbort<T>(
    promise: Promise<T>,
    signal: AbortSignal | undefined,
    context: RequestContext,
  ): Promise<T> {
    if (!signal) {
      return promise;
    }

    if (signal.aborted) {
      throw this.abortError(context);
    }

    return await new Promise<T>((resolve, reject) => {
      let settled = false;
      const cleanup = () => {
        signal.removeEventListener("abort", onAbort);
      };

      const onAbort = () => {
        if (settled) return;
        settled = true;
        cleanup();
        reject(this.abortError(context));
      };

      signal.addEventListener("abort", onAbort, { once: true });
      promise.then(
        (value) => {
          if (settled) return;
          settled = true;
          cleanup();
          resolve(value);
        },
        (error) => {
          if (settled) return;
          settled = true;
          cleanup();
          reject(error);
        },
      );
    });
  }

  private invalidResponseError(
    context: RequestContext,
    message: string,
    cause?: unknown,
  ): AgentError {
    return createAgentError(
      context.operation === "discover"
        ? "MCP_DISCOVERY_FAILED"
        : context.operation === "call"
          ? "MCP_RESPONSE_INVALID"
          : "MCP_CONNECTION_UNAVAILABLE",
      message,
      {
        ...(cause !== undefined ? { cause } : {}),
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: false,
        },
      },
    );
  }

  private async parseJsonRpcEnvelope(
    response: Response,
    context: RequestContext,
  ): Promise<JsonRpcEnvelope> {
    let payload: unknown;
    try {
      payload = await response.json();
    } catch (error) {
      throw this.invalidResponseError(
        context,
        `MCP server ${context.connectionId} returned invalid JSON.`,
        error,
      );
    }

    if (!isJsonRpcEnvelope(payload)) {
      throw this.invalidResponseError(
        context,
        `MCP response for ${context.connectionId} was not a valid JSON-RPC envelope.`,
      );
    }

    return payload;
  }

  async listTools(
    connection: MCPNormalizedConnection,
    signal?: AbortSignal,
    options: { interactiveAllowed?: boolean } = {},
  ): Promise<MCPRemoteToolDescriptor[]> {
    const tools: MCPRemoteToolDescriptor[] = [];
    let cursor: string | undefined;

    do {
      const result = await this.sendRequest(
        connection,
        {
          jsonrpc: JSON_RPC_VERSION,
          id: this.takeRequestId(),
          method: "tools/list",
          params: cursor ? { cursor } : {},
        },
        {
          connectionId: connection.id,
          operation: "discover",
        },
        signal,
        { interactiveAllowed: options.interactiveAllowed },
      );

      if (!isPlainObject(result) || !Array.isArray(result.tools)) {
        throw createAgentError(
          "MCP_DISCOVERY_FAILED",
          `MCP discovery returned an invalid tools/list payload for ${connection.id}.`,
          {
            details: {
              connectionId: connection.id,
              retryable: false,
            },
          },
        );
      }

      for (const rawTool of result.tools) {
        if (!isPlainObject(rawTool) || typeof rawTool.name !== "string") {
          throw createAgentError(
            "MCP_DISCOVERY_FAILED",
            `MCP discovery returned a malformed tool descriptor for ${connection.id}.`,
            {
              details: {
                connectionId: connection.id,
                retryable: false,
              },
            },
          );
        }

        tools.push({
          name: rawTool.name,
          description:
            typeof rawTool.description === "string"
              ? rawTool.description
              : undefined,
          inputSchema: isPlainObject(rawTool.inputSchema)
            ? rawTool.inputSchema
            : undefined,
        });
      }

      cursor =
        typeof result.nextCursor === "string" && result.nextCursor.trim()
          ? result.nextCursor
          : undefined;
    } while (cursor);

    return tools;
  }

  async callTool(
    connection: MCPNormalizedConnection,
    remoteToolName: string,
    args: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<ToolResult> {
    if (signal?.aborted) {
      throw createAgentError(
        "MCP_TOOL_ABORTED",
        `MCP tool ${remoteToolName} cancelled before invocation.`,
        {
          details: {
            connectionId: connection.id,
            toolName: remoteToolName,
            retryable: false,
          },
        },
      );
    }

    const result = await this.sendRequest(
      connection,
      {
        jsonrpc: JSON_RPC_VERSION,
        id: this.takeRequestId(),
        method: "tools/call",
        params: {
          name: remoteToolName,
          arguments: args,
        },
      },
      {
        connectionId: connection.id,
        remoteToolName,
        operation: "call",
      },
      signal,
    );

    return this.mapToolResult(result, connection.id, remoteToolName);
  }

  closeConnection(connectionId: string): void {
    this.sessions.delete(connectionId);
    this.initInFlight.delete(connectionId);
  }

  private async sendRequest(
    connection: MCPNormalizedConnection,
    request: JsonRpcRequest,
    context: RequestContext,
    signal?: AbortSignal,
    options: { interactiveAllowed?: boolean } = {},
  ): Promise<Record<string, unknown>> {
    const interactiveAllowed = options.interactiveAllowed !== false;

    return await this.withEntraUnauthorizedRefresh(
      connection,
      context,
      async () => {
        await this.ensureInitialized(
          connection,
          context,
          signal,
          interactiveAllowed,
        );

        const result = await this.withRetries(
          async () => {
            const session = this.getSession(connection.id);
            const response =
              connection.transport === "streamable_http"
                ? await this.sendStreamableHttpMessage(
                    connection,
                    session,
                    request,
                    context,
                    signal,
                    interactiveAllowed,
                  )
                : await this.sendLegacySseMessage(
                    connection,
                    session,
                    request,
                    context,
                    signal,
                    interactiveAllowed,
                  );
            this.mergeSessionState(connection.id, response);
            return this.unwrapResponseEnvelope(response.json, context);
          },
          context,
          signal,
        );

        return result;
      },
      signal,
    );
  }

  private async ensureInitialized(
    connection: MCPNormalizedConnection,
    callerContext: RequestContext,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<void> {
    if (this.sessions.get(connection.id)?.initialized) {
      return;
    }

    // Single-flight: collapse concurrent first-touch handshakes onto one
    // initialize sequence so we never send `notifications/initialized` twice
    // for the same connection. Individual callers can still stop waiting on
    // their own AbortSignal without cancelling the shared handshake.
    const existing = this.initInFlight.get(connection.id);
    if (existing) {
      await this.waitForPromiseOrAbort(existing, signal, callerContext);
      return;
    }

    const initPromise = this.runInitialize(
      connection,
      signal,
      interactiveAllowed,
    );
    this.initInFlight.set(connection.id, initPromise);
    const clearInitPromise = () => {
      if (this.initInFlight.get(connection.id) === initPromise) {
        this.initInFlight.delete(connection.id);
      }
    };
    void initPromise.then(clearInitPromise, clearInitPromise);

    await this.waitForPromiseOrAbort(initPromise, signal, callerContext);
  }

  private async runInitialize(
    connection: MCPNormalizedConnection,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<void> {
    const initContext: RequestContext = {
      connectionId: connection.id,
      operation: "initialize",
    };

    await this.withRetries(async () => {
      if (this.sessions.get(connection.id)?.initialized) {
        return;
      }

      const baseSession: ConnectionSessionState = {
        initialized: false,
        protocolVersion: protocolVersionFor(connection),
      };

      const initializeRequest: JsonRpcRequest = {
        jsonrpc: JSON_RPC_VERSION,
        id: this.takeRequestId(),
        method: "initialize",
        params: {
          protocolVersion: baseSession.protocolVersion,
          capabilities: {},
          clientInfo: buildClientInfo(),
        },
      };

      const initializeResponse =
        connection.transport === "streamable_http"
          ? await this.sendStreamableHttpMessage(
              connection,
              baseSession,
              initializeRequest,
              initContext,
              signal,
              interactiveAllowed,
            )
          : await this.sendLegacySseMessage(
              connection,
              baseSession,
              initializeRequest,
              initContext,
              signal,
              interactiveAllowed,
            );

      const initializeResult = this.unwrapResponseEnvelope(
        initializeResponse.json,
        initContext,
      );

      const negotiatedProtocol =
        isPlainObject(initializeResult) &&
        typeof initializeResult.protocolVersion === "string" &&
        initializeResult.protocolVersion.trim()
          ? initializeResult.protocolVersion
          : baseSession.protocolVersion;

      const negotiatedSession: ConnectionSessionState = {
        initialized: false,
        protocolVersion: negotiatedProtocol,
        sessionId: initializeResponse.sessionId,
        legacyPostEndpoint: initializeResponse.legacyPostEndpoint,
      };

      await this.sendNotification(
        connection,
        negotiatedSession,
        {
          jsonrpc: JSON_RPC_VERSION,
          method: "notifications/initialized",
        },
        signal,
        interactiveAllowed,
      );

      const establishedSession = this.getSession(connection.id);
      this.sessions.set(connection.id, {
        initialized: true,
        protocolVersion:
          establishedSession.protocolVersion ??
          negotiatedSession.protocolVersion,
        sessionId: establishedSession.sessionId ?? negotiatedSession.sessionId,
        legacyPostEndpoint:
          establishedSession.legacyPostEndpoint ??
          negotiatedSession.legacyPostEndpoint,
      });
    }, initContext);
  }

  private async sendNotification(
    connection: MCPNormalizedConnection,
    session: ConnectionSessionState,
    notification: JsonRpcNotification,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<void> {
    const response =
      connection.transport === "streamable_http"
        ? await this.sendStreamableHttpMessage(
            connection,
            session,
            notification,
            {
              connectionId: connection.id,
              operation: "notify",
            },
            signal,
            interactiveAllowed,
          )
        : await this.sendLegacySseMessage(
            connection,
            session,
            notification,
            {
              connectionId: connection.id,
              operation: "notify",
            },
            signal,
            interactiveAllowed,
          );
    this.mergeSessionState(connection.id, response);
  }

  private async withRetries<T>(
    operation: () => Promise<T>,
    context: RequestContext,
    signal?: AbortSignal,
  ): Promise<T> {
    let attempt = 0;
    let lastError: unknown;

    while (attempt <= this.maxRetries) {
      if (signal?.aborted) {
        throw this.abortError(context);
      }
      try {
        return await operation();
      } catch (error) {
        lastError = error;
        if (
          !isAgentError(error) ||
          !isRetryableError(error) ||
          attempt >= this.maxRetries
        ) {
          throw error;
        }

        const delay = this.computeRetryDelay(attempt);
        attempt += 1;
        await this.sleep(delay, signal);
        if (signal?.aborted) {
          throw this.abortError(context);
        }
      }
    }

    throw lastError;
  }

  private computeRetryDelay(attempt: number): number {
    const base = this.baseRetryDelayMs * 2 ** attempt;
    return Math.floor(base + base * this.random());
  }

  private async sendStreamableHttpMessage(
    connection: MCPNormalizedConnection,
    session: ConnectionSessionState,
    message: JsonRpcRequest | JsonRpcNotification,
    context: RequestContext,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<TransportResponse> {
    const headers = await this.buildRequestHeaders(
      connection,
      session,
      true,
      context,
      signal,
      interactiveAllowed,
    );
    headers.set("Accept", "application/json, text/event-stream");
    headers.set("Content-Type", "application/json");

    const response = await this.fetchWithTimeout(
      connection.endpoint,
      {
        method: "POST",
        headers,
        body: JSON.stringify(message),
      },
      signal,
      connection.requestTimeoutMs,
      context,
    );

    if ((message as JsonRpcNotification).method.startsWith("notifications/")) {
      if (response.status === 202) {
        return {
          json: null,
          sessionId: response.headers.get("MCP-Session-Id") ?? undefined,
          protocolVersion:
            response.headers.get("MCP-Protocol-Version") ??
            session.protocolVersion,
        };
      }
      if (!response.ok) {
        throw await this.httpErrorFromResponse(response, context, connection);
      }
      return {
        json: null,
        sessionId: response.headers.get("MCP-Session-Id") ?? undefined,
        protocolVersion:
          response.headers.get("MCP-Protocol-Version") ??
          session.protocolVersion,
      };
    }

    if (!response.ok) {
      throw await this.httpErrorFromResponse(response, context, connection);
    }

    const contentType =
      response.headers.get("Content-Type")?.toLowerCase() ?? "";
    if (contentType.includes("application/json")) {
      const json = await this.parseJsonRpcEnvelope(response, context);
      return {
        json,
        sessionId: response.headers.get("MCP-Session-Id") ?? undefined,
        protocolVersion:
          response.headers.get("MCP-Protocol-Version") ??
          session.protocolVersion,
      };
    }

    if (contentType.includes("text/event-stream")) {
      const requestId = "id" in message ? message.id : null;
      const json = await this.readJsonRpcResponseFromSse(
        response,
        requestId,
        context,
        signal,
        AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs,
      );
      return {
        json,
        sessionId: response.headers.get("MCP-Session-Id") ?? undefined,
        protocolVersion:
          response.headers.get("MCP-Protocol-Version") ??
          session.protocolVersion,
      };
    }

    throw createAgentError(
      context.operation === "discover"
        ? "MCP_DISCOVERY_FAILED"
        : context.operation === "call"
          ? "MCP_RESPONSE_INVALID"
          : "MCP_CONNECTION_UNAVAILABLE",
      `MCP server ${connection.id} returned unsupported content type '${contentType || "<empty>"}'.`,
      {
        details: {
          connectionId: connection.id,
          toolName: context.remoteToolName,
          retryable: false,
        },
      },
    );
  }

  private async sendLegacySseMessage(
    connection: MCPNormalizedConnection,
    session: ConnectionSessionState,
    message: JsonRpcRequest | JsonRpcNotification,
    context: RequestContext,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<TransportResponse> {
    const headers = await this.buildRequestHeaders(
      connection,
      session,
      false,
      context,
      signal,
      interactiveAllowed,
    );
    headers.set("Accept", "text/event-stream");

    const response = await this.fetchWithTimeout(
      connection.endpoint,
      {
        method: "GET",
        headers,
      },
      signal,
      connection.requestTimeoutMs,
      context,
    );

    if (!response.ok) {
      throw await this.httpErrorFromResponse(response, context, connection);
    }

    const reader = response.body?.getReader();
    if (!reader) {
      throw createAgentError(
        context.operation === "discover"
          ? "MCP_DISCOVERY_FAILED"
          : "MCP_RESPONSE_INVALID",
        `Legacy MCP SSE response for ${context.connectionId} did not expose a readable stream.`,
        {
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: false,
          },
        },
      );
    }

    const decoder = new TextDecoder();
    let buffer = "";
    let postUrl = session.legacyPostEndpoint;
    let postPromise: Promise<void> | null = null;
    const requestId = "id" in message ? message.id : null;

    const startPost = async () => {
      if (!postUrl) {
        throw createAgentError(
          "MCP_CONNECTION_UNAVAILABLE",
          `Legacy MCP SSE server ${context.connectionId} did not announce a POST endpoint.`,
          {
            details: {
              connectionId: context.connectionId,
              toolName: context.remoteToolName,
              retryable: false,
            },
          },
        );
      }

      const postHeaders = await this.buildRequestHeaders(
        connection,
        session,
        false,
        context,
        signal,
        interactiveAllowed,
      );
      postHeaders.set("Content-Type", "application/json");
      postHeaders.set("Accept", "application/json");

      const postResponse = await this.fetchWithTimeout(
        postUrl,
        {
          method: "POST",
          headers: postHeaders,
          body: JSON.stringify(message),
        },
        signal,
        connection.requestTimeoutMs,
        context,
      );

      if (!postResponse.ok && postResponse.status !== 202) {
        throw await this.httpErrorFromResponse(
          postResponse,
          context,
          connection,
        );
      }
    };

    while (true) {
      if (signal?.aborted) {
        throw this.abortError(context);
      }

      const { done, value } = await readStreamChunkWithTimeout(reader, {
        signal,
        idleTimeoutMs: AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs,
        providerName: `MCP ${context.connectionId}`,
        createAbortError: () => this.abortError(context),
        createIdleTimeoutError: () => this.timeoutError(context),
      });
      if (done) {
        break;
      }

      buffer += decoder.decode(value, { stream: true }).replace(/\r\n/g, "\n");

      while (true) {
        const boundary = buffer.indexOf("\n\n");
        if (boundary < 0) {
          break;
        }

        const rawEvent = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);
        const parsed = this.parseSseEvent(rawEvent);
        if (!parsed) {
          continue;
        }

        if (parsed.event === "endpoint") {
          const endpointValue = parsed.data.trim();
          if (!endpointValue) {
            throw createAgentError(
              "MCP_CONNECTION_UNAVAILABLE",
              `Legacy MCP SSE endpoint announcement for ${context.connectionId} was empty.`,
              {
                details: {
                  connectionId: context.connectionId,
                  toolName: context.remoteToolName,
                  retryable: false,
                },
              },
            );
          }

          try {
            postUrl = new URL(endpointValue, connection.endpoint).toString();
          } catch (error) {
            throw createAgentError(
              "MCP_CONNECTION_UNAVAILABLE",
              `Legacy MCP SSE endpoint announcement for ${context.connectionId} was not a valid URL.`,
              {
                cause: error,
                details: {
                  connectionId: context.connectionId,
                  toolName: context.remoteToolName,
                  retryable: false,
                },
              },
            );
          }

          if (!postPromise) {
            postPromise = startPost();
          }

          if (
            (message as JsonRpcNotification).method.startsWith("notifications/")
          ) {
            await postPromise;
            await reader.cancel();
            return {
              json: null,
              legacyPostEndpoint: postUrl,
            };
          }

          continue;
        }

        if (
          (parsed.event === "message" || parsed.event === "") &&
          requestId !== null
        ) {
          let payload: unknown;
          try {
            payload = JSON.parse(parsed.data);
          } catch (error) {
            throw createAgentError(
              context.operation === "discover"
                ? "MCP_DISCOVERY_FAILED"
                : "MCP_RESPONSE_INVALID",
              `MCP SSE stream for ${context.connectionId} returned invalid JSON.`,
              {
                cause: error,
                details: {
                  connectionId: context.connectionId,
                  toolName: context.remoteToolName,
                  retryable: false,
                },
              },
            );
          }

          if (!isJsonRpcEnvelope(payload)) {
            continue;
          }

          const payloadId = payload.id;
          if (payloadId !== requestId) {
            continue;
          }

          if (postPromise) {
            await postPromise;
          }
          await reader.cancel();
          return {
            json: payload,
            legacyPostEndpoint: postUrl,
          };
        }
      }
    }

    if (postPromise) {
      await postPromise;
    }

    throw createAgentError(
      context.operation === "discover"
        ? "MCP_DISCOVERY_FAILED"
        : "MCP_RESPONSE_INVALID",
      `Legacy MCP SSE stream for ${context.connectionId} ended before returning a response.`,
      {
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: true,
        },
      },
    );
  }

  private async buildRequestHeaders(
    connection: MCPNormalizedConnection,
    session: ConnectionSessionState,
    includeProtocolHeader: boolean,
    context: RequestContext,
    signal?: AbortSignal,
    interactiveAllowed = true,
  ): Promise<Headers> {
    const headers = new Headers();
    if (includeProtocolHeader) {
      headers.set("MCP-Protocol-Version", session.protocolVersion);
    }
    if (session.sessionId) {
      headers.set("MCP-Session-Id", session.sessionId);
    }

    if (connection.auth.type === "entra") {
      try {
        const token = await this.entraTokenProvider.getToken({
          connectionId: connection.id,
          auth: connection.auth,
          interactiveAllowed,
          signal,
        });
        headers.set("Authorization", `Bearer ${token}`);
      } catch (error) {
        throw this.mapEntraTokenError(error, context);
      }
    } else {
      const authHeaders = this.resolveAuthHeaders(connection);
      for (const [key, value] of Object.entries(authHeaders)) {
        headers.set(key, value);
      }
    }

    return headers;
  }

  private async withEntraUnauthorizedRefresh<T>(
    connection: MCPNormalizedConnection,
    context: RequestContext,
    operation: () => Promise<T>,
    signal?: AbortSignal,
  ): Promise<T> {
    if (connection.auth.type !== "entra") {
      return await operation();
    }

    try {
      return await operation();
    } catch (error) {
      if (
        signal?.aborted ||
        !isAgentError(error) ||
        error.code !== "MCP_CONNECTION_UNAUTHORIZED" ||
        (error.details?.status !== 401 && error.details?.status !== 403)
      ) {
        throw error;
      }
      this.entraTokenProvider.invalidate({
        connectionId: connection.id,
        auth: connection.auth,
      });
      this.closeConnection(connection.id);
      try {
        return await operation();
      } catch (secondError) {
        if (
          isAgentError(secondError) &&
          secondError.code === "MCP_CONNECTION_UNAUTHORIZED"
        ) {
          throw createAgentError(
            "MCP_CONNECTION_UNAUTHORIZED",
            `MCP server rejected token for ${context.connectionId}. Verify the MCP API scope audience matches the server app registration.`,
            {
              cause: secondError,
              details: {
                ...secondError.details,
                connectionId: context.connectionId,
                toolName: context.remoteToolName,
                retryable: false,
              },
            },
          );
        }
        throw secondError;
      }
    }
  }

  private mapEntraTokenError(
    error: unknown,
    context: RequestContext,
  ): AgentError {
    if (isAgentError(error)) return error;
    if (isEntraTokenError(error)) {
      if (error.kind === "aborted") {
        return this.abortError(context);
      }
      if (error.kind === "interactive_required") {
        return createAgentError(
          "MCP_CONNECTION_UNAUTHORIZED",
          `MCP connection ${context.connectionId} needs Microsoft sign-in before a token can be retrieved.`,
          {
            details: {
              connectionId: context.connectionId,
              toolName: context.remoteToolName,
              retryable: false,
              authFailureStage: "token",
            },
          },
        );
      }
      if (error.kind === "unauthorized") {
        return createAgentError(
          "MCP_CONNECTION_UNAUTHORIZED",
          `Unable to retrieve an Entra access token for MCP connection ${context.connectionId}.`,
          {
            cause: error.cause,
            details: {
              connectionId: context.connectionId,
              toolName: context.remoteToolName,
              retryable: false,
              authFailureStage: "token",
            },
          },
        );
      }
      return createAgentError(
        "MCP_CONNECTION_UNAVAILABLE",
        `Unable to retrieve an Entra access token for MCP connection ${context.connectionId}.`,
        {
          cause: error.cause,
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: true,
          },
        },
      );
    }
    return createAgentError(
      "MCP_CONNECTION_UNAVAILABLE",
      `Unable to retrieve an Entra access token for MCP connection ${context.connectionId}.`,
      {
        cause: error,
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: true,
        },
      },
    );
  }

  private resolveAuthHeaders(
    connection: MCPNormalizedConnection,
  ): Record<string, string> {
    if (connection.auth.type === "none") {
      return {};
    }
    if (connection.auth.type === "entra") {
      return {};
    }

    const storage =
      connection.auth.type === "bearer"
        ? this.storageForScope(connection.auth.tokenRef.scope)
        : this.storageForScope(connection.auth.headerValueRef.scope);
    const key =
      connection.auth.type === "bearer"
        ? connection.auth.tokenRef.key
        : connection.auth.headerValueRef.key;
    const secret = storage?.getItem(key) ?? null;

    if (!secret) {
      throw createAgentError(
        "MCP_CONNECTION_UNAUTHORIZED",
        `Missing MCP secret for connection ${connection.id}.`,
        {
          details: {
            connectionId: connection.id,
            retryable: false,
          },
        },
      );
    }

    if (connection.auth.type === "bearer") {
      return { Authorization: `Bearer ${secret}` };
    }

    return { [connection.auth.headerName]: secret };
  }

  private storageForScope(scope: "session" | "local"): StorageLike | undefined {
    return scope === "session" ? this.sessionStorageRef : this.localStorageRef;
  }

  private async fetchWithTimeout(
    url: string,
    init: RequestInit,
    signal: AbortSignal | undefined,
    requestTimeoutMs: number,
    context: RequestContext,
  ): Promise<Response> {
    const timeoutController = new AbortController();
    let timedOut = false;
    const onAbort = () => timeoutController.abort();

    if (signal?.aborted) {
      timeoutController.abort();
    } else if (signal) {
      signal.addEventListener("abort", onAbort, { once: true });
    }

    const timeoutId = setTimeout(() => {
      timedOut = true;
      timeoutController.abort();
    }, requestTimeoutMs);

    const fetchContext: FetchLogContext = {
      ...context,
      url: sanitizeUrlForLog(url),
      method: init.method ?? "GET",
      startedAtMs: Date.now(),
    };

    logMcpTransport("debug", "fetch:start", {
      connectionId: fetchContext.connectionId,
      operation: fetchContext.operation,
      toolName: fetchContext.remoteToolName,
      method: fetchContext.method,
      url: fetchContext.url,
      requestTimeoutMs,
    });

    try {
      const response = await this.fetchImpl(url, {
        ...init,
        signal: timeoutController.signal,
      });
      logMcpTransport("debug", "fetch:response", {
        connectionId: fetchContext.connectionId,
        operation: fetchContext.operation,
        toolName: fetchContext.remoteToolName,
        method: fetchContext.method,
        url: fetchContext.url,
        status: response.status,
        ok: response.ok,
        contentType: response.headers.get("Content-Type") ?? "",
        durationMs: Math.max(0, Date.now() - fetchContext.startedAtMs),
      });
      return response;
    } catch (error) {
      if (signal?.aborted) {
        logMcpTransport("warn", "fetch:aborted", {
          connectionId: fetchContext.connectionId,
          operation: fetchContext.operation,
          toolName: fetchContext.remoteToolName,
          method: fetchContext.method,
          url: fetchContext.url,
          durationMs: Math.max(0, Date.now() - fetchContext.startedAtMs),
        });
        throw this.abortError(context);
      }
      if (timedOut) {
        logMcpTransport("warn", "fetch:timeout", {
          connectionId: fetchContext.connectionId,
          operation: fetchContext.operation,
          toolName: fetchContext.remoteToolName,
          method: fetchContext.method,
          url: fetchContext.url,
          requestTimeoutMs,
          durationMs: Math.max(0, Date.now() - fetchContext.startedAtMs),
        });
        throw this.timeoutError(context);
      }
      if (isAgentError(error)) {
        logMcpTransport("warn", "fetch:agent-error", {
          connectionId: fetchContext.connectionId,
          operation: fetchContext.operation,
          toolName: fetchContext.remoteToolName,
          method: fetchContext.method,
          url: fetchContext.url,
          durationMs: Math.max(0, Date.now() - fetchContext.startedAtMs),
          error: describeErrorForLog(error),
        });
        throw error;
      }
      logMcpTransport("warn", "fetch:failed-before-response", {
        connectionId: fetchContext.connectionId,
        operation: fetchContext.operation,
        toolName: fetchContext.remoteToolName,
        method: fetchContext.method,
        url: fetchContext.url,
        durationMs: Math.max(0, Date.now() - fetchContext.startedAtMs),
        error: describeErrorForLog(error),
        hint: "Browser fetch rejected before a response. Check CORS preflight, TLS/certificate trust, DNS, mixed content, or Office WebView network policy.",
      });
      throw createAgentError(
        context.operation === "discover"
          ? "MCP_DISCOVERY_FAILED"
          : context.operation === "call"
            ? "MCP_TOOL_INVOCATION_FAILED"
            : "MCP_CONNECTION_UNAVAILABLE",
        `MCP request for ${context.connectionId} failed before receiving a response.`,
        {
          cause: error,
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: true,
          },
        },
      );
    } finally {
      clearTimeout(timeoutId);
      signal?.removeEventListener("abort", onAbort);
    }
  }

  private abortError(context: RequestContext) {
    return createAgentError(
      context.operation === "call"
        ? "MCP_TOOL_ABORTED"
        : "MCP_CONNECTION_UNAVAILABLE",
      context.operation === "call"
        ? `MCP tool ${context.remoteToolName ?? "<unknown>"} was cancelled.`
        : `MCP request for ${context.connectionId} was cancelled.`,
      {
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: false,
        },
      },
    );
  }

  private timeoutError(context: RequestContext) {
    return createAgentError(
      context.operation === "call"
        ? "MCP_TOOL_TIMEOUT"
        : context.operation === "discover"
          ? "MCP_DISCOVERY_FAILED"
          : "MCP_CONNECTION_UNAVAILABLE",
      context.operation === "call"
        ? `MCP tool ${context.remoteToolName ?? "<unknown>"} timed out.`
        : `MCP request for ${context.connectionId} timed out.`,
      {
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: true,
        },
      },
    );
  }

  private async httpErrorFromResponse(
    response: Response,
    context: RequestContext,
    connection: MCPNormalizedConnection,
  ) {
    const bodyText = truncateText(await response.text());

    if (response.status === 401 || response.status === 403) {
      const isEntra = connection.auth.type === "entra";
      return createAgentError(
        "MCP_CONNECTION_UNAUTHORIZED",
        isEntra
          ? `MCP server rejected token for ${context.connectionId}.`
          : `MCP server rejected authentication for ${context.connectionId}. ${bodyText}`.trim(),
        {
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: false,
            status: response.status,
            ...(isEntra ? { diagnostic: bodyText } : {}),
          },
        },
      );
    }

    if (context.operation === "discover") {
      return createAgentError(
        "MCP_DISCOVERY_FAILED",
        `MCP discovery failed for ${context.connectionId} with HTTP ${response.status}. ${bodyText}`.trim(),
        {
          details: {
            connectionId: context.connectionId,
            retryable: response.status >= 500,
            status: response.status,
          },
        },
      );
    }

    if (context.operation === "call") {
      return createAgentError(
        "MCP_TOOL_INVOCATION_FAILED",
        `MCP tool ${context.remoteToolName ?? "<unknown>"} failed with HTTP ${response.status}. ${bodyText}`.trim(),
        {
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: response.status >= 500,
            status: response.status,
          },
        },
      );
    }

    return createAgentError(
      "MCP_CONNECTION_UNAVAILABLE",
      `MCP connection ${context.connectionId} returned HTTP ${response.status}. ${bodyText}`.trim(),
      {
        details: {
          connectionId: context.connectionId,
          retryable: response.status >= 500,
          status: response.status,
        },
      },
    );
  }

  private async readLegacySseEndpoint(
    response: Response,
    context: RequestContext,
    signal?: AbortSignal,
  ): Promise<string> {
    return this.consumeSse(
      response,
      context,
      signal,
      AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs,
      async (event) => {
        if (event.event !== "endpoint") {
          return undefined;
        }
        const value = event.data.trim();
        if (!value) {
          throw createAgentError(
            "MCP_CONNECTION_UNAVAILABLE",
            `Legacy MCP SSE endpoint announcement for ${context.connectionId} was empty.`,
            {
              details: {
                connectionId: context.connectionId,
                retryable: false,
              },
            },
          );
        }
        return value;
      },
    );
  }

  private async readJsonRpcResponseFromSse(
    response: Response,
    requestId: number | string | null,
    context: RequestContext,
    signal?: AbortSignal,
    streamIdleTimeoutMs: number = AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs,
  ): Promise<JsonRpcEnvelope> {
    return this.consumeSse(
      response,
      context,
      signal,
      streamIdleTimeoutMs,
      async (event) => {
        if (event.event !== "message" && event.event !== "") {
          return undefined;
        }

        let payload: unknown;
        try {
          payload = JSON.parse(event.data);
        } catch (error) {
          throw createAgentError(
            context.operation === "discover"
              ? "MCP_DISCOVERY_FAILED"
              : "MCP_RESPONSE_INVALID",
            `MCP SSE stream for ${context.connectionId} returned invalid JSON.`,
            {
              cause: error,
              details: {
                connectionId: context.connectionId,
                toolName: context.remoteToolName,
                retryable: false,
              },
            },
          );
        }

        if (!isJsonRpcEnvelope(payload)) {
          return undefined;
        }

        const payloadId = payload.id;
        if (requestId !== null && payloadId !== requestId) {
          return undefined;
        }

        return payload;
      },
    );
  }

  private async consumeSse<T>(
    response: Response,
    context: RequestContext,
    signal: AbortSignal | undefined,
    streamIdleTimeoutMs: number,
    onEvent: (event: SseEvent) => Promise<T | undefined>,
  ): Promise<T> {
    const reader = response.body?.getReader();
    if (!reader) {
      throw createAgentError(
        context.operation === "discover"
          ? "MCP_DISCOVERY_FAILED"
          : "MCP_RESPONSE_INVALID",
        `MCP SSE response for ${context.connectionId} did not expose a readable stream.`,
        {
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: false,
          },
        },
      );
    }

    const decoder = new TextDecoder();
    let buffer = "";

    while (true) {
      if (signal?.aborted) {
        throw this.abortError(context);
      }
      const { done, value } = await readStreamChunkWithTimeout(reader, {
        signal,
        idleTimeoutMs: streamIdleTimeoutMs,
        providerName: `MCP ${context.connectionId}`,
        createAbortError: () => this.abortError(context),
        createIdleTimeoutError: () => this.timeoutError(context),
      });
      if (done) {
        break;
      }
      buffer += decoder.decode(value, { stream: true }).replace(/\r\n/g, "\n");

      while (true) {
        const boundary = buffer.indexOf("\n\n");
        if (boundary < 0) {
          break;
        }
        const rawEvent = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary + 2);
        const parsed = this.parseSseEvent(rawEvent);
        if (!parsed) {
          continue;
        }
        const result = await onEvent(parsed);
        if (result !== undefined) {
          await reader.cancel();
          return result;
        }
      }
    }

    throw createAgentError(
      context.operation === "discover"
        ? "MCP_DISCOVERY_FAILED"
        : "MCP_RESPONSE_INVALID",
      `MCP SSE stream for ${context.connectionId} ended before returning a response.`,
      {
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: true,
        },
      },
    );
  }

  private parseSseEvent(rawEvent: string): SseEvent | null {
    const lines = rawEvent.split("\n");
    let event = "message";
    const dataLines: string[] = [];

    for (const line of lines) {
      if (!line || line.startsWith(":")) {
        continue;
      }
      const separator = line.indexOf(":");
      const field = separator >= 0 ? line.slice(0, separator) : line;
      const value = separator >= 0 ? line.slice(separator + 1).trimStart() : "";
      if (field === "event") {
        event = value;
      } else if (field === "data") {
        dataLines.push(value);
      }
    }

    if (dataLines.length === 0 && event !== "endpoint") {
      return null;
    }

    return {
      event,
      data: dataLines.join("\n"),
    };
  }

  private unwrapResponseEnvelope(
    envelope: JsonRpcEnvelope | null,
    context: RequestContext,
  ): Record<string, unknown> {
    if (!envelope) {
      return {};
    }
    if ("error" in envelope) {
      const message = envelope.error.message || "Unknown MCP JSON-RPC error";
      const lower = message.toLowerCase();
      const code =
        context.operation === "call" && lower.includes("unknown tool")
          ? "MCP_TOOL_NOT_FOUND"
          : context.operation === "discover"
            ? "MCP_DISCOVERY_FAILED"
            : context.operation === "call"
              ? "MCP_TOOL_INVOCATION_FAILED"
              : "MCP_CONNECTION_UNAVAILABLE";

      throw createAgentError(code, message, {
        details: {
          connectionId: context.connectionId,
          toolName: context.remoteToolName,
          retryable: false,
          jsonRpcCode: envelope.error.code,
          data: envelope.error.data,
        },
      });
    }
    if (!isPlainObject(envelope.result)) {
      throw createAgentError(
        context.operation === "discover"
          ? "MCP_DISCOVERY_FAILED"
          : "MCP_RESPONSE_INVALID",
        `MCP response for ${context.connectionId} was missing an object result.`,
        {
          details: {
            connectionId: context.connectionId,
            toolName: context.remoteToolName,
            retryable: false,
          },
        },
      );
    }
    return envelope.result;
  }

  private mapToolResult(
    result: Record<string, unknown>,
    connectionId: string,
    remoteToolName: string,
  ): ToolResult {
    if (!Array.isArray(result.content)) {
      throw createAgentError(
        "MCP_RESPONSE_INVALID",
        `MCP tool ${remoteToolName} returned an invalid content payload.`,
        {
          details: {
            connectionId,
            toolName: remoteToolName,
            retryable: false,
          },
        },
      );
    }

    const mappedContent: ToolContent[] = result.content.map((item) => {
      if (
        isPlainObject(item) &&
        item.type === "text" &&
        typeof item.text === "string"
      ) {
        return { type: "text", text: truncateText(item.text) };
      }
      if (
        isPlainObject(item) &&
        item.type === "image" &&
        typeof item.data === "string" &&
        typeof item.mimeType === "string"
      ) {
        return {
          type: "image",
          data: item.data,
          mimeType: item.mimeType,
        };
      }
      return {
        type: "text",
        text: truncateText(stringifyUnknown(item)),
      };
    });

    if (result.isError === true) {
      const message =
        mappedContent.find((item) => item.type === "text")?.text ||
        `MCP tool ${remoteToolName} reported an error.`;
      throw createAgentError("MCP_TOOL_INVOCATION_FAILED", message, {
        details: {
          connectionId,
          toolName: remoteToolName,
          retryable: false,
        },
      });
    }

    return {
      content:
        mappedContent.length > 0
          ? mappedContent
          : [
              {
                type: "text",
                text: `MCP tool ${remoteToolName} returned no content.`,
              },
            ],
    };
  }

  private mergeSessionState(
    connectionId: string,
    response: TransportResponse,
  ): void {
    const current = this.getSession(connectionId);
    this.sessions.set(connectionId, {
      initialized: current.initialized,
      protocolVersion: response.protocolVersion ?? current.protocolVersion,
      sessionId: response.sessionId ?? current.sessionId,
      legacyPostEndpoint:
        response.legacyPostEndpoint ?? current.legacyPostEndpoint,
    });
  }

  private getSession(connectionId: string): ConnectionSessionState {
    return (
      this.sessions.get(connectionId) ?? {
        initialized: false,
        protocolVersion: STREAMABLE_HTTP_PROTOCOL_VERSION,
      }
    );
  }

  private takeRequestId(): number {
    const next = this.nextRequestId;
    this.nextRequestId += 1;
    return next;
  }
}
