/**
 * Pure helper that translates an Azure 400 error body into incremental
 * fallback adjustments on the request options.
 *
 * Extracted from the old Azure agent implementation so PR-2 can land table-driven conformance
 * tests for the fallback chain without spinning up a real fetch loop.
 *
 * See docs/agent-refactor-implementation-plan.md PR-2 step 1.5.
 */

export type AzureFallbackAdjustment =
  | "max_tokens_swap"
  | "drop_stream_options"
  | "drop_temperature"
  | "drop_tools"
  | "drop_reasoning_effort";

export interface AzureFallbackResult {
  adjusted: boolean;
  adjustments: AzureFallbackAdjustment[];
}

/**
 * Mutates `currentOptions` in place with whatever adjustments the error
 * body indicates are necessary. Returns whether any adjustment was made
 * and which adjustment(s) were applied (for telemetry / tests).
 *
 * Mirrors the four conditional branches that lived inside
 * the legacy Azure streaming path.
 */
export function applyAzure400Fallback(
  currentOptions: Record<string, unknown>,
  errorText: string,
): AzureFallbackResult {
  const normalizedError = errorText.toLowerCase();
  const adjustments: AzureFallbackAdjustment[] = [];

  // 1. max_completion_tokens → max_tokens swap.
  if (
    Object.prototype.hasOwnProperty.call(
      currentOptions,
      "max_completion_tokens",
    ) &&
    (normalizedError.includes("max_completion_tokens") ||
      normalizedError.includes("unknown parameter") ||
      normalizedError.includes("unrecognized"))
  ) {
    currentOptions.max_tokens = currentOptions.max_completion_tokens;
    delete currentOptions.max_completion_tokens;
    adjustments.push("max_tokens_swap");
  }

  // 2. Drop stream_options when rejected.
  if (
    Object.prototype.hasOwnProperty.call(currentOptions, "stream_options") &&
    normalizedError.includes("stream_options")
  ) {
    delete currentOptions.stream_options;
    adjustments.push("drop_stream_options");
  }

  // 3. Drop temperature when rejected by reasoning/Responses deployments.
  // Covers both the legacy `unsupported_parameter` shape ("Unsupported
  // parameter: temperature is not supported") and the newer
  // `unsupported_value` shape ("Unsupported value: 'temperature' does not
  // support 0.2 with this model. Only the default (1) value is supported.")
  // that reasoning models such as `o1`/`o3`/`gpt-5` return when any
  // non-default temperature is sent.
  if (
    Object.prototype.hasOwnProperty.call(currentOptions, "temperature") &&
    normalizedError.includes("temperature") &&
    (normalizedError.includes("not supported") ||
      normalizedError.includes("does not support") ||
      normalizedError.includes("unsupported parameter") ||
      normalizedError.includes("unsupported value") ||
      normalizedError.includes("only the default"))
  ) {
    delete currentOptions.temperature;
    adjustments.push("drop_temperature");
  }

  // 4. Drop tools / tool_choice when function calling is unsupported.
  if (
    (Object.prototype.hasOwnProperty.call(currentOptions, "tools") ||
      Object.prototype.hasOwnProperty.call(currentOptions, "tool_choice")) &&
    (normalizedError.includes("tool") ||
      normalizedError.includes("function") ||
      normalizedError.includes("not supported"))
  ) {
    delete currentOptions.tools;
    delete currentOptions.tool_choice;
    adjustments.push("drop_tools");
  }

  // 5. Drop reasoning_effort / reasoning when the deployment is not a
  // reasoning model. Covers both chat-completions (`reasoning_effort`) and
  // the responses API (`reasoning: { effort }`). Matching is intentionally
  // strict — we only fire when the error body explicitly mentions the
  // reasoning field, so that an unrelated 400 (e.g. about a different
  // parameter) does not accidentally strip the user's selected effort.
  if (
    (Object.prototype.hasOwnProperty.call(currentOptions, "reasoning_effort") ||
      Object.prototype.hasOwnProperty.call(currentOptions, "reasoning")) &&
    normalizedError.includes("reasoning")
  ) {
    delete currentOptions.reasoning_effort;
    delete currentOptions.reasoning;
    adjustments.push("drop_reasoning_effort");
  }

  return { adjusted: adjustments.length > 0, adjustments };
}
