/**
 * MCP lifecycle manager (PR-3B.3).
 *
 * Coordinates per-connection lifecycle FSM, discovery (initial +
 * periodic refresh), per-turn frozen catalog snapshots, run-scoped
 * circuit breaker, and telemetry emission for the MCP subsystem.
 *
 * This module is deliberately decoupled from `Agent` construction —
 * runtime-config/Agent wiring is tracked separately in PR-3B.2/3
 * follow-ups. Tests inject a fake telemetry sink and a fake discovery
 * client to exercise the lifecycle without live transports.
 *
 * See docs/mcp-connection-contract.md §5–§6 and
 * docs/agent-refactor-implementation-plan.md §2.5.5 / §2.5.9–§2.5.10c.
 */

import { isAgentError } from "../errors";
import {
  DEFAULT_CIRCUIT_BREAKER_THRESHOLD,
  MCPCircuitBreaker,
  type MCPCircuitBreakerOptions,
  type MCPCircuitOpenEvent,
  type MCPCircuitResetEvent,
  type MCPToolFailureCode,
} from "./circuit-breaker";
import type { MCPDiscoveryClient } from "./client";
import {
  type MCPConnectionEvent,
  type MCPConnectionStateRecord,
  applyConnectionEvent,
  initialConnectionRecord,
} from "./connection-state";
import type {
  MCPConnectionState,
  MCPNormalizedConnection,
  MCPRemoteToolDescriptor,
} from "./types";

export const DEFAULT_REFRESH_INTERVAL_MS = 5 * 60 * 1000;

export interface MCPTelemetrySink {
  emit(name: string, properties: Record<string, string>): void;
}

export interface MCPLifecycleManagerOptions {
  connections: ReadonlyMap<string, MCPNormalizedConnection>;
  client: MCPDiscoveryClient;
  telemetry?: MCPTelemetrySink;
  now?: () => number;
  refreshIntervalMs?: number;
  circuitBreakerOptions?: MCPCircuitBreakerOptions;
}

export interface MCPCatalogSnapshot {
  /** Monotonic version that increases each time any catalog publish lands. */
  version: number;
  catalog: ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>>;
}

const DEFAULT_TELEMETRY_SINK: MCPTelemetrySink = {
  emit: () => {
    /* no-op: tests inject a recording sink */
  },
};

function redactSecrets(
  properties: Record<string, string>,
): Record<string, string> {
  // Defensive: callers MUST NOT include secrets, but redact known-bad
  // shapes (Authorization-style values) just in case.
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(properties)) {
    const lower = key.toLowerCase();
    if (
      lower.includes("token") ||
      lower.includes("secret") ||
      lower.includes("authorization")
    ) {
      out[key] = "<redacted>";
    } else {
      out[key] = value;
    }
  }
  return out;
}

export class MCPLifecycleManager {
  private readonly connections: ReadonlyMap<string, MCPNormalizedConnection>;
  private readonly client: MCPDiscoveryClient;
  private readonly telemetry: MCPTelemetrySink;
  private readonly now: () => number;
  private readonly refreshIntervalMs: number;
  private readonly states = new Map<string, MCPConnectionStateRecord>();
  private readonly catalog = new Map<
    string,
    ReadonlyArray<MCPRemoteToolDescriptor>
  >();
  private readonly breaker: MCPCircuitBreaker;
  private catalogVersion = 0;
  private refreshTimer: ReturnType<typeof setInterval> | null = null;
  private readonly discoveryGeneration = new Map<string, number>();
  private readonly discoveryControllers = new Map<string, AbortController>();

  constructor(options: MCPLifecycleManagerOptions) {
    this.connections = options.connections;
    this.client = options.client;
    this.telemetry = options.telemetry ?? DEFAULT_TELEMETRY_SINK;
    this.now = options.now ?? (() => Date.now());
    this.refreshIntervalMs = Math.max(
      1000,
      options.refreshIntervalMs ?? DEFAULT_REFRESH_INTERVAL_MS,
    );
    this.breaker = new MCPCircuitBreaker(options.circuitBreakerOptions);

    for (const [id, connection] of options.connections) {
      this.states.set(
        id,
        initialConnectionRecord(id, connection.enabled, this.now()),
      );
    }
  }

  // ---------------- lifecycle introspection ----------------

  getState(connectionId: string): MCPConnectionState | undefined {
    return this.states.get(connectionId)?.state;
  }

  getRecord(connectionId: string): MCPConnectionStateRecord | undefined {
    return this.states.get(connectionId);
  }

  /**
   * Snapshot the current published catalog. The returned map is a
   * shallow clone with frozen entries so mid-turn refreshes do not
   * affect dispatchers that captured this snapshot at turn start.
   */
  snapshotCatalog(): MCPCatalogSnapshot {
    const frozen = new Map<string, ReadonlyArray<MCPRemoteToolDescriptor>>();
    for (const [id, descriptors] of this.catalog) {
      frozen.set(id, descriptors.slice());
    }
    return {
      version: this.catalogVersion,
      catalog: frozen,
    };
  }

  /**
   * Live (un-frozen) catalog view for callers that explicitly opt out
   * of snapshot semantics (e.g. settings UI listing discovered tools).
   */
  liveCatalog(): ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>> {
    return this.catalog;
  }

  // ---------------- circuit breaker ----------------

  isToolUnavailable(connectionId: string, toolName: string): boolean {
    return this.breaker.isOpen(connectionId, toolName);
  }

  /**
   * Record a tool invocation outcome for breaker accounting. Emits
   * `mcp_tool_circuit_opened` exactly once on the transition. Should
   * be called by the dispatcher (or its caller) immediately after a
   * tool result settles. Per blueprint §4.1, only
   * `MCP_TOOL_INVOCATION_FAILED` counts toward the threshold; TIMEOUT
   * and ABORTED are ignored.
   */
  recordToolResult(
    connectionId: string,
    toolName: string,
    outcome: "success" | MCPToolFailureCode,
  ): MCPCircuitOpenEvent | null {
    const opened = this.breaker.recordResult(connectionId, toolName, outcome);
    if (opened) {
      this.emit("mcp_tool_circuit_opened", {
        connectionId: opened.connectionId,
        toolName: opened.toolName,
        failureCount: String(opened.failureCount),
        threshold: String(this.breakerThreshold()),
      });
    }
    return opened;
  }

  /**
   * Reset all open breakers and emit `mcp_tool_circuit_reset` per
   * pair so dashboards see matched open/close events. Callers MUST
   * invoke this at run end.
   */
  resetCircuitBreakers(): MCPCircuitResetEvent[] {
    const events = this.breaker.reset();
    for (const event of events) {
      this.emit("mcp_tool_circuit_reset", {
        connectionId: event.connectionId,
        toolName: event.toolName,
      });
    }
    return events;
  }

  private breakerThreshold(): number {
    // Internal accessor for telemetry; falls back to the documented
    // default when callers did not override it.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const t = (this.breaker as unknown as { threshold?: number }).threshold;
    return t ?? DEFAULT_CIRCUIT_BREAKER_THRESHOLD;
  }

  // ---------------- connect / refresh ----------------

  /**
   * Drive a connection through its handshake + initial discovery.
   * Idempotent: calling on an already-connected connection only
   * triggers a discovery refresh.
   */
  async connect(connectionId: string): Promise<void> {
    const connection = this.connections.get(connectionId);
    if (!connection) return;

    const current = this.states.get(connectionId);
    if (current?.state === "disabled") {
      return;
    }

    if (current?.state === "connecting") {
      return;
    }

    if (current?.state === "unauthorized") {
      // unauthorized requires explicit user action (re-enable / config
      // save). Silently no-op rather than retry.
      return;
    }

    if (current?.state === "failed") {
      // Terminal states require explicit `setEnabled(true)` / config
      // change to leave; `connect()` MUST NOT silently re-enable.
      return;
    }

    if (current?.state === "connected" || current?.state === "degraded") {
      await this.refresh(connectionId);
      return;
    }

    this.transition(connectionId, { type: "connect_start" });
    this.emit("mcp_connection_attempt", { connectionId });
    const discovery = this.beginDiscovery(connectionId);

    try {
      const tools = await this.client.listTools({
        connectionId,
        signal: discovery.signal,
        interactiveAllowed: true,
      });
      if (!this.isDiscoveryCurrent(connectionId, discovery.generation)) {
        return;
      }
      this.publishCatalog(connectionId, tools);
      this.transition(connectionId, { type: "handshake_success" });
      this.emit("mcp_discovery_completed", {
        connectionId,
        toolCount: String(tools.length),
      });
    } catch (error) {
      if (!this.isDiscoveryCurrent(connectionId, discovery.generation)) {
        return;
      }
      if (discovery.signal.aborted) {
        return;
      }
      this.handleConnectFailure(connectionId, error);
    } finally {
      this.finishDiscovery(connectionId, discovery.generation);
    }
  }

  /**
   * Refresh discovery for a single connection. Used by both the
   * periodic refresh tick and the manual refresh trigger from the
   * settings UI. Removed tools are evicted from the published catalog.
   */
  async refresh(connectionId: string): Promise<void> {
    const connection = this.connections.get(connectionId);
    const current = this.states.get(connectionId);
    if (!connection || current?.state === "disabled") {
      this.dropCatalog(connectionId);
      return;
    }

    if (current?.state !== "connected" && current?.state !== "degraded") {
      // Refresh only makes sense post-handshake; let `connect()`
      // handle the cold path.
      return;
    }

    const discovery = this.beginDiscovery(connectionId);

    try {
      const tools = await this.client.listTools({
        connectionId,
        signal: discovery.signal,
        interactiveAllowed: false,
      });
      if (!this.isDiscoveryCurrent(connectionId, discovery.generation)) {
        return;
      }
      this.publishCatalog(connectionId, tools);
      if (current.state === "degraded") {
        this.transition(connectionId, { type: "recovered" });
      }
      this.emit("mcp_discovery_completed", {
        connectionId,
        toolCount: String(tools.length),
      });
    } catch (error) {
      if (!this.isDiscoveryCurrent(connectionId, discovery.generation)) {
        return;
      }
      if (discovery.signal.aborted) {
        return;
      }
      this.handleRefreshFailure(connectionId, error);
    } finally {
      this.finishDiscovery(connectionId, discovery.generation);
    }
  }

  /**
   * Manual disconnect: drops the catalog and transitions to
   * `disconnected`. Closes underlying transport state.
   */
  disconnect(connectionId: string): void {
    if (!this.connections.has(connectionId)) return;
    this.invalidateDiscovery(connectionId);
    this.dropCatalog(connectionId);
    this.client.closeConnection(connectionId);
    this.transition(connectionId, { type: "disconnect" });
  }

  /**
   * Toggle a connection's enabled flag. Disabling drops the catalog
   * and closes transport state; enabling moves a `disabled`/`failed`
   * record back to `disconnected` so the next `connect()` call can
   * proceed.
   */
  setEnabled(connectionId: string, enabled: boolean): void {
    if (!this.connections.has(connectionId)) return;
    this.invalidateDiscovery(connectionId);
    if (enabled) {
      this.transition(connectionId, { type: "enable" });
    } else {
      this.dropCatalog(connectionId);
      this.client.closeConnection(connectionId);
      this.transition(connectionId, { type: "disable" });
    }
  }

  // ---------------- periodic refresh ----------------

  startPeriodicRefresh(): void {
    if (this.refreshTimer !== null) return;
    this.refreshTimer = setInterval(() => {
      void this.refreshAll();
    }, this.refreshIntervalMs);
  }

  stopPeriodicRefresh(): void {
    if (this.refreshTimer === null) return;
    clearInterval(this.refreshTimer);
    this.refreshTimer = null;
  }

  async refreshAll(): Promise<void> {
    await Promise.all(
      Array.from(this.connections.keys()).map((id) => this.refresh(id)),
    );
  }

  private beginDiscovery(connectionId: string): {
    generation: number;
    signal: AbortSignal;
  } {
    this.abortDiscovery(connectionId);
    const generation = (this.discoveryGeneration.get(connectionId) ?? 0) + 1;
    this.discoveryGeneration.set(connectionId, generation);
    const controller = new AbortController();
    this.discoveryControllers.set(connectionId, controller);
    return { generation, signal: controller.signal };
  }

  private invalidateDiscovery(connectionId: string): void {
    this.abortDiscovery(connectionId);
    this.discoveryGeneration.set(
      connectionId,
      (this.discoveryGeneration.get(connectionId) ?? 0) + 1,
    );
  }

  private abortDiscovery(connectionId: string): void {
    const controller = this.discoveryControllers.get(connectionId);
    if (!controller) {
      return;
    }
    controller.abort();
    this.discoveryControllers.delete(connectionId);
  }

  private isDiscoveryCurrent(
    connectionId: string,
    generation: number,
  ): boolean {
    return this.discoveryGeneration.get(connectionId) === generation;
  }

  private finishDiscovery(connectionId: string, generation: number): void {
    if (!this.isDiscoveryCurrent(connectionId, generation)) {
      return;
    }
    this.discoveryControllers.delete(connectionId);
  }

  // ---------------- internals ----------------

  private transition(connectionId: string, event: MCPConnectionEvent): void {
    const current = this.states.get(connectionId);
    if (!current) return;
    const result = applyConnectionEvent(current, event, this.now());
    this.states.set(connectionId, result.record);
    if (result.changed) {
      this.emit("mcp_connection_state_changed", {
        connectionId,
        previous: result.previous,
        next: result.next,
        ...(event.message ? { reason: event.message } : {}),
      });
    }
  }

  private publishCatalog(
    connectionId: string,
    tools: ReadonlyArray<MCPRemoteToolDescriptor>,
  ): void {
    this.catalog.set(connectionId, tools.slice());
    this.catalogVersion += 1;
  }

  private dropCatalog(connectionId: string): void {
    if (this.catalog.delete(connectionId)) {
      this.catalogVersion += 1;
    }
  }

  private handleConnectFailure(connectionId: string, error: unknown): void {
    const message = errorMessage(error);
    if (isAgentError(error) && error.code === "MCP_CONNECTION_UNAUTHORIZED") {
      this.transition(connectionId, {
        type: "handshake_unauthorized",
        message,
      });
    } else {
      this.transition(connectionId, {
        type: "handshake_failed",
        message,
      });
    }
  }

  private handleRefreshFailure(connectionId: string, error: unknown): void {
    const message = errorMessage(error);
    if (isAgentError(error) && error.code === "MCP_CONNECTION_UNAUTHORIZED") {
      this.transition(connectionId, {
        type: "handshake_unauthorized",
        message,
      });
      this.dropCatalog(connectionId);
      return;
    }
    this.transition(connectionId, {
      type: "transient_failure",
      message,
    });
  }

  private emit(name: string, properties: Record<string, string>): void {
    this.telemetry.emit(name, redactSecrets(properties));
  }
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return typeof error === "string" ? error : "unknown error";
}
