import { Type } from "@sinclair/typebox";
import {
  type DocumentIntelligenceConfig,
  getDocumentIntelligenceConfig,
  processDocumentWithIntelligence,
} from "../document-intelligence";
import { loadSavedConfig } from "../provider-config";
import { writeFile, fileExists, getFileStat } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

// Store attachment iterators for streaming
const attachmentIterators = new Map<
  string,
  AsyncGenerator<string, void, unknown>
>();

/**
 * Helper to fetch attachment data using Promise wrapper (exact pattern from getEmailData.js)
 */
async function getAttachmentData(
  item: Office.MessageRead,
  attachment: Office.AttachmentDetails,
): Promise<Office.AttachmentContent> {
  return new Promise((resolve, reject) => {
    item.getAttachmentContentAsync(attachment.id, (result) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(
          new Error(`Failed to get content for attachment: ${attachment.name}`),
        );
      }
    });
  });
}

/**
 * Store attachment base64 data in sessionStorage (exact pattern from getEmailData.js)
 */
function storeAttachmentInSessionStorage(
  attachmentId: string,
  base64Content: string,
): void {
  const key = `attachment_${attachmentId}`;
  sessionStorage.setItem(key, base64Content);
  console.log(
    `[email-read] Stored attachment in sessionStorage: ${attachmentId}`,
  );
}

/**
 * Returns a ReadableStream-like async iterator for the base-64 blob (exact pattern from getEmailData.js)
 */
async function* readAttachmentBase64Stream(
  attachmentId: string,
  chunk = 8192,
): AsyncGenerator<string, void, unknown> {
  console.log(`[email-read] readAttachmentBase64Stream: ${attachmentId}`);
  const key = `attachment_${attachmentId}`;
  const b64 = sessionStorage.getItem(key);
  if (!b64) return;

  for (let i = 0; i < b64.length; i += chunk) yield b64.slice(i, i + chunk);
}

/**
 * Start streaming an attachment by creating an iterator
 */
async function startAttachmentStream(attachmentId: string): Promise<boolean> {
  const iter = readAttachmentBase64Stream(attachmentId);
  attachmentIterators.set(attachmentId, iter);
  return true;
}

/**
 * Read next chunk from the attachment stream
 */
async function readNextChunk(attachmentId: string): Promise<string | null> {
  const iter = attachmentIterators.get(attachmentId);
  if (!iter) return null;

  const result = await iter.next();
  if (result.done) {
    attachmentIterators.delete(attachmentId);
    return null;
  }
  // The generator yields strings, so result.value must be string when not done
  return result.value as string;
}

/**
 * Get the full base64 content from sessionStorage
 */
function getAttachmentFromSessionStorage(attachmentId: string): string | null {
  const key = `attachment_${attachmentId}`;
  return sessionStorage.getItem(key);
}

interface EmailAttachment {
  name: string;
  contentType: string;
  size: number;
  id?: string;
  vfsPath?: string;
  parsedPath?: string;
}

type AnyAttachmentDetails =
  | Office.AttachmentDetails
  | Office.AttachmentDetailsCompose;

interface EmailDetails {
  subject: string;
  body: string;
  sender: {
    name: string;
    email: string;
  } | null;
  to: { name: string; email: string }[];
  cc: { name: string; email: string }[];
  bcc: { name: string; email: string }[];
  attachments: EmailAttachment[];
  importance: string;
  received?: string;
}

function parseRecipients(
  recipients: Office.EmailAddressDetails[] | undefined,
): { name: string; email: string }[] {
  if (!recipients) return [];
  return recipients.map((r) => ({
    name: r.displayName,
    email: r.emailAddress,
  }));
}

export const emailReadTool = defineTool({
  name: "email_read",
  category: "read",
  parallelSafe: false,
  label: "Read Email",
  description:
    "Read the current email message in Outlook. " +
    "Returns the subject, body, sender, recipients, attachments, and other properties. " +
    "Can optionally download attachment content to the virtual filesystem. " +
    "Use this to review an email before replying, forwarding, or analyzing its content.",
  parameters: Type.Object({
    bodyFormat: Type.Optional(
      Type.String({
        enum: ["text", "html"],
        description: "Format to return the body in. Default: 'text'",
        default: "text",
      }),
    ),
    includeAttachments: Type.Optional(
      Type.Boolean({
        description: "Whether to Include attachment metadata. Default: true",
        default: true,
      }),
    ),
    downloadAttachments: Type.Optional(
      Type.Boolean({
        description:
          "Download attachment content to /home/user/uploads/ (requires Mailbox 1.8). Default: false",
        default: false,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of why you're reading this email (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      const mailbox = Office.context.mailbox;
      if (!mailbox) {
        return toolError("Outlook mailbox is not available");
      }

      // Check if we have an item (email open in read/compose mode) or need to get selected items
      const item = mailbox.item;
      if (item) {
        return await readOpenEmail(item, params);
      }

      // Check if getSelectedItemsAsync is available (Mailbox 1.13+)
      if (
        Office.context?.requirements?.isSetSupported("Mailbox", "1.13") &&
        mailbox.getSelectedItemsAsync
      ) {
        return await readSelectedEmailsFromInbox(mailbox, params);
      }

      return toolError(
        "No email is currently open. To read emails from the inbox, Mailbox 1.13+ is required.",
      );
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error reading email";
      return toolError(message);
    }
  },
});

/**
 * Read an email that is currently open (read mode or compose mode)
 */
async function readOpenEmail(
  item: Office.MessageRead | Office.MessageCompose,
  params: {
    bodyFormat?: string;
    includeAttachments?: boolean;
    downloadAttachments?: boolean;
  },
): Promise<ReturnType<typeof toolSuccess>> {
  // Only works with messages (not appointments)
  if (item.itemType !== Office.MailboxEnums.ItemType.Message) {
    return toolError("Current item is not an email message");
  }

  // Check if attachment download is supported (Mailbox 1.8+)
  const canDownloadAttachments =
    params.downloadAttachments === true &&
    Office.context?.requirements?.isSetSupported("Mailbox", "1.8");

  const details = await new Promise<EmailDetails>((resolve) => {
    const result: EmailDetails = {
      subject: "",
      body: "",
      sender: null,
      to: [],
      cc: [],
      bcc: [],
      attachments: [],
      importance: "normal",
    };

    // Track pending operations - use an object for mutable reference in closures
    const state = { pendingOps: 0, resolved: false };
    const checkComplete = () => {
      if (state.pendingOps === 0 && !state.resolved) {
        state.resolved = true;
        resolve(result);
      }
    };

    // Detect read mode vs compose mode
    const isReadMode =
      "displayReplyForm" in item &&
      typeof (item as Office.MessageRead).displayReplyForm === "function";

    if (!isReadMode) {
      // Compose mode - use async APIs for recipients
      const msgCompose = item as Office.MessageCompose;

      // Subject
      if (typeof msgCompose.subject !== "undefined") {
        state.pendingOps++;
        msgCompose.subject.getAsync((asyncResult) => {
          if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
            result.subject = asyncResult.value;
          }
          state.pendingOps--;
          checkComplete();
        });
      }

      // Sender - not available in compose mode (user is the sender)
      result.sender = null;

      // Recipients - use async API in compose mode
      if (msgCompose.to) {
        state.pendingOps++;
        msgCompose.to.getAsync((asyncResult) => {
          if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
            result.to = parseRecipients(asyncResult.value);
          }
          state.pendingOps--;
          checkComplete();
        });
      }
      if (msgCompose.cc) {
        state.pendingOps++;
        msgCompose.cc.getAsync((asyncResult) => {
          if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
            result.cc = parseRecipients(asyncResult.value);
          }
          state.pendingOps--;
          checkComplete();
        });
      }
      if (msgCompose.bcc) {
        state.pendingOps++;
        msgCompose.bcc.getAsync((asyncResult) => {
          if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
            result.bcc = parseRecipients(asyncResult.value);
          }
          state.pendingOps--;
          checkComplete();
        });
      }
    } else {
      // Read mode - use direct properties
      const msgRead = item as Office.MessageRead;

      // Subject - available directly on MessageRead
      if (msgRead.subject !== undefined) {
        result.subject = msgRead.subject;
      }

      // Sender
      if (msgRead.from) {
        result.sender = {
          name: msgRead.from.displayName,
          email: msgRead.from.emailAddress,
        };
      }

      // Recipients - use direct properties for MessageRead (they are arrays)
      if (Array.isArray(msgRead.to)) {
        result.to = parseRecipients(msgRead.to);
      }
      if (Array.isArray(msgRead.cc)) {
        result.cc = parseRecipients(msgRead.cc);
      }
    }

    // Body
    const bodyFormat =
      params.bodyFormat === "html"
        ? Office.CoercionType.Html
        : Office.CoercionType.Text;
    state.pendingOps++;
    item.body.getAsync(bodyFormat, (asyncResult) => {
      if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
        result.body = asyncResult.value;
      }
      state.pendingOps--;
      checkComplete();
    });

    // Attachments (metadata + optional download)
    // Fallback to item.attachments if getAttachmentsAsync not available (e.g., compose mode)
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const rawAttachments = (item as any).attachments as
      | Office.AttachmentDetails[]
      | undefined;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const hasGetAttachmentsAsync =
      typeof (item as any).getAttachmentsAsync === "function";

    if (params.includeAttachments !== false) {
      if (hasGetAttachmentsAsync) {
        // Use async API to get attachments (read mode) - EXACT pattern from getEmailData.js
        state.pendingOps++;
        console.log(
          `[email-read] getAttachmentsAsync called, canDownloadAttachments=${canDownloadAttachments}`,
        );

        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (item as any).getAttachmentsAsync(
          (asyncResult: Office.AsyncResult<Office.AttachmentDetails[]>) => {
            console.log(
              `[email-read] getAttachmentsAsync callback invoked, status=${asyncResult.status}`,
            );
            if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
              const attachments = asyncResult.value || [];
              console.log(
                `[email-read] Found ${attachments.length} attachments`,
              );

              // Initialize result attachments
              result.attachments = attachments.map((att) => ({
                name: att.name,
                contentType: att.attachmentType,
                size: att.size,
                id: att.id,
              }));
            } else {
              console.warn(
                `[email-read] getAttachmentsAsync failed: ${asyncResult.error?.message || "Unknown error"}`,
              );
            }
            // Decrement pendingOps for getAttachmentsAsync
            state.pendingOps--;
            checkComplete();
          },
        );
      } else if (rawAttachments && rawAttachments.length > 0) {
        // Fallback to item.attachments (some compose modes)
        result.attachments = rawAttachments.map((att) => ({
          name: att.name,
          contentType: att.attachmentType,
          size: att.size,
          id: att.id,
        }));
      }
    }

    // Date received - only available in read mode
    if (isReadMode) {
      const msgRead = item as Office.MessageRead;
      if (msgRead.dateTimeCreated) {
        result.received = msgRead.dateTimeCreated.toISOString();
      }
    }

    checkComplete();
  });

  // Process attachment downloads AFTER the Promise resolves (like getEmailData.js pattern)
  // This ensures Office.js callbacks have completed before we start async operations
  const msgReadItem = item as Office.MessageRead;
  const canGetAttachmentContent =
    typeof msgReadItem.getAttachmentContentAsync === "function";

  console.log(
    `[email-read] Post-resolve: attachments=${details.attachments.length}, canDownload=${canDownloadAttachments}, canGetContent=${canGetAttachmentContent}`,
  );

  if (
    canDownloadAttachments &&
    details.attachments.length > 0 &&
    canGetAttachmentContent
  ) {
    console.log(
      `[email-read] Processing ${details.attachments.length} attachments for download (post-resolve)`,
    );

    // Get Document Intelligence config if needed
    const providerConfig = loadSavedConfig();
    const diConfig = providerConfig
      ? getDocumentIntelligenceConfig(providerConfig)
      : null;

    for (const att of details.attachments) {
      if (!att.id) {
        console.warn(`[email-read] Attachment has no id: ${att.name}`);
        continue;
      }
      console.log(
        `[email-read] Starting download for: ${att.name} (${att.id})`,
      );
      try {
        // Use Promise wrapper like getEmailData.js
        // Need to cast attachment to Office.AttachmentDetails for the API
        const attachmentDetails = att as unknown as Office.AttachmentDetails;
        const attachmentContent = await getAttachmentData(
          msgReadItem,
          attachmentDetails,
        );
        console.log(
          `[email-read] Got attachment content: ${attachmentContent ? "yes" : "no"}`,
        );

        if (!attachmentContent || !attachmentContent.content) {
          console.warn(`[email-read] No content for attachment: ${att.name}`);
          continue;
        }

        console.log(
          `[email-read] Content length: ${attachmentContent.content.length}`,
        );

        // Store base64 content in sessionStorage (exact pattern from getEmailData.js)
        storeAttachmentInSessionStorage(att.id, attachmentContent.content);

        // Read back from sessionStorage using stream (exact pattern from getEmailData.js)
        const base64Content = getAttachmentFromSessionStorage(att.id);
        if (!base64Content) {
          console.warn(
            `[email-read] Failed to retrieve attachment from sessionStorage: ${att.name}`,
          );
          continue;
        }

        // Decode base64 content and save to VFS
        console.log(
          `[email-read] Decoding base64 content (${base64Content.length} chars)`,
        );
        const binaryString = atob(base64Content);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        console.log(`[email-read] Decoded to ${bytes.length} bytes`);

        // Sanitize filename for filesystem
        const safeName = att.name.replace(/[^a-zA-Z0-9._-]/g, "_");
        const vfsPath = `/home/user/uploads/${safeName}`;
        console.log(`[email-read] Writing to VFS: ${vfsPath}`);

        // Write original file to VFS
        await writeFile(vfsPath, bytes);

        // Verify file was written correctly
        const fileStat = await getFileStat(vfsPath);
        if (!fileStat) {
          console.warn(`[email-read] Failed to verify file in VFS: ${vfsPath}`);
          continue;
        }
        if (fileStat.size === 0) {
          console.warn(
            `[email-read] WARNING: File written to VFS is empty (0 bytes): ${vfsPath}`,
          );
        } else {
          console.log(
            `[email-read] Successfully wrote ${fileStat.size} bytes to VFS: ${vfsPath}`,
          );
        }

        // Update the attachment info
        const existing = details.attachments.find((a) => a.id === att.id);
        if (existing) {
          existing.vfsPath = vfsPath;
          if (fileStat.size === 0) {
            existing.size = 0;
          }
        }

        // Process with Document Intelligence if available
        if (diConfig) {
          try {
            const file = new File([bytes], att.name, {
              type: getAttachmentMimeType(att.name),
            });
            const diResult = await processDocumentWithIntelligence(
              file,
              bytes,
              diConfig,
            );
            if (diResult.parsedPath && existing) {
              existing.parsedPath = diResult.parsedPath;
              console.log(
                `[email-read] Document Intelligence parsed attachment to: ${diResult.parsedPath}`,
              );
            }
          } catch (diError) {
            console.warn(
              `[email-read] Document Intelligence failed for ${att.name}:`,
              diError,
            );
          }
        }
      } catch (err) {
        console.error(
          `[email-read] Failed to download attachment ${att.name}:`,
          err instanceof Error ? err.message : String(err),
        );
      }
    }

    console.log("[email-read] All attachment downloads completed");
  }

  return toolSuccess({
    success: true,
    ...details,
    attachmentDownloadSupported: canDownloadAttachments,
  });
}

/**
 * Read selected emails from the inbox without opening them
 * Requires Mailbox 1.13+
 */
async function readSelectedEmailsFromInbox(
  mailbox: Office.Mailbox,
  _params: {
    bodyFormat?: string;
    includeAttachments?: boolean;
    downloadAttachments?: boolean;
  },
): Promise<ReturnType<typeof toolSuccess>> {
  return new Promise((resolve) => {
    mailbox.getSelectedItemsAsync!((result) => {
      if (result.status !== Office.AsyncResultStatus.Succeeded) {
        resolve(
          toolError(`Failed to get selected items: ${result.error?.message}`),
        );
        return;
      }

      const items = result.value || [];
      if (items.length === 0) {
        resolve(toolError("No emails are selected in the inbox"));
        return;
      }

      // For now, return basic info about selected emails
      // Full body and attachment content would require EWS or Graph API calls
      const selectedEmails = items.map((item) => ({
        subject: (item as { subject?: string }).subject || "",
        itemId: item.itemId,
        itemType: item.itemType,
      }));

      resolve(
        toolSuccess({
          success: true,
          selectedEmails,
          count: items.length,
          note: "Selected emails from inbox. Open an email to read full content including body and attachments.",
        }),
      );
    });
  });
}

/**
 * Get MIME type for attachment based on file extension
 */
function getAttachmentMimeType(filename: string): string {
  const ext = filename.toLowerCase().split(".").pop();
  const mimeTypes: Record<string, string> = {
    pdf: "application/pdf",
    docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    doc: "application/msword",
    xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    xls: "application/vnd.ms-excel",
    pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    ppt: "application/vnd.ms-powerpoint",
    png: "image/png",
    jpg: "image/jpeg",
    jpeg: "image/jpeg",
    tiff: "image/tiff",
    bmp: "image/bmp",
    txt: "text/plain",
    csv: "text/csv",
  };
  return mimeTypes[ext ?? ""] || "application/octet-stream";
}
