import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

const SPACING_PREVIEW_LIMIT = 20;
type SpacingFixType =
  | "period-space"
  | "comma-space"
  | "semicolon-space"
  | "colon-space"
  | "multiple-spaces";

type SpacingFixOperation = {
  type: SpacingFixType;
  searchText: string;
  replaceText: string;
  occurrences: number;
  countPerOccurrence: number;
};

export const fixSpacingTool = defineTool({
  name: "fix_spacing",
  category: "deliverable",
  parallelSafe: false,
  label: "Fix Text Spacing",
  description:
    "Fix common spacing issues in Word documents. " +
    "Can add missing spaces after periods, fix multiple spaces, and normalize spacing around punctuation. " +
    "Use this to clean up formatting issues like 'word.This' becoming 'word. This'.",
  parameters: Type.Object({
    scope: Type.Union(
      [
        Type.Literal("document", { description: "Fix entire document" }),
        Type.Literal("selection", { description: "Fix selected text only" }),
      ],
      { description: "What to fix", default: "document" },
    ),
    fixes: Type.Array(
      Type.Union([
        Type.Literal("period-space", {
          description: "Add space after periods: 'word.This' → 'word. This'",
        }),
        Type.Literal("comma-space", {
          description: "Add space after commas: 'word,word' → 'word, word'",
        }),
        Type.Literal("semicolon-space", {
          description: "Add space after semicolons: 'word;word' → 'word; word'",
        }),
        Type.Literal("colon-space", {
          description: "Add space after colons in sentences",
        }),
        Type.Literal("multiple-spaces", {
          description: "Replace multiple spaces with single space",
        }),
        Type.Literal("all", {
          description: "Apply all spacing fixes",
        }),
      ]),
      {
        description: "Which spacing fixes to apply",
        default: ["all"],
      },
    ),
    previewOnly: Type.Optional(
      Type.Boolean({
        description:
          "Preview planned spacing fixes without applying them. Default: false",
        default: false,
      }),
    ),
    maxEdits: Type.Optional(
      Type.Number({
        description:
          "Maximum number of spacing edits allowed before the tool refuses to apply changes. Must be a positive integer.",
        minimum: 1,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation of spacing fix (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      const fixList: SpacingFixType[] = params.fixes.includes("all")
        ? [
            "period-space",
            "comma-space",
            "semicolon-space",
            "colon-space",
            "multiple-spaces",
          ]
        : (Array.from(new Set(params.fixes)) as SpacingFixType[]);
      const previewOnly = params.previewOnly ?? false;
      const maxEdits = normalizeMaxEdits(params.maxEdits);

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          !previewOnly,
          async () => {
            throwIfToolAborted(signal);
            const body = context.document.body;
            const range =
              params.scope === "selection"
                ? context.document.getSelection()
                : body.getRange();

            const analysis = await analyzeSpacingFixes(
              context,
              range,
              fixList,
              signal,
            );

            if (previewOnly) {
              return {
                previewOnly: true,
                totalPotentialEdits: analysis.totalPotentialEdits,
                scope: params.scope,
                fixesRequested: fixList,
                fixSummaries: analysis.fixSummaries,
                preview: analysis.preview,
                previewTruncated: analysis.previewTruncated,
                maxEdits,
                exceedsMaxEdits:
                  maxEdits !== undefined &&
                  analysis.totalPotentialEdits > maxEdits,
              };
            }

            if (
              maxEdits !== undefined &&
              analysis.totalPotentialEdits > maxEdits
            ) {
              return {
                applied: false,
                blockedByMaxEdits: true,
                totalPotentialEdits: analysis.totalPotentialEdits,
                scope: params.scope,
                fixesRequested: fixList,
                fixSummaries: analysis.fixSummaries,
                preview: analysis.preview,
                previewTruncated: analysis.previewTruncated,
                maxEdits,
                message:
                  `Planned ${analysis.totalPotentialEdits} spacing fixes exceeds maxEdits ${maxEdits}. ` +
                  "Use previewOnly, narrow the scope, or increase maxEdits.",
              };
            }

            const appliedFixCounts = new Map<SpacingFixType, number>();

            for (const operation of analysis.operations) {
              throwIfToolAborted(signal);
              const searchResult = range.search(operation.searchText, {
                matchCase: true,
                matchWholeWord: false,
                matchWildcards: false,
              });

              searchResult.load("items/text");
              await syncWordContext(context, signal);

              let appliedOccurrences = 0;
              for (const item of searchResult.items) {
                if ((item.text ?? "") !== operation.searchText) {
                  continue;
                }

                item.insertText(
                  operation.replaceText,
                  Word.InsertLocation.replace,
                );
                appliedOccurrences++;
              }

              if (appliedOccurrences === 0) {
                continue;
              }

              await syncWordContext(context, signal);

              const appliedCount =
                appliedOccurrences * operation.countPerOccurrence;
              appliedFixCounts.set(
                operation.type,
                (appliedFixCounts.get(operation.type) ?? 0) + appliedCount,
              );
            }

            const fixesApplied = fixList
              .map((type) => ({ type, count: appliedFixCounts.get(type) ?? 0 }))
              .filter((fix) => fix.count > 0);

            return {
              fixesApplied,
              totalFixes: fixesApplied.reduce((sum, f) => sum + f.count, 0),
              scope: params.scope,
              fixesRequested: fixList,
              previewOnly: false,
              maxEdits,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error fixing spacing";
      return toolError(message);
    }
  },
});

function normalizeMaxEdits(maxEdits?: number): number | undefined {
  if (maxEdits === undefined) {
    return undefined;
  }

  if (!Number.isInteger(maxEdits) || maxEdits < 1) {
    throw new Error("maxEdits must be a positive integer");
  }

  return maxEdits;
}

async function analyzeSpacingFixes(
  context: Word.RequestContext,
  range: Word.Range,
  fixList: string[],
  signal?: AbortSignal,
): Promise<{
  totalPotentialEdits: number;
  fixSummaries: Array<{ type: string; count: number }>;
  operations: SpacingFixOperation[];
  preview: Array<{
    type: SpacingFixType;
    before: string;
    after: string;
    operations: number;
  }>;
  previewTruncated: boolean;
}> {
  range.load("text");
  await syncWordContext(context, signal);

  return buildSpacingAnalysis(range.text ?? "", fixList as SpacingFixType[]);
}

function buildSpacingAnalysis(
  text: string,
  fixList: SpacingFixType[],
): {
  totalPotentialEdits: number;
  fixSummaries: Array<{ type: string; count: number }>;
  operations: SpacingFixOperation[];
  preview: Array<{
    type: SpacingFixType;
    before: string;
    after: string;
    operations: number;
  }>;
  previewTruncated: boolean;
} {
  const preview: Array<{
    type: SpacingFixType;
    before: string;
    after: string;
    operations: number;
  }> = [];
  let previewTruncated = false;
  const fixSummaries: Array<{ type: string; count: number }> = [];
  const operationMap = new Map<string, SpacingFixOperation>();

  const pushPreview = (entry: {
    type: SpacingFixType;
    before: string;
    after: string;
    operations: number;
  }) => {
    if (preview.length < SPACING_PREVIEW_LIMIT) {
      preview.push(entry);
    } else {
      previewTruncated = true;
    }
  };

  const addOperation = (operation: {
    type: SpacingFixType;
    searchText: string;
    replaceText: string;
    countPerOccurrence: number;
  }) => {
    const key = [
      operation.type,
      operation.searchText,
      operation.replaceText,
      String(operation.countPerOccurrence),
    ].join("\u0000");
    const existing = operationMap.get(key);
    if (existing) {
      existing.occurrences += 1;
      return;
    }

    operationMap.set(key, {
      ...operation,
      occurrences: 1,
    });
  };

  const addRegexFix = (
    type: Exclude<SpacingFixType, "multiple-spaces">,
    regex: RegExp,
    buildAfter: (match: RegExpExecArray) => string,
  ) => {
    let count = 0;
    for (const match of text.matchAll(regex)) {
      const searchText = match[0];
      const replaceText = buildAfter(match);
      count += 1;
      pushPreview({
        type,
        before: searchText,
        after: replaceText,
        operations: 1,
      });
      addOperation({
        type,
        searchText,
        replaceText,
        countPerOccurrence: 1,
      });
    }

    if (count > 0) {
      fixSummaries.push({ type, count });
    }
  };

  if (fixList.includes("period-space")) {
    addRegexFix("period-space", /([a-zA-Z0-9])\.([a-zA-Z])/g, (match) => {
      return `${match[1]}. ${match[2]}`;
    });
  }

  if (fixList.includes("comma-space")) {
    addRegexFix("comma-space", /([a-zA-Z0-9]),([a-zA-Z])/g, (match) => {
      return `${match[1]}, ${match[2]}`;
    });
  }

  if (fixList.includes("semicolon-space")) {
    addRegexFix("semicolon-space", /([a-zA-Z0-9]);([a-zA-Z])/g, (match) => {
      return `${match[1]}; ${match[2]}`;
    });
  }

  if (fixList.includes("colon-space")) {
    addRegexFix("colon-space", /([a-zA-Z0-9]):([a-zA-Z])/g, (match) => {
      return `${match[1]}: ${match[2]}`;
    });
  }

  if (fixList.includes("multiple-spaces")) {
    let count = 0;
    for (const match of text.matchAll(/ {2,}/g)) {
      const operations = match[0].length - 1;
      const searchText = match[0];
      count += operations;
      pushPreview({
        type: "multiple-spaces",
        before: searchText,
        after: " ",
        operations,
      });
      addOperation({
        type: "multiple-spaces",
        searchText,
        replaceText: " ",
        countPerOccurrence: operations,
      });
    }

    if (count > 0) {
      fixSummaries.push({ type: "multiple-spaces", count });
    }
  }

  return {
    totalPotentialEdits: fixSummaries.reduce((sum, fix) => sum + fix.count, 0),
    fixSummaries,
    operations: Array.from(operationMap.values()),
    preview,
    previewTruncated,
  };
}
