/**
 * OpenAIProvider — provider implementation for OpenAI chat-completions
 * compatible endpoints (api.openai.com and OpenAI-compatible reverse proxies).
 *
 * PR-3 step 2.1: encapsulates wire-format conversion, retry policy,
 * SSE streaming, and chunk decoding behind the {@link LLMProvider} interface.
 *
 * The provider owns ONLY: HTTP transport, request/response shape, and
 * stream decoding via the shared helpers. It MUST NOT mutate orchestrator
 * state, push messages, emit agent events, or make loop decisions.
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §7
 *   - docs/agent-refactor-implementation-plan.md Phase 2
 */

import { AIRGAP_CONFIG } from "../../airgap-config";
import { prepareMessagesForApi } from "../../token-manager";
import type { WorkflowManager } from "../../workflow";
import { type AgentError, asAgentError, createAgentError } from "../errors";
import type { AgentMessage, Tool } from "../types";
import type {
  JSONSchema,
  LLMProvider,
  LLMTurnRequest,
  LLMTurnResult,
  StructuredOutputOptions,
  TokenEstimate,
} from "./provider";
import { convertMessagesToChatCompletions } from "./shared/message-format";
import { buildReasoningOptions, isReasoningModel } from "./shared/reasoning";
import {
  decodeChatCompletionStream,
  hasMeaningfulChatCompletionDelta,
} from "./shared/stream-decoder";
import {
  isStreamIdleTimeoutError,
  readStreamChunkWithTimeout,
} from "./shared/stream-read";

export interface OpenAIProviderConfig {
  apiKey: string;
  model: string;
  baseUrl?: string;
  /** Max retries for the provider's internal HTTP retry loop. */
  maxRetries?: number;
  /** Workflow manager used for rate limiting and recoverable HTTP error reporting. */
  workflowManager: WorkflowManager;
}

interface RawStreamChunk {
  choices?: Array<{
    delta?: {
      content?: string;
      reasoning_content?: string;
      tool_calls?: Array<{
        index?: number;
        id?: string;
        function?: { name?: string; arguments?: string };
      }>;
    };
    finish_reason?: string | null;
  }>;
  usage?: {
    prompt_tokens?: number;
    completion_tokens?: number;
    total_tokens?: number;
  };
}

export class OpenAIProvider implements LLMProvider {
  readonly id = "openai" as const;

  private readonly config: OpenAIProviderConfig;
  private readonly logPrefix = "[OpenAIProvider]";

  constructor(config: OpenAIProviderConfig) {
    this.config = {
      maxRetries: 3,
      baseUrl: "https://api.openai.com/v1",
      ...config,
    };
  }

  setWorkflowManager(workflowManager: WorkflowManager): void {
    (this.config as { workflowManager: WorkflowManager }).workflowManager =
      workflowManager;
  }

  /**
   * PR-9b: orchestrator-side token budget calls this to get the exact
   * wire-shape tools JSON. OpenAI uses the chat-completions function-tool
   * shape unconditionally.
   */
  toToolsJsonForBudget(tools: Tool[]): string {
    return JSON.stringify(this.convertToolsToOpenAIFormat(tools));
  }

  estimateTokens(
    messages: AgentMessage[],
    systemPrompt: string,
    tools: Tool[],
  ): TokenEstimate {
    const toolsJson = this.toToolsJsonForBudget(tools);
    const result = prepareMessagesForApi(
      messages,
      systemPrompt,
      toolsJson,
      undefined,
    );
    return {
      inputTokens: result.tokenCount.total,
      perMessageOverhead: result.tokenCount.messages,
      toolSchemaTokens: result.tokenCount.tools,
    };
  }

  async runTurn(req: LLMTurnRequest): Promise<LLMTurnResult> {
    try {
      const wireMessages = convertMessagesToChatCompletions(
        req.messages,
        req.systemPrompt,
        { logPrefix: this.logPrefix },
      ).messages;

      const wireTools =
        req.tools.length > 0
          ? this.convertToolsToOpenAIFormat(req.tools)
          : undefined;

      // Reasoning models (o1/o3/o4/gpt-5*) reject any non-default
      // temperature. The OpenAI provider has no 400 fallback chain, so
      // this check is the only safeguard.
      const omitTemperature =
        isReasoningModel(this.config.model) || req.thinkingLevel !== "off";

      const options: Record<string, unknown> = {
        tools: wireTools,
        tool_choice: req.tools.length > 0 ? "auto" : undefined,
        ...(omitTemperature ? {} : { temperature: 0.2 }),
        max_completion_tokens: req.maxOutputTokens,
        stream_options: { include_usage: true },
        // Apply the user-selected reasoning effort, but only for known
        // reasoning model families. OpenAI returns a non-recoverable 400
        // when this field is sent to a non-reasoning model (e.g. gpt-4o).
        ...(isReasoningModel(this.config.model)
          ? buildReasoningOptions(req.thinkingLevel, "chat-completions")
          : {}),
      };

      const events = this.streamChatCompletions(
        wireMessages,
        options,
        req.abortSignal,
      );

      return await this.decodeStream(events, req.abortSignal);
    } catch (error) {
      if (req.abortSignal.aborted) {
        throw error;
      }
      throw this.mapProviderError(error);
    }
  }

  async runStructured<T>(
    req: LLMTurnRequest,
    schema: JSONSchema,
    options: StructuredOutputOptions,
  ): Promise<T> {
    try {
      const wireMessages = convertMessagesToChatCompletions(
        req.messages,
        req.systemPrompt,
        { logPrefix: this.logPrefix },
      ).messages;

      // Mirror runTurn: reasoning models reject non-default temperature.
      const omitTemperature =
        isReasoningModel(this.config.model) || req.thinkingLevel !== "off";

      const requestOptions: Record<string, unknown> = {
        tools: [this.createStructuredTool(options.toolName, schema)],
        tool_choice: {
          type: "function",
          function: { name: options.toolName },
        },
        ...(omitTemperature ? {} : { temperature: 0.2 }),
        max_completion_tokens: req.maxOutputTokens,
        stream_options: { include_usage: true },
        // Mirror runTurn: honour reasoning effort for structured planner
        // submissions on reasoning model families only.
        ...(isReasoningModel(this.config.model)
          ? buildReasoningOptions(req.thinkingLevel, "chat-completions")
          : {}),
      };

      const events = this.streamChatCompletions(
        wireMessages,
        requestOptions,
        req.abortSignal,
      );
      const turn = await this.decodeStream(events, req.abortSignal);
      return this.extractStructuredPayload<T>(turn, options.toolName);
    } catch (error) {
      if (req.abortSignal.aborted) {
        throw error;
      }
      throw this.mapProviderError(error);
    }
  }

  // ============ Stream decoding ============

  private decodeStream(
    events: AsyncIterableIterator<RawStreamChunk>,
    signal: AbortSignal,
  ): Promise<LLMTurnResult> {
    return decodeChatCompletionStream(events, signal, {
      logPrefix: this.logPrefix,
      // OpenAI's stream omits ids on some `tool_calls` deltas; preserve the
      // pre-PR-9a id shape (`openai_tool_call_<ts>_<idx>`) so any downstream
      // dedup / logging that keyed on that prefix keeps working.
      synthesizeMissingToolCallId: (idx) =>
        `openai_tool_call_${Date.now()}_${idx}`,
      // OpenAI does not use the legacy `function_call` shape — omit the
      // synthesizer so the decoder skips that path entirely.
    });
  }

  // ============ HTTP / streaming ============

  private async *streamChatCompletions(
    messages: unknown[],
    options: Record<string, unknown>,
    abortSignal: AbortSignal,
  ): AsyncIterableIterator<RawStreamChunk> {
    const { apiKey, model } = this.config;
    const baseUrl = this.getBaseUrl();
    const url = `${baseUrl}/chat/completions`;
    const workflowManager = this.config.workflowManager;
    const maxAttempts = this.config.maxRetries ?? 3;
    const requestTimeoutMs = AIRGAP_CONFIG.timeouts.requestTimeoutMs;
    const streamIdleTimeoutMs = AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs;
    const meaningfulStreamTimeoutMs =
      AIRGAP_CONFIG.timeouts.meaningfulStreamTimeoutMs;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    };

    const body = JSON.stringify({
      model,
      messages,
      stream: true,
      ...options,
    });

    let lastError: Error | undefined;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      if (attempt === 0) {
        const rateLimitResult =
          await workflowManager.acquireRateLimitToken(30000);
        if (!rateLimitResult.allowed) {
          throw createAgentError(
            "PROVIDER_RATE_LIMITED",
            `Rate limit exceeded. Retry after ${rateLimitResult.retryAfterMs}ms`,
          );
        }
      }

      if (attempt > 0) {
        const baseDelay = Math.min(2000 * 2 ** (attempt - 1), 30000);
        const jitter = baseDelay * 0.2 * (Math.random() * 2 - 1);
        const delay = Math.max(500, Math.floor(baseDelay + jitter));
        console.log(
          `${this.logPrefix} Retrying in ${delay}ms (attempt ${attempt + 1}/${maxAttempts})...`,
        );
        await new Promise((resolve) => setTimeout(resolve, delay));
      }

      const response = await this.fetchWithTimeout(
        url,
        { method: "POST", headers, body },
        abortSignal,
        requestTimeoutMs,
      );

      if (response.status === 400) {
        workflowManager.reportRecoverableHttpError(400);
      }

      if (response.status === 429) {
        const retryAfter = response.headers.get("retry-after");
        const retryAfterMs = retryAfter
          ? Number.parseInt(retryAfter, 10) * 1000
          : undefined;
        workflowManager.reportRecoverableHttpError(429, retryAfterMs);

        if (retryAfter) {
          console.log(
            `${this.logPrefix} Server requested Retry-After: ${retryAfter}s`,
          );
          await new Promise((resolve) =>
            setTimeout(resolve, Number.parseInt(retryAfter, 10) * 1000),
          );
          continue;
        }
        lastError = createAgentError(
          "PROVIDER_RATE_LIMITED",
          await response.text(),
        );
        continue;
      }

      if (
        response.status >= 500 &&
        response.status < 600 &&
        attempt < maxAttempts - 1
      ) {
        console.warn(
          `${this.logPrefix} Server error ${response.status}, will retry...`,
        );
        lastError = createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Server error: ${response.status}`,
        );
        continue;
      }

      if (response.status === 408 || response.status === 524) {
        console.warn(`${this.logPrefix} Request timeout, will retry...`);
        lastError = createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Timeout: ${response.status}`,
        );
        continue;
      }

      if (!response.ok) {
        const errorText = await response.text();
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `OpenAI API error (${response.status}): ${errorText}`,
        );
      }

      if (!response.body) {
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          "No response body from OpenAI API",
        );
      }

      workflowManager.reportSuccess();

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let lastMeaningfulDeltaAt = Date.now();
      let streamCancelReason: unknown;
      // Tracks whether this attempt has yielded at least one chunk that the
      // decoder would treat as meaningful (content / reasoning / tool-call
      // delta / finish_reason). Used below to decide whether a stream-body
      // timeout is safely retryable: if no consumer-visible bytes have been
      // emitted yet, restarting the request loses nothing.
      let hasYieldedMeaningfulChunk = false;

      const throwIfStreamAborted = () => {
        if (!abortSignal.aborted) return;
        throw (
          abortSignal.reason ??
          new DOMException("OpenAI stream aborted", "AbortError")
        );
      };

      const assertMeaningfulDeltaFresh = () => {
        const idleMs = Date.now() - lastMeaningfulDeltaAt;
        if (idleMs < meaningfulStreamTimeoutMs) return;

        const timeoutReason = new DOMException(
          `OpenAI stream produced no model output for ${Math.round(idleMs / 1000)}s`,
          "TimeoutError",
        );
        streamCancelReason = timeoutReason;
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `OpenAI stream produced no model output for ${Math.round(meaningfulStreamTimeoutMs / 1000)}s while receiving non-content events. Please retry or switch models.`,
          { cause: timeoutReason },
        );
      };

      try {
        while (true) {
          throwIfStreamAborted();
          const { done, value } = await readStreamChunkWithTimeout(reader, {
            signal: abortSignal,
            idleTimeoutMs: streamIdleTimeoutMs,
            providerName: "OpenAI",
          });
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() ?? "";

          for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || !trimmed.startsWith("data: ")) continue;
            const data = trimmed.slice(6);
            if (data === "[DONE]") return;

            let parsed: RawStreamChunk;
            try {
              parsed = JSON.parse(data) as RawStreamChunk;
            } catch {
              assertMeaningfulDeltaFresh();
              // Invalid JSON, skip this chunk
              continue;
            }

            if (hasMeaningfulChatCompletionDelta(parsed)) {
              lastMeaningfulDeltaAt = Date.now();
              hasYieldedMeaningfulChunk = true;
            }
            assertMeaningfulDeltaFresh();
            yield parsed;
          }

          assertMeaningfulDeltaFresh();
        }

        if (buffer.trim()) {
          const trimmed = buffer.trim();
          if (trimmed.startsWith("data: ")) {
            const data = trimmed.slice(6);
            if (data && data !== "[DONE]") {
              let parsed: RawStreamChunk;
              try {
                parsed = JSON.parse(data) as RawStreamChunk;
              } catch {
                assertMeaningfulDeltaFresh();
                // Invalid JSON
                return;
              }

              if (hasMeaningfulChatCompletionDelta(parsed)) {
                lastMeaningfulDeltaAt = Date.now();
                hasYieldedMeaningfulChunk = true;
              }
              assertMeaningfulDeltaFresh();
              yield parsed;
            }
          }
        }
      } catch (error) {
        void reader.cancel(streamCancelReason ?? error).catch(() => undefined);
        // Retry-on-stall: if the stream timed out before any meaningful
        // chunk reached the consumer, treat it like a transient transport
        // error (analogous to a 5xx) and restart the request. This covers
        // the slow-first-chunk pattern seen with large prompts on OpenAI-
        // compatible endpoints, where the model spends >45 s reasoning
        // before emitting its first byte. Retrying mid-stream would lose
        // partial output, so we only retry when `hasYieldedMeaningfulChunk`
        // is still false. The error's `cause` is a `DOMException` with
        // `name === "TimeoutError"` for both `readStreamChunkWithTimeout`
        // (per-chunk idle) and `assertMeaningfulDeltaFresh` (keepalive-
        // only) — both are eligible.
        if (
          !hasYieldedMeaningfulChunk &&
          isStreamIdleTimeoutError(error) &&
          attempt < maxAttempts - 1
        ) {
          console.warn(
            `${this.logPrefix} Stream stalled before any model output (attempt ${attempt + 1}/${maxAttempts}); retrying...`,
          );
          lastError = asAgentError(
            error,
            "PROVIDER_TRANSPORT_ERROR",
            "OpenAI stream stalled before any model output",
          );
          continue;
        }
        throw error;
      } finally {
        reader.releaseLock();
      }

      return;
    }

    throw (
      lastError ??
      createAgentError(
        "PROVIDER_TRANSPORT_ERROR",
        "Max retries exceeded for OpenAI API",
      )
    );
  }

  private async fetchWithTimeout(
    url: string,
    init: RequestInit,
    signal: AbortSignal,
    requestTimeoutMs: number,
  ): Promise<Response> {
    const timeoutController = new AbortController();
    // Track whether the timeout (vs. the outer signal) was the source of the
    // abort so the caller can surface a clear "timed out" message instead of
    // the platform-default `DOMException: signal is aborted without reason`.
    let timedOut = false;

    const onAbort = () => {
      // Forward the outer signal's reason (if any) so user-initiated aborts
      // carry meaningful diagnostic info downstream.
      timeoutController.abort(signal.reason);
    };

    if (signal.aborted) {
      timeoutController.abort(signal.reason);
    } else {
      signal.addEventListener("abort", onAbort, { once: true });
    }

    const timeoutId = setTimeout(() => {
      timedOut = true;
      timeoutController.abort(
        new DOMException(
          `OpenAI request exceeded ${requestTimeoutMs}ms timeout`,
          "TimeoutError",
        ),
      );
    }, requestTimeoutMs);

    try {
      return await fetch(url, { ...init, signal: timeoutController.signal });
    } catch (error) {
      if (timedOut) {
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `OpenAI request timed out after ${Math.round(requestTimeoutMs / 1000)}s. The API did not respond in time.`,
        );
      }
      throw error;
    } finally {
      clearTimeout(timeoutId);
      signal.removeEventListener("abort", onAbort);
    }
  }

  // ============ Wire format conversion ============

  private convertToolsToOpenAIFormat(tools: Tool[]): unknown[] {
    return tools.map((tool) => ({
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      },
    }));
  }

  private createStructuredTool(toolName: string, schema: JSONSchema): unknown {
    return {
      type: "function",
      function: {
        name: toolName,
        description: `Submit structured planner payload for ${toolName}.`,
        parameters: schema,
      },
    };
  }

  private extractStructuredPayload<T>(
    turn: LLMTurnResult,
    toolName: string,
  ): T {
    const call = turn.toolCalls.find((toolCall) => toolCall.name === toolName);
    if (!call) {
      throw createAgentError(
        "PROVIDER_STREAM_PARSE_ERROR",
        `Structured response did not include a ${toolName} tool call.`,
      );
    }
    return call.arguments as T;
  }

  private getBaseUrl(): string {
    return (this.config.baseUrl || "https://api.openai.com/v1").replace(
      /\/+$/,
      "",
    );
  }

  private mapProviderError(error: unknown): AgentError {
    const typed = asAgentError(
      error,
      "PROVIDER_TRANSPORT_ERROR",
      "OpenAI provider request failed",
    );
    if (typed.code.startsWith("PROVIDER_")) {
      return typed;
    }

    const loweredMessage = typed.message.toLowerCase();
    if (
      loweredMessage.includes("rate limit") ||
      loweredMessage.includes("retry-after")
    ) {
      return createAgentError("PROVIDER_RATE_LIMITED", typed.message, {
        cause: error,
      });
    }

    return createAgentError("PROVIDER_TRANSPORT_ERROR", typed.message, {
      cause: error,
    });
  }
}

export function createOpenAIProvider(
  config: OpenAIProviderConfig,
): OpenAIProvider {
  return new OpenAIProvider(config);
}
