const ADAPTIVE_STATUS_CODES = new Set([400, 429]);

export function extractHttpStatusCode(error: unknown): number | undefined {
  if (!(error instanceof Error)) {
    return undefined;
  }

  const statusCodeMatch = error.message.match(/\b(400|408|429|500|502|503|504|524)\b/);
  if (!statusCodeMatch) {
    return undefined;
  }

  return Number.parseInt(statusCodeMatch[1], 10);
}

export function isAdaptiveThrottleError(error: unknown): boolean {
  if (!(error instanceof Error)) {
    return false;
  }

  const message = error.message.toLowerCase();
  const statusCode = extractHttpStatusCode(error);

  return (
    (statusCode !== undefined && ADAPTIVE_STATUS_CODES.has(statusCode)) ||
    message.includes("rate limit") ||
    message.includes("bad request")
  );
}

export function extractRetryAfterMsFromError(error: unknown): number | undefined {
  if (!(error instanceof Error)) {
    return undefined;
  }

  const retryAfterMatch = error.message.match(/retry.{0,20}(\d+)/i);
  if (!retryAfterMatch) {
    return undefined;
  }

  return Number.parseInt(retryAfterMatch[1], 10) * 1000;
}