/**
 * Dual run-budget enforcement (blueprint §5 dual budget policy).
 *
 * The orchestrator runs two budget guards per iteration:
 *   - Pre-turn: before calling `provider.runTurn(...)`.
 *   - Post-action: after `apply()` settles the action and before the next
 *     turn is dispatched.
 *
 * Both guards use the SAME `nowMs` value sampled at iteration boundary so
 * timeout decisions are consistent within a single iteration.
 */

import type { AgentRunState, RunStopReason } from "./state";

export interface BudgetGuardResult {
  /** When non-null, the run MUST terminate with this stop reason. */
  stopReason: RunStopReason | null;
}

/**
 * Pre-turn guard: stop if the timeout has elapsed or the iteration budget
 * is exhausted (and no finalization grace pass is pending).
 */
export function checkPreTurnBudget(
  state: AgentRunState,
  nowMs: number,
): BudgetGuardResult {
  if (nowMs >= state.timeoutAtMs) {
    return { stopReason: "timeout" };
  }
  if (
    state.iteration >= state.maxIterations &&
    !state.flags.grantedFinalizationPass
  ) {
    return { stopReason: "max_turns" };
  }
  return { stopReason: null };
}

/**
 * Post-action guard: re-checks the timeout clock with a freshly sampled
 * `nowMs` between turns. The iteration count is checked again here so a
 * grace pass that consumed its slot stops cleanly.
 */
export function checkPostActionBudget(
  state: AgentRunState,
  nowMs: number,
): BudgetGuardResult {
  if (nowMs >= state.timeoutAtMs) {
    return { stopReason: "timeout" };
  }
  // After a granted grace pass, the next iteration ticking past max_turns
  // is the natural stop point.
  if (
    state.flags.grantedFinalizationPass &&
    state.iteration >= state.maxIterations
  ) {
    return { stopReason: "max_turns" };
  }
  return { stopReason: null };
}

/**
 * Default wall-clock budget when the caller does not provide one.
 * 10 minutes mirrors the typical Office.js add-in user attention window
 * and is conservative enough to avoid spurious timeouts during long
 * planner-mode runs.
 */
export const DEFAULT_MAX_WALL_CLOCK_MS = 10 * 60 * 1000;
