import { getRuntimeConfigSync } from "../runtime-config";
import { trackEvent } from "../telemetry";
import {
  MAX_CONTEXT_TOKENS,
  MAX_INPUT_TOKENS,
  type TokenCount,
  estimateTokens,
  prepareMessagesForApi,
} from "../token-manager";
import type { WorkflowManager } from "../workflow";
import {
  type AgentError,
  asAgentError,
  createAgentError,
  formatCodeAndMessage,
} from "./errors";
import type { Action } from "./loop/actions";
import { type Clock, systemClock } from "./loop/clock";
import { decide } from "./loop/decide";
import {
  DEFAULT_MAX_WALL_CLOCK_MS,
  checkPostActionBudget,
  checkPreTurnBudget,
} from "./loop/iteration-budget";
import { nudgeText } from "./loop/nudges";
import { RunCircuitBreaker } from "./loop/run-circuit-breaker";
import {
  type EmitEvent,
  type ExecutedTool,
  apply,
  createInitialState,
  resetForPlannerFallback,
} from "./loop/state";
import {
  DEFAULT_TOKEN_BUDGET,
  prepareOutboundMessages,
} from "./loop/token-budget";
import { type MCPRuntime, setupMcpRuntime } from "./mcp";
import {
  type PlannerPromptContext,
  buildPlannerExecutionPrompt as buildPlannerExecutionPromptPure,
  formatPlanAsChecklist,
  submitPlanWithRetry,
} from "./planner";
import type { LLMProvider } from "./providers/provider";
import type { LLMTurnResult } from "./providers/provider";
import { normalizeToolMetadata } from "./tool-metadata";
import {
  DEFAULT_MAX_PARALLEL_READ_TOOLS,
  type DispatchResult,
  type ToolCallToDispatch,
  ToolDispatcher,
} from "./tools/dispatcher";
import {
  getTurnRecorder,
  summarizeContentBlocks,
  summarizeMessages,
  summarizeToolCalls,
} from "./turn-recorder";
import type {
  AgentEvent,
  AgentEventHandler,
  AgentMessage,
  AgentState,
  AgentStopReason,
  AssistantContentBlock,
  AssistantMessage,
  ThinkingLevel,
  Tool,
  ToolResultMessage,
  UsageInfo,
  UserMessage,
} from "./types";

export interface AgentRunConfig {
  /** Provider instance. The Agent does NOT construct providers itself. */
  provider: LLMProvider;
  systemPrompt: string;
  thinkingLevel: ThinkingLevel;
  tools: Tool[];
  /** Optional raw MCP connections config; validated by the agent layer. */
  mcpConfig?: unknown;
  messages?: AgentMessage[];
  /** Delay between tool execution rounds to avoid rate limits (ms). Default: 1000 */
  rateLimitDelayMs?: number;
  /** Max tokens for context window. */
  maxContextTokens?: number;
  /** Max tokens generated per assistant response. */
  maxOutputTokens?: number;
  /** Enable circuit breaker for failing requests. Default: true */
  enableCircuitBreaker?: boolean;
  /** Workflow manager (constructed by the caller and shared with the provider). */
  workflowManager: WorkflowManager;
  /** Whether the Agent owns the workflow manager and should dispose it. */
  ownsWorkflowManager?: boolean;
  /** Agent execution behavior model. */
  executionModel?: "standard" | "planner";
  /**
   * Recorder/log label, e.g. "AzureAgent" or "OpenAIAgent". Used by the
   * turn recorder and console log prefixes so existing telemetry remains
   * stable across the PR-3 refactor.
   */
  agentLabel?: string;
  /** Optional model label for turn-recorder run_start metadata. */
  modelLabel?: string;
  /** Optional Azure API mode label for turn-recorder run_start metadata. */
  apiMode?: string;
  /** Optional override for runtime-config `agentLoop.enableParallelTools`. */
  enableParallelTools?: boolean;
  /** Optional override for runtime-config `agentLoop.maxParallelReadTools`. */
  maxParallelReadTools?: number;
  /**
   * Optional clock for replay determinism (PR-8a). Defaults to the
   * production system clock backed by `Date.now()`.
   */
  clock?: Clock;
  /**
   * @deprecated Use {@link clock} instead. Retained for one release for
   *   replay-test backward compatibility; PR-8a normalizes this into a
   *   {@link Clock} at construction time.
   */
  nowMs?: () => number;
}

interface AgentLoopResult {
  stopReason: AgentStopReason;
  runError?: string;
}

export class Agent {
  protected config: AgentRunConfig;
  private eventHandlers: AgentEventHandler[] = [];
  private abortController: AbortController | null = null;
  private isRunning = false;
  private internalState: AgentState;
  private providerCircuitBreaker: RunCircuitBreaker;
  private tokenCount: TokenCount;
  private toolsJson: string;
  private workflowManager: WorkflowManager;
  private ownsWorkflowManager: boolean;
  private readonly logPrefix: string;
  private readonly toolDispatcher: ToolDispatcher;
  private localTools: Tool[];
  private readonly mcpRuntime: MCPRuntime | null;
  /** PR-6 §6.3: cached structured plan checklist for the in-flight run. */
  private cachedStructuredPlanText: string | null = null;
  /** PR-8a: replay-deterministic clock injected via {@link AgentRunConfig.clock}. */
  private readonly clock: Clock;

  get state(): AgentState {
    return { ...this.internalState };
  }

  get currentTokenCount(): TokenCount {
    return { ...this.tokenCount };
  }

  constructor(config: AgentRunConfig) {
    // Build a defaults-then-overrides merge that ignores `undefined` keys
    // from `config`. Without the explicit filter, an untuned upstream
    // (e.g. `chat-context` passing `maxOutputTokens: undefined` because
    // `runtime-config.json` agentTuning is empty) would clobber the
    // intended defaults, silently demoting `maxOutputTokens` to
    // `undefined` and forcing the per-turn floor at request time. That
    // capped 100-row Azure writes mid-stream because the real limit was
    // 4096 instead of whatever the provider factory configured (8192).
    const overrides: Partial<AgentRunConfig> = {};
    for (const key of Object.keys(config) as Array<keyof AgentRunConfig>) {
      const value = config[key];
      if (value !== undefined) {
        (overrides as Record<string, unknown>)[key as string] = value;
      }
    }
    this.config = {
      rateLimitDelayMs: 1000,
      maxContextTokens: MAX_CONTEXT_TOKENS,
      maxOutputTokens: 4096,
      enableCircuitBreaker: true,
      executionModel: "planner",
      ...overrides,
    } as AgentRunConfig;
    this.clock =
      config.clock ?? (config.nowMs ? { now: config.nowMs } : systemClock);
    this.internalState = {
      messages: config.messages ?? [],
      systemPrompt: config.systemPrompt,
      thinkingLevel: config.thinkingLevel,
      tools: config.tools,
    };
    this.providerCircuitBreaker = new RunCircuitBreaker({
      clock: this.clock,
      onOpen: () =>
        console.warn(
          `${this.logPrefix} Circuit breaker opened due to repeated failures`,
        ),
    });
    this.tokenCount = { total: 0, system: 0, messages: 0, tools: 0 };
    this.workflowManager = config.workflowManager;
    this.ownsWorkflowManager = config.ownsWorkflowManager ?? false;
    this.logPrefix = `[${config.agentLabel ?? "Agent"}]`;
    this.localTools = [...config.tools];
    this.mcpRuntime = setupMcpRuntime(config.mcpConfig, {
      logPrefix: this.logPrefix,
      clock: this.clock,
      emitTelemetry: (name, properties) => trackEvent(name, properties),
    });
    const runtimeLoopConfig = getRuntimeConfigSync().agentLoop;
    this.toolDispatcher = new ToolDispatcher({
      logPrefix: this.logPrefix,
      enableParallelTools:
        config.enableParallelTools ??
        runtimeLoopConfig.enableParallelTools ??
        true,
      maxParallelReadTools:
        config.maxParallelReadTools ??
        runtimeLoopConfig.maxParallelReadTools ??
        DEFAULT_MAX_PARALLEL_READ_TOOLS,
      mcpRuntime: this.mcpRuntime?.createDispatchRuntime(),
      clock: this.clock,
    });

    this.toolsJson = this.config.provider.toToolsJsonForBudget(config.tools);
    this.updateTokenCount();
  }

  // ============ Lifecycle ============

  /**
   * Aborts the current run, if any. `reason` is forwarded to the
   * underlying `AbortController.abort(reason)` so downstream `fetch()` /
   * stream consumers can surface a meaningful cause instead of the
   * platform-default `"signal is aborted without reason"`. Defaults to a
   * tagged `AbortError` for callers that don't supply one.
   */
  abort(reason?: unknown): void {
    if (this.abortController) {
      this.abortController.abort(
        reason ?? new DOMException("Agent run aborted", "AbortError"),
      );
      this.abortController = null;
    }
  }

  reset(): void {
    this.abort(new DOMException("Agent reset", "AbortError"));
    this.internalState.messages = [];
    this.internalState.tools = [...this.localTools];
    this.toolDispatcher.clear();
    this.mcpRuntime?.clearPendingTurnNotes();
    this.cachedStructuredPlanText = null;
  }

  dispose(): void {
    this.abort(new DOMException("Agent disposed", "AbortError"));
    this.eventHandlers = [];
    this.toolDispatcher.clear();
    this.mcpRuntime?.clearPendingTurnNotes();
    this.mcpRuntime?.dispose();
    if (this.ownsWorkflowManager) {
      this.workflowManager.dispose();
    }
  }

  replaceMessages(messages: AgentMessage[]): void {
    this.internalState.messages = [...messages];
  }

  subscribe(handler: AgentEventHandler): () => void {
    this.eventHandlers.push(handler);
    return () => {
      const index = this.eventHandlers.indexOf(handler);
      if (index !== -1) {
        this.eventHandlers.splice(index, 1);
      }
    };
  }

  /**
   * Apply a partial config update. Sub-classes may override to forward
   * provider-specific config fields, then call super.applyAgentConfigUpdate
   * for shared fields.
   */
  applyAgentConfigUpdate(update: Partial<AgentRunConfig>): void {
    const previousWorkflowManager = this.workflowManager;
    const previousOwnsWorkflowManager = this.ownsWorkflowManager;

    this.config = { ...this.config, ...update };

    if (update.workflowManager !== undefined) {
      this.workflowManager = update.workflowManager;
    }
    if (update.ownsWorkflowManager !== undefined) {
      this.ownsWorkflowManager = update.ownsWorkflowManager;
    }

    if (update.systemPrompt !== undefined) {
      this.internalState.systemPrompt = update.systemPrompt;
    }
    if (update.thinkingLevel !== undefined) {
      this.internalState.thinkingLevel = update.thinkingLevel;
    }
    if (update.tools !== undefined) {
      this.localTools = [...update.tools];
      this.internalState.tools = [...update.tools];
      this.toolsJson = this.config.provider.toToolsJsonForBudget(update.tools);
    }
    if (update.messages !== undefined) {
      this.internalState.messages = update.messages;
    }
    if (
      update.enableParallelTools !== undefined ||
      update.maxParallelReadTools !== undefined
    ) {
      this.toolDispatcher.updateParallelConfig({
        enableParallelTools: update.enableParallelTools,
        maxParallelReadTools: update.maxParallelReadTools,
      });
    }

    if (
      previousOwnsWorkflowManager &&
      previousWorkflowManager !== this.workflowManager
    ) {
      previousWorkflowManager.dispose();
    }
  }

  // ============ Prompt entry point ============

  async prompt(content: string): Promise<void> {
    if (this.isRunning) {
      throw createAgentError(
        "RUN_ALREADY_IN_PROGRESS",
        "Another agent run is already in progress for this session.",
      );
    }

    const inputTokens = estimateTokens(content);
    if (inputTokens > MAX_INPUT_TOKENS) {
      throw new Error(
        `Input too large (${inputTokens} estimated tokens). Maximum allowed is ${MAX_INPUT_TOKENS}.`,
      );
    }

    this.isRunning = true;
    this.abortController = new AbortController();
    const signal = this.abortController.signal;
    this.toolDispatcher.clear();
    await this.refreshToolsForNextTurn();

    const recorder = getTurnRecorder();
    const runId =
      typeof crypto !== "undefined" && "randomUUID" in crypto
        ? crypto.randomUUID()
        : `run_${this.nowMs()}_${Math.random().toString(36).slice(2)}`;
    this.toolDispatcher.setRunId(runId);
    let stopReason: AgentStopReason = "complete";
    let runError: string | undefined;
    recorder?.record({
      type: "run_start",
      runId,
      timestampMs: this.nowMs(),
      agent: this.config.agentLabel ?? "Agent",
      model: this.config.modelLabel,
      apiMode: this.config.apiMode,
      executionModel: this.config.executionModel,
      toolCount: this.internalState.tools.length,
    });

    try {
      const userMessage = this.createUserMessage(content);
      this.internalState.messages.push(userMessage);
      this.cachedStructuredPlanText = null;
      const planSubmission = await this.maybeSubmitStructuredPlan(
        signal,
        runId,
      );
      const loopResult = await this.runAgentLoop(signal, recorder, runId, {
        plannerStructuredFallback: planSubmission.fallback,
      });
      stopReason = loopResult.stopReason;
      runError = loopResult.runError;
    } catch (error) {
      const typedError = asAgentError(
        error,
        "RUN_PROVIDER_ERROR",
        "Agent prompt failed",
      );

      if (typedError.code === "RUN_ABORTED") {
        const formattedError = formatCodeAndMessage(
          typedError.code,
          typedError.message,
        );
        stopReason = "aborted";
        runError = formattedError;
        this.emitAgentEnd(stopReason, runError);
        return;
      }

      const errorMessage = typedError.message;
      const formattedError = formatCodeAndMessage(
        typedError.code,
        errorMessage,
      );
      console.error(`${this.logPrefix} Prompt error:`, error);
      stopReason = "error";
      runError = formattedError;

      const errorAssistant: AssistantMessage = {
        role: "assistant",
        content: [{ type: "text", text: `Error: ${formattedError}` }],
        timestamp: this.nowMs(),
        stopReason: "error",
        errorMessage: formattedError,
      };

      this.emit({ type: "message_start", message: errorAssistant });
      this.emit({ type: "message_end", message: errorAssistant });
      this.emitAgentEnd(stopReason, runError);
    } finally {
      this.mcpRuntime?.resetCircuitBreakers();
      this.mcpRuntime?.clearPendingTurnNotes();
      this.cachedStructuredPlanText = null;
      this.abortController = null;
      this.isRunning = false;
      recorder?.record({
        type: "run_end",
        runId,
        timestampMs: this.nowMs(),
        stopReason,
        error: runError,
      });
    }
  }

  // ============ Agent loop ============

  private async runAgentLoop(
    signal: AbortSignal,
    recorder: ReturnType<typeof getTurnRecorder>,
    runId: string,
    options: { plannerStructuredFallback?: boolean } = {},
  ): Promise<AgentLoopResult> {
    if (
      this.config.enableCircuitBreaker &&
      this.providerCircuitBreaker.shouldBlock()
    ) {
      throw createAgentError(
        "RUN_PROVIDER_ERROR",
        "Circuit breaker is open due to repeated failures. Please wait a minute before retrying.",
      );
    }

    const maxIterations = 50;
    const runtimeLoop = getRuntimeConfigSync().agentLoop;
    const lastUserText = this.getLastUserMessageText();
    const shouldUsePlannerExecution =
      this.shouldForcePlannerExecution(lastUserText) &&
      // PR-8c: if structured-plan submission exhausted retries with a
      // schema validation failure, the loop must run as non-planner so
      // the prose planner directive is not injected into a degraded
      // run. `resetForPlannerFallback` below also clears the planner
      // flags / counters; we additionally suppress the initial
      // `plannerMode: true` to avoid a brief planner-mode window during
      // the very first decide().
      !options.plannerStructuredFallback;
    const useComplexWorkflowMode =
      this.shouldUseComplexWorkflowMode(lastUserText);

    // Snapshot whether the registered tool set contains any
    // `category: "deliverable"` tool. `prompt()` already called
    // `refreshToolsForNextTurn()`, so MCP-adapted tools are included
    // here. When this is `false`, the planner-mode deliverable gate is
    // bypassed (decide.ts §rule 8) so research-only runs don't trigger
    // `planner_no_deliverable` retry storms (root cause of the
    // duplicate-answer bug for MCP doc-search prompts).
    const hasDeliverableTools = this.internalState.tools.some(
      (tool) => normalizeToolMetadata(tool).category === "deliverable",
    );

    let executedToolCallsInRun = 0;
    let state = createInitialState({
      maxIterations,
      maxWallClockMs: runtimeLoop.maxWallClockMs ?? DEFAULT_MAX_WALL_CLOCK_MS,
      startedAtMs: this.nowMs(),
      lastUserText,
      plannerMode: shouldUsePlannerExecution,
      hasDeliverableTools,
    });

    if (options.plannerStructuredFallback) {
      // Belt-and-suspenders. `shouldUsePlannerExecution` already gates
      // `plannerMode: false`, but `resetForPlannerFallback` is the
      // documented blueprint §9.1 reset surface and pins the planner
      // flag / nudge counters in addition to `plannerMode`. Calling it
      // explicitly here keeps the post-fallback state machine
      // observably equivalent to a fresh non-planner run.
      state = resetForPlannerFallback(state);
    }

    while (!signal.aborted && state.status.kind !== "done") {
      const preBudget = checkPreTurnBudget(state, this.nowMs());
      if (preBudget.stopReason === "timeout") {
        recorder?.record({
          type: "decision",
          runId,
          timestampMs: this.nowMs(),
          branch: "timeout",
          detail: { iteration: state.iteration },
        });
        this.emitTimeoutMessage();
        this.emitAgentEnd("timeout");
        return { stopReason: "timeout" };
      }
      if (preBudget.stopReason === "max_turns") {
        recorder?.record({
          type: "decision",
          runId,
          timestampMs: this.nowMs(),
          branch: "max_iterations",
          detail: { iteration: state.iteration, maxIterations },
        });
        this.emitMaxIterationMessage();
        this.emitAgentEnd("max_iterations");
        return { stopReason: "max_iterations" };
      }

      state = { ...state, iteration: state.iteration + 1 };

      const shouldForceCompaction =
        useComplexWorkflowMode &&
        state.executedToolsThisRun.length > 0 &&
        executedToolCallsInRun > 0 &&
        executedToolCallsInRun % 4 === 0;

      let plannerInstruction: UserMessage | null = null;
      if (state.plannerMode && !state.flags.plannerDirectiveInjected) {
        plannerInstruction = this.createUserMessage(
          buildPlannerExecutionPromptPure(
            this.plannerPromptContext(),
            state.executedToolsThisRun.length > 0,
            {
              complexMode: useComplexWorkflowMode,
              forceCompaction: shouldForceCompaction,
              executedToolCalls: executedToolCallsInRun,
            },
          ),
        );
        state = {
          ...state,
          flags: { ...state.flags, plannerDirectiveInjected: true },
        };
      }

      const maxOutputTokens = this.config.maxOutputTokens ?? 4096;
      const maxTokens = this.config.maxContextTokens ?? MAX_CONTEXT_TOKENS;
      const turnTools = await this.refreshToolsForNextTurn();
      const turnSystemPrompt = this.buildTurnSystemPrompt();
      const budgetResult = prepareOutboundMessages(
        this.internalState.messages,
        state.ephemeralMessages,
        turnSystemPrompt,
        this.config.provider,
        this.toolsJson,
        {
          ...DEFAULT_TOKEN_BUDGET,
          maxContextTokens: maxTokens,
          reservedOutputTokens: maxOutputTokens,
        },
        {
          onNudgeDroppedForBudget: () => {
            trackEvent("agent.budget_ephemeral_dropped", {
              runId,
              iteration: String(state.iteration),
            });
          },
          onBudgetInfeasibleDegraded: (info) => {
            trackEvent("agent.budget_infeasible_degraded", {
              runId,
              iteration: String(state.iteration),
              availableForPersistent: String(info.availableForPersistent),
              systemPromptTokens: String(info.systemPromptTokens),
              toolSchemaTokens: String(info.toolSchemaTokens),
              droppedPersistent: String(info.droppedPersistent),
              droppedEphemeral: String(info.droppedEphemeral),
            });
          },
        },
      );

      this.tokenCount = budgetResult.tokenCount;

      const outboundMessages = plannerInstruction
        ? [...budgetResult.messages, plannerInstruction]
        : budgetResult.messages;

      recorder?.record({
        type: "turn_request",
        runId,
        timestampMs: this.nowMs(),
        iteration: state.iteration,
        requestMode:
          this.config.apiMode === "responses"
            ? "responses"
            : "chat_completions",
        messageCount: outboundMessages.length,
        messages: summarizeMessages(outboundMessages),
        toolNames: turnTools.map((tool) => tool.name),
        toolCount: turnTools.length,
        thinkingLevel: this.internalState.thinkingLevel,
        maxOutputTokens,
        wasTruncated: budgetResult.compacted,
        plannerInstructionInjected: plannerInstruction !== null,
        tokenCount: budgetResult.tokenCount,
      });

      let turn: LLMTurnResult;
      try {
        turn = await this.config.provider.runTurn({
          messages: outboundMessages,
          systemPrompt: turnSystemPrompt,
          tools: turnTools,
          thinkingLevel: this.internalState.thinkingLevel,
          maxOutputTokens,
          abortSignal: signal,
        });
        if (this.config.enableCircuitBreaker) {
          this.providerCircuitBreaker.recordSuccess();
        }
        this.mcpRuntime?.clearPendingTurnNotes();
      } catch (error) {
        if (signal.aborted) {
          recorder?.record({
            type: "decision",
            runId,
            timestampMs: this.nowMs(),
            branch: "aborted",
            detail: { iteration: state.iteration },
          });
          const abortedResult = this.buildAbortedLoopResult();
          this.emitAgentEnd(abortedResult.stopReason, abortedResult.runError);
          return abortedResult;
        }

        if (this.config.enableCircuitBreaker) {
          this.providerCircuitBreaker.recordFailure();
        }

        // Ephemeral resend-then-drop policy (blueprint §8). The current
        // ephemeral batch survives exactly one resend; a second failure
        // drops the batch before the next retry surface so nudges do not
        // accumulate indefinitely across error/timeout storms.
        if (state.ephemeralMessages.length > 0) {
          if (state.ephemeralResendAttempts >= 1) {
            trackEvent("agent.budget_ephemeral_dropped", {
              runId,
              iteration: String(state.iteration),
              reason: "resend_failed",
            });
            state = {
              ...state,
              ephemeralMessages: [],
              ephemeralResendAttempts: 0,
            };
            this.emit({ type: "ephemeral_messages_cleared" });
          } else {
            state = {
              ...state,
              ephemeralResendAttempts: state.ephemeralResendAttempts + 1,
            };
            continue;
          }
        } else if (state.ephemeralResendAttempts !== 0) {
          state = {
            ...state,
            ephemeralResendAttempts: 0,
          };
        }

        const classifiedError = this.classifyLoopError(error);
        const formattedError = formatCodeAndMessage(
          classifiedError.code,
          classifiedError.message,
        );
        recorder?.record({
          type: "decision",
          runId,
          timestampMs: this.nowMs(),
          branch: "api_error",
          detail: {
            iteration: state.iteration,
            code: classifiedError.code,
            error: classifiedError.message,
          },
        });

        const errorAssistant: AssistantMessage = {
          role: "assistant",
          content: [{ type: "text", text: `API Error: ${formattedError}` }],
          timestamp: this.nowMs(),
          stopReason: "error",
          errorMessage: formattedError,
        };
        this.emit({ type: "message_start", message: errorAssistant });
        this.emit({ type: "message_end", message: errorAssistant });
        this.emitAgentEnd("error", formattedError);
        return { stopReason: "error", runError: formattedError };
      }

      if (state.ephemeralMessages.length > 0) {
        state = {
          ...state,
          ephemeralMessages: [],
          ephemeralResendAttempts: 0,
        };
        this.emit({ type: "ephemeral_messages_cleared" });
      } else if (state.ephemeralResendAttempts !== 0) {
        state = { ...state, ephemeralResendAttempts: 0 };
      }

      recorder?.record({
        type: "turn_result",
        runId,
        timestampMs: this.nowMs(),
        iteration: state.iteration,
        contentBlocks: summarizeContentBlocks(turn.blocks),
        toolCalls: summarizeToolCalls(turn.toolCalls),
        finishReason: turn.finishReason,
        sawToolCallSignal: turn.sawToolCallSignal,
        rawChunkCount: turn.rawChunkCount,
        usage: turn.usage,
      });

      const { action, rule } = decide(turn, state, { nowMs: this.nowMs() });
      this.handleFsmEmitEvent(
        {
          type: "rule_fired",
          rule,
          iteration: state.iteration,
          runId,
          nudgeReason:
            action.type === "nudge_and_retry" ? action.reason : undefined,
        },
        recorder,
      );

      const shouldPersistAssistant = this.shouldPersistAssistantTurn(
        rule,
        action,
        turn.blocks,
        turn.toolCalls.length > 0,
      );
      if (shouldPersistAssistant) {
        const assistantMessage = this.createAssistantMessage(
          turn.blocks,
          turn.toolCalls.length > 0 ? "tool_calls" : "complete",
          turn.usage,
        );
        this.internalState.messages.push(assistantMessage);
        this.emit({ type: "message_start", message: assistantMessage });
        this.emit({ type: "message_update", message: assistantMessage });
        this.emit({ type: "message_end", message: assistantMessage });
      }

      state = await apply(action, state, {
        runId,
        nowMs: this.nowMs(),
        signal,
        emit: (event) => this.handleFsmEmitEvent(event, recorder),
        dispatch: async (calls, applySignal) =>
          this.dispatchToolsForFsm(calls, turnTools, applySignal),
      });

      if (action.type === "execute_tools") {
        executedToolCallsInRun += action.calls.length;
      }
      if (action.type === "nudge_and_retry" && action.noIterCharge) {
        state = { ...state, iteration: Math.max(0, state.iteration - 1) };
      }

      const postBudget = checkPostActionBudget(state, this.nowMs());
      if (postBudget.stopReason === "timeout" && state.status.kind !== "done") {
        recorder?.record({
          type: "decision",
          runId,
          timestampMs: this.nowMs(),
          branch: "timeout",
          detail: { iteration: state.iteration },
        });
        this.emitTimeoutMessage();
        this.emitAgentEnd("timeout");
        return { stopReason: "timeout" };
      }
      if (
        postBudget.stopReason === "max_turns" &&
        state.status.kind !== "done"
      ) {
        recorder?.record({
          type: "decision",
          runId,
          timestampMs: this.nowMs(),
          branch: "max_iterations",
          detail: { iteration: state.iteration, maxIterations },
        });
        this.emitMaxIterationMessage();
        this.emitAgentEnd("max_iterations");
        return { stopReason: "max_iterations" };
      }
    }

    if (signal.aborted) {
      recorder?.record({
        type: "decision",
        runId,
        timestampMs: this.nowMs(),
        branch: "aborted",
        detail: { iteration: state.iteration },
      });
      const abortedResult = this.buildAbortedLoopResult();
      this.emitAgentEnd(abortedResult.stopReason, abortedResult.runError);
      return abortedResult;
    }

    if (state.status.kind === "done") {
      const stopReason = state.status.stopReason;
      if (stopReason === "timeout") {
        this.emitAgentEnd("timeout");
        return { stopReason: "timeout" };
      }
      if (stopReason === "aborted") {
        const abortedResult = this.buildAbortedLoopResult();
        this.emitAgentEnd(abortedResult.stopReason, abortedResult.runError);
        return abortedResult;
      }
      if (stopReason === "max_turns") {
        this.emitAgentEnd("max_iterations");
        return { stopReason: "max_iterations" };
      }
      if (stopReason === "error") {
        this.emitAgentEnd("error");
        return { stopReason: "error" };
      }
      this.emitAgentEnd("complete");
      return { stopReason: "complete" };
    }

    this.emitAgentEnd("complete");
    return { stopReason: "complete" };
  }

  private async dispatchToolsForFsm(
    calls: { id: string; name: string; arguments: Record<string, unknown> }[],
    tools: Tool[],
    signal: AbortSignal,
  ): Promise<ExecutedTool[]> {
    const dispatched = await this.dispatchToolCalls(calls, tools, signal);
    const settled: ExecutedTool[] = [];

    for (const { call, result } of dispatched) {
      const found = tools.find((tool) => tool.name === call.name);
      const category = found ? normalizeToolMetadata(found).category : "read";

      settled.push({
        name: call.name,
        category,
        toolCallId: call.id,
        ok: !result.isError,
        dedupSuppressed: result.dedupSuppressed === true,
      });
    }

    return settled;
  }

  private async dispatchToolCalls(
    calls: ToolCallToDispatch[],
    tools: Tool[],
    signal: AbortSignal,
  ): Promise<
    Array<{
      call: ToolCallToDispatch;
      message: ToolResultMessage;
      result: DispatchResult;
    }>
  > {
    const results = await this.toolDispatcher.dispatchBatch(
      calls,
      tools,
      this.workflowManager,
      signal,
      (event) => this.emit(event),
    );

    const dispatched = calls.map((call, index) => ({
      call,
      message: results[index].message,
      result: results[index],
    }));
    this.internalState.messages.push(
      ...dispatched.map(({ message }) => message),
    );
    return dispatched;
  }

  private shouldPersistAssistantTurn(
    _rule: number,
    _action: Action,
    blocks: AssistantContentBlock[],
    hasToolCalls: boolean,
  ): boolean {
    // Persist whenever the assistant produced any content. Rules 1 and 3
    // are guarded on `blocks.length === 0 && toolCalls.length === 0`, so
    // they are filtered here naturally; rule 4 (toolcall_parse_miss) may
    // carry a text preamble alongside the unparseable tool call —
    // dropping it would lose user-visible content (PR-4A review item 2).
    return blocks.length > 0 || hasToolCalls;
  }

  private handleFsmEmitEvent(
    event: EmitEvent,
    recorder: ReturnType<typeof getTurnRecorder>,
  ): void {
    if (event.type === "rule_fired") {
      trackEvent("agent.rule_fired", {
        runId: event.runId,
        iteration: String(event.iteration),
        rule: String(event.rule),
        nudgeReason: event.nudgeReason ?? "",
      });
      recorder?.record({
        type: "decision",
        runId: event.runId,
        timestampMs: this.nowMs(),
        branch: `rule_${event.rule}`,
        detail: {
          iteration: event.iteration,
          nudgeReason: event.nudgeReason,
        },
      });
      return;
    }

    if (event.type === "finalize") {
      trackEvent("agent.finalize", {
        runId: event.runId,
        iteration: String(event.iteration),
        stopReason: event.stopReason,
        deliverableGateSatisfied: String(event.deliverableGateSatisfied),
        executedToolCount: String(event.executedToolCount),
      });
      recorder?.record({
        type: "decision",
        runId: event.runId,
        timestampMs: this.nowMs(),
        branch: "finalize",
        detail: {
          iteration: event.iteration,
          stopReason: event.stopReason,
          deliverableGateSatisfied: event.deliverableGateSatisfied,
          executedToolCount: event.executedToolCount,
        },
      });
      return;
    }

    if (event.type === "nudge_appended") {
      // Ephemeral nudges are rendered live to the UI but intentionally
      // excluded from persisted agent history (blueprint §8).
      const nudgeMessage: AssistantMessage = {
        role: "assistant",
        content: [{ type: "text", text: nudgeText(event.reason) }],
        timestamp: this.nowMs(),
        stopReason: "complete",
        transient: true,
      };
      this.emit({
        type: "message_start",
        message: nudgeMessage,
        transient: true,
      });
      this.emit({
        type: "message_update",
        message: nudgeMessage,
        transient: true,
      });
      this.emit({
        type: "message_end",
        message: nudgeMessage,
        transient: true,
      });
      return;
    }

    if (event.type === "nudge_dropped_for_budget") {
      trackEvent("agent.budget_ephemeral_dropped", {
        runId: event.runId,
        iteration: String(event.iteration),
        reason: event.reason ?? "",
      });
      return;
    }
  }

  private emitMaxIterationMessage(): void {
    const limitMessage: AssistantMessage = {
      role: "assistant",
      content: [
        {
          type: "text",
          text: "Execution stopped after reaching the iteration budget. Partial results are preserved; retry to continue from current state.",
        },
      ],
      timestamp: this.nowMs(),
      stopReason: "complete",
    };
    this.emit({ type: "message_start", message: limitMessage });
    this.emit({ type: "message_update", message: limitMessage });
    this.emit({ type: "message_end", message: limitMessage });
  }

  private emitTimeoutMessage(): void {
    const timeoutMessage: AssistantMessage = {
      role: "assistant",
      content: [
        {
          type: "text",
          text: "Execution stopped after reaching the wall-clock timeout. Partial results are preserved; retry to continue from current state.",
        },
      ],
      timestamp: this.nowMs(),
      stopReason: "complete",
    };
    this.emit({ type: "message_start", message: timeoutMessage });
    this.emit({ type: "message_update", message: timeoutMessage });
    this.emit({ type: "message_end", message: timeoutMessage });
  }

  // ============ Helpers (formerly duplicated across both agents) ============

  private nowMs(): number {
    return this.clock.now();
  }

  protected emit(event: AgentEvent): void {
    for (const handler of this.eventHandlers) {
      try {
        handler(event);
      } catch (err) {
        console.error(`${this.logPrefix} Event handler error:`, err);
      }
    }
  }

  private emitAgentEnd(stopReason: AgentStopReason, error?: string): void {
    this.emit({ type: "agent_end", stopReason, error });
  }

  private createUserMessage(content: string): UserMessage {
    return { role: "user", content, timestamp: this.nowMs() };
  }

  private createAssistantMessage(
    content: AssistantContentBlock[],
    stopReason: AssistantMessage["stopReason"] = "complete",
    usage?: UsageInfo,
  ): AssistantMessage {
    // NOTE: large tool-call arguments (e.g. `write_file` content) are NOT
    // compacted here. The full arguments stay on `internalState.messages`
    // so the UI tool-call inspector can still show the real payload.
    // Compaction happens at the wire layer in `convertMessagesToChatCompletions`
    // and `AzureProvider.stringifyToolArguments` (both via
    // `stringifyToolArgumentsForHistory`), and `estimateMessageTokens` mirrors
    // that same length in its token budget estimate.
    return {
      role: "assistant",
      content,
      timestamp: this.nowMs(),
      stopReason,
      usage,
    };
  }

  private normalizeTextContent(value: unknown): string {
    if (typeof value !== "string") return "";
    return value.trim();
  }

  private getLastUserMessageText(): string {
    for (let i = this.internalState.messages.length - 1; i >= 0; i--) {
      const msg = this.internalState.messages[i];
      if (msg.role === "user") {
        // Strip <wb_context>, <attachments>, and <llm_wiki> enrichment
        // wrappers so classification helpers (`isGreetingOrSmallTalk`,
        // `isShortAffirmativeOrOptionPick`, planner-mode gates) see the
        // user's actual prompt rather than the workbook-context-padded
        // payload that gets shipped to the provider. Without this, a
        // simple "hi" in Excel becomes a 6k-token enriched string that
        // bypasses the small-talk shortcut, forces planner mode, and
        // triggers `planner_no_deliverable` nudges (rule 9) — producing
        // 2-3 duplicate prose replies for a single greeting.
        const raw = stripEnrichment((msg as UserMessage).content);
        return this.normalizeTextContent(raw).toLowerCase();
      }
    }
    return "";
  }

  private isGreetingOrSmallTalk(text: string): boolean {
    if (!text) return false;
    const compact = text.trim().toLowerCase();
    if (!compact) return false;
    if (compact.length > 64) return false;
    return /^(hi|hello|hey|yo|sup|howdy|good\s+(morning|afternoon|evening)|how are you|thanks|thank you|thx|nice to meet you)([!.?,\s].*)?$/.test(
      compact,
    );
  }

  private isPlannerMode(): boolean {
    return this.config.executionModel === "planner";
  }

  private shouldForcePlannerExecution(lastUserText: string): boolean {
    if (!this.isPlannerMode()) return false;
    return !this.isGreetingOrSmallTalk(lastUserText);
  }

  private hasToolNamed(toolName: string): boolean {
    return this.internalState.tools.some((tool) => tool.name === toolName);
  }

  /**
   * PR-10a: snapshot the per-call context the pure planner prompt
   * builders need. Keeps the call sites short and avoids leaking the
   * `this.hasToolNamed` bound method into multiple closures.
   */
  private plannerPromptContext(): PlannerPromptContext {
    return {
      cachedStructuredPlanText: this.cachedStructuredPlanText,
      hasToolNamed: (toolName) => this.hasToolNamed(toolName),
    };
  }

  private shouldUseComplexWorkflowMode(lastUserText: string): boolean {
    if (!this.shouldForcePlannerExecution(lastUserText)) return false;
    const complexSignals = [
      /\bplan\b/i,
      /\bworkflow\b/i,
      /\bcomplex\b/i,
      /\bmulti[-\s]?step\b/i,
      /\bend[-\s]?to[-\s]?end\b/i,
      /\bimplement\b/i,
      /\bexecute\b/i,
      /\bvalidate\b/i,
      /\bquality\b/i,
      /\bcheck\b/i,
      /\bverify\b/i,
      /\baudit\b/i,
    ];
    return (
      lastUserText.length > 220 ||
      complexSignals.some((pattern) => pattern.test(lastUserText))
    );
  }

  // PR-10a: `buildPlannerExecutionPrompt` and
  // `composeStructuredPlannerInstruction` were moved to pure functions
  // in `src/lib/agent/planner/prompts.ts` and the orchestrator now
  // calls `buildPlannerExecutionPromptPure(plannerPromptContext(), ...)`
  // directly inside the run loop. The thin shim below is retained
  // because tests/workflow/workflow-manager.test.ts reaches into the
  // class via a type assertion to assert prompt content; the structural
  // refactor is preserved (prose lives in planner/prompts.ts; the agent
  // owns no template strings).
  private buildPlannerExecutionPrompt(
    hasExecutedToolsInRun: boolean,
    options?: {
      complexMode?: boolean;
      forceCompaction?: boolean;
      executedToolCalls?: number;
    },
  ): string {
    return buildPlannerExecutionPromptPure(
      this.plannerPromptContext(),
      hasExecutedToolsInRun,
      options,
    );
  }

  // ============ Token / circuit breaker ============

  private updateTokenCount(): void {
    const { total, system, messages, tools } = prepareMessagesForApi(
      this.internalState.messages,
      this.internalState.systemPrompt,
      this.toolsJson,
      this.config.maxContextTokens,
    ).tokenCount;
    this.tokenCount = { total, system, messages, tools };
  }

  private buildTurnSystemPrompt(): string {
    const notes = this.mcpRuntime?.pendingTurnNotes() ?? [];
    if (notes.length === 0) {
      return this.internalState.systemPrompt;
    }

    const base = this.internalState.systemPrompt.trim();
    const noteBlock = notes.join("\n");
    return base ? `${base}\n\n${noteBlock}` : noteBlock;
  }

  /**
   * PR-6 §6.3 — opportunistic structured planner submission.
   *
   * Runs once per `prompt()` call before the first iteration:
   *   - Skips entirely when not in planner mode, when the latest user
   *     message is greeting/small-talk, or when the provider does not
   *     implement `runStructured` (the orchestrator falls back to the
   *     prose-driven planner prompt automatically).
   *   - On schema-valid `submit_plan` response, caches the formatted
   *     checklist on `this.cachedStructuredPlanText` so
   *     {@link buildPlannerExecutionPrompt} returns the structured plan
   *     instead of the prose phases.
   *   - On `validation_failed`, retries up to
   *     {@link PLAN_SCHEMA_INVALID_MAX_ATTEMPTS} times with the
   *     validator errors fed back to the model as a synthetic
   *     user-message context (blueprint §9.1). After exhaustion the
   *     cache is left `null` so the prose path remains the source of
   *     truth and the orchestrator emits
   *     `planner.structured_fallback_to_prose` telemetry.
   *   - On `error` (transport/provider failure) the helper does NOT
   *     retry — the orchestrator falls straight to prose so a flaky
   *     network does not burn the schema-retry budget.
   *
   * TODO(post-PR-7): wire `submit_qc_report` into the planner step loop.
   * The schema is exported and unit-tested at
   * `src/lib/agent/planner/planner.ts` (see `submitQcReport`), but no
   * caller invokes it yet. Acceptance criteria and the deferral rationale
   * live in `docs/post-pr7-cleanup-plan.md` PR-12a (lines 282-294).
   */
  private async maybeSubmitStructuredPlan(
    signal: AbortSignal,
    runId: string,
  ): Promise<{ fallback: boolean }> {
    if (this.cachedStructuredPlanText !== null) return { fallback: false };
    if (!this.isPlannerMode()) return { fallback: false };
    if (typeof this.config.provider.runStructured !== "function") {
      return { fallback: false };
    }

    const lastUserText = this.getLastUserMessageText();
    if (!lastUserText || this.isGreetingOrSmallTalk(lastUserText)) {
      return { fallback: false };
    }

    let turnTools: Tool[];
    try {
      turnTools = await this.refreshToolsForNextTurn();
    } catch (error) {
      console.warn(
        `${this.logPrefix} Skipping structured planner submission: tool refresh failed`,
        error,
      );
      return { fallback: false };
    }

    const outcome = await submitPlanWithRetry({
      provider: this.config.provider,
      runId,
      request: {
        messages: this.internalState.messages,
        systemPrompt: this.buildTurnSystemPrompt(),
        tools: turnTools,
        thinkingLevel: this.internalState.thinkingLevel,
        maxOutputTokens: this.config.maxOutputTokens ?? 4096,
        abortSignal: signal,
      },
    });

    if (outcome.kind === "ok") {
      this.cachedStructuredPlanText = formatPlanAsChecklist(outcome.value);
      return { fallback: false };
    }
    // PR-8c: structured submission exhausted retries with a
    // schema-validation failure. Per blueprint §9.1 the next agent loop
    // must run as non-planner — leaving the planner-mode flags set
    // (without a structured plan in the cache) creates a partial-state
    // run where the prose planner directive still gets injected even
    // though the structured surface failed. Surface this so the loop
    // resets `plannerMode` / `plannerDirectiveInjected` /
    // `plannerNudgesUsed` via `resetForPlannerFallback`.
    if (outcome.kind === "fallback" && outcome.reason === "validation_failed") {
      return { fallback: true };
    }
    // `unsupported`, `aborted`, or `fallback` due to provider transport
    // errors intentionally do NOT trigger the planner-fallback reset:
    // unsupported still allows the prose path; aborted/error paths
    // re-surface to the orchestrator catch.
    return { fallback: false };
  }

  private async refreshToolsForNextTurn(): Promise<Tool[]> {
    if (this.mcpRuntime) {
      await this.mcpRuntime.ensureCatalogReady();
    }
    const tools = this.mcpRuntime?.buildToolSnapshot(this.localTools) ?? [
      ...this.localTools,
    ];
    this.internalState.tools = tools;
    this.toolsJson = this.config.provider.toToolsJsonForBudget(tools);
    return tools;
  }

  private createRunAbortedError(): AgentError {
    return createAgentError("RUN_ABORTED", "Run aborted by user.");
  }

  private buildAbortedLoopResult(): AgentLoopResult {
    const abortedError = this.createRunAbortedError();
    return {
      stopReason: "aborted",
      runError: formatCodeAndMessage(abortedError.code, abortedError.message),
    };
  }

  private classifyLoopError(error: unknown): AgentError {
    const typedError = asAgentError(
      error,
      "RUN_PROVIDER_ERROR",
      "Provider call failed",
    );

    if (typedError.code.startsWith("PROVIDER_")) {
      return createAgentError("RUN_PROVIDER_ERROR", typedError.message, {
        cause: typedError,
        details: {
          providerCode: typedError.code,
        },
      });
    }

    if (typedError.code.startsWith("TOOL_")) {
      return typedError;
    }

    if (
      typedError.code === "RUN_ALREADY_IN_PROGRESS" ||
      typedError.code.startsWith("RUN_")
    ) {
      return typedError;
    }

    return createAgentError(
      "RUN_PROVIDER_ERROR",
      typedError.message || "Provider call failed",
      {
        cause: typedError,
      },
    );
  }
}
