export function loadSavedConfig(): ProviderConfig | null {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const config = JSON.parse(saved);
      if (config.proxyUrl === undefined) config.proxyUrl = "";
      if (config.followMode === undefined) config.followMode = true;
      if (config.azureEndpoint === undefined) config.azureEndpoint = "";
      if (config.azureDeploymentName === undefined)
        config.azureDeploymentName = "";
      if (config.azureApiMode === undefined)
        config.azureApiMode = "chat-completions";
      if (config.useEntraId === undefined) config.useEntraId = false;
      if (config.azureClientId === undefined) config.azureClientId = "";
      if (config.documentIntelligenceEndpoint === undefined)
        config.documentIntelligenceEndpoint = "";
      if (config.documentIntelligenceKey === undefined)
        config.documentIntelligenceKey = "";
      if (config.myAiBaseUrl === undefined) config.myAiBaseUrl = "";
      if (config.provider === undefined) config.provider = "azure";
      return config;
    }
  } catch {}
  return null;
}

export function saveConfig(config: ProviderConfig) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(config));
}

/** Azure OpenAI-specific model configuration */
export interface AzureModelConfig {
  /** Maximum context window for model */
  contextWindow: number;
  /** Maximum tokens to generate */
  maxTokens: number;
}

export function getDefaultAzureModelConfig(): AzureModelConfig {
  return {
    contextWindow: 128000,
    maxTokens: 32000,
  };
}
