/**
 * Get Azure endpoint with optional proxy
 */
export function getAzureEndpoint(config: ProviderConfig): string {
  let endpoint = config.azureEndpoint;
  if (config.useProxy && config.proxyUrl) {
    endpoint = `${config.proxyUrl}/?url=${encodeURIComponent(endpoint)}`;
  }
  return endpoint;
}
