import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { resolveDocumentParagraphIndexes } from "./word-anchor-utils";

/* global Word */

const PARAGRAPH_PREVIEW_LENGTH = 80;

export const searchDocumentTool = defineTool({
  name: "search_document",
  category: "read",
  parallelSafe: true,
  label: "Search Document",
  description:
    "Search for text within the Word document and return matches with context. " +
    "Returns the text surrounding each match plus anchor metadata for repeated matches. " +
    "Useful for finding content before modifying.",
  parameters: Type.Object({
    searchText: Type.String({ description: "The text to search for" }),
    scope: Type.Union(
      [
        Type.Literal("body", { description: "Search entire document body" }),
        Type.Literal("selection", {
          description: "Search within current selection only",
        }),
      ],
      { description: "Where to search", default: "body" },
    ),
    matchCase: Type.Optional(
      Type.Boolean({
        description: "Match case exactly. Default: false",
        default: false,
      }),
    ),
    matchWholeWord: Type.Optional(
      Type.Boolean({
        description: "Match whole words only. Default: false",
        default: false,
      }),
    ),
    useWildcards: Type.Optional(
      Type.Boolean({
        description: "Use wildcards (* and ?). Default: false",
        default: false,
      }),
    ),
    maxResults: Type.Optional(
      Type.Number({
        description: "Maximum matches to return. Default: 20",
        default: 20,
      }),
    ),
    contextChars: Type.Optional(
      Type.Number({
        description: "Characters of context around each match. Default: 50",
        default: 50,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're searching for (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      const result = await Word.run(async (context) => {
        const searchOptions = {
          matchCase: params.matchCase ?? false,
          matchWholeWord: params.matchWholeWord ?? false,
          matchWildcards: params.useWildcards ?? false,
        };

        let searchResult: Word.RangeCollection;

        if (params.scope === "selection") {
          const selection = context.document.getSelection();
          searchResult = selection.search(params.searchText, searchOptions);
        } else {
          const body = context.document.body;
          searchResult = body.search(params.searchText, searchOptions);
        }

        searchResult.load("items");
        await context.sync();

        const matchCount = searchResult.items.length;

        if (matchCount === 0) {
          return {
            matches: [],
            count: 0,
            message: `No matches found for "${params.searchText}"`,
          };
        }

        const maxResults = params.maxResults ?? 20;
        const contextChars = params.contextChars ?? 50;
        const limitedRanges = searchResult.items.slice(0, maxResults);
        const paragraphs = limitedRanges.map((range) =>
          range.paragraphs.getFirst(),
        );

        for (const range of limitedRanges) {
          range.load("text");
        }

        for (const paragraph of paragraphs) {
          paragraph.load("text");
        }

        let scopeParagraphTexts: string[] = [];
        let documentParagraphIndexes: Array<number | null> | null = null;
        let documentParagraphs: Word.ParagraphCollection | null = null;
        let scopeParagraphs: Word.ParagraphCollection;

        if (params.scope === "body") {
          scopeParagraphs = context.document.body.paragraphs;
        } else {
          scopeParagraphs = context.document.getSelection().paragraphs;
          documentParagraphs = context.document.body.paragraphs;
          documentParagraphs.load("items/text");
        }

        scopeParagraphs.load("items/text");

        await context.sync();

        scopeParagraphTexts = scopeParagraphs.items.map(
          (paragraph) => paragraph.text ?? "",
        );
        if (params.scope === "selection" && documentParagraphs) {
          documentParagraphIndexes = resolveDocumentParagraphIndexes(
            scopeParagraphTexts,
            documentParagraphs.items.map((paragraph) => paragraph.text ?? ""),
          );
        }

        const loadedMatches = limitedRanges.map((range, index) => ({
          matchText: range.text ?? "",
          paragraphText: paragraphs[index]?.text ?? "",
        }));
        const paragraphMatchMetadata =
          createParagraphMatchMetadata(loadedMatches);
        const scopeParagraphIndexes = assignParagraphIndexesInOrderedTexts(
          loadedMatches,
          scopeParagraphTexts,
        );
        const paragraphIndexes =
          params.scope === "body"
            ? scopeParagraphIndexes
            : scopeParagraphIndexes.map((scopeParagraphIndex) =>
                scopeParagraphIndex === null
                  ? null
                  : (documentParagraphIndexes?.[scopeParagraphIndex] ?? null),
              );

        const matches = loadedMatches.map((match, index) => {
          const metadata = paragraphMatchMetadata[index];
          const paragraphIndex = paragraphIndexes[index];
          const scopeParagraphIndex = scopeParagraphIndexes[index] ?? null;
          const contextStart = Math.max(
            0,
            metadata.startOffsetInParagraph - contextChars,
          );
          const contextEnd = Math.min(
            match.paragraphText.length,
            metadata.endOffsetInParagraph + contextChars,
          );

          return {
            index,
            text: match.matchText,
            paragraphIndex,
            scopeParagraphIndex,
            matchedParagraphIndex: metadata.matchedParagraphIndex,
            occurrenceIndexInParagraph: metadata.occurrenceIndexInParagraph,
            startOffsetInParagraph: metadata.startOffsetInParagraph,
            endOffsetInParagraph: metadata.endOffsetInParagraph,
            contextBefore: match.paragraphText
              .substring(contextStart, metadata.startOffsetInParagraph)
              .trim(),
            contextAfter: match.paragraphText
              .substring(metadata.endOffsetInParagraph, contextEnd)
              .trim(),
            anchor: {
              paragraphIndex,
              scopeParagraphIndex,
              matchedParagraphIndex: metadata.matchedParagraphIndex,
              occurrenceIndexInParagraph: metadata.occurrenceIndexInParagraph,
              startOffsetInParagraph: metadata.startOffsetInParagraph,
              endOffsetInParagraph: metadata.endOffsetInParagraph,
              prefix: match.paragraphText
                .substring(contextStart, metadata.startOffsetInParagraph)
                .trim(),
              quote: match.matchText,
              suffix: match.paragraphText
                .substring(metadata.endOffsetInParagraph, contextEnd)
                .trim(),
              paragraphPreview: createPreview(
                match.paragraphText,
                PARAGRAPH_PREVIEW_LENGTH,
              ),
            },
          };
        });

        return {
          matches,
          count: matches.length,
          totalMatches: matchCount,
          searchText: params.searchText,
          truncated: matchCount > maxResults,
        };
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error searching document";
      return toolError(message);
    }
  },
});

function createParagraphMatchMetadata(
  matches: Array<{ matchText: string; paragraphText: string }>,
): Array<{
  matchedParagraphIndex: number;
  occurrenceIndexInParagraph: number;
  startOffsetInParagraph: number;
  endOffsetInParagraph: number;
}> {
  let nextParagraphIndex = 0;
  let currentParagraph: {
    matchedParagraphIndex: number;
    paragraphText: string;
    usedCounts: Map<string, number>;
  } | null = null;

  return matches.map((match) => {
    const offsets = findExactMatchOffsets(match.paragraphText, match.matchText);
    const usedCount = currentParagraph?.usedCounts.get(match.matchText) ?? 0;
    const canReuseCurrentParagraph =
      currentParagraph !== null &&
      currentParagraph.paragraphText === match.paragraphText &&
      usedCount < offsets.length;

    if (!canReuseCurrentParagraph) {
      currentParagraph = {
        matchedParagraphIndex: nextParagraphIndex,
        paragraphText: match.paragraphText,
        usedCounts: new Map(),
      };
      nextParagraphIndex++;
    }

    const occurrenceIndexInParagraph =
      currentParagraph.usedCounts.get(match.matchText) ?? 0;
    const startOffsetInParagraph =
      offsets[occurrenceIndexInParagraph] ??
      Math.max(0, match.paragraphText.indexOf(match.matchText));
    const endOffsetInParagraph =
      startOffsetInParagraph + match.matchText.length;

    currentParagraph.usedCounts.set(
      match.matchText,
      occurrenceIndexInParagraph + 1,
    );

    return {
      matchedParagraphIndex: currentParagraph.matchedParagraphIndex,
      occurrenceIndexInParagraph,
      startOffsetInParagraph,
      endOffsetInParagraph,
    };
  });
}

function assignParagraphIndexesInOrderedTexts(
  matches: Array<{ matchText: string; paragraphText: string }>,
  paragraphTexts: string[],
): Array<number | null> {
  const paragraphUsage = new Map<number, Map<string, number>>();
  let activeParagraphIndex: number | null = null;

  return matches.map((match) => {
    let paragraphIndex: number | null = null;

    if (
      activeParagraphIndex !== null &&
      paragraphTexts[activeParagraphIndex] === match.paragraphText &&
      hasRemainingOccurrence(
        paragraphTexts[activeParagraphIndex] ?? "",
        match.matchText,
        getUsedCount(paragraphUsage, activeParagraphIndex, match.matchText),
      )
    ) {
      paragraphIndex = activeParagraphIndex;
    }

    if (paragraphIndex === null) {
      const searchStart =
        activeParagraphIndex === null ? 0 : activeParagraphIndex + 1;

      for (
        let candidateIndex = searchStart;
        candidateIndex < paragraphTexts.length;
        candidateIndex++
      ) {
        const candidateText = paragraphTexts[candidateIndex] ?? "";
        if (candidateText !== match.paragraphText) {
          continue;
        }

        if (
          findExactMatchOffsets(candidateText, match.matchText).length === 0
        ) {
          continue;
        }

        paragraphIndex = candidateIndex;
        break;
      }
    }

    if (
      paragraphIndex === null &&
      activeParagraphIndex !== null &&
      paragraphTexts[activeParagraphIndex] === match.paragraphText
    ) {
      paragraphIndex = activeParagraphIndex;
    }

    if (paragraphIndex !== null) {
      activeParagraphIndex = paragraphIndex;
      incrementUsedCount(paragraphUsage, paragraphIndex, match.matchText);
    }

    return paragraphIndex;
  });
}

function findExactMatchOffsets(text: string, matchText: string): number[] {
  if (!matchText) {
    return [0];
  }

  const offsets: number[] = [];
  let searchFrom = 0;

  while (searchFrom <= text.length - matchText.length) {
    const nextIndex = text.indexOf(matchText, searchFrom);
    if (nextIndex === -1) {
      break;
    }

    offsets.push(nextIndex);
    searchFrom = nextIndex + Math.max(1, matchText.length);
  }

  return offsets;
}

function hasRemainingOccurrence(
  text: string,
  matchText: string,
  usedCount: number,
): boolean {
  return findExactMatchOffsets(text, matchText).length > usedCount;
}

function getUsedCount(
  usage: Map<number, Map<string, number>>,
  paragraphIndex: number,
  matchText: string,
): number {
  return usage.get(paragraphIndex)?.get(matchText) ?? 0;
}

function incrementUsedCount(
  usage: Map<number, Map<string, number>>,
  paragraphIndex: number,
  matchText: string,
): void {
  const paragraphUsage = usage.get(paragraphIndex) ?? new Map<string, number>();
  paragraphUsage.set(matchText, (paragraphUsage.get(matchText) ?? 0) + 1);
  usage.set(paragraphIndex, paragraphUsage);
}

function createPreview(text: string, maxLength: number): string {
  const normalizedText = text.replace(/\s+/g, " ").trim();
  if (normalizedText.length <= maxLength) {
    return normalizedText;
  }

  return `${normalizedText.substring(0, maxLength - 3)}...`;
}
