import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

export const insertTableTool = defineTool({
  name: "insert_table",
  category: "deliverable",
  parallelSafe: false,
  label: "Insert Table",
  description:
    "Insert a native Word table into the document. " +
    "Creates a properly formatted table with headers and rows. " +
    "Use this instead of insert_content for tables.",
  parameters: Type.Object({
    headers: Type.Array(Type.String({ description: "Column header text" }), {
      description: "Column headers",
    }),
    rows: Type.Array(
      Type.Array(Type.String({ description: "Cell text" }), {
        description: "Row data (array of cell values for each column)",
      }),
      { description: "Table rows data" },
    ),
    location: Type.Union(
      [
        Type.Literal("end", { description: "Insert at end of document" }),
        Type.Literal("start", { description: "Insert at start of document" }),
        Type.Literal("selection", { description: "Replace current selection" }),
      ],
      { description: "Where to insert the table", default: "end" },
    ),
    style: Type.Optional(
      Type.Union(
        [
          Type.Literal("grid", { description: "Grid style (default)" }),
          Type.Literal("plain", { description: "Plain table" }),
          Type.Literal("list", { description: "List table style" }),
        ],
        { description: "Table style", default: "grid" },
      ),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're inserting (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      if (params.headers.length === 0) {
        return toolError("At least one header is required");
      }

      for (const row of params.rows) {
        if (row.length !== params.headers.length) {
          return toolError(
            `Row length ${row.length} does not match header count ${params.headers.length}`,
          );
        }
      }

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          true,
          async () => {
            const body = context.document.body;
            const numRows = params.rows.length + 1;
            const numCols = params.headers.length;

            let table: Word.Table;
            if (params.location === "selection") {
              const selection = context.document.getSelection();
              const selectionTarget = selection as unknown as {
                insertTable(
                  rowCount: number,
                  columnCount: number,
                  insertLocation: Word.InsertLocation | string,
                ): Word.Table;
              };
              table = selectionTarget.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.replace,
              );
            } else if (params.location === "start") {
              table = body.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.start,
              );
            } else {
              table = body.insertTable(
                numRows,
                numCols,
                Word.InsertLocation.end,
              );
            }

            context.trackedObjects.add(table);

            if (params.style) {
              switch (params.style) {
                case "plain":
                  table.style = "TableGrid";
                  break;
                case "list":
                  table.style = "TableList";
                  break;
                case "grid":
                default:
                  break;
              }
            }

            table.load("rows,rowCount");
            await syncWordContext(context, signal);

            for (
              let colIndex = 0;
              colIndex < params.headers.length;
              colIndex++
            ) {
              throwIfToolAborted(signal);
              const cell = table.getCell(0, colIndex);
              cell.body.insertText(
                params.headers[colIndex],
                Word.InsertLocation.replace,
              );
            }
            await syncWordContext(context, signal);

            for (let rowIndex = 0; rowIndex < params.rows.length; rowIndex++) {
              throwIfToolAborted(signal);
              const rowData = params.rows[rowIndex];
              for (
                let colIndex = 0;
                colIndex < rowData.length && colIndex < numCols;
                colIndex++
              ) {
                throwIfToolAborted(signal);
                const cell = table.getCell(rowIndex + 1, colIndex);
                cell.body.insertText(
                  rowData[colIndex],
                  Word.InsertLocation.replace,
                );
              }
            }
            await syncWordContext(context, signal);

            context.trackedObjects.remove(table);

            return {
              inserted: true,
              rows: params.rows.length,
              columns: params.headers.length,
              style: params.style ?? "default",
              location: params.location,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error inserting table";
      return toolError(message);
    }
  },
});
