/**
 * Planner JSON schemas (PR-6 step 6.1).
 *
 * Defines the structured payloads exchanged with `provider.runStructured`
 * for planner phase 1 (`submit_plan`) and phase 3 (`submit_qc_report`).
 *
 * Schemas are TypeBox `Type.Object(...)` definitions so:
 *   - The same definition produces JSON Schema (handed to providers via
 *     `provider.runStructured(req, schema, { toolName })`).
 *   - Static TypeScript types are derived via `Static<typeof Schema>`.
 *   - Runtime validation lives in {@link validateSubmitPlan} /
 *     {@link validateSubmitQcReport} and never throws — they return a
 *     discriminated union so callers can fall back to the prose path
 *     instead of crashing the run.
 *
 * Per the recorded plan decisions:
 *   - Schemas intentionally OMIT `maxSteps` / explicit string-length caps;
 *     payload size is bounded by token budget + the planner retry ceiling.
 *   - The codebase convention is `@sinclair/typebox` (used pervasively in
 *     `src/lib/tools/`), not Ajv. TypeBox covers both schema emission and
 *     runtime validation via `@sinclair/typebox/value`.
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §3 (planner module layout)
 *   - docs/agent-refactor-implementation-plan.md §6.1
 */

import { type Static, Type } from "@sinclair/typebox";
import { Value } from "@sinclair/typebox/value";

// ============ submit_plan ============

/**
 * One step in the planner's PLAN phase. Each step is a small actionable
 * description plus an optional list of canonical tool names the model
 * intends to call. Tool names are advisory; the orchestrator does not
 * enforce that the model only calls these tools.
 */
export const PlanStepSchema = Type.Object(
  {
    title: Type.String({ minLength: 1 }),
    detail: Type.Optional(Type.String()),
    tools: Type.Optional(Type.Array(Type.String({ minLength: 1 }))),
  },
  { additionalProperties: false },
);

export const SubmitPlanSchema = Type.Object(
  {
    objective: Type.String({ minLength: 1 }),
    assumptions: Type.Optional(Type.Array(Type.String())),
    steps: Type.Array(PlanStepSchema, { minItems: 1 }),
    /** Optional explicit list of risks the model already knows about. */
    risks: Type.Optional(Type.Array(Type.String())),
  },
  { additionalProperties: false },
);

export type PlanStep = Static<typeof PlanStepSchema>;
export type SubmitPlan = Static<typeof SubmitPlanSchema>;

// ============ submit_qc_report ============

/**
 * One QC check entry. `passed: false` MUST be accompanied by `remediation`
 * — the schema marks `remediation` optional so the model can submit
 * partial QC reports, but {@link validateSubmitQcReport} cross-checks the
 * pairing and surfaces a structured diagnostic.
 */
export const QcCheckSchema = Type.Object(
  {
    requirement: Type.String({ minLength: 1 }),
    passed: Type.Boolean(),
    evidence: Type.Optional(Type.String()),
    remediation: Type.Optional(Type.String()),
  },
  { additionalProperties: false },
);

export const SubmitQcReportSchema = Type.Object(
  {
    summary: Type.String({ minLength: 1 }),
    checks: Type.Array(QcCheckSchema, { minItems: 1 }),
    residualRisk: Type.Optional(Type.String()),
  },
  { additionalProperties: false },
);

export type QcCheck = Static<typeof QcCheckSchema>;
export type SubmitQcReport = Static<typeof SubmitQcReportSchema>;

// ============ validators ============

export type PlannerValidationResult<T> =
  | { ok: true; value: T }
  | { ok: false; errors: string[] };

function collectErrors(schema: unknown, value: unknown): string[] {
  const errors: string[] = [];
  for (const error of Value.Errors(
    schema as Parameters<typeof Value.Errors>[0],
    value,
  )) {
    const path = error.path === "" ? "(root)" : error.path;
    errors.push(`${path}: ${error.message}`);
  }
  return errors;
}

/**
 * Validate a candidate `submit_plan` payload. Returns a discriminated
 * union so the caller can either consume the typed value or fall back to
 * the prose-driven planner prompt.
 */
export function validateSubmitPlan(
  candidate: unknown,
): PlannerValidationResult<SubmitPlan> {
  if (!Value.Check(SubmitPlanSchema, candidate)) {
    return { ok: false, errors: collectErrors(SubmitPlanSchema, candidate) };
  }
  return { ok: true, value: candidate };
}

/**
 * Validate a candidate `submit_qc_report` payload. In addition to the
 * TypeBox schema check, asserts that any failed check carries a
 * `remediation` string — the schema cannot express that conditional.
 */
export function validateSubmitQcReport(
  candidate: unknown,
): PlannerValidationResult<SubmitQcReport> {
  if (!Value.Check(SubmitQcReportSchema, candidate)) {
    return {
      ok: false,
      errors: collectErrors(SubmitQcReportSchema, candidate),
    };
  }
  const missingRemediation = candidate.checks
    .map((check, index) =>
      !check.passed && !check.remediation
        ? `checks[${index}]: failed check requires remediation`
        : null,
    )
    .filter((entry): entry is string => entry !== null);
  if (missingRemediation.length > 0) {
    return { ok: false, errors: missingRemediation };
  }
  return { ok: true, value: candidate };
}

// ============ planner-tool descriptors ============

/**
 * Canonical names the orchestrator uses when surfacing planner phases as
 * `provider.runStructured(...)` requests. Providers that wrap the schemas
 * as named tools (e.g. OpenAI `tool_choice`) SHOULD use these names so
 * telemetry stays consistent across providers.
 */
export const SUBMIT_PLAN_TOOL_NAME = "submit_plan";
export const SUBMIT_QC_REPORT_TOOL_NAME = "submit_qc_report";
