type ToolCallPart = Extract<MessagePart, { type: "toolCall" }>;

function parseDirtyRanges(result: string | undefined): DirtyRange[] | null {
  if (!result) return null;
  try {
    const parsed = JSON.parse(result);
    if (parsed._dirtyRanges && Array.isArray(parsed._dirtyRanges)) {
      return parsed._dirtyRanges;
    }
  } catch {
    // Not valid JSON or no dirty ranges
  }
  return null;
}

function DirtyRangeLink({ range }: { range: DirtyRange }) {
  const { getSheetName } = useChat();
  const styles = useStyles();
  const sheetName = getSheetName(range.sheetId);

  if (range.sheetId < 0) {
    const label =
      range.range === "*" ? "Unknown sheet" : `Unknown!${range.range}`;
    return (
      <Caption2 style={{ color: tokens.colorStatusWarningForeground1 }}>
        {label}
      </Caption2>
    );
  }

  if (!sheetName) {
    return null;
  }

  const label =
    range.range === "*" ? `${sheetName} (all)` : `${sheetName}!${range.range}`;

  return (
    <Button
      appearance="transparent"
      className={styles.dirtyRangeLink}
      onClick={(e) => {
        e.stopPropagation();
        const navRange = range.range === "*" ? undefined : range.range;
        navigateTo(range.sheetId, navRange).catch((err) => {
          console.error("[DirtyRange] Navigation failed:", err);
        });
      }}
      size="small"
    >
      {label}
    </Button>
  );
}

function DirtyRangeLinks({ ranges }: { ranges: DirtyRange[] }) {
  const { getSheetName } = useChat();
  const merged = useMemo(() => mergeRanges(ranges), [ranges]);

  const validRanges = merged.filter(
    (r) => r.sheetId < 0 || getSheetName(r.sheetId),
  );

  if (validRanges.length === 0) return null;

  return (
    <>
      {validRanges.map((r, i) => (
        <span key={`${r.sheetId}-${r.range}`}>
          {i > 0 && <span className="text-(--chat-warning-muted)">, </span>}
          <DirtyRangeLink range={r} />
        </span>
      ))}
    </>
  );
}

function DirtyRangeSummary({ ranges }: { ranges: DirtyRange[] }) {
  const { getSheetName, state } = useChat();
  const merged = useMemo(() => mergeRanges(ranges), [ranges]);

  console.log("[DirtyRangeSummary] sheetNames map:", state.sheetNames);
  console.log("[DirtyRangeSummary] merged ranges:", merged);

  if (merged.length === 0) return null;

  const formatBrief = (range: DirtyRange): string | null => {
    if (range.sheetId < 0) return range.range === "*" ? "unknown" : range.range;
    const sheetName = getSheetName(range.sheetId);
    console.log(
      `[DirtyRangeSummary] sheetId=${range.sheetId} -> sheetName=${sheetName}`,
    );
    if (!sheetName) return null;
    if (range.range === "*") return sheetName;
    return `${range.range}`;
  };

  if (merged.length === 1) {
    const brief = formatBrief(merged[0]);
    if (!brief) return null;
    return (
      <Caption2
        style={{
          color: tokens.colorStatusWarningForeground1,
          textOverflow: "ellipsis",
          overflow: "hidden",
          whiteSpace: "nowrap",
        }}
      >
        → {brief}
      </Caption2>
    );
  }

  const validRanges = merged.filter(
    (r) => r.sheetId < 0 || getSheetName(r.sheetId),
  );
  if (validRanges.length === 0) return null;

  return (
    <Caption2 style={{ color: tokens.colorStatusWarningForeground1 }}>
      → {validRanges.length} ranges
    </Caption2>
  );
}

/**
 * Download button component for VFS files
 */
function DownloadButton({
  filePath,
  label,
  tooltip,
}: {
  filePath: string;
  label: string;
  tooltip?: string;
}) {
  const [isDownloading, setIsDownloading] = useState(false);

  const handleDownload = async () => {
    setIsDownloading(true);
    try {
      await downloadFile(filePath);
    } catch (err) {
      console.error("[DownloadButton] Failed to download:", err);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <Tooltip
      content={tooltip || `Download ${filePath.split("/").pop()}`}
      relationship="label"
    >
      <Button
        appearance="secondary"
        size="small"
        onClick={handleDownload}
        disabled={isDownloading}
        icon={isDownloading ? <span>⏳</span> : <span>💾</span>}
      >
        {isDownloading ? "Downloading..." : label}
      </Button>
    </Tooltip>
  );
}

function ToolResultContent({
  result,
  toolName,
}: {
  result: string;
  toolName: string;
}) {
  // Parse the result
  let parsed: unknown;
  try {
    parsed = JSON.parse(result);
  } catch {
    // Not valid JSON, show as plain text
    return (
      <Streamdown plugins={{ code }}>{`\`\`\`\n${result}\n\`\`\``}</Streamdown>
    );
  }

  // For email tools, show a cleaner summary instead of raw HTML
  if (
    toolName === "email_create" ||
    toolName === "email_reply" ||
    toolName === "email_forward"
  ) {
    const emailResult = parsed as {
      success?: boolean;
      message?: string;
      subject?: string;
      to?: string[];
      cc?: string[];
      bcc?: string[];
      importance?: string;
      error?: string;
    };

    return (
      <div
        style={{
          fontFamily: tokens.fontFamilyMonospace,
          fontSize: tokens.fontSizeBase200,
        }}
      >
        <div
          style={{
            color: tokens.colorStatusSuccessForeground1,
            marginBottom: tokens.spacingVerticalXS,
          }}
        >
          ✓ {emailResult.message || "Email draft created"}
        </div>
        {emailResult.subject && (
          <div style={{ marginBottom: tokens.spacingVerticalXS }}>
            <strong>Subject:</strong> {emailResult.subject}
          </div>
        )}
        {emailResult.to && emailResult.to.length > 0 && (
          <div style={{ marginBottom: tokens.spacingVerticalXS }}>
            <strong>To:</strong> {emailResult.to.join(", ")}
          </div>
        )}
        {emailResult.cc && emailResult.cc.length > 0 && (
          <div style={{ marginBottom: tokens.spacingVerticalXS }}>
            <strong>Cc:</strong> {emailResult.cc.join(", ")}
          </div>
        )}
        {emailResult.importance && emailResult.importance !== "normal" && (
          <div>
            <strong>Importance:</strong> {emailResult.importance}
          </div>
        )}
      </div>
    );
  }

  // For drawio tool, show download button for the .drawio file
  if (toolName === "generate_map_chart") {
    const mapResult = parsed as {
      success?: boolean;
      filePath?: string;
      fileName?: string;
      width?: number;
      height?: number;
      totalPoints?: number;
      mapType?: string;
      mapSource?: string;
      error?: string;
    };

    return (
      <div
        style={{
          fontFamily: tokens.fontFamilyMonospace,
          fontSize: tokens.fontSizeBase200,
        }}
      >
        {mapResult.success ? (
          <>
            <div
              style={{
                color: tokens.colorStatusSuccessForeground1,
                marginBottom: tokens.spacingVerticalXS,
              }}
            >
              ✓ Map generated
            </div>
            {typeof mapResult.totalPoints === "number" && (
              <div style={{ marginBottom: tokens.spacingVerticalXS }}>
                <strong>Points:</strong> {mapResult.totalPoints}
              </div>
            )}
            {mapResult.width && mapResult.height && (
              <div style={{ marginBottom: tokens.spacingVerticalXS }}>
                <strong>Size:</strong> {mapResult.width} x {mapResult.height}
              </div>
            )}
            {mapResult.mapType && (
              <div style={{ marginBottom: tokens.spacingVerticalXS }}>
                <strong>Type:</strong> {mapResult.mapType}
              </div>
            )}
            {mapResult.mapSource && (
              <div style={{ marginBottom: tokens.spacingVerticalXS }}>
                <strong>Source:</strong> {mapResult.mapSource}
              </div>
            )}
            {mapResult.filePath && (
              <div style={{ marginTop: tokens.spacingVerticalS }}>
                <DownloadButton
                  filePath={mapResult.filePath}
                  label="Download map SVG"
                  tooltip="Download the generated map SVG file"
                />
              </div>
            )}
          </>
        ) : (
          <div style={{ color: tokens.colorStatusDangerForeground1 }}>
            ✗ {mapResult.error || "Failed to generate map"}
          </div>
        )}
      </div>
    );
  }

  // For drawio tool, show download button for the .drawio file
  if (toolName === "insert_drawio") {
    const drawioResult = parsed as {
      success?: boolean;
      filePath?: string;
      drawioFilePath?: string;
      shapeId?: string;
      anchor?: string;
      width?: number;
      height?: number;
      error?: string;
    };

    return (
      <div
        style={{
          fontFamily: tokens.fontFamilyMonospace,
          fontSize: tokens.fontSizeBase200,
        }}
      >
        {drawioResult.success ? (
          <>
            <div
              style={{
                color: tokens.colorStatusSuccessForeground1,
                marginBottom: tokens.spacingVerticalXS,
              }}
            >
              ✓ Diagram inserted successfully
            </div>
            {drawioResult.width && drawioResult.height && (
              <div style={{ marginBottom: tokens.spacingVerticalXS }}>
                <strong>Size:</strong> {drawioResult.width} ×{" "}
                {drawioResult.height}
              </div>
            )}
            {drawioResult.drawioFilePath && (
              <div style={{ marginTop: tokens.spacingVerticalS }}>
                <DownloadButton
                  filePath={drawioResult.drawioFilePath}
                  label="Download .drawio file\t"
                  tooltip="Open this file at diagrams.net to edit"
                />
              </div>
            )}
          </>
        ) : (
          <div style={{ color: tokens.colorStatusDangerForeground1 }}>
            ✗ {drawioResult.error || "Failed to create diagram"}
          </div>
        )}
      </div>
    );
  }

  // Default: show as formatted JSON
  return (
    <Streamdown
      plugins={{ code }}
    >{`\`\`\`json\n${JSON.stringify(parsed, null, 2)}\n\`\`\``}</Streamdown>
  );
}

function ToolCallBlock({ part }: { part: ToolCallPart }) {
  const { getSheetName } = useChat();
  const styles = useStyles();
  const [isExpanded, setIsExpanded] = useState(false);
  const explanation = (part.args as { explanation?: string })?.explanation;
  const showStatusText =
    !!part.statusText && part.status !== "complete" && part.status !== "error";

  const dirtyRanges = useMemo(
    () => parseDirtyRanges(part.result),
    [part.result],
  );
  const hasValidDirtyRanges = useMemo(() => {
    if (!dirtyRanges || dirtyRanges.length === 0) return false;
    return dirtyRanges.some((r) => r.sheetId < 0 || getSheetName(r.sheetId));
  }, [dirtyRanges, getSheetName]);

  const getStatusIcon = () => {
    switch (part.status) {
      case "pending":
        return (
          <Caption2 style={{ color: tokens.colorNeutralForeground3 }}>
            ⏳
          </Caption2>
        );
      case "running":
        return (
          <Caption2 style={{ color: tokens.colorBrandForeground1 }}>
            ⏳
          </Caption2>
        );
      case "complete":
        return (
          <CheckmarkCircleRegular
            fontSize={14}
            style={{ color: tokens.colorStatusSuccessForeground1 }}
          />
        );
      case "error":
        return (
          <DismissCircleRegular
            fontSize={14}
            style={{ color: tokens.colorStatusDangerForeground1 }}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className={styles.toolCallBlock}>
      <Button
        appearance="transparent"
        onClick={() => setIsExpanded(!isExpanded)}
        icon={
          isExpanded ? (
            <ChevronDownRegular fontSize={12} />
          ) : (
            <ChevronRightRegular fontSize={12} />
          )
        }
        size="small"
        style={{
          width: "100%",
          justifyContent: "flex-start",
          fontSize: tokens.fontSizeBase100,
          color: tokens.colorNeutralForeground2,
        }}
      >
        <WrenchRegular
          fontSize={12}
          style={{ marginRight: tokens.spacingHorizontalXS }}
        />
        <div className={styles.toolCallText}>
          <span className={styles.toolCallTitle}>
            {explanation || part.name}
          </span>
          {showStatusText && (
            <Caption2 className={styles.toolCallStatusText}>
              {part.statusText}
            </Caption2>
          )}
        </div>
        {hasValidDirtyRanges && !isExpanded && (
          <Tooltip content="Modified cells" relationship="label">
            <span
              style={{
                display: "flex",
                alignItems: "center",
                gap: tokens.spacingHorizontalXS,
                color: tokens.colorStatusWarningForeground1,
                flexShrink: 0,
              }}
            >
              <EditRegular fontSize={12} />
              <DirtyRangeSummary ranges={dirtyRanges} />
            </span>
          </Tooltip>
        )}
        {getStatusIcon()}
      </Button>
      {isExpanded && (
        <div className={styles.toolCallExpanded}>
          {hasValidDirtyRanges && (
            <div className={styles.dirtyRangesBanner}>
              <EditRegular fontSize={12} />
              <span>Modified:</span>
              <DirtyRangeLinks ranges={dirtyRanges} />
            </div>
          )}
          <div style={{ padding: tokens.spacingHorizontalS }}>
            <div
              style={{
                fontSize: tokens.fontSizeBase100,
                color: tokens.colorNeutralForeground3,
                textTransform: "uppercase",
                marginBottom: tokens.spacingVerticalXS,
              }}
            >
              args
            </div>
            <div style={{ maxHeight: "128px", overflowY: "auto" }}>
              <Streamdown
                plugins={{ code }}
              >{`\`\`\`json\n${JSON.stringify(part.args, null, 2)}\n\`\`\``}</Streamdown>
            </div>
          </div>
          {part.result && (
            <div
              style={{
                padding: tokens.spacingHorizontalS,
                borderTop: `1px solid ${tokens.colorNeutralStroke1}`,
              }}
            >
              <div
                style={{
                  fontSize: tokens.fontSizeBase100,
                  color: tokens.colorNeutralForeground3,
                  textTransform: "uppercase",
                  marginBottom: tokens.spacingVerticalXS,
                }}
              >
                {part.status === "error" ? "error" : "result"}
              </div>
              <div style={{ maxHeight: "160px", overflowY: "auto" }}>
                <ToolResultContent result={part.result} toolName={part.name} />
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function LoadingIndicator() {
  const styles = useStyles();
  const [frameIndex, setFrameIndex] = useState(0);

  useEffect(() => {
    const intervalId = window.setInterval(() => {
      setFrameIndex((current) => (current + 1) % LOADING_FRAMES.length);
    }, 220);

    return () => window.clearInterval(intervalId);
  }, []);

  return (
    <output aria-live="polite" className={styles.loadingIndicator}>
      <span aria-hidden="true" className={styles.loadingCharacter}>
        {LOADING_FRAMES[frameIndex]}
      </span>
      <span>Thinking</span>
    </output>
  );
}

function parseCitationUri(
  href: string,
): { sheetId: number; range?: string } | null {
  if (!href.startsWith("#cite:")) return null;
  const path = href.slice("#cite:".length);
  const bangIdx = path.indexOf("!");
  if (bangIdx === -1) {
    const sheetId = Number.parseInt(path, 10);
    return Number.isNaN(sheetId) ? null : { sheetId };
  }
  const sheetId = Number.parseInt(path.slice(0, bangIdx), 10);
  const range = path.slice(bangIdx + 1);
  return Number.isNaN(sheetId) ? null : { sheetId, range };
}

function CitationLink({
  href,
  children,
  ...props
}: AnchorHTMLAttributes<HTMLAnchorElement>) {
  const citation = href ? parseCitationUri(href) : null;

  if (!citation) {
    return (
      <a href={href} target="_blank" rel="noopener noreferrer" {...props}>
        {children}
      </a>
    );
  }

  return (
    <Button
      appearance="transparent"
      onClick={() => {
        navigateTo(citation.sheetId, citation.range).catch((err) => {
          console.error("[Citation] Navigation failed:", err);
        });
      }}
      size="small"
      style={{ color: tokens.colorBrandForeground1, cursor: "pointer" }}
    >
      {children}
    </Button>
  );
}

