/**
 * Agent run state + `apply()` reducer.
 *
 * PR-4A. Per blueprint §4:
 *   - `apply()` is the SOLE mutator of {@link AgentRunState}.
 *   - `apply()` MUST NOT call provider.runTurn(...). The only async work
 *     permitted is `dispatcher.dispatch(...)` and synchronous `emit()`
 *     events (fire-and-forget) into a buffered sink.
 *   - At most one `apply()` call may be in flight per Agent instance; the
 *     orchestrator enforces this externally via the `isRunning` flag (see
 *     {@link Agent.prompt}).
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §4, §5, §8, §9.1
 *   - docs/agent-refactor-implementation-plan.md PR-4A step 3.1, 3.6, 3.7
 */

import type { AgentMessage, AssistantContentBlock, UsageInfo } from "../types";
import type { ToolCategory } from "../types";
import type { Action } from "./actions";
import type { NudgeReason } from "./nudges";
import { nudgeCeiling } from "./nudges";

export type RunStopReason =
  | "complete"
  | "max_turns"
  | "timeout"
  | "aborted"
  | "error";

export type RunStatus =
  | { kind: "init" }
  | { kind: "planning" }
  | { kind: "executing"; deliverableCount: number }
  | { kind: "verifying" }
  | { kind: "nudging"; reason: NudgeReason; attempt: number }
  | { kind: "done"; stopReason: RunStopReason };

export interface ExecutedTool {
  name: string;
  category: ToolCategory;
  toolCallId: string;
  ok: boolean;
  /** True when dispatcher short-circuited as TOOL_DEDUP_SUPPRESSED. */
  dedupSuppressed?: boolean;
}

export interface AgentRunFlags {
  plannerNudgesUsed: number;
  actionNudgeUsed: boolean;
  grantedFinalizationPass: boolean;
  plannerDirectiveInjected: boolean;
}

export interface AgentRunState {
  status: RunStatus;
  iteration: number; // 1-based once the first turn starts; 0 before
  maxIterations: number;
  startedAtMs: number;
  maxWallClockMs: number;
  /** `startedAtMs + maxWallClockMs`, cached for fast guards. */
  timeoutAtMs: number;
  nudgeAttempts: Partial<Record<NudgeReason, number>>;
  executedToolsThisRun: ExecutedTool[];
  /** Mirrors `executedToolsThisRun` outside planner mode (blueprint §5). */
  executedToolsThisStep: ExecutedTool[];
  ephemeralMessages: AgentMessage[];
  /**
   * Number of times the current ephemeral batch has already survived a
   * failed `provider.runTurn` (blueprint §8). The orchestrator drops the
   * batch after one failed resend to avoid indefinite retention.
   */
  ephemeralResendAttempts: number;
  lastUserText: string;
  /** True when this run is operating in planner-mode. */
  plannerMode: boolean;
  /**
   * Snapshot at run start: does the registered tool set contain any
   * `category: "deliverable"` tool? When `false`, the planner-mode
   * deliverable gate (decide.ts §rules 8/9) is bypassed because the
   * assistant's prose IS the deliverable for the run (research-only /
   * pure Q&A tasks).
   */
  hasDeliverableTools: boolean;
  flags: AgentRunFlags;
  /** Last finalize result captured by `apply()` for the orchestrator. */
  finalize?: {
    blocks: AssistantContentBlock[];
    usage?: UsageInfo;
    stopReason: RunStopReason;
  };
}

export interface InitialStateInput {
  maxIterations: number;
  maxWallClockMs: number;
  startedAtMs: number;
  lastUserText: string;
  plannerMode: boolean;
  /**
   * Optional snapshot indicating whether the registered tool set
   * contains any `category: "deliverable"` tool. Defaults to `true` so
   * that callers (and existing tests) which omit the field preserve the
   * historical strict planner gate behavior. Set to `false` for
   * research-only runs (no deliverable-category tools registered) so
   * the planner gate is bypassed and the assistant's prose answer is
   * treated as the deliverable.
   */
  hasDeliverableTools?: boolean;
}

export function createInitialState(input: InitialStateInput): AgentRunState {
  return {
    status: { kind: "init" },
    iteration: 0,
    maxIterations: input.maxIterations,
    startedAtMs: input.startedAtMs,
    maxWallClockMs: input.maxWallClockMs,
    timeoutAtMs: input.startedAtMs + input.maxWallClockMs,
    nudgeAttempts: {},
    executedToolsThisRun: [],
    executedToolsThisStep: [],
    ephemeralMessages: [],
    ephemeralResendAttempts: 0,
    lastUserText: input.lastUserText,
    plannerMode: input.plannerMode,
    hasDeliverableTools: input.hasDeliverableTools ?? true,
    flags: {
      plannerNudgesUsed: 0,
      actionNudgeUsed: false,
      grantedFinalizationPass: false,
      plannerDirectiveInjected: false,
    },
  };
}

// ============ Telemetry events ============

export type EmitEvent =
  | {
      type: "rule_fired";
      rule: number;
      iteration: number;
      runId: string;
      nudgeReason?: NudgeReason;
    }
  | {
      type: "tool_dispatched";
      iteration: number;
      runId: string;
      toolNames: string[];
    }
  | {
      type: "tool_settled";
      iteration: number;
      runId: string;
      results: ExecutedTool[];
    }
  | {
      type: "nudge_appended";
      iteration: number;
      runId: string;
      reason: NudgeReason;
    }
  | {
      type: "nudge_dropped_for_budget";
      iteration: number;
      runId: string;
      reason?: NudgeReason;
    }
  | {
      type: "finalize";
      iteration: number;
      runId: string;
      stopReason: RunStopReason;
      deliverableGateSatisfied: boolean;
      executedToolCount: number;
    };

export type Emit = (event: EmitEvent) => void;

// ============ apply() reducer ============

/**
 * Tool-dispatch callback. The orchestrator owns the real
 * {@link ToolDispatcher}; tests inject a fake. apply() awaits the
 * returned promise and appends results to the run state.
 */
export type ApplyDispatch = (
  calls: { id: string; name: string; arguments: Record<string, unknown> }[],
  signal: AbortSignal,
) => Promise<ExecutedTool[]>;

export interface ApplyContext {
  runId: string;
  dispatch: ApplyDispatch;
  signal: AbortSignal;
  emit: Emit;
  /** Wall-clock sample for status-transition timestamps. */
  nowMs: number;
}

/**
 * apply(action, state, ctx) — the only function that mutates state.
 *
 * Re-entrancy: the orchestrator MUST guarantee at most one in-flight
 * apply() per Agent. apply() does not check this itself; double-entry
 * would corrupt `executedToolsThis*` and `nudgeAttempts`.
 */
export async function apply(
  action: Action,
  state: AgentRunState,
  ctx: ApplyContext,
): Promise<AgentRunState> {
  switch (action.type) {
    case "execute_tools": {
      const next: AgentRunState = {
        ...state,
        status: {
          kind: "executing",
          deliverableCount:
            state.status.kind === "executing"
              ? state.status.deliverableCount
              : 0,
        },
      };

      ctx.emit({
        type: "tool_dispatched",
        iteration: state.iteration,
        runId: ctx.runId,
        toolNames: action.calls.map((c) => c.name),
      });

      const results = await ctx.dispatch(action.calls, ctx.signal);

      ctx.emit({
        type: "tool_settled",
        iteration: state.iteration,
        runId: ctx.runId,
        results,
      });

      // Append all settled executions to run-scope history. In planner mode,
      // dedup-suppressed calls MUST NOT count as fresh step work.
      const settled = results;
      const stepEligible = state.plannerMode
        ? settled.filter((r) => !r.dedupSuppressed)
        : settled;
      const newRun = [...state.executedToolsThisRun, ...settled];
      const newStep = [...state.executedToolsThisStep, ...stepEligible];
      next.executedToolsThisRun = newRun;
      next.executedToolsThisStep = newStep;

      // Update deliverableCount for status visibility (blueprint §4).
      const deliverableHits = stepEligible.filter(
        (r) => r.ok && r.category === "deliverable",
      ).length;
      next.status = {
        kind: "executing",
        deliverableCount:
          (state.status.kind === "executing"
            ? state.status.deliverableCount
            : 0) + deliverableHits,
      };

      return next;
    }

    case "nudge_and_retry": {
      const reason = action.reason;
      const prior = state.nudgeAttempts[reason] ?? 0;
      const ceiling = nudgeCeiling(reason);

      // Defensive: decide() is responsible for ceiling enforcement, but if
      // a caller emits an over-ceiling nudge we drop it and emit telemetry
      // rather than corrupting state.
      if (prior >= ceiling) {
        ctx.emit({
          type: "nudge_dropped_for_budget",
          iteration: state.iteration,
          runId: ctx.runId,
          reason,
        });
        return state;
      }

      const next: AgentRunState = {
        ...state,
        status: { kind: "nudging", reason, attempt: prior + 1 },
        nudgeAttempts: { ...state.nudgeAttempts, [reason]: prior + 1 },
        ephemeralMessages: action.ephemeral
          ? [
              ...state.ephemeralMessages,
              {
                role: "user",
                content: action.userText,
                timestamp: ctx.nowMs,
              },
            ]
          : state.ephemeralMessages,
        flags: { ...state.flags },
      };

      if (reason === "action_without_tools") {
        next.flags.actionNudgeUsed = true;
      }
      if (reason === "planner_no_deliverable") {
        next.flags.plannerNudgesUsed = state.flags.plannerNudgesUsed + 1;
      }
      if (reason === "final_finalization_pass") {
        next.flags.grantedFinalizationPass = true;
      }

      ctx.emit({
        type: "nudge_appended",
        iteration: state.iteration,
        runId: ctx.runId,
        reason,
      });

      return next;
    }

    case "finalize": {
      const deliverableScope = state.plannerMode
        ? state.executedToolsThisStep
        : state.executedToolsThisRun;
      const deliverableGateSatisfied = deliverableScope.some(
        (t) => t.ok && t.category === "deliverable",
      );
      ctx.emit({
        type: "finalize",
        iteration: state.iteration,
        runId: ctx.runId,
        stopReason: action.stopReason,
        deliverableGateSatisfied,
        executedToolCount: state.executedToolsThisRun.length,
      });
      return {
        ...state,
        status: { kind: "done", stopReason: action.stopReason },
        finalize: {
          blocks: action.blocks,
          usage: action.usage,
          stopReason: action.stopReason,
        },
      };
    }

    case "abort": {
      ctx.emit({
        type: "finalize",
        iteration: state.iteration,
        runId: ctx.runId,
        stopReason: "aborted",
        deliverableGateSatisfied: false,
        executedToolCount: state.executedToolsThisRun.length,
      });
      return {
        ...state,
        status: { kind: "done", stopReason: "aborted" },
      };
    }
  }
}

// ============ Planner-mode fallback reset (blueprint §9.1) ============

/**
 * Reset planner-scoped state when the planner phase aborts mid-run and
 * execution falls back to non-planner mode.
 *
 * Per blueprint §9.1:
 *   - Clear `executedToolsThisStep` (so rule 9 starts fresh).
 *   - Clear `flags.plannerDirectiveInjected`; reset `plannerNudgesUsed` to 0.
 *   - Preserve `executedToolsThisRun` (run-scope history is still valid).
 *   - Preserve non-planner `nudgeAttempts`; only `planner_no_deliverable`
 *     and `plan_schema_invalid` counters are reset.
 */
export function resetForPlannerFallback(state: AgentRunState): AgentRunState {
  const { planner_no_deliverable, plan_schema_invalid, ...keep } =
    state.nudgeAttempts;
  void planner_no_deliverable;
  void plan_schema_invalid;
  return {
    ...state,
    plannerMode: false,
    executedToolsThisStep: [],
    nudgeAttempts: keep,
    flags: {
      ...state.flags,
      plannerDirectiveInjected: false,
      plannerNudgesUsed: 0,
    },
  };
}

/**
 * Advance to the next planner step: reset `executedToolsThisStep` only.
 * `executedToolsThisRun` and `nudgeAttempts` are preserved so run-scope
 * counters keep accumulating across steps.
 */
export function advancePlannerStep(state: AgentRunState): AgentRunState {
  return {
    ...state,
    executedToolsThisStep: [],
  };
}
