/**
 * AzureProvider — provider implementation for Azure OpenAI deployments.
 *
 * PR-3 step 2.1: encapsulates wire-format conversion, retry/fallback policy,
 * SSE streaming, and chunk decoding behind the {@link LLMProvider} interface.
 *
 * The provider owns ONLY: HTTP transport, request/response shape, Azure
 * responses-API quirks, 400 fallback adjustments, and stream decoding via
 * the shared helpers. It MUST NOT mutate orchestrator state, push messages,
 * emit agent events, or make loop decisions.
 *
 * See:
 *   - docs/agent-refactor-blueprint.md §7 (Provider responsibilities)
 *   - docs/agent-refactor-implementation-plan.md Phase 2
 */

import { InteractiveBrowserCredential } from "@azure/identity";
import { AIRGAP_CONFIG } from "../../airgap-config";
import { captureEntraIdentityFromAccessToken } from "../../entra-identity";
import { estimateTokens, prepareMessagesForApi } from "../../token-manager";
import type { WorkflowManager } from "../../workflow";
import { type AgentError, asAgentError, createAgentError } from "../errors";
import { stringifyToolArgumentsForHistory } from "../tool-argument-history";
import type {
  AgentMessage,
  AssistantMessage,
  Tool,
  ToolResultMessage,
  UserMessage,
} from "../types";
import type {
  JSONSchema,
  LLMProvider,
  LLMTurnRequest,
  LLMTurnResult,
  StructuredOutputOptions,
  TokenEstimate,
} from "./provider";
import { applyAzure400Fallback } from "./shared/azure-fallback";
import { convertMessagesToChatCompletions } from "./shared/message-format";
import { buildReasoningOptions, isReasoningModel } from "./shared/reasoning";
import {
  type ChatCompletionStreamChunk,
  decodeChatCompletionStream,
  hasMeaningfulChatCompletionDelta,
} from "./shared/stream-decoder";
import { readStreamChunkWithTimeout } from "./shared/stream-read";

export type AzureApiMode = "chat-completions" | "responses";

export interface AzureProviderConfig {
  endpoint: string;
  deploymentName: string;
  apiMode?: AzureApiMode;
  apiKey?: string;
  useEntraId?: boolean;
  azureClientId?: string;
  /** Max retries for the provider's internal HTTP retry loop. */
  maxRetries?: number;
  /** Workflow manager used for rate limiting and recoverable HTTP error reporting. */
  workflowManager: WorkflowManager;
}

// Azure-specific stream chunks share the chat-completions wire shape with
// OpenAI; the shared `ChatCompletionStreamChunk` is the canonical type. Per
// PR-9a the inline `NormalizedStreamChunk` / `LegacyFunctionCallDelta`
// definitions were replaced with re-exports of the shared shape so the
// transport and decoder agree on a single contract.
type NormalizedStreamChunk = ChatCompletionStreamChunk;

/**
 * PR-9c: gate noisy debug-only payload dumps (chunk-by-chunk SSE dumps and
 * full converted-message JSON dumps) behind Vite's `import.meta.env.DEV`.
 * These were intended as developer-time tracing aids and were always-on in
 * production prior to this PR. Operational signals (retry attempts, 4xx/5xx
 * details, rate-limit notices) are NOT gated and continue to log at all
 * times via console.warn / console.error. The try/catch keeps node test
 * runners that don't expose `import.meta.env` happy. Mirrors the
 * `isDevBuild()` pattern used in turn-recorder.ts.
 */
function isDevBuild(): boolean {
  try {
    return Boolean(
      (import.meta as unknown as { env?: { DEV?: boolean } })?.env?.DEV,
    );
  } catch {
    return false;
  }
}

export class AzureProvider implements LLMProvider {
  readonly id = "azure" as const;

  private readonly config: AzureProviderConfig;
  private readonly normalizedEndpoint: string;
  private readonly logPrefix = "[AzureProvider]";

  constructor(config: AzureProviderConfig) {
    this.config = { apiMode: "chat-completions", maxRetries: 5, ...config };
    this.normalizedEndpoint = this.normalizeEndpoint(config.endpoint);
  }

  /** Allow the orchestrator to swap the workflow manager (e.g. on reconfig). */
  setWorkflowManager(workflowManager: WorkflowManager): void {
    (this.config as { workflowManager: WorkflowManager }).workflowManager =
      workflowManager;
  }

  /**
   * PR-9b: orchestrator-side token budget calls this to get the exact
   * wire-shape tools JSON. Azure has TWO different shapes — chat-completions
   * uses the nested `{ type: "function", function: {...} }` shape; the
   * responses API uses a flat `{ type: "function", name, ... }` shape.
   * The pre-PR-9b orchestrator hard-coded the chat-completions shape via
   * `computeToolsJsonFromProvider`, which produced an undercount in
   * responses-API mode.
   */
  toToolsJsonForBudget(tools: Tool[]): string {
    const wireShape =
      this.config.apiMode === "responses"
        ? this.convertToolsToResponsesFormat(tools)
        : this.convertToolsToAzureFormat(tools);
    return JSON.stringify(wireShape);
  }

  estimateTokens(
    messages: AgentMessage[],
    systemPrompt: string,
    tools: Tool[],
  ): TokenEstimate {
    const toolsJson = this.toToolsJsonForBudget(tools);
    const result = prepareMessagesForApi(
      messages,
      systemPrompt,
      toolsJson,
      undefined,
    );
    return {
      inputTokens: result.tokenCount.total,
      perMessageOverhead: result.tokenCount.messages,
      toolSchemaTokens: result.tokenCount.tools,
    };
  }

  async runTurn(req: LLMTurnRequest): Promise<LLMTurnResult> {
    try {
      const useResponsesApi = this.config.apiMode === "responses";

      const wireMessages = useResponsesApi
        ? this.convertMessagesToResponsesFormat(req.messages, req.systemPrompt)
        : this.convertMessagesToAzureFormat(req.messages, req.systemPrompt);

      const wireTools =
        req.tools.length > 0
          ? useResponsesApi
            ? this.convertToolsToResponsesFormat(req.tools)
            : this.convertToolsToAzureFormat(req.tools)
          : undefined;

      // Reasoning models (o1/o3/o4/gpt-5*, plus Azure responses-API
      // deployments) reject any non-default `temperature`. Skip it when:
      //   - the responses API is in use, OR
      //   - the user has selected a non-`off` thinking level (implies a
      //     reasoning model), OR
      //   - the deployment name matches a known reasoning family.
      // The 400 fallback chain still drops `temperature` as a safety net
      // for opaque deployment names.
      const omitTemperature =
        useResponsesApi ||
        req.thinkingLevel !== "off" ||
        isReasoningModel(this.config.deploymentName);

      const options: Record<string, unknown> = {
        tools: wireTools,
        tool_choice: req.tools.length > 0 ? "auto" : undefined,
        ...(omitTemperature ? {} : { temperature: 0.2 }),
        ...(useResponsesApi
          ? { max_output_tokens: req.maxOutputTokens }
          : {
              max_completion_tokens: req.maxOutputTokens,
              stream_options: { include_usage: true },
            }),
        // Apply the user-selected reasoning effort. Non-reasoning Azure
        // deployments reject this with 400; the fallback chain in
        // `applyAzure400Fallback` drops it and retries.
        ...buildReasoningOptions(
          req.thinkingLevel,
          useResponsesApi ? "responses" : "chat-completions",
        ),
      };

      const events = this.streamChatCompletions(
        wireMessages,
        options,
        req.abortSignal,
      );

      return await this.decodeStream(events, req.abortSignal);
    } catch (error) {
      if (req.abortSignal.aborted) {
        throw error;
      }
      throw this.mapProviderError(error);
    }
  }

  async runStructured<T>(
    req: LLMTurnRequest,
    schema: JSONSchema,
    options: StructuredOutputOptions,
  ): Promise<T> {
    try {
      const useResponsesApi = this.config.apiMode === "responses";
      const wireMessages = useResponsesApi
        ? this.convertMessagesToResponsesFormat(req.messages, req.systemPrompt)
        : this.convertMessagesToAzureFormat(req.messages, req.systemPrompt);

      // Mirror runTurn: reasoning deployments reject `temperature`.
      const omitTemperature =
        useResponsesApi ||
        req.thinkingLevel !== "off" ||
        isReasoningModel(this.config.deploymentName);

      const requestOptions: Record<string, unknown> = {
        tools: [
          this.createStructuredTool(options.toolName, schema, useResponsesApi),
        ],
        tool_choice: useResponsesApi
          ? { type: "function", name: options.toolName }
          : { type: "function", function: { name: options.toolName } },
        ...(omitTemperature ? {} : { temperature: 0.2 }),
        ...(useResponsesApi
          ? { max_output_tokens: req.maxOutputTokens }
          : {
              max_completion_tokens: req.maxOutputTokens,
              stream_options: { include_usage: true },
            }),
        // Mirror the runTurn path so structured planner submissions also
        // honour the user-selected reasoning effort.
        ...buildReasoningOptions(
          req.thinkingLevel,
          useResponsesApi ? "responses" : "chat-completions",
        ),
      };

      const events = this.streamChatCompletions(
        wireMessages,
        requestOptions,
        req.abortSignal,
      );
      const turn = await this.decodeStream(events, req.abortSignal);
      return this.extractStructuredPayload<T>(turn, options.toolName);
    } catch (error) {
      if (req.abortSignal.aborted) {
        throw error;
      }
      throw this.mapProviderError(error);
    }
  }

  // ============ Stream decoding ============

  private decodeStream(
    events: AsyncIterableIterator<NormalizedStreamChunk>,
    signal: AbortSignal,
  ): Promise<LLMTurnResult> {
    return decodeChatCompletionStream(events, signal, {
      logPrefix: this.logPrefix,
      // Preserve the pre-PR-9a id shape (`azure_tool_call_<ts>_<idx>`,
      // `azure_function_call_<ts>`) for any downstream dedup / logging.
      synthesizeMissingToolCallId: (idx) =>
        `azure_tool_call_${Date.now()}_${idx}`,
      synthesizeLegacyFunctionCallId: () => `azure_function_call_${Date.now()}`,
      onChunk: (event, chunkIndex) => {
        if (chunkIndex <= 5 && isDevBuild()) {
          console.log(
            `${this.logPrefix} Chunk ${chunkIndex}:`,
            JSON.stringify(event, null, 2).slice(0, 500),
          );
        }
      },
    });
  }

  // ============ HTTP / streaming ============

  private async *streamChatCompletions(
    messages: unknown[],
    options: Record<string, unknown>,
    abortSignal: AbortSignal,
  ): AsyncIterableIterator<NormalizedStreamChunk> {
    const { useEntraId, azureClientId, apiKey, deploymentName, apiMode } =
      this.config;
    const useResponsesApi = apiMode === "responses";
    const url = useResponsesApi
      ? `${this.normalizedEndpoint}/openai/responses?api-version=2025-04-01-preview`
      : `${this.normalizedEndpoint}/openai/deployments/${deploymentName}/chat/completions?api-version=2024-08-01-preview`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (useEntraId) {
      if (!azureClientId?.trim()) {
        throw createAgentError(
          "PROVIDER_REQUEST_INVALID",
          "Azure Entra Client ID is required when useEntraId is enabled",
        );
      }
      const redirectUri =
        typeof window !== "undefined"
          ? `${window.location.origin}/taskpane.html`
          : undefined;
      const credential = new InteractiveBrowserCredential({
        tenantId: "common",
        clientId: azureClientId,
        redirectUri,
      });
      const response = await credential.getToken(
        "https://cognitiveservices.azure.com/.default",
      );
      const token = response.token;
      captureEntraIdentityFromAccessToken(token);
      headers.Authorization = `Bearer ${token}`;
    } else if (apiKey) {
      headers["api-key"] = apiKey;
    } else {
      throw createAgentError(
        "PROVIDER_REQUEST_INVALID",
        "Either apiKey or useEntraId must be provided",
      );
    }

    const currentOptions: Record<string, unknown> = { ...(options ?? {}) };
    const workflowManager = this.config.workflowManager;
    const maxAttempts = this.config.maxRetries ?? 5;
    const requestTimeoutMs = AIRGAP_CONFIG.timeouts.requestTimeoutMs;
    const streamIdleTimeoutMs = AIRGAP_CONFIG.timeouts.streamIdleTimeoutMs;
    const meaningfulStreamTimeoutMs =
      AIRGAP_CONFIG.timeouts.meaningfulStreamTimeoutMs;

    let lastError: Error | undefined;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      let sawMeaningfulResponsesEvent = false;
      let keepaliveCount = 0;
      const streamStartTime = Date.now();

      const updateResponsesStreamHealth = (parsed: unknown): void => {
        if (!useResponsesApi) return;
        const event = parsed as Record<string, unknown>;
        const eventType =
          typeof event.type === "string" ? event.type : undefined;
        if (!eventType) return;
        if (eventType === "keepalive") {
          keepaliveCount += 1;
          const elapsedMs = Date.now() - streamStartTime;
          if (
            !sawMeaningfulResponsesEvent &&
            keepaliveCount >= 10 &&
            elapsedMs >= 30000
          ) {
            throw createAgentError(
              "PROVIDER_TRANSPORT_ERROR",
              "Azure Responses stream timed out with keepalive-only events and no model output. Please retry or switch Azure API mode.",
            );
          }
          return;
        }
        if (
          eventType === "response.created" ||
          eventType === "response.in_progress"
        ) {
          return;
        }
        sawMeaningfulResponsesEvent = true;
      };

      const requestOptionsForApi = { ...currentOptions };
      if (
        useResponsesApi &&
        Object.prototype.hasOwnProperty.call(
          requestOptionsForApi,
          "max_completion_tokens",
        ) &&
        !Object.prototype.hasOwnProperty.call(
          requestOptionsForApi,
          "max_output_tokens",
        )
      ) {
        requestOptionsForApi.max_output_tokens =
          requestOptionsForApi.max_completion_tokens;
        requestOptionsForApi.max_completion_tokens = undefined;
      }

      const body = useResponsesApi
        ? JSON.stringify({
            model: deploymentName,
            input: messages,
            stream: true,
            ...requestOptionsForApi,
          })
        : JSON.stringify({
            messages,
            stream: true,
            ...requestOptionsForApi,
          });

      if (attempt === 0) {
        const rateLimitResult =
          await workflowManager.acquireRateLimitToken(30000);
        if (!rateLimitResult.allowed) {
          throw createAgentError(
            "PROVIDER_RATE_LIMITED",
            `Rate limit exceeded. Retry after ${rateLimitResult.retryAfterMs}ms`,
          );
        }
      }

      if (attempt > 0) {
        const baseDelay = Math.min(5000 * 2 ** (attempt - 1), 60000);
        const jitter = baseDelay * 0.2 * (Math.random() * 2 - 1);
        const delay = Math.max(1000, Math.floor(baseDelay + jitter));
        console.log(
          `${this.logPrefix} Rate limited, retrying in ${delay}ms (attempt ${attempt + 1}/${maxAttempts})...`,
        );
        await new Promise((resolve) => setTimeout(resolve, delay));
      }

      const response = await this.fetchWithTimeout(
        url,
        { method: "POST", headers, body },
        abortSignal,
        requestTimeoutMs,
      );

      if (response.status === 400) {
        const errorText = await response.text();
        workflowManager.reportRecoverableHttpError(400);

        if (attempt < maxAttempts - 1) {
          const fallback = applyAzure400Fallback(currentOptions, errorText);
          for (const adjustment of fallback.adjustments) {
            console.warn(
              `${this.logPrefix} Retrying with fallback adjustment: ${adjustment}`,
            );
          }
          if (fallback.adjusted) {
            lastError = createAgentError("PROVIDER_REQUEST_INVALID", errorText);
            continue;
          }
        }

        console.error(`${this.logPrefix} 400 Bad Request details:`, errorText);
        // One-shot diagnostic dump of the outgoing request so the trigger
        // (system prompt vs. planner injection vs. user turn vs. tool result
        // vs. tool descriptions) can be isolated. Especially useful for
        // Azure Prompt Shield / content_filter rejections where the body
        // gives the category but not the offending content.
        this.logRequest400Diagnostic(body, errorText, useResponsesApi, url);
        console.error(
          `${this.logPrefix} 400 hint: verify deployment model supports tools and that request history has no orphan tool messages.`,
        );
        throw createAgentError(
          "PROVIDER_REQUEST_INVALID",
          `Azure OpenAI API error (400): ${errorText}`,
        );
      }

      if (response.status === 429) {
        const retryAfter = response.headers.get("retry-after");
        const retryAfterMs = retryAfter
          ? Number.parseInt(retryAfter, 10) * 1000
          : undefined;
        workflowManager.reportRecoverableHttpError(429, retryAfterMs);

        if (retryAfter) {
          console.log(
            `${this.logPrefix} Server requested Retry-After: ${retryAfter}s`,
          );
          await new Promise((resolve) =>
            setTimeout(resolve, Number.parseInt(retryAfter, 10) * 1000),
          );
          continue;
        }
        lastError = createAgentError(
          "PROVIDER_RATE_LIMITED",
          await response.text(),
        );
        continue;
      }

      if (
        response.status >= 500 &&
        response.status < 600 &&
        attempt < maxAttempts - 1
      ) {
        console.warn(
          `${this.logPrefix} Server error ${response.status}, will retry...`,
        );
        lastError = createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Server error: ${response.status}`,
        );
        continue;
      }

      if (response.status === 408 || response.status === 524) {
        console.warn(`${this.logPrefix} Request timeout, will retry...`);
        lastError = createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Timeout: ${response.status}`,
        );
        continue;
      }

      if (!response.ok) {
        const errorText = await response.text();
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Azure OpenAI API error (${response.status}): ${errorText}`,
        );
      }

      if (!response.body) {
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          "No response body from Azure OpenAI API",
        );
      }

      workflowManager.reportSuccess();

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      let lastMeaningfulDeltaAt = Date.now();
      let streamCancelReason: unknown;

      const throwIfStreamAborted = () => {
        if (!abortSignal.aborted) return;
        throw (
          abortSignal.reason ??
          new DOMException("Azure OpenAI stream aborted", "AbortError")
        );
      };

      const assertMeaningfulDeltaFresh = () => {
        if (useResponsesApi) return;

        const idleMs = Date.now() - lastMeaningfulDeltaAt;
        if (idleMs < meaningfulStreamTimeoutMs) return;

        const timeoutReason = new DOMException(
          `Azure OpenAI stream produced no model output for ${Math.round(idleMs / 1000)}s`,
          "TimeoutError",
        );
        streamCancelReason = timeoutReason;
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Azure OpenAI stream produced no model output for ${Math.round(meaningfulStreamTimeoutMs / 1000)}s while receiving non-content events. Please retry or switch Azure API mode.`,
          { cause: timeoutReason },
        );
      };

      try {
        while (true) {
          throwIfStreamAborted();
          const { done, value } = await readStreamChunkWithTimeout(reader, {
            signal: abortSignal,
            idleTimeoutMs: streamIdleTimeoutMs,
            providerName: "Azure OpenAI",
          });
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split("\n");
          buffer = lines.pop() ?? "";

          for (const line of lines) {
            const trimmed = line.trim();
            if (!trimmed || !trimmed.startsWith("data: ")) continue;
            const data = trimmed.slice(6);
            if (data === "[DONE]") return;

            let parsed: unknown;
            try {
              parsed = JSON.parse(data);
            } catch (error) {
              if (error instanceof SyntaxError) {
                assertMeaningfulDeltaFresh();
                continue;
              }
              throw error;
            }

            updateResponsesStreamHealth(parsed);
            const normalized = this.normalizeStreamChunk(parsed);
            if (normalized) {
              if (hasMeaningfulChatCompletionDelta(normalized)) {
                lastMeaningfulDeltaAt = Date.now();
              }
              assertMeaningfulDeltaFresh();
              yield normalized;
            } else {
              assertMeaningfulDeltaFresh();
            }
          }

          assertMeaningfulDeltaFresh();
        }

        if (buffer.trim()) {
          const trimmed = buffer.trim();
          if (trimmed.startsWith("data: ")) {
            const data = trimmed.slice(6);
            if (data && data !== "[DONE]") {
              let parsed: unknown;
              try {
                parsed = JSON.parse(data);
              } catch (error) {
                if (error instanceof SyntaxError) {
                  assertMeaningfulDeltaFresh();
                  return;
                }
                throw error;
              }

              updateResponsesStreamHealth(parsed);
              const normalized = this.normalizeStreamChunk(parsed);
              if (normalized) {
                if (hasMeaningfulChatCompletionDelta(normalized)) {
                  lastMeaningfulDeltaAt = Date.now();
                }
                assertMeaningfulDeltaFresh();
                yield normalized;
              } else {
                assertMeaningfulDeltaFresh();
              }
            }
          }
        }
      } catch (error) {
        void reader.cancel(streamCancelReason ?? error).catch(() => undefined);
        throw error;
      } finally {
        reader.releaseLock();
      }

      return;
    }

    throw (
      lastError ??
      createAgentError(
        "PROVIDER_TRANSPORT_ERROR",
        "Max retries exceeded for Azure OpenAI API",
      )
    );
  }

  /**
   * Dump a one-shot, copy-pasteable summary of the outgoing request after a
   * 400 response so the trigger can be isolated by role/length/snippet
   * without spelunking through the network panel. Especially useful for
   * Azure Prompt Shield (`code: "content_filter"`) rejections, where the
   * error body identifies the category (`jailbreak`, `indirect_attack`,
   * `hate`, etc.) but not the offending message.
   *
   * Logs:
   *   - Detected content_filter category flags from the error body.
   *   - Per-message {role, content length, optional first-200-char snippet,
   *     tool-call names, tool_call_id} table — works for both chat-
   *     completions (`messages: [...]`) and Responses (`input: [...]`)
   *     wire formats.
   *   - List of tool names + total counts so an oversized tool schema or a
   *     suspicious tool description (e.g. `bash`/`eval_officejs`) is
   *     immediately visible.
   *   - The full parsed body as a console object so it can be right-click
   *     copied and replayed against a different deployment with `curl` or
   *     a fresh fetch.
   */
  private logRequest400Diagnostic(
    body: string,
    errorText: string,
    useResponsesApi: boolean,
    url: string,
  ): void {
    let parsedBody: Record<string, unknown> | null = null;
    try {
      parsedBody = JSON.parse(body) as Record<string, unknown>;
    } catch {
      console.error(
        `${this.logPrefix} 400 diagnostic: outgoing request body was not valid JSON; skipping dump.`,
      );
      return;
    }

    const isContentFilter =
      errorText.includes('"code":"content_filter"') ||
      errorText.includes('"code": "content_filter"');

    const flaggedCategories: string[] = [];
    if (isContentFilter) {
      try {
        const parsedError = JSON.parse(errorText) as {
          error?: {
            innererror?: {
              content_filter_result?: Record<
                string,
                { filtered?: boolean; detected?: boolean }
              >;
            };
          };
        };
        const result = parsedError?.error?.innererror?.content_filter_result;
        if (result) {
          for (const [category, info] of Object.entries(result)) {
            if (info?.filtered || info?.detected) {
              flaggedCategories.push(category);
            }
          }
        }
      } catch {
        // ignore — fall back to raw body
      }
    }

    const items: unknown[] = useResponsesApi
      ? Array.isArray((parsedBody as { input?: unknown[] }).input)
        ? ((parsedBody as { input: unknown[] }).input ?? [])
        : []
      : Array.isArray((parsedBody as { messages?: unknown[] }).messages)
        ? ((parsedBody as { messages: unknown[] }).messages ?? [])
        : [];

    const messageSummary = items.map((raw, idx) => {
      const m = (raw ?? {}) as Record<string, unknown>;
      const role =
        (m.role as string | undefined) ??
        (m.type as string | undefined) ??
        "unknown";

      // Extract text content + length across the various shapes:
      //   - chat-completions: content is string OR array of {type, text}
      //   - Responses input message: content is array of {type:"input_text"|"output_text", text}
      //   - Responses function_call: arguments string
      //   - Responses function_call_output: output string
      let textBuf = "";
      const content = m.content;
      if (typeof content === "string") {
        textBuf = content;
      } else if (Array.isArray(content)) {
        for (const part of content) {
          const p = (part ?? {}) as Record<string, unknown>;
          if (typeof p.text === "string") textBuf += p.text;
        }
      } else if (typeof m.output === "string") {
        textBuf = m.output; // function_call_output (Responses)
      } else if (typeof m.arguments === "string") {
        textBuf = m.arguments; // function_call (Responses)
      }

      // tool_call names from chat-completions assistant messages
      const toolCalls = Array.isArray(m.tool_calls)
        ? (m.tool_calls as Array<Record<string, unknown>>)
        : [];
      const toolCallNames = toolCalls
        .map((tc) => {
          const fn = tc.function as { name?: string } | undefined;
          return fn?.name;
        })
        .filter((n): n is string => Boolean(n));

      // For Responses function_call items, the name is on the item itself
      const responsesFnName =
        m.type === "function_call" && typeof m.name === "string"
          ? (m.name as string)
          : undefined;

      const callId =
        (m.tool_call_id as string | undefined) ??
        (m.call_id as string | undefined);

      const snippet = textBuf.slice(0, 200).replace(/\s+/g, " ").trim();

      return {
        i: idx,
        role,
        contentLen: textBuf.length,
        toolCallNames:
          toolCallNames.length > 0
            ? toolCallNames.join(",")
            : (responsesFnName ?? ""),
        callId: callId ?? "",
        snippet,
      };
    });

    // Tool schema names — Azure chat-completions: tools[].function.name;
    // Responses: tools[].name (top-level).
    const toolsRaw = Array.isArray((parsedBody as { tools?: unknown[] }).tools)
      ? ((parsedBody as { tools: unknown[] }).tools ?? [])
      : [];
    const toolNames = toolsRaw
      .map((t) => {
        const tt = (t ?? {}) as Record<string, unknown>;
        if (useResponsesApi) {
          return typeof tt.name === "string" ? (tt.name as string) : undefined;
        }
        const fn = tt.function as { name?: string } | undefined;
        return fn?.name;
      })
      .filter((n): n is string => Boolean(n));

    const header = `${this.logPrefix} 400 request diagnostic — ${
      isContentFilter ? "CONTENT FILTER (Prompt Shield)" : "other"
    }`;

    // Use console.group when available so the dump is collapsible in
    // browser DevTools; gracefully degrade to plain console.error.
    const useGroup =
      typeof console.group === "function" &&
      typeof console.groupEnd === "function";
    if (useGroup) console.group(header);
    else console.error(header);

    console.error("URL:", url);
    console.error(
      "API mode:",
      useResponsesApi ? "responses" : "chat-completions",
    );
    if (isContentFilter) {
      console.error(
        flaggedCategories.length > 0
          ? `Prompt Shield flagged: ${flaggedCategories.join(", ")}`
          : "Prompt Shield rejected the request (no specific category flagged in body).",
      );
    }
    console.error(
      `Outgoing items: ${messageSummary.length} | Tool schemas: ${toolNames.length}`,
    );
    if (typeof console.table === "function") {
      console.table(messageSummary);
    } else {
      console.error("Items:", messageSummary);
    }
    console.error("Tool names:", toolNames);
    console.error(
      "Full outgoing body (right-click → Copy object to replay against another deployment):",
      parsedBody,
    );
    if (useGroup) console.groupEnd();
  }

  private async fetchWithTimeout(
    url: string,
    init: RequestInit,
    signal: AbortSignal,
    requestTimeoutMs: number,
  ): Promise<Response> {
    const timeoutController = new AbortController();
    // Track whether the timeout (vs. the outer signal) was the source of the
    // abort so the caller can surface a clear "timed out" message instead of
    // the platform-default `DOMException: signal is aborted without reason`.
    let timedOut = false;

    const onAbort = () => {
      // Forward the outer signal's reason (if any) so user-initiated aborts
      // carry meaningful diagnostic info downstream.
      timeoutController.abort(signal.reason);
    };

    if (signal.aborted) {
      timeoutController.abort(signal.reason);
    } else {
      signal.addEventListener("abort", onAbort, { once: true });
    }

    const timeoutId = setTimeout(() => {
      timedOut = true;
      timeoutController.abort(
        new DOMException(
          `Azure OpenAI request exceeded ${requestTimeoutMs}ms timeout`,
          "TimeoutError",
        ),
      );
    }, requestTimeoutMs);

    try {
      return await fetch(url, { ...init, signal: timeoutController.signal });
    } catch (error) {
      if (timedOut) {
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Azure OpenAI request timed out after ${Math.round(requestTimeoutMs / 1000)}s. The API did not respond in time.`,
        );
      }
      throw error;
    } finally {
      clearTimeout(timeoutId);
      signal.removeEventListener("abort", onAbort);
    }
  }

  private normalizeStreamChunk(chunk: unknown): NormalizedStreamChunk | null {
    if (this.config.apiMode !== "responses") {
      return chunk as NormalizedStreamChunk;
    }

    const event = chunk as Record<string, unknown>;
    const eventType = typeof event.type === "string" ? event.type : undefined;

    const eventError = event.error as Record<string, unknown> | undefined;
    if (eventError) {
      const message =
        (typeof eventError.message === "string" && eventError.message) ||
        "Unknown Azure Responses stream error";
      throw createAgentError(
        "PROVIDER_TRANSPORT_ERROR",
        `Azure Responses stream error: ${message}`,
      );
    }

    if (!eventType) return null;

    if (eventType === "response.output_text.delta") {
      const delta = typeof event.delta === "string" ? event.delta : "";
      if (!delta) return null;
      return { choices: [{ delta: { content: delta } }] };
    }

    if (eventType.includes("reasoning") && typeof event.delta === "string") {
      return { choices: [{ delta: { reasoning_content: event.delta } }] };
    }

    if (eventType === "response.output_item.added") {
      const item = event.item as Record<string, unknown> | undefined;
      if (item?.type !== "function_call") return null;
      return {
        choices: [
          {
            delta: {
              tool_calls: [
                {
                  index:
                    typeof event.output_index === "number"
                      ? event.output_index
                      : 0,
                  id:
                    (typeof item.call_id === "string" && item.call_id) ||
                    (typeof item.id === "string" ? item.id : undefined),
                  function: {
                    name: typeof item.name === "string" ? item.name : undefined,
                  },
                },
              ],
            },
          },
        ],
      };
    }

    if (eventType === "response.function_call_arguments.delta") {
      const delta = typeof event.delta === "string" ? event.delta : "";
      if (!delta) return null;
      return {
        choices: [
          {
            delta: {
              tool_calls: [
                {
                  index:
                    typeof event.output_index === "number"
                      ? event.output_index
                      : 0,
                  id:
                    typeof event.call_id === "string"
                      ? event.call_id
                      : undefined,
                  function: {
                    name:
                      typeof event.name === "string" ? event.name : undefined,
                    arguments: delta,
                  },
                },
              ],
            },
          },
        ],
      };
    }

    if (eventType === "response.output_text.done") {
      return null;
    }

    // `response.function_call_arguments.done` carries the FULL accumulated
    // arguments string as a convenience for clients that ignore the per-
    // chunk `.delta` events. We use the delta-accumulating path
    // (`upsertStreamedToolCall` appends every `function.arguments`), so
    // re-emitting the complete string here would double the args and
    // produce invalid JSON like `{...}{...}` (parse fails, args fall back
    // to `{}`, the model retries the same tool call → loop). Treat it as
    // a marker, mirroring how `response.output_text.done` is handled.
    if (eventType === "response.function_call_arguments.done") {
      return null;
    }

    if (
      eventType === "response.completed" ||
      eventType === "response.done" ||
      eventType === "response.failed"
    ) {
      const response = event.response as Record<string, unknown> | undefined;
      const responseError = response?.error as
        | Record<string, unknown>
        | undefined;
      if (eventType === "response.failed" || responseError) {
        const message =
          (typeof responseError?.message === "string" &&
            responseError.message) ||
          "Azure Responses request failed";
        throw createAgentError(
          "PROVIDER_TRANSPORT_ERROR",
          `Azure Responses request failed: ${message}`,
        );
      }
      const usage = response?.usage as Record<string, unknown> | undefined;
      const outputItems = Array.isArray(response?.output)
        ? (response?.output as Array<Record<string, unknown>>)
        : [];
      const hasFunctionCall = outputItems.some(
        (item) => item?.type === "function_call",
      );
      return {
        choices: [{ finish_reason: hasFunctionCall ? "tool_calls" : "stop" }],
        usage: {
          prompt_tokens:
            typeof usage?.input_tokens === "number" ? usage.input_tokens : 0,
          completion_tokens:
            typeof usage?.output_tokens === "number" ? usage.output_tokens : 0,
          total_tokens:
            typeof usage?.total_tokens === "number"
              ? usage.total_tokens
              : undefined,
        },
      };
    }

    return null;
  }

  // ============ Wire format conversion ============

  private convertMessagesToAzureFormat(
    messages: AgentMessage[],
    systemPrompt: string,
  ): unknown[] {
    const result = convertMessagesToChatCompletions(messages, systemPrompt, {
      logPrefix: this.logPrefix,
    });

    if (isDevBuild()) {
      console.log(
        `${this.logPrefix} Converted messages for Azure:`,
        JSON.stringify(result.messages, null, 2),
      );
    }

    return result.messages;
  }

  private convertMessagesToResponsesFormat(
    messages: AgentMessage[],
    systemPrompt: string,
  ): unknown[] {
    const responseInput: unknown[] = [];
    const announcedToolCalls = new Set<string>();

    const sys = typeof systemPrompt === "string" ? systemPrompt.trim() : "";
    if (sys) {
      responseInput.push({
        role: "system",
        content: [{ type: "input_text", text: sys }],
      });
    }

    for (const msg of messages) {
      if (msg.role === "user") {
        const content =
          typeof (msg as UserMessage).content === "string"
            ? (msg as UserMessage).content.trim()
            : "";
        if (!content) continue;
        responseInput.push({
          role: "user",
          content: [{ type: "input_text", text: content }],
        });
        continue;
      }

      if (msg.role === "assistant") {
        const assistantMsg = msg as AssistantMessage;
        const textParts: string[] = [];

        for (const block of assistantMsg.content) {
          if (block.type === "text") {
            const normalized = (block.text ?? "").trim();
            if (normalized) textParts.push(normalized);
          }
          if (block.type === "thinking") {
            const normalized = (block.thinking ?? "").trim();
            if (normalized) textParts.push(`[Thinking: ${normalized}]`);
          }
          if (block.type === "tool_call") {
            const id = (block.id ?? "").trim();
            const name = (block.name ?? "").trim();
            if (!id || !name) continue;
            announcedToolCalls.add(id);
            responseInput.push({
              type: "function_call",
              call_id: id,
              name,
              arguments: this.stringifyToolArguments(name, block.arguments),
            });
          }
        }

        const assistantText = textParts.join("\n");
        if (assistantText) {
          responseInput.push({
            role: "assistant",
            content: [{ type: "output_text", text: assistantText }],
          });
        }
        continue;
      }

      if (msg.role === "tool") {
        const toolMsg = msg as ToolResultMessage;
        const toolCallId = (toolMsg.toolCallId ?? "").trim();
        if (!toolCallId || !announcedToolCalls.has(toolCallId)) continue;

        const text = toolMsg.content
          .filter((c) => c.type === "text")
          .map((c) => (c as { type: "text"; text: string }).text)
          .map((t) => (typeof t === "string" ? t.trim() : ""))
          .filter(Boolean)
          .join("\n");

        responseInput.push({
          type: "function_call_output",
          call_id: toolCallId,
          output: text || "[Tool result with images]",
        });
      }
    }

    if (isDevBuild()) {
      console.log(
        `${this.logPrefix} Converted messages for Azure Responses:`,
        JSON.stringify(responseInput, null, 2),
      );
    }

    return responseInput;
  }

  private convertToolsToAzureFormat(tools: Tool[]): unknown[] {
    return tools.map((tool) => ({
      type: "function",
      function: {
        name: tool.name,
        description: tool.description,
        parameters: tool.parameters,
      },
    }));
  }

  private convertToolsToResponsesFormat(tools: Tool[]): unknown[] {
    return tools.map((tool) => ({
      type: "function",
      name: tool.name,
      description: tool.description,
      parameters: tool.parameters,
    }));
  }

  private createStructuredTool(
    toolName: string,
    schema: JSONSchema,
    responsesApi: boolean,
  ): unknown {
    if (responsesApi) {
      return {
        type: "function",
        name: toolName,
        description: `Submit structured planner payload for ${toolName}.`,
        parameters: schema,
      };
    }
    return {
      type: "function",
      function: {
        name: toolName,
        description: `Submit structured planner payload for ${toolName}.`,
        parameters: schema,
      },
    };
  }

  private extractStructuredPayload<T>(
    turn: LLMTurnResult,
    toolName: string,
  ): T {
    const call = turn.toolCalls.find((toolCall) => toolCall.name === toolName);
    if (!call) {
      throw createAgentError(
        "PROVIDER_STREAM_PARSE_ERROR",
        `Structured response did not include a ${toolName} tool call.`,
      );
    }
    return call.arguments as T;
  }

  private stringifyToolArguments(
    toolName: string,
    args: Record<string, unknown>,
  ): string {
    return stringifyToolArgumentsForHistory(toolName, args);
  }

  private normalizeEndpoint(endpoint: string): string {
    let normalized = endpoint.trim();
    const openaiPathIndex = normalized.indexOf("/openai/");
    if (openaiPathIndex !== -1) {
      normalized = normalized.substring(0, openaiPathIndex);
    }
    return normalized.replace(/\/+$/, "");
  }

  private mapProviderError(error: unknown): AgentError {
    const typed = asAgentError(
      error,
      "PROVIDER_TRANSPORT_ERROR",
      "Azure provider request failed",
    );
    if (typed.code.startsWith("PROVIDER_")) {
      return typed;
    }

    const loweredMessage = typed.message.toLowerCase();
    if (
      loweredMessage.includes("rate limit") ||
      loweredMessage.includes("retry-after")
    ) {
      return createAgentError("PROVIDER_RATE_LIMITED", typed.message, {
        cause: error,
      });
    }

    return createAgentError("PROVIDER_TRANSPORT_ERROR", typed.message, {
      cause: error,
    });
  }
}

export function createAzureProvider(
  config: AzureProviderConfig,
): AzureProvider {
  return new AzureProvider(config);
}

