/**
 * MCP registry (PR-3B.1 skeleton).
 *
 * Accepts a pre-discovered tool catalog (a map from connection id →
 * remote tool descriptors) plus the corresponding normalized
 * connection configs, adapts each descriptor through
 * {@link adaptMCPTool}, and detects collisions with already-registered
 * tools.
 *
 * Live discovery (`list tools` over SSE / streamable HTTP) lands in
 * PR-3B.2; this skeleton is the integration point.
 *
 * See docs/agent-refactor-blueprint.md §4.1, §4.2 and PR-3B.1 step
 * 2.5.3a in docs/agent-refactor-implementation-plan.md.
 */

import { createAgentError } from "../errors";
import type { Tool } from "../types";
import type { MCPInvocationClient } from "./client";
import { adaptMCPTool } from "./tool-adapter";
import type {
  MCPNormalizedConnection,
  MCPRemoteToolDescriptor,
} from "./types";

export interface MCPRegistryInputs {
  /** Validated, normalized connection configs keyed by connection id. */
  connections: ReadonlyMap<string, MCPNormalizedConnection>;
  /** Pre-discovered remote tool descriptors keyed by connection id. */
  catalog: ReadonlyMap<string, ReadonlyArray<MCPRemoteToolDescriptor>>;
  /** Existing tool names to check for collisions (local + already-loaded MCP). */
  existingToolNames: ReadonlySet<string>;
  /** Invocation client used by adapted tool execute closures. */
  client: MCPInvocationClient;
}

export interface MCPRegistryDiagnostic {
  connectionId: string;
  toolName?: string;
  message: string;
}

export interface MCPRegistryResult {
  /** Adapted Tool records ready for dispatcher consumption. */
  tools: Tool[];
  /** Per-connection diagnostics (e.g. dropped/collided/over-length tools). */
  diagnostics: MCPRegistryDiagnostic[];
}

/**
 * Build the adapted-tool list from a pre-discovered catalog.
 *
 * Behavior:
 * - Catalog entries require a normalized connection config; enabled/disabled
 *   state is owned by the lifecycle manager and its published catalog.
 * - Each remote tool is namespaced + adapted via {@link adaptMCPTool}.
 * - Names that collide with `existingToolNames` or with an earlier
 *   adapted tool in the same call are dropped with a diagnostic; the
 *   *first* registration wins (blueprint §4.2 fail-fast variant).
 * - Adapter failures (e.g. over-length names) are dropped with a
 *   diagnostic.
 */
export function buildMCPRegistry(
  inputs: MCPRegistryInputs,
): MCPRegistryResult {
  const tools: Tool[] = [];
  const diagnostics: MCPRegistryDiagnostic[] = [];
  const usedNames = new Set<string>(inputs.existingToolNames);

  for (const [connectionId, descriptors] of inputs.catalog) {
    const connection = inputs.connections.get(connectionId);
    if (!connection) {
      diagnostics.push({
        connectionId,
        message: "no normalized connection config; tools dropped",
      });
      continue;
    }

    for (const descriptor of descriptors) {
      const adapted = adaptMCPTool(descriptor, {
        connectionId: connection.id,
        serverLabel: connection.label,
        client: inputs.client,
      });
      if (!adapted) {
        diagnostics.push({
          connectionId,
          toolName: descriptor.name,
          message:
            "could not produce a namespaced tool name within the 64-char budget",
        });
        continue;
      }

      if (usedNames.has(adapted.tool.name)) {
        diagnostics.push({
          connectionId,
          toolName: descriptor.name,
          message: `namespaced tool name '${adapted.tool.name}' collides with an existing tool; first registration wins`,
        });
        continue;
      }

      usedNames.add(adapted.tool.name);
      tools.push(adapted.tool);
    }
  }

  return { tools, diagnostics };
}

/**
 * Throwing variant: builds the registry and throws an `MCP_CONFIG_INVALID`
 * AgentError if any diagnostics fired. Useful at startup-time loading
 * paths that prefer fail-fast behavior; callers that want soft loading
 * should use {@link buildMCPRegistry} directly.
 */
export function buildMCPRegistryStrict(inputs: MCPRegistryInputs): Tool[] {
  const result = buildMCPRegistry(inputs);
  if (result.diagnostics.length > 0) {
    throw createAgentError(
      "MCP_CONFIG_INVALID",
      `Failed to build MCP registry: ${result.diagnostics.length} diagnostic(s)`,
      { details: { diagnostics: result.diagnostics } },
    );
  }
  return result.tools;
}
