/**
 * write_progress — bookkeeping VFS write tool.
 *
 * PR-1c (blueprint §4 / plan step 0.3): split out of `write_file` so the
 * orchestrator can gate deliverables off `category === "deliverable"`
 * without path-based detection.
 *
 * Shares the same VFS write implementation as write_file; only the tool
 * name + metadata differ.
 */

import { Type } from "@sinclair/typebox";
import { writeFile } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

const writeProgressParameters = Type.Object({
  path: Type.String({
    description:
      "Path to the progress/log/status file in the virtual filesystem (e.g. 'progress.md' or '/home/user/uploads/wiki.md').",
  }),
  content: Type.String({
    description: "Text content to write to the file.",
  }),
  overwrite: Type.Optional(
    Type.Boolean({
      description:
        "If false, the tool errors if the file already exists. Defaults to true.",
      default: true,
    }),
  ),
});

async function executeWriteProgress(params: {
  path: string;
  content: string;
  overwrite?: boolean;
}) {
  try {
    await writeFile(params.path, params.content);
    return toolSuccess(`Wrote ${params.path}`);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown error writing file";
    return toolError(message);
  }
}

export { executeWriteProgress };

export const writeProgressTool = defineTool({
  name: "write_progress",
  category: "bookkeeping",
  parallelSafe: false,
  label: "Write Progress",
  description:
    "Write progress, log, status, plan, checklist, or wiki content to a file in the virtual filesystem. " +
    "Use this for run logs and bookkeeping that supports your reasoning but is NOT the user-visible deliverable. " +
    "For user-visible artifacts, use write_file instead.",
  parameters: writeProgressParameters,
  execute: async (_toolCallId, params) => executeWriteProgress(params),
});
