/**
 * Shared chat-completions message converter (Azure + OpenAI).
 *
 * PR-2: Extracts the previously duplicated `convertMessagesTo{Azure,OpenAI}Format`
 * methods from the old Azure/OpenAI agent implementations. Both providers' chat-completions
 * wire format is identical at this layer.
 *
 * The Azure responses-API converter (`convertMessagesToResponsesFormat`) is
 * NOT shared and stays in AzureProvider.
 *
 * See docs/agent-refactor-blueprint.md §3 and docs/agent-refactor-implementation-plan.md PR-2 step 1.2.
 */

import { stringifyToolArgumentsForHistory } from "../../tool-argument-history";
import type {
  AgentMessage,
  AssistantMessage,
  ToolResultMessage,
  UserMessage,
} from "../../types";

export interface ChatCompletionsConversionOptions {
  /** Optional log prefix for warnings (e.g. "[AzureAgent]" / "[OpenAIAgent]"). */
  logPrefix?: string;
}

export interface ChatCompletionsConversionResult {
  messages: unknown[];
  skippedOrphanToolMessages: number;
  skippedInvalidAssistantMessages: number;
}

function normalizeTextContent(value: unknown): string {
  if (typeof value !== "string") return "";
  return value.trim();
}

export function convertMessagesToChatCompletions(
  messages: AgentMessage[],
  systemPrompt: string,
  options: ChatCompletionsConversionOptions = {},
): ChatCompletionsConversionResult {
  const out: unknown[] = [];
  const announcedToolCalls = new Set<string>();
  let skippedOrphanToolMessages = 0;
  let skippedInvalidAssistantMessages = 0;

  const sys = normalizeTextContent(systemPrompt);
  if (sys) {
    out.push({ role: "system", content: sys });
  }

  for (const msg of messages) {
    if (msg.role === "user") {
      const content = normalizeTextContent((msg as UserMessage).content);
      if (!content) continue;
      out.push({ role: "user", content });
    } else if (msg.role === "assistant") {
      const assistantMsg = msg as AssistantMessage;
      const textParts: string[] = [];
      const toolCalls: Array<{
        id: string;
        type: string;
        function: { name: string; arguments: string };
      }> = [];

      for (const block of assistantMsg.content) {
        if (block.type === "text") {
          const normalized = normalizeTextContent(block.text);
          if (normalized) textParts.push(normalized);
        } else if (block.type === "thinking") {
          const normalized = normalizeTextContent(block.thinking);
          if (normalized) textParts.push(`[Thinking: ${normalized}]`);
        } else if (block.type === "tool_call") {
          const id = normalizeTextContent(block.id);
          const name = normalizeTextContent(block.name);
          if (!id || !name) continue;
          announcedToolCalls.add(id);
          toolCalls.push({
            id,
            type: "function",
            function: {
              name,
              arguments: stringifyToolArgumentsForHistory(
                name,
                block.arguments,
              ),
            },
          });
        }
      }

      const wireMsg: Record<string, unknown> = { role: "assistant" };
      const contentText = textParts.join("\n");
      if (contentText) wireMsg.content = contentText;
      if (toolCalls.length > 0) wireMsg.tool_calls = toolCalls;

      if (!("content" in wireMsg) && !("tool_calls" in wireMsg)) {
        skippedInvalidAssistantMessages++;
        continue;
      }

      out.push(wireMsg);
    } else if (msg.role === "tool") {
      const toolMsg = msg as ToolResultMessage;
      const toolCallId = normalizeTextContent(toolMsg.toolCallId);
      if (!toolCallId || !announcedToolCalls.has(toolCallId)) {
        skippedOrphanToolMessages++;
        continue;
      }

      const text = toolMsg.content
        .filter((c) => c.type === "text")
        .map((c) => (c as { type: "text"; text: string }).text)
        .map((t) => normalizeTextContent(t))
        .filter(Boolean)
        .join("\n");

      out.push({
        role: "tool",
        tool_call_id: toolCallId,
        content: text || "[Tool result with images]",
      });
    }
  }

  if (options.logPrefix) {
    if (skippedOrphanToolMessages > 0) {
      console.warn(
        `${options.logPrefix} Skipped ${skippedOrphanToolMessages} orphan tool message(s) to avoid API errors`,
      );
    }
    if (skippedInvalidAssistantMessages > 0) {
      console.warn(
        `${options.logPrefix} Skipped ${skippedInvalidAssistantMessages} invalid assistant message(s) with no content/tool_calls`,
      );
    }
  }

  return {
    messages: out,
    skippedOrphanToolMessages,
    skippedInvalidAssistantMessages,
  };
}
