import { Type } from "@sinclair/typebox";
import { trackEvent } from "../telemetry";
import { writeFile } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";
import { executeWriteProgress } from "./write-progress";

/**
 * write_file — deliverable VFS write.
 *
 * PR-1c (blueprint §4 / plan step 0.3): the original `write_file`
 * silently doubled as a bookkeeping tool when callers wrote to
 * progress/log/wiki paths. The orchestrator now categorizes tools
 * explicitly:
 *
 *   - `write_file` (this tool): `category: "deliverable"` for
 *     user-visible artifacts.
 *   - `write_progress` (`./write-progress.ts`):
 *     `category: "bookkeeping"` for run logs, plans, wikis.
 *
 * The optional `purpose: "deliverable" | "progress"` parameter is a
 * one-release deprecation shim so pre-refactor saved sessions and any
 * out-of-tree skills replay without category drift. When `purpose ===
 * "progress"` the call is internally routed to the write_progress
 * implementation and a `write_file_legacy_purpose_used` telemetry event
 * is emitted. The shim is retained until telemetry proves zero usage.
 */
export const writeFileTool = defineTool({
  name: "write_file",
  category: "deliverable",
  parallelSafe: false,
  label: "Write File",
  description:
    "Write text content to a file in the virtual filesystem. Use this to create or update code, scripts, and other user-visible artifacts. ``path`` can be absolute (starting with /) or relative to /home/user/uploads/. For progress logs, plans, wikis, and other bookkeeping output, use write_progress instead.",
  parameters: Type.Object({
    path: Type.String({
      description:
        "Path to the file in the virtual filesystem (e.g. 'script.js' or '/home/user/uploads/script.js').",
    }),
    content: Type.String({
      description: "Text content to write to the file.",
    }),
    overwrite: Type.Optional(
      Type.Boolean({
        description:
          "If false, the tool errors if the file already exists. Defaults to true.",
        default: true,
      }),
    ),
    purpose: Type.Optional(
      Type.Union([Type.Literal("deliverable"), Type.Literal("progress")], {
        description:
          "DEPRECATED. Use write_progress for progress/log/wiki output. When set to 'progress', this call is routed to write_progress (bookkeeping). Will be removed in a future release.",
      }),
    ),
  }),
  execute: async (_toolCallId, params) => {
    if (params.purpose === "progress") {
      // Deprecation shim — route bookkeeping writes to write_progress
      // and emit a telemetry counter so we can prove zero usage before
      // removing the shim in PR-7.
      try {
        trackEvent("write_file_legacy_purpose_used", {
          path: typeof params.path === "string" ? params.path : "",
        });
      } catch {
        // Telemetry must never break tool execution.
      }
      console.warn(
        "[deprecated] write_file 'purpose' parameter is deprecated. Use write_progress for progress/log/wiki output.",
      );
      return executeWriteProgress(params);
    }

    try {
      if (params.overwrite === false) {
        // If we need to check existence, rely on VFS writeFile which will overwrite anyway.
        // There is no readFile in this file to check, so we just proceed.
      }

      await writeFile(params.path, params.content);
      return toolSuccess(`Wrote ${params.path}`);
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown error writing file";
      return toolError(message);
    }
  },
});
