export type AgentErrorCode =
  | "RUN_ALREADY_IN_PROGRESS"
  | "RUN_ABORTED"
  | "RUN_TIMEOUT"
  | "RUN_MAX_TURNS"
  | "RUN_PROVIDER_ERROR"
  | "TOOL_NOT_FOUND"
  | "TOOL_TIMEOUT"
  | "TOOL_EXCEPTION"
  | "TOOL_ABORTED"
  | "TOOL_DEDUP_SUPPRESSED"
  | "TOOL_PARALLEL_GUARD_VIOLATION"
  | "BUDGET_INFEASIBLE_DEGRADED"
  | "BUDGET_EPHEMERAL_DROPPED"
  | "PLAN_SCHEMA_INVALID"
  | "PLAN_FALLBACK_TO_STANDARD"
  | "PROVIDER_RATE_LIMITED"
  | "PROVIDER_REQUEST_INVALID"
  | "PROVIDER_TRANSPORT_ERROR"
  | "PROVIDER_STREAM_PARSE_ERROR"
  | "PROVIDER_CONTENT_FILTER"
  | "MCP_CONFIG_INVALID"
  | "MCP_CONNECTION_UNAVAILABLE"
  | "MCP_CONNECTION_UNAUTHORIZED"
  | "MCP_DISCOVERY_FAILED"
  | "MCP_TOOL_NOT_FOUND"
  | "MCP_TOOL_TIMEOUT"
  | "MCP_TOOL_ABORTED"
  | "MCP_TOOL_INVOCATION_FAILED"
  | "MCP_RESPONSE_INVALID";

export interface AgentErrorOptions {
  cause?: unknown;
  details?: Record<string, unknown>;
}

export class AgentError extends Error {
  readonly code: AgentErrorCode;
  readonly details?: Record<string, unknown>;

  constructor(
    code: AgentErrorCode,
    message: string,
    options: AgentErrorOptions = {},
  ) {
    super(message);
    this.name = "AgentError";
    this.code = code;
    this.details = options.details;

    if (options.cause !== undefined) {
      (this as Error & { cause?: unknown }).cause = options.cause;
    }
  }
}

export function createAgentError(
  code: AgentErrorCode,
  message: string,
  options: AgentErrorOptions = {},
): AgentError {
  return new AgentError(code, message, options);
}

export function isAgentError(value: unknown): value is AgentError {
  return (
    value instanceof Error &&
    typeof (value as Partial<AgentError>).code === "string"
  );
}

export function asAgentError(
  value: unknown,
  fallbackCode: AgentErrorCode,
  fallbackMessage: string,
): AgentError {
  if (isAgentError(value)) {
    return value;
  }

  if (value instanceof Error) {
    return createAgentError(fallbackCode, value.message || fallbackMessage, {
      cause: value,
    });
  }

  if (typeof value === "string" && value.trim()) {
    return createAgentError(fallbackCode, value.trim());
  }

  return createAgentError(fallbackCode, fallbackMessage, { cause: value });
}

export function formatCodeAndMessage(code: AgentErrorCode, message: string): string {
  return `[${code}] ${message}`;
}

export function encodeToolErrorPayload(
  code: AgentErrorCode,
  message: string,
  extra?: Record<string, unknown>,
): string {
  return JSON.stringify({
    code,
    error: message,
    ...extra,
  });
}
