import { Type } from "@sinclair/typebox";
import { defineTool, toolError, toolSuccess } from "./types";
import { withTemporaryChangeTracking } from "./word-change-tracking";
import {
  anchorMatchesParagraphText,
  getAnchorDocumentParagraphIndex,
  getAnchorScopeParagraphIndex,
  type WordAnchor,
  wordAnchorSchema,
} from "./word-anchor-utils";
import { syncWordContext, throwIfToolAborted } from "./word-tool-utils";

/* global Word */

type InsertContentParams = {
  content: string;
  type?: "text" | "paragraph" | "html";
  location?:
    | "end"
    | "start"
    | "selection"
    | "after"
    | "before"
    | "afterParagraph"
    | "beforeParagraph";
  paragraphIndex?: number;
  anchor?: WordAnchor;
  formatting?: {
    bold?: boolean;
    italic?: boolean;
    underline?: boolean;
    fontSize?: number;
    fontColor?: string;
    fontName?: string;
  };
};

type ParagraphTarget = {
  paragraph: Word.Paragraph | null;
  paragraphIndex: number | null;
  scopeParagraphIndex: number | null;
  anchorUsed: boolean;
  fallbackBodyLocation: "start" | "end" | null;
};

type CanonicalInsertLocation =
  | "end"
  | "start"
  | "selection"
  | "after"
  | "before";

export const insertContentTool = defineTool({
  name: "insert_content",
  category: "deliverable",
  parallelSafe: false,
  label: "Insert Content",
  description:
    "Insert text, paragraphs, or HTML content into the Word document. " +
    "Can insert at the end of document, at current selection, or at a specific paragraph. " +
    "Use this to add content to the document. " +
    "Can also target paragraph anchors from get_document_content or search_document. " +
    "IMPORTANT: For tables, use the insert_table tool instead - HTML tables will show as raw tags.",
  parameters: Type.Object({
    content: Type.String({ description: "The text or HTML content to insert" }),
    type: Type.Union(
      [
        Type.Literal("text", { description: "Plain text" }),
        Type.Literal("paragraph", { description: "Text as new paragraph" }),
        Type.Literal("html", { description: "HTML formatted content" }),
      ],
      { description: "Type of content to insert", default: "text" },
    ),
    location: Type.Union(
      [
        Type.Literal("end", { description: "Insert at end of document" }),
        Type.Literal("start", { description: "Insert at start of document" }),
        Type.Literal("selection", { description: "Replace current selection" }),
        Type.Literal("after", {
          description: "Insert after specified paragraph index",
        }),
        Type.Literal("before", {
          description: "Insert before specified paragraph index",
        }),
        Type.Literal("afterParagraph", {
          description: "Alias for inserting after a specified paragraph index",
        }),
        Type.Literal("beforeParagraph", {
          description: "Alias for inserting before a specified paragraph index",
        }),
      ],
      { description: "Where to insert the content", default: "end" },
    ),
    paragraphIndex: Type.Optional(
      Type.Number({
        description:
          "Paragraph index for 'after' or 'before' location (0-based)",
      }),
    ),
    anchor: Type.Optional(wordAnchorSchema),
    formatting: Type.Optional(
      Type.Object({
        bold: Type.Optional(Type.Boolean()),
        italic: Type.Optional(Type.Boolean()),
        underline: Type.Optional(Type.Boolean()),
        fontSize: Type.Optional(
          Type.Number({ description: "Font size in points" }),
        ),
        fontColor: Type.Optional(
          Type.String({ description: "Hex color like '#FF0000'" }),
        ),
        fontName: Type.Optional(Type.String()),
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description:
          "Brief explanation of what you're inserting (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    try {
      if (typeof Word === "undefined") {
        return toolError(
          "Word API is not available. This tool only works in Microsoft Word.",
        );
      }

      throwIfToolAborted(signal);

      const result = await Word.run(async (context) => {
        throwIfToolAborted(signal);
        return withTemporaryChangeTracking(
          context,
          true,
          async () => {
            const normalizedLocation = normalizeInsertLocation(params.location);
            const normalizedParams: InsertContentParams = {
              ...params,
              location: normalizedLocation,
            };
            const body = context.document.body;
            const selection = context.document.getSelection();
            let formatRange: Word.Range | null = null;
            let resolvedLocation: CanonicalInsertLocation = normalizedLocation;
            let paragraphIndex: number | null = null;
            let scopeParagraphIndex: number | null = null;
            let anchorUsed = false;

            switch (normalizedLocation) {
              case "selection": {
                formatRange = await insertAtSelection(
                  context,
                  selection,
                  normalizedParams,
                  signal,
                );
                break;
              }
              case "after":
              case "before": {
                const target = await resolveParagraphTarget(
                  context,
                  normalizedParams,
                  signal,
                );
                paragraphIndex = target.paragraphIndex;
                scopeParagraphIndex = target.scopeParagraphIndex;
                anchorUsed = target.anchorUsed;

                if (target.fallbackBodyLocation) {
                  resolvedLocation = target.fallbackBodyLocation;
                  formatRange = await insertIntoBody(
                    context,
                    body,
                    normalizedParams,
                    target.fallbackBodyLocation,
                    signal,
                  );
                } else if (target.paragraph) {
                  formatRange = await insertRelativeToParagraph(
                    context,
                    target.paragraph,
                    normalizedParams,
                    normalizedLocation,
                    signal,
                  );
                }
                break;
              }
              case "start": {
                formatRange = await insertIntoBody(
                  context,
                  body,
                  normalizedParams,
                  Word.InsertLocation.start,
                  signal,
                );
                break;
              }
              case "end":
              default: {
                formatRange = await insertIntoBody(
                  context,
                  body,
                  normalizedParams,
                  Word.InsertLocation.end,
                  signal,
                );
              }
            }

            if (params.formatting && formatRange) {
              throwIfToolAborted(signal);
              if (params.formatting.bold !== undefined) {
                formatRange.font.bold = params.formatting.bold;
              }
              if (params.formatting.italic !== undefined) {
                formatRange.font.italic = params.formatting.italic;
              }
              if (params.formatting.underline !== undefined) {
                formatRange.font.underline = params.formatting.underline
                  ? Word.UnderlineType.single
                  : Word.UnderlineType.none;
              }
              if (params.formatting.fontSize !== undefined) {
                formatRange.font.size = params.formatting.fontSize;
              }
              if (params.formatting.fontColor !== undefined) {
                formatRange.font.color = params.formatting.fontColor;
              }
              if (params.formatting.fontName !== undefined) {
                formatRange.font.name = params.formatting.fontName;
              }
              await syncWordContext(context, signal);
            }

            return {
              inserted: true,
              length: params.content.length,
              type: params.type,
              location: params.location,
              resolvedLocation,
              paragraphIndex,
              scopeParagraphIndex,
              anchorUsed,
            };
          },
          signal,
        );
      });

      return toolSuccess(result);
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error inserting content";
      return toolError(message);
    }
  },
});

function normalizeInsertLocation(
  location: InsertContentParams["location"],
): CanonicalInsertLocation {
  switch (location) {
    case "afterParagraph":
      return "after";
    case "beforeParagraph":
      return "before";
    case "start":
    case "selection":
    case "after":
    case "before":
      return location;
    case "end":
    default:
      return "end";
  }
}

async function insertAtSelection(
  context: Word.RequestContext,
  selection: Word.Range,
  params: InsertContentParams,
  signal?: AbortSignal,
): Promise<Word.Range> {
  throwIfToolAborted(signal);
  let insertedRange: Word.Range;

  if (params.type === "paragraph") {
    insertedRange = selection.insertHtml(
      buildParagraphHtml(params.content),
      Word.InsertLocation.replace,
    );
  } else if (params.type === "html") {
    insertedRange = selection.insertHtml(
      params.content,
      Word.InsertLocation.replace,
    );
  } else {
    insertedRange = selection.insertText(
      params.content,
      Word.InsertLocation.replace,
    );
  }

  insertedRange.load("font");
  await syncWordContext(context, signal);
  return insertedRange;
}

async function insertRelativeToParagraph(
  context: Word.RequestContext,
  paragraph: Word.Paragraph,
  params: InsertContentParams,
  location: "before" | "after",
  signal?: AbortSignal,
): Promise<Word.Range> {
  throwIfToolAborted(signal);
  let insertedRange: Word.Range;
  const paragraphTarget = paragraph as unknown as {
    insertHtml(
      content: string,
      location: Word.InsertLocation | string,
    ): Word.Range;
    insertText(
      content: string,
      location: Word.InsertLocation | string,
    ): Word.Range;
  };
  const insertLocation =
    location === "before"
      ? Word.InsertLocation.before
      : Word.InsertLocation.after;

  if (params.type === "paragraph") {
    insertedRange = paragraphTarget.insertHtml(
      buildParagraphHtml(params.content),
      insertLocation,
    );
  } else if (params.type === "html") {
    insertedRange = paragraphTarget.insertHtml(params.content, insertLocation);
  } else {
    insertedRange = paragraphTarget.insertText(params.content, insertLocation);
  }

  insertedRange.load("font");
  await syncWordContext(context, signal);
  return insertedRange;
}

async function insertIntoBody(
  context: Word.RequestContext,
  body: Word.Body,
  params: InsertContentParams,
  location:
    | Word.InsertLocation.start
    | Word.InsertLocation.end
    | "start"
    | "end",
  signal?: AbortSignal,
): Promise<Word.Range> {
  throwIfToolAborted(signal);
  let insertedRange: Word.Range;
  const insertLocation =
    location === Word.InsertLocation.start || location === "start"
      ? Word.InsertLocation.start
      : Word.InsertLocation.end;

  if (params.type === "paragraph") {
    insertedRange = body.insertHtml(
      buildParagraphHtml(params.content),
      insertLocation,
    );
  } else if (params.type === "html") {
    insertedRange = body.insertHtml(params.content, insertLocation);
  } else {
    insertedRange = body.insertText(params.content, insertLocation);
  }

  insertedRange.load("font");
  await syncWordContext(context, signal);
  return insertedRange;
}

async function resolveParagraphTarget(
  context: Word.RequestContext,
  params: InsertContentParams,
  signal?: AbortSignal,
): Promise<ParagraphTarget> {
  let anchorMismatch = false;
  const documentParagraphIndex = getAnchorDocumentParagraphIndex(params.anchor);
  if (documentParagraphIndex !== null) {
    const paragraphs = context.document.body.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (
      documentParagraphIndex < 0 ||
      documentParagraphIndex >= paragraphs.items.length
    ) {
      throw new Error(
        `Anchor paragraphIndex ${documentParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[documentParagraphIndex] ?? null;
    if (
      paragraph &&
      anchorMatchesParagraphText(params.anchor, paragraph.text ?? "")
    ) {
      return {
        paragraph,
        paragraphIndex: documentParagraphIndex,
        scopeParagraphIndex: getAnchorScopeParagraphIndex(params.anchor),
        anchorUsed: true,
        fallbackBodyLocation: null,
      };
    }

    anchorMismatch = true;
  }

  const scopeParagraphIndex = getAnchorScopeParagraphIndex(params.anchor);
  if (scopeParagraphIndex !== null) {
    const selection = context.document.getSelection();
    const paragraphs = selection.paragraphs;
    paragraphs.load("items/text");
    await syncWordContext(context, signal);

    if (
      scopeParagraphIndex < 0 ||
      scopeParagraphIndex >= paragraphs.items.length
    ) {
      throw new Error(
        `Anchor scopeParagraphIndex ${scopeParagraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
      );
    }

    const paragraph = paragraphs.items[scopeParagraphIndex] ?? null;
    if (
      paragraph &&
      anchorMatchesParagraphText(params.anchor, paragraph.text ?? "")
    ) {
      return {
        paragraph,
        paragraphIndex: null,
        scopeParagraphIndex,
        anchorUsed: true,
        fallbackBodyLocation: null,
      };
    }

    anchorMismatch = true;
  }

  if (anchorMismatch) {
    throw new Error(
      "Anchor no longer matches current document content. Read the target again before editing.",
    );
  }

  const paragraphs = context.document.body.paragraphs;
  paragraphs.load("items");
  await syncWordContext(context, signal);

  if (paragraphs.items.length === 0) {
    return {
      paragraph: null,
      paragraphIndex: null,
      scopeParagraphIndex: null,
      anchorUsed: false,
      fallbackBodyLocation: params.location === "before" ? "start" : "end",
    };
  }

  const paragraphIndex = params.paragraphIndex ?? 0;
  if (!Number.isInteger(paragraphIndex) || paragraphIndex < 0) {
    throw new Error("paragraphIndex must be a non-negative integer");
  }

  if (paragraphIndex >= paragraphs.items.length) {
    throw new Error(
      `Paragraph index ${paragraphIndex} is out of range (0-${paragraphs.items.length - 1})`,
    );
  }

  return {
    paragraph: paragraphs.items[paragraphIndex] ?? null,
    paragraphIndex,
    scopeParagraphIndex: null,
    anchorUsed: false,
    fallbackBodyLocation: null,
  };
}

function buildParagraphHtml(content: string): string {
  const normalizedContent = content.replace(/\r\n?/g, "\n");
  const paragraphBlocks = normalizedContent.split(/\n{2,}/).map((block) => {
    const escapedBlock = escapeHtml(block).replace(/\n/g, "<br>");
    return `<p>${escapedBlock || "<br>"}</p>`;
  });

  return paragraphBlocks.join("");
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
