const HISTORY_STRING_ARG_MAX_CHARS = 1200;
const HISTORY_STRING_ARG_PREVIEW_CHARS = 240;

const COMPACTABLE_STRING_ARGS: Readonly<Record<string, readonly string[]>> = {
  write_file: ["content"],
  write_progress: ["content"],
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function compactWhitespace(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

function compactLargeStringArg(
  toolName: string,
  argName: string,
  value: string,
  args: Record<string, unknown>,
): string {
  const path = typeof args.path === "string" ? args.path : undefined;
  const pathText = path ? ` for ${path}` : "";
  const preview = compactWhitespace(value).slice(
    0,
    HISTORY_STRING_ARG_PREVIEW_CHARS,
  );
  const previewText = preview
    ? ` Preview: ${preview}${value.length > preview.length ? " ..." : ""}`
    : "";
  return `[${argName} omitted from model history: ${value.length} characters were supplied to ${toolName}${pathText}. The tool already received the full value; use read_file on the path if the content is needed.${previewText}]`;
}

export function compactToolArgumentsForHistory(
  toolName: string,
  args: Record<string, unknown>,
): Record<string, unknown> {
  if (!isRecord(args)) return args;

  const argNames = COMPACTABLE_STRING_ARGS[toolName];
  if (!argNames) return args;

  let changed = false;
  const compacted: Record<string, unknown> = { ...args };
  for (const argName of argNames) {
    const value = compacted[argName];
    if (typeof value !== "string") continue;
    if (value.length <= HISTORY_STRING_ARG_MAX_CHARS) continue;
    compacted[argName] = compactLargeStringArg(
      toolName,
      argName,
      value,
      compacted,
    );
    changed = true;
  }

  return changed ? compacted : args;
}

export function stringifyToolArgumentsForHistory(
  toolName: string,
  args: Record<string, unknown>,
): string {
  try {
    return JSON.stringify(compactToolArgumentsForHistory(toolName, args) ?? {});
  } catch {
    return "{}";
  }
}

export function estimateToolArgumentsLengthForHistory(
  toolName: string,
  args: Record<string, unknown>,
): number {
  return stringifyToolArgumentsForHistory(toolName, args).length;
}
