import { Type } from "@sinclair/typebox";
import {
  DEFAULT_MAX_BYTES,
  DEFAULT_MAX_LINES,
  formatSize,
  truncateTail,
  type TruncationResult,
} from "../truncate";
import { getBash } from "../vfs";
import { defineTool, toolError, toolSuccess } from "./types";

const DEFAULT_TIMEOUT_MS = 30_000;

export interface BashExecutionOptions {
  signal?: AbortSignal;
  timeoutMs?: number;
}

export interface BashExecutionResult {
  output: string;
  exitCode: number;
  timedOut: boolean;
  aborted: boolean;
  truncation?: TruncationResult;
}

function normalizeBashOutput(result: {
  stdout?: string;
  stderr?: string;
  exitCode: number;
}): string {
  let output = "";

  if (result.stdout) {
    output += result.stdout;
  }

  if (result.stderr) {
    if (output && !output.endsWith("\n")) output += "\n";
    output += `stderr: ${result.stderr}`;
  }

  if (result.exitCode !== 0) {
    if (output && !output.endsWith("\n")) output += "\n";
    output += `[exit code: ${result.exitCode}]`;
  }

  return output.trim() || "[no output]";
}

function formatTruncatedOutput(truncation: TruncationResult): string {
  let outputText = truncation.content;

  if (!truncation.truncated) {
    return outputText;
  }

  const startLine = truncation.totalLines - truncation.outputLines + 1;
  const endLine = truncation.totalLines;

  if (truncation.truncatedBy === "lines") {
    outputText += `\n\n[Showing last ${truncation.outputLines} of ${truncation.totalLines} lines. Output truncated.]`;
  } else {
    outputText += `\n\n[Showing lines ${startLine}-${endLine} of ${truncation.totalLines} (${formatSize(truncation.maxBytes)} limit). Output truncated.]`;
  }

  return outputText;
}

async function executeBashCommand(
  command: string,
  options: BashExecutionOptions = {},
): Promise<BashExecutionResult> {
  const bash = getBash();
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;

  let timedOut = false;
  let aborted = false;

  const execPromise = bash.exec(command);

  const timeoutPromise = new Promise<never>((_, reject) => {
    const timer = setTimeout(() => {
      timedOut = true;
      reject(
        new Error(
          `Command timed out after ${timeoutMs}ms. Consider filtering data or using smaller files.`,
        ),
      );
    }, timeoutMs);

    options.signal?.addEventListener(
      "abort",
      () => {
        aborted = true;
        clearTimeout(timer);
        reject(new Error("Command aborted"));
      },
      { once: true },
    );
  });

  try {
    const result = await Promise.race([execPromise, timeoutPromise]);
    const rawOutput = normalizeBashOutput(result);
    const truncation = truncateTail(rawOutput);

    return {
      output: formatTruncatedOutput(truncation),
      exitCode: result.exitCode,
      timedOut: false,
      aborted: false,
      truncation: truncation.truncated ? truncation : undefined,
    };
  } catch (error) {
    if (timedOut || aborted) {
      return {
        output:
          error instanceof Error ? error.message : "Bash execution interrupted",
        exitCode: -1,
        timedOut,
        aborted,
      };
    }

    throw error;
  }
}

export const bashTool = defineTool({
  name: "bash",
  category: "read",
  parallelSafe: false,
  label: "Bash",
  description: `Execute bash commands in a sandboxed virtual environment. Output is truncated to last ${DEFAULT_MAX_LINES} lines or ${DEFAULT_MAX_BYTES / 1024}KB (whichever is hit first). The filesystem is in-memory with user uploads in /home/user/uploads/. Useful for: file operations (ls, cat, grep, find), text processing (awk, sed, jq, sort, uniq), data analysis (wc, cut, paste), and general scripting. Network access is disabled. No external runtimes (node, python, etc.) are available.`,
  parameters: Type.Object({
    command: Type.String({
      description:
        "Bash command(s) to execute. Can be a single command or a script with multiple lines. Supports pipes (|), redirections (>, >>), command chaining (&&, ||, ;), variables, loops, conditionals, and functions.",
    }),
    timeoutMs: Type.Optional(
      Type.Number({
        description: "Optional timeout in milliseconds",
        minimum: 1,
        maximum: 120000,
      }),
    ),
    explanation: Type.Optional(
      Type.String({
        description: "Brief explanation (max 50 chars)",
        maxLength: 50,
      }),
    ),
  }),
  execute: async (_toolCallId, params, signal) => {
    console.log(
      `[BashTool] Executing command: ${params.command.slice(0, 100)}...`,
    );

    try {
      const result = await executeBashCommand(params.command, {
        signal,
        timeoutMs: params.timeoutMs,
      });

      console.log(
        `[BashTool] Completed, exitCode=${result.exitCode}, timedOut=${result.timedOut}, aborted=${result.aborted}`,
      );

      return toolSuccess({
        output: result.output,
        exitCode: result.exitCode,
        timedOut: result.timedOut,
        aborted: result.aborted,
        truncation: result.truncation,
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown error executing bash command";

      console.error(`[BashTool] Error: ${message}`);
      return toolError(message);
    }
  },
});
